   private boolean canBlockAir(int blockAirValue) {
      if (this.useTemporaryBlocks.isEnabled()
         && this.getHotbarDirtSlot() != -1
         && this.schematicCells != null
         && mc.world != null
         && blockAirValue != Integer.MIN_VALUE) {
         if (this.isTempBlockDebtAtLimit()) {
            return false;
         } else {
            this.rebuildReachableComponent();
             LongPredicate longPredicate = packedCandidatePos -> this.component
                .contains(BlockPos.asLong(ProofSupportUtils.getValueInt(packedCandidatePos), ProofSupportUtils.getValue(packedCandidatePos), ProofSupportUtils.getValueForLong(packedCandidatePos)));

            for (int n = 0; n < this.schematicCells.size(); n++) {
               BlockPos blockPos = this.schematicCells.get(n);
               if (blockPos.getY() == blockAirValue) {
                  BlockState blockState = this.targetFluidItems.get(n);
                  BlockState currentState = mc.world.getBlockState(blockPos);
                  if (currentState.getBlock() != blockState.getBlock()
                     && (currentState.isAir() || currentState.isReplaceable())
                     && !hasFluidState(blockState)
                     && !isFlaggedBlockState(blockState)
                     && !this.isCellBlockedByTemporaryNeighbors(blockPos)
                     && !this.isMachineArmedAt(blockPos)
                     && !this.isPoweredOrCompletionCell(blockPos.asLong())
                     && !blockState.getCollisionShape(mc.world, blockPos).isEmpty()
                     && this.getRequiredSupportDirection(blockPos, blockState) == null
                     && !isPlaceableWithoutSpecialSneak(blockState)
                     && getDirectionForBlockState(blockState) == null
                     && !this.hasSolidNeighborToPlaceOn(blockPos)
                     && !this.isSupportCellEmptyAir(blockPos, blockState)
                     && !this.isIslandHandoverRecent(blockPos.asLong())
                     && this.canObtainItemForPlacement(getItemForBlockState(blockState))
                     && !this.excludedTargets.canFingerprintCells(blockPos.asLong(), this::getRawBlockStateIdAt)
                     && !this.isNeededByUnbuiltNeighbor(blockPos)
                     && !this.isWithinSchematicCellDistance(blockPos, 3)
                     && this.hasSolidNonDirectionalTarget(blockPos.up())
                     && mc.world.getBlockState(blockPos.up()).isAir()) {
                      BlockPos upperGapPos = blockPos.down();
                      BlockPos lowerGapPos = blockPos.down(2);
                      if (this.getSchematicCells(upperGapPos) < 0
                         && this.getSchematicCells(lowerGapPos) < 0
                         && mc.world.getBlockState(upperGapPos).isAir()
                         && mc.world.getBlockState(lowerGapPos).isAir()
                         && this.isSolidNonReplaceableAt(lowerGapPos.getX(), lowerGapPos.getY() - 1, lowerGapPos.getZ())
                         && !this.cells.contains(lowerGapPos.down().asLong())
                         && DescendReturnUtils.isWithinDescendLimitFiltered(lowerGapPos.getX(), lowerGapPos.getY(), lowerGapPos.getZ(), longPredicate)) {
                        if (!this.canFiniteBlocked(
                           "foot layer " + blockAirValue + ": faceless " + blockPos.toShortString() + " over a 2-high gap - floor pillar before the layer is left"
                        )) {
                           return false;
                        }

                        this.longFiniteBlocked = blockPos.asLong();
                        return true;
                     }
                  }
               }
            }

            return false;
         }
      } else {
         return false;
      }
   }

   private boolean canCompletionMission(SupportStandUtils.Mission mission) {
      if (mc.player != null && !mission.unsolved().isEmpty()) {
         boolean flag = false;

         for (SupportStandUtils.Cell cell : mission.unsolved()) {
            BlockPos blockPos = toBlockPos(cell);
            BlockState blockState = this.completionMissionMap.get(blockPos.asLong());
            if (blockState != null) {
               Direction down = this.getRequiredSupportDirection(blockPos, blockState);
               if (down == null && isRedstoneComponentBlock(blockState)) {
                  down = Direction.DOWN;
               }

               if (down != null) {
                  BlockPos supportPos = blockPos.offset(down);
                  if (this.completionMissionMap.containsKey(supportPos.asLong()) && !mission.unsolved().contains(getDataForBlockPos(supportPos))) {
                     flag = true;
                     break;
                  }
               }
            }
         }

         if (!flag) {
            return false;
         } else {
            if (this.held <= 0) {
               BlockPos feetBlockPos = this.getFeetBlockPos();
               ArrayList<BlockPos[]> arrayList = new ArrayList<>();

               for (long l : new ArrayList<>(this.completionMissionMap.keySet())) {
                  BlockPos fromLong = BlockPos.fromLong(l);
                  if (this.isMachineArmedAt(fromLong) && this.getRedstoneDeferralReason(fromLong) != null && this.blockPos2ShortPowered != null) {
                     arrayList.add(new BlockPos[]{this.blockPos2ShortPowered, fromLong});
                  }
               }

               arrayList.sort(Comparator.comparingDouble(blockPossx -> blockPossx[0].getSquaredDistance(feetBlockPos)));

               for (BlockPos[] blockPoss : arrayList) {
                  if (this.tryReclaimTempBesideCircuit(blockPoss[0], blockPoss[1])) {
                     this.unsolvedCompletionTick = this.moduleTick;
                     return true;
                  }
               }
            }

            int n = 0;
            if (this.confirms != this.completionMissionValue) {
               for (long l2 : this.completionMissionMap.keySet()) {
                  if (this.excludedTargets.canFingerprintCells(l2, this::getRawBlockStateIdAt)) {
                     n++;
                  }
               }
            }

            if (n == 0) {
               return this.tryReplanUnsolvedTail(mission);
            } else {
               this.completionMissionValue = this.confirms;

               for (long l3 : this.completionMissionMap.keySet()) {
                  this.excludedTargets.hasBan(l3);
               }

               this.logDebugMessage(
                  "\u00a7e[CompletionMission]\u00a7r steps=0 on "
                     + mission.unsolved().size()
                     + " cell(s) whose support was held out of the plan - "
                     + n
                     + " parked cell(s) re-admitted once before the tail is called unsolvable"
               );
               return true;
            }
         }
      } else {
         return false;
      }
   }

   private BlockStateUtilsNodes.WorkSource getAbsentShapeApi() {
      final BlockPos blockPos = this.getFeetBlockPos();
      return new BlockStateUtilsNodes.WorkSource() {
         private List<Long> cachedPositionKeys;

         @Override
         public long getPosBlock() {
            return blockPos.asLong();
         }

         @Override
         public Iterable<Long> getFacelessPave() {
            return AutoBuilder.this.paveFacelessMap.keySet();
         }

         @Override
         public int getFacelessPave(long facelessPaveValue) {
            Integer pavefacelessmap = AutoBuilder.this.paveFacelessMap.get(facelessPaveValue);
            return pavefacelessmap == null ? -1 : pavefacelessmap;
         }

         @Override
         public boolean canBlock(BlockState state) {
            return AutoBuilder.hasFluidState(state) || state.getBlock() instanceof FluidBlock || state.getBlock() instanceof BubbleColumnBlock;
         }

         @Override
         public ShapeContext getAbsent() {
            return AutoBuilder.this.getShapeContext();
         }

         @Override
         public BlockState getAutoBuilder(long positionKey) {
            int schematicCells = AutoBuilder.this.getSchematicCells(BlockPos.fromLong(positionKey));
            return schematicCells < 0 ? null : AutoBuilder.this.targetFluidItems.get(schematicCells);
         }

         @Override
         public boolean canAutoBuilder(BlockState state) {
            return AutoBuilder.this.canObtainItemForPlacement(AutoBuilder.getItemForBlockState(state));
         }

         @Override
         public boolean canFacelessPave(long positionKey) {
            return AutoBuilder.this.paveFacelessMap.containsKey(positionKey);
         }

         @Override
         public Iterable<Long> getAutoBuilder() {
            if (this.cachedPositionKeys != null) {
               return this.cachedPositionKeys;
            } else {
               var candidatePositions = new ArrayList();

               for (int i = 0; i < AutoBuilder.this.schematicCells.size(); i++) {
                  BlockPos schematiccell = AutoBuilder.this.schematicCells.get(i);
                  BlockState targetfluiditem = AutoBuilder.this.targetFluidItems.get(i);
                  if (!targetfluiditem.isAir() && (AutoBuilder.this.anchor <= -1000000 || schematiccell.getY() >= AutoBuilder.this.anchor)) {
                     Integer cooldown = AutoBuilder.this.cooldown.get(schematiccell.asLong());
                     if ((cooldown == null || AutoBuilder.this.moduleTick >= cooldown)
                        && !AutoBuilder.this.isCellBlockedByTemporaryNeighbors(schematiccell)
                        && (AutoBuilder.this.held <= 0 || !AutoBuilder.this.machineArmedSet.contains(schematiccell.asLong()))
                        && AutoBuilder.this.findPlaceableCellForRail(schematiccell, targetfluiditem) == null) {
                        AutoBuilder.FailRec failRec = AutoBuilder.this.entries.get(schematiccell.asLong());
                        if ((failRec == null || !AutoBuilder.this.isFailureRecordStillValid(schematiccell, failRec)) && !AutoBuilder.this.computeBlockStateMismatch(schematiccell, targetfluiditem).empty) {
                           candidatePositions.add(schematiccell.asLong());
                        }
                     }
                  }
               }

               this.cachedPositionKeys = candidatePositions;
               return candidatePositions;
            }
         }

         @Override
         public Policy getApiAuto() {
            return AutoBuilder.this.apiAutoPolicy;
         }

         @Override
         public Requirements getAutoBuilder(BlockView blockView, long positionKey, BlockState state) {
            BlockPos pos = BlockPos.fromLong(positionKey);
            return new Requirements(
               AutoBuilder.this.getRequiredSupportDirection(pos, state),
               AutoBuilder.this.getPlacementFacing(pos, state),
               AutoBuilder.this.getPlacementFloatHint(pos, state),
               AutoBuilder.this.isRelaxedBlockShortCell(pos) ? null : AutoBuilder.getAxis(state),
               AutoBuilder.isPlaceableWithoutSpecialSneak(state) && !AutoBuilder.this.isRelaxedBlockShortCell(pos)
            );
         }

         @Override
         public double getSettingAuto() {
            return AutoBuilder.this.reachSetting.getValue();
         }

         @Override
         public Iterable<Long> getAutoBuilder(long positionKey, double maxSquaredDistance) {
            var arrayList = new ArrayList();
            BlockPos eyePos = BlockPos.fromLong(positionKey);
            double eyeX = eyePos.getX() + 0.5;
            double eyeY = eyePos.getY() + 1.62;
            double eyeZ = eyePos.getZ() + 0.5;

            for (int j = 0; j < AutoBuilder.this.schematicCells.size(); j++) {
               BlockPos schematiccell2 = AutoBuilder.this.schematicCells.get(j);
               double dx = schematiccell2.getX() + 0.5 - eyeX;
               double dy = schematiccell2.getY() + 0.5 - eyeY;
               double dz = schematiccell2.getZ() + 0.5 - eyeZ;
               if (!(dx * dx + dy * dy + dz * dz > maxSquaredDistance)) {
                  BlockState targetfluiditem2 = AutoBuilder.this.targetFluidItems.get(j);
                  if (!targetfluiditem2.isAir() && (AutoBuilder.this.anchor <= -1000000 || schematiccell2.getY() >= AutoBuilder.this.anchor)) {
                     Integer cooldown2 = AutoBuilder.this.cooldown.get(schematiccell2.asLong());
                     if ((cooldown2 == null || AutoBuilder.this.moduleTick >= cooldown2)
                        && !AutoBuilder.this.isCellBlockedByTemporaryNeighbors(schematiccell2)
                        && (AutoBuilder.this.held <= 0 || !AutoBuilder.this.machineArmedSet.contains(schematiccell2.asLong()))
                        && AutoBuilder.this.findPlaceableCellForRail(schematiccell2, targetfluiditem2) == null) {
                        AutoBuilder.FailRec failRec2 = AutoBuilder.this.entries.get(schematiccell2.asLong());
                        if ((failRec2 == null || !AutoBuilder.this.isFailureRecordStillValid(schematiccell2, failRec2)) && !AutoBuilder.this.computeBlockStateMismatch(schematiccell2, targetfluiditem2).empty
                           )
                         {
                           arrayList.add(schematiccell2.asLong());
                        }
                     }
                  }
               }
            }

            return arrayList;
         }
      };
   }

   private void handleBlockDefer(String blockDeferText) {
      if (this.reason != null
         && this.reason.isPinnedDispatched()
         && this.currentTargetPos != null
         && this.currentTargetPos.asLong() == this.reason.getUnassignedMembersUnassignedMembersData()) {
         this.onRouteRedirectInvalidated("deferred: " + blockDeferText);
      }

      if (this.placementExplicit != null && this.placementExplicit.owner == Owner.DECK) {
         this.dispatchedFailureCount++;
         this.failExplicitPlacement("EXECUTOR_FAILURE: " + blockDeferText);
      }

      this.accessIsolated.recordReason(BlockedReasonTracker.classifyReason(blockDeferText), this.moduleTick, this.currentTargetPos == null ? 0L : this.currentTargetPos.asLong());
      if (this.currentTargetPos != null && this.superseded != null && this.superseded.isContains(this.currentTargetPos.asLong())) {
         this.sessionResetTimeUpdate.resetPrimaryCount();
      }

      this.onAccessRouteFailed(blockDeferText);
      this.setBudgetExhaustedReason("defer: " + blockDeferText);
      this.releaseUnknownOwnerForTarget("access failed: " + blockDeferText);
      this.blockDeferCount++;
      this.confirmed = "defer";
      if (this.blockPos != null && this.blockPos.equals(this.currentTargetPos)) {
         this.recordRepairFailure(this.currentTargetPos, blockDeferText);
         this.blockPos = null;
         this.repairBreakFlag = false;
      }

      if (this.currentTargetPos != null) {
         int n = this.deferCount.merge(this.currentTargetPos.asLong(), 1, Integer::sum);
         this.setCellCooldown(this.currentTargetPos.asLong(), this.moduleTick + (160 << Math.min(n - 1, 6)));
         this.nextCooldown = 0;
         this.recordLayerPlanHash(this.currentTargetPos);
         this.recordAccessFailure(this.currentTargetPos.asLong(), blockDeferText);
         if (StandReachable.getTextsExecutor(blockDeferText) == FailureKind.ACCESS) {
            this.holdAccessFamilyMembers(this.currentTargetPos, blockDeferText);
         }

         this.handleGeometryEmergency(this.currentTargetPos, blockDeferText);
         if (!this.shouldRelaxStandRequirement(this.currentTargetPos, n, blockDeferText)) {
            this.relaxFacingForStuckBlock(this.currentTargetPos, n);
         }
      }

      this.updatePressedOptions2();
      if (this.blockMultifaceBlockPos != null && this.currentTargetPos != null && !this.blockMultifaceBlockPos.equals(this.currentTargetPos)) {
         BlockPos blockPos = this.blockMultifaceBlockPos;
         BlockPos blockDeferBlockPos2 = this.blockDeferBlockPos;
         this.blockMultifaceBlockPos = null;
         this.blockDeferBlockPos = null;
         int schematicCells2 = this.getSchematicCells(blockPos);
         if (schematicCells2 >= 0 && this.cooldown.getOrDefault(blockPos.asLong(), 0) <= this.moduleTick) {
            BlockState blockState2 = mc.world.getBlockState(blockPos);
            if (blockState2.getBlock() != this.targetFluidItems.get(schematicCells2).getBlock() && (blockState2.isAir() || blockState2.isReplaceable())) {
               this.currentTargetPos = blockPos;
               this.supportAccessValue = schematicCells2;
               this.blockHitResultEgressStand = null;
               this.sideRunValue = 0;
               this.blockPos2LayerAccess = blockDeferBlockPos2;
               BlockState blockState = this.targetFluidItems.get(schematicCells2);
               this.discoveryConcreteFlag = isPlaceableWithoutSpecialSneak(blockState);
               this.solverUnavailableDirection = null;
               this.blockHitResult = null;
               this.resetCameraPredictionTimes();
               this.updatePlacementRecipeForTarget(blockPos, blockState);
               this.routePlanFlag = this.getRotateYcounterclockwise(blockPos, blockState) != null;
               this.transitionToState(AutoBuilder.State.GO_TO_POSITION, blockDeferText + " - resuming route");
               return;
            }
         }
      }

      if (this.state2Builder == AutoBuilder.State.SELECT_TARGET && this.wakeRev.getRevSinceTime() < 8L) {
         this.wakeRev.handleForcePending("dead_pick");
      }

      this.transitionToState(AutoBuilder.State.SELECT_TARGET, blockDeferText);
   }

   public void updateTeamLeaving() {
      if (!this.multiplayer.isEnabled()) {
         if (this.multiLeaving.isHostMulti()) {
            this.multiLeaving.updateMultiHost();
         }

         this.multiLeaving.updateChashCdigest();
         this.lastTickMultiLeaving = -1;
         this.multiLeavingActive = false;
         this.teamLiveFlag = false;
      } else if (mc.world != null && mc.player != null) {
         if (!this.multiLeaving.isHostMulti()) {
            if (this.multiLeaving.canChashCdigest(this.mpContext)) {
               return;
            }

            if (this.schematicBuilder.getLoadedSchematic() == null || this.schematicCells == null || this.schematicCells.isEmpty()) {
               return;
            }

            this.hostTeamText = this.getDimensionId();
            if ("Host".equals(this.sessionMode.getCurrentOption())) {
               this.multiLeaving.handleHostMultiForContext(this.mpContext);
            } else {
               this.multiLeaving.handleHostMulti3(this.mpContext);
            }
         }

         if (this.schematicBuilder.getLoadedSchematic() != null && this.isPlacementMatchingSchematic()) {
            this.syncSchematicFromHelper();
         }

         this.multiLeaving.handleMultiHost(this.mpContext);
         boolean flag = this.multiLeaving.isHostMulti8();
         if (flag && !this.teamLiveFlag) {
            DisabledEnabled.getInstance()
               .handleDisabledEnabled("Multiplayer", this.isEnabled() ? "Team session live" : "Team session live - turn Auto Builder on to build", true);
         }

         this.teamLiveFlag = flag;
         this.announceMultiBuilderTeamChanges();
      }
   }

