   private boolean canDeckFrontier(BlockPos pos, Vec3d vec, double reachValue, double reachLimit) {
      if (!this.deckMicroMoves.isProbingExitingConfirmed() || this.schematicCells == null) {
         return false;
      } else if (this.placementExplicit != null && this.placementExplicit.isRevalidateAlign()) {
         this.updateMissionArrival();
         return true;
      } else if (this.islandDeckFlag || !this.isCompletionPhaseActive() && !this.hasActiveBlockersStep() && this.islandAbort == 0L) {
         this.islandDeckFlag = false;
         if (this.layer == Integer.MIN_VALUE
            || this.deckMicroMoves.getWalkableDeckValue() == this.layer
            || this.deckMicroMoves.getWalkableDeckValue() > this.layer
               && this.layerStats != null
               && this.layerStats.solvableBuildableCount == 0
               && this.layerStats.solvableMatCount == 0) {
            this.refreshRemainingCandidates(this.deckMicroMoves.getWalkableDeckValue(), this.getPrimaryStandPosition());
            this.deckMicroMoves.onMaxSurface(this.remaining);
            this.updateEyeStandsData();
            if (this.remaining == null) {
               this.exitDeckMission("surface vanished");
               return false;
            } else {
               if (this.deckMicroMoves.isProbingExitingLatched() && (this.candidateSearch != null || this.deckPlanning.getSearchCandidate().isCommittedDiscovered())) {
                  this.deckPlanning.setCandidateSearchValue(this.deckMicroMoves.getWalkableDeckValue());
                  this.candidateSearch = null;
               }

               BlockPos primaryStandPosition = this.getPrimaryStandPosition();
               if (this.canDroppedPlaced(primaryStandPosition, vec, reachValue)) {
                  return true;
               } else if (this.tryRunRemainingSideStrategy(primaryStandPosition, vec, reachValue)) {
                  return true;
               } else {
                  this.preparedDeck = null;
                  if (this.stockUpcomingDeckItems()) {
                     return true;
                  } else {
                     Map<FloorBuildPlanner.Pick, AutoBuilder.MissionPlacement> map = new HashMap<>();
                     SurfaceFrontier.Action action = this.deckMicroMoves.getFrontierSurface(primaryStandPosition.getX(), primaryStandPosition.getY(), primaryStandPosition.getZ(), pickx -> {
                        AutoBuilder.MissionPlacement missionPlacement = this.planEdgePlacement(pickx, primaryStandPosition, vec, reachValue, true);
                        if (missionPlacement != null) {
                           map.put(pickx, missionPlacement);
                        }

                        return missionPlacement != null;
                     }, pickx -> {
                        BlockPos blockPosx = BlockPos.fromLong(pickx.stand());
                        AutoBuilder.MissionPlacement missionPlacement = this.planEdgePlacement(pickx, blockPosx, getStandingEyePos(blockPosx), reachValue, false);
                        if (missionPlacement != null) {
                           map.put(pickx, missionPlacement);
                        }

                        return missionPlacement != null;
                     }, this::canWalkFlatBetween);
                     this.distinctCountDroppedPlaced = (int)map.keySet()
                        .stream()
                        .filter(pickx -> pickx.standDist() == 0)
                        .map(FloorBuildPlanner.Pick::cell)
                        .distinct()
                        .count();
                     this.count = (int)map.keySet()
                        .stream()
                        .filter(pickx -> pickx.standDist() <= 3)
                        .map(FloorBuildPlanner.Pick::cell)
                        .distinct()
                        .count();
                     this.distinctCount = (int)map.keySet()
                        .stream()
                        .filter(pickx -> pickx.standDist() <= 8)
                        .map(FloorBuildPlanner.Pick::cell)
                        .distinct()
                        .count();
                     this.candidatesCandidate = FloorBuildPlanner.searchDistancesFrom(this.remaining, primaryStandPosition.asLong(), this::canWalkFlatBetween);
                     switch (action.kind()) {
                        case PLACE:
                        case MOVE:
                           if (action.picks().isEmpty()) {
                              return this.startDeckSurfaceMove(BlockPos.fromLong(action.stand()), null, primaryStandPosition);
                           } else {
                              FloorBuildPlanner.Pick pick = this.choosePlacementPick(action.picks(), map);
                              this.noneFrontierValue = this.candidatesCandidate.getDistance(pick.stand());
                              this.orElse = map.keySet()
                                 .stream()
                                 .filter(pick2 -> pick2.cell() == pick.cell())
                                 .mapToInt(pickx -> this.candidatesCandidate.getDistance(pickx.stand()))
                                 .filter(deckFrontierLimit -> deckFrontierLimit >= 0)
                                 .min()
                                 .orElse(this.noneFrontierValue);
                              this.deckFrontierText = this.noneFrontierValue > 8 ? action.why() : "none";
                              if (this.noneFrontierValue > 8) {
                                 if (!"LOCAL_FRONTIER_EXHAUSTED".equals(this.deckFrontierText) || this.distinctCount > 0) {
                                    this.updatePressedOptions2();
                                    this.logDebugMessage("\u00a7e[DeckNavigation]\u00a7r refused long relocation: productive local frontier remains");
                                    return true;
                                 }

                                 this.navigationDeckCount++;
                              }

                              return this.tryExecuteMissionPick(pick, map.get(pick), primaryStandPosition);
                           }
                        case ENTER:
                           return this.startDeckBootstrap(primaryStandPosition, vec, reachValue, BlockPos.fromLong(action.stand()));
                        case EXIT:
                           this.exitDeckMission(action.why());
                           return false;
                        default:
                           return true;
                     }
                  }
               }
            }
         } else {
            this.exitDeckMission("layer left the work horizon (deck " + this.deckMicroMoves.getWalkableDeckValue() + " vs active " + this.layer + ")");
            return false;
         }
      } else {
         this.exitDeckMission("another mission owns scheduling");
         return false;
      }
   }

   private void handleWorldDown(BlockPos pos) {
      if (!this.componentPositionSet.contains(pos.asLong())) {
         HashSet<Long> hashSet = new HashSet<>();
         ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
         hashSet.add(pos.asLong());
         arrayDeque.add(pos);

         while (!arrayDeque.isEmpty() && hashSet.size() <= 12) {
             BlockPos currentPos = arrayDeque.poll();

            for (Direction direction : Type.HORIZONTAL) {
                BlockPos blockPos = currentPos.offset(direction);
               BlockPos offset = null;
               if (WalkRouteFinder.isStandable(mc.world, blockPos)) {
                  offset = blockPos;
               } else if (WalkRouteFinder.isStandable(mc.world, blockPos.up())) {
                  offset = blockPos.up();
               } else if (mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()
                  && WalkRouteFinder.isStandable(mc.world, blockPos.down())) {
                  offset = blockPos.down();
               }

               if (offset != null && hashSet.add(offset.asLong())) {
                  arrayDeque.add(offset);
               }
            }
         }

         if (hashSet.size() <= 12) {
            this.componentPositionSet.addAll(hashSet);
         }
      }
   }

   private boolean canPlanContinuation(BlockPos longValue, int supportAccessValue, BlockState state) {
      IncompleteStand incompleteStand = this.getStandSnapshot();
      if (!incompleteStand.hasArrived()) {
         this.planContinuationAttemptCount++;
         return false;
      } else {
         this.planContinuationRetryCount++;
         if (this.blockers != null && mc.player != null) {
            com.corz.client.utils.PlannedLiveUtils.Certificate certificate = this.getPlannedStepCertificate(longValue);
            if (certificate != null) {
               BlockPos blockPos = this.getFeetBlockPos();
               long l = ProofSupportUtils.getTime(blockPos.getX(), blockPos.getY(), blockPos.getZ());
               Vec3d vec3d = this.getAimPointForSneakState(blockPos, longValue, mc.player.getEyePos(), true);
               com.corz.client.utils.PlannedLiveUtils.Verdict verdict = PlannedLiveUtils.getStandCertified(
                  certificate, l, Math.sqrt(vec3d.squaredDistanceTo(Vec3d.ofCenter(longValue))), this.reachSetting.getValue()
               );
               if (verdict.result() == com.corz.client.utils.PlannedLiveUtils.Result.STAND_MISMATCH && verdict.liveDistance() > this.reachSetting.getValue()) {
                  this.planContinuationCount++;
                  this.logDebugMessage(
                     "\u00a7c[CompletionParity]\u00a7r "
                        + PlannedLiveUtils.formatLivePlanned(certificate, l, verdict)
                        + " - not dispatched from an uncertified pose"
                  );
                  return false;
               }
            }
         }

         this.currentTargetPos = longValue;
         this.supportAccessValue = supportAccessValue;
         this.blockHitResultEgressStand = null;
         this.sideRunValue = 0;
         this.pulledActive = true;
         this.recoveryAccessValue = -1;
         this.blockPos2LayerAccess = null;
         this.standRouteCount = 0;
         this.partnerClickFlag = false;
         this.sneakEgressFlag = false;
         this.sneakOwner = AutoBuilder.SneakOwner.NONE;
         this.discoveryConcreteFlag = false;
         this.solverUnavailableDirection = null;
         this.blockHitResult = null;
         this.resetCameraPredictionTimes();
         this.updatePlacementRecipeForTarget(longValue, state);
         this.routePlanFlag = this.getRotateYcounterclockwise(longValue, state) != null;
         if (!longValue.equals(this.blockPos3PlanContinuation)) {
            this.recordTargetSwitch("plan-continue");
            this.blockPos3PlanContinuation = longValue;
         }

         this.setSupportText("BUILD_REACHABLE", "plan continuation - next block placeable from here");
         this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "plan continuation (visible from here)");
         return true;
      }
   }

