   private boolean isFiniteBlocked() {
      if (mc.player != null
         && this.schematicCells != null
         && this.targetFluidItems != null
         && this.floats <= 32
         && this.held > 0
         && this.held != Integer.MAX_VALUE
         && this.lastFiniteBlockedConfirms != this.confirms
         && this.finiteBlockedCount < 3
         && (!this.multiplayer.isEnabled() || !this.multiLeaving.isHostMulti8())) {
         for (BlockState blockState : this.targetFluidItems) {
            if (blockState.getBlock() instanceof TntBlock) {
               return false;
            }
         }

         BlockPos blockPos = this.getFeetBlockPos();
         long next = Long.MIN_VALUE;
         int max = Integer.MAX_VALUE;

         for (long l : this.completionMissionMap.keySet()) {
            if (this.machineArmedSet.contains(l) && !this.excludedTargets.canFingerprintCells(l, this::getRawBlockStateIdAt)) {
               int n = Math.max(Math.abs(BlockPos.unpackLongX(l) - blockPos.getX()), Math.abs(BlockPos.unpackLongZ(l) - blockPos.getZ()));
               if (n < max) {
                  next = l;
                  max = n;
               }
            }
         }

         if (next == Long.MIN_VALUE) {
            return false;
         } else {
            this.lastFiniteBlockedConfirms = this.confirms;
            this.finiteBlockedLastHeld = this.held;
            this.finiteBlockedCount++;

            for (long l2 : this.completionMissionMap.keySet()) {
               if (this.machineArmedSet.contains(l2)) {
                  this.cooldown.remove(l2);
                  this.layerPlanMap.remove(l2);
                  this.standReachable.handleReadmittedStamps(l2);
                  this.proofLayerMap.remove(l2);
               }
            }

            this.recNoroute.getTarget(com.corz.client.utils.DepsReasonData.Kind.ACCESS_FAMILY_BLOCKED, finiteBlockedValue -> this.machineArmedSet.contains(finiteBlockedValue));
            this.logDebugMessage(
               "\u00a7e[RedstoneSafety]\u00a7r terminal stall with "
                  + this.held
                  + " other machine cell(s) unbuildable - the armed-last outputs (nearest "
                  + BlockPos.fromLong(next).toShortString()
                  + ") are placed before any pause"
            );
            this.finiteBlockedText = "finite blocked list";
            this.finiteBlockedTime = Long.MIN_VALUE;
            this.finiteBlockedActive = true;
            this.recoveryAccessValue = -1;
            this.finiteBlockedPlacedCount = 0;
            this.next = Long.MIN_VALUE;
            this.longFiniteBlocked = next;
            this.blockers = null;
            this.stepIndex = -1;
            this.stepsTimeBudget.updateTimeMax();
            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "terminal stall: armed-last outputs placed before any pause");
            return true;
         }
      } else {
         return false;
      }
   }

