   private long getIntentCell(SupportStandUtils.Step step) {
      SupportStandUtils.Step effectiveStep = step.op() == SupportStandUtils.Op.PLACE ? step : this.getNextPlaceOrRemoveStep();
      long l = (effectiveStep != null ? toBlockPos(effectiveStep.cell()) : toBlockPos(step.cell())).asLong();
      SupportStandUtils.Intent intent = step.intent() != null ? step.intent() : (effectiveStep != null ? effectiveStep.intent() : null);
      this.rebuildReachableComponent();
      boolean flag = step.op() == SupportStandUtils.Op.PILLAR;
      return TimeBuilderHandle.getTime(
         l,
         step.op().ordinal(),
         step.stand() == null ? 0L : toBlockPos(step.stand()).asLong(),
         intent == null ? 0L : toBlockPos(intent.support()).asLong(),
         intent == null ? -1 : intent.face(),
         intent != null && intent.sneak(),
         flag ? toBlockPos(step.cell()).asLong() : 0L,
         flag ? step.count() : 0,
         this.componentKey
      );
   }

   private EyePoseData getOffsetTemporary(BlockPos pos, Direction facing) {
      if (facing == null) {
         return null;
      } else {
         int schematicCells4 = this.getSchematicCells(pos);
         BlockState blockState = schematicCells4 >= 0 ? this.targetFluidItems.get(schematicCells4) : null;
         if (blockState == null) {
            return null;
         } else {
            double d = this.reachSetting.getValue();
            if (facing.getAxis() == Axis.Y) {
               for (Direction direction : Type.HORIZONTAL) {
                  for (int n = 0; n >= -2; n--) {
                     BlockPos blockPos = pos.offset(direction).up(n);
                     if (!this.cellTemporarySet.contains(blockPos.asLong()) && WalkRouteFinder.isStandable(mc.world, blockPos)) {
                        EyePoseData eyePoseData = this.computeEyePoseForPlacement(pos, blockState, blockPos, d);
                        if (eyePoseData != null) {
                           return eyePoseData;
                        }
                     }
                  }
               }

               return null;
            } else {
               Direction opposite = facing.getOpposite();

               for (int n3 = 1; n3 <= 3; n3++) {
                  for (int n2 = -1; n2 <= 0; n2++) {
                      BlockPos standPos = pos.offset(opposite, n3).up(n2);
                      if (!this.cellTemporarySet.contains(standPos.asLong()) && WalkRouteFinder.isStandable(mc.world, standPos)) {
                         EyePoseData placementEyePose = this.computeEyePoseForPlacement(pos, blockState, standPos, d);
                         if (placementEyePose != null) {
                            return placementEyePose;
                        }
                     }
                  }
               }

               return null;
            }
         }
      }
   }

   private boolean isMemberArrival() {
      if (this.expectedConfirms == null) {
         return false;
      } else {
         this.cursor++;
         Step step = this.getNextUnbuiltPlanStep();
         if (step == null) {
            return false;
         } else if (step.isPlaceKind()) {
            return this.canProgramSupport(step);
         } else {
            BlockPos blockPos = BlockPos.fromLong(step.target());
            if (!this.getStandSnapshot().hasArrived()) {
               this.resetExpectedConfirms("the body left the program's stand");
               return false;
            } else {
               int n = this.getSchematicCells(blockPos);
               if (n < 0) {
                  this.resetExpectedConfirms("a member left the schematic");
                  return false;
               } else {
                  BlockState blockState = this.targetFluidItems.get(n);
                  if (!this.canObtainItemForPlacement(getItemForBlockState(blockState))) {
                     this.resetExpectedConfirms("material for the next member is gone");
                     return false;
                  } else if (this.findPlaceableCellForRail(blockPos, blockState) != null) {
                     return false;
                  } else if (this.canMachineDownForced(blockPos)) {
                     this.resetExpectedConfirms("the next member caps a lower target held for a teammate's block (dependency)");
                     return false;
                  } else {
                     Vec3d vec3d = mc.player.getEyePos();
                     double d = this.reachSetting.getValue();
                     if (this.getBlockHitResultNoSneakOverride(
                           blockPos,
                           vec3d,
                           d,
                           this.getRequiredSupportDirection(blockPos, blockState),
                           this.getPlacementFacing(blockPos, blockState),
                           this.getPlacementFloatHint(blockPos, blockState),
                           this.isRelaxedBlockShortCell(blockPos) ? null : getAxis(blockState)
                        )
                        == null) {
                        this.resetExpectedConfirms("the next member is not placeable from this pose");
                        return false;
                     } else if ((isPlaceableWithoutSpecialSneak(blockState) || !this.isRelaxedBlockShortCell(blockPos) && isOrientationDependentBlock(blockState)) && this.canPlaceFromStandWithoutSealing(blockPos, this.getStandingCellPos())
                        )
                      {
                        this.resetExpectedConfirms("the next member would seal the builder in from this pose");
                        return false;
                     } else if (!this.canPlaceTrapdoorState(blockPos, blockState, this.getAimPointForSneakState(this.getFeetBlockPos(), blockPos, vec3d, true), d)) {
                        this.resetExpectedConfirms("the next member is not placeable from this pose");
                        return false;
                     } else if (this.shouldDeferCompletionCell(blockPos)) {
                        this.resetExpectedConfirms("the next member would wall in an unbuilt neighbour (interior first - dependency)");
                        return false;
                     } else if (!this.canPlanContinuation(blockPos, n, blockState)) {
                        this.resetExpectedConfirms("arrival lost between members");
                        return false;
                     } else {
                        this.memberArrivalCount++;
                        this.membersArrivalCount++;
                        this.blockPosPosBlock = null;
                        return true;
                     }
                  }
               }
            }
         }
      }
   }

   private BlockPos getReplaceableWorld(BlockPos pos) {
      BlockPos up = pos;

      for (int n = 0; n < 10; n++) {
         BlockState blockState = mc.world.getBlockState(up);
         if (blockState.isAir() || blockState.isReplaceable()) {
            return WalkRouteFinder.isStandable(mc.world, up) ? up : null;
         }

         up = up.up();
      }

      return null;
   }

