   private void computeCoverageAnchors(List<Integer> cellIndices, int min, double coverageValue) {
      if (this.moduleTick != this.lastCoverageTick) {
         this.lastCoverageTick = this.moduleTick;
         BlockPos feetBlockPos = this.getFeetBlockPos();
         boolean flag3 = this.coverageValue == min
            && this.coverageConfirms == this.confirms
            && this.blockPos3Coverage != null
            && this.blockPos3Coverage.getSquaredDistance(feetBlockPos) <= 36.0
            && this.moduleTick - this.lastTickCoverage < 60;
         if (!flag3) {
            long nanoTime2 = this.selectPasses.getNanoTime();
            if (this.coverageConfirms != this.confirms) {
               this.coverageBooleanMap.clear();
            }

            if (this.coverageBooleanMap.size() > 20000) {
               this.coverageBooleanMap.clear();
            }

            this.lastTickCoverage = this.moduleTick;
            this.coverageConfirms = this.confirms;
            this.coverageValue = min;
            this.blockPos3Coverage = feetBlockPos;
            this.coveragePositionMap.clear();
            ArrayList<Integer> arrayList2 = new ArrayList<>();

            for (int n : cellIndices) {
               if (this.schematicCells.get(n).getY() == min) {
                  arrayList2.add(n);
               }
            }

            if (arrayList2.size() < 2) {
               this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.SELECT_COVERAGE, nanoTime2);
            } else {
               arrayList2.sort(Comparator.comparingDouble(integerx -> this.schematicCells.get(integerx).getSquaredDistance(feetBlockPos)));
               if (arrayList2.size() > 32) {
                  arrayList2.subList(32, arrayList2.size()).clear();
               }

               double max2 = Math.max(1.0, coverageValue - 0.6);
               double d3 = max2 * max2;
               int ceil7 = (int)Math.ceil(coverageValue);
               int n8 = 600;
               LinkedHashMap<Long, List<Long>> linkedHashMap = new LinkedHashMap<>();

               for (int n5 : arrayList2) {
                   BlockPos targetPos = this.schematicCells.get(n5);
                  BlockState blockState = this.targetFluidItems.get(n5);
                  ArrayList<Long> arrayList = new ArrayList<>();

                  for (int n4 = -ceil7; n4 <= ceil7 && arrayList.size() < 10; n4++) {
                     for (int n3 = -ceil7; n3 <= ceil7 && arrayList.size() < 10; n3++) {
                        for (int n2 : ProofSupportUtils.coverageTable) {
                           if (arrayList.size() >= 10) {
                              break;
                           }

                            BlockPos candidateStandPos = targetPos.add(n4, n2, n3);
                            if (this.component.contains(candidateStandPos.asLong())
                               && !candidateStandPos.equals(targetPos)
                               && !candidateStandPos.equals(targetPos.down())
                               && !this.canSealsDeferred(targetPos, candidateStandPos)
                               && !(getStandingEyePos(candidateStandPos).squaredDistanceTo(Vec3d.ofCenter(targetPos)) > d3)) {
                              boolean flag = this.safeSneak.isEnabled()
                                  && (targetPos.getY() < candidateStandPos.getY() || WalkRouteFinder.hasOpenHorizontalNeighbor(mc.world, candidateStandPos));
                               long l = candidateStandPos.asLong() * -7046029254386353131L ^ targetPos.asLong();
                              Boolean booleanValue = this.coverageBooleanMap.get(l);
                              boolean finish;
                              if (booleanValue != null) {
                                 finish = booleanValue;
                              } else {
                                 if (n8 <= 0) {
                                    continue;
                                 }

                                 n8--;
                                  finish = this.canPlaceFromEyePosition(targetPos, blockState, getStandingEyePos(candidateStandPos), coverageValue, false)
                                     || flag && this.canPlaceFromEyePosition(targetPos, blockState, getLoweredTargetPoint(candidateStandPos), coverageValue, true);
                                 this.coverageBooleanMap.put(l, finish);
                              }

                              if (finish) {
                                  arrayList.add(candidateStandPos.asLong());
                              }
                           }
                        }
                     }
                  }

                  if (!arrayList.isEmpty()) {
                      linkedHashMap.put(targetPos.asLong(), arrayList);
                  }
               }

               if (linkedHashMap.size() < 2) {
                  this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.SELECT_COVERAGE, nanoTime2);
               } else {
                   final BlockPos builderFeetPos = feetBlockPos;
                  var metricsImpl = new LinkedHashUtils.Metrics() {
                     @Override
                     public boolean isWithinAnchorSpacing(long autoBuilderValue, long autoBuilderValue2) {
                        BlockPos long2 = BlockPos.fromLong(autoBuilderValue);
                        BlockPos long3 = BlockPos.fromLong(autoBuilderValue2);
                        return Math.abs(long2.getX() - long3.getX()) <= 2 && Math.abs(long2.getZ() - long3.getZ()) <= 2 && Math.abs(long2.getY() - long3.getY()) <= 1;
                     }

                     @Override
                     public double getSquaredDistanceToBuilder(long squaredDistanceValue) {
                         return BlockPos.fromLong(squaredDistanceValue).getSquaredDistance(builderFeetPos);
                     }
                  };
                  LinkedHashUtils.Assignment assignment = LinkedHashUtils.getInstance(linkedHashMap, metricsImpl, 8);

                  for (Entry<Long, Long> entry : assignment.anchorByTarget().entrySet()) {
                     Integer integer = assignment.coverage().get(entry.getValue());
                     if (integer != null && integer >= 2) {
                        this.coveragePositionMap.put(entry.getKey(), entry.getValue());
                     }
                  }

                  this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.SELECT_COVERAGE, nanoTime2);
               }
            }
         }
      }
   }

   private void updateExitStairColumns(BlockPos pos) {
      if (this.moduleTick - this.lastTickPassWait >= 40 && !this.cells.isEmpty()) {
         this.lastTickPassWait = this.moduleTick;
         this.unpackCellsIntArrayMap.entrySet().removeIf(entry -> {
            int nx = BlockPos.unpackLongX(entry.getKey());
            int n2x = BlockPos.unpackLongZ(entry.getKey());
            int[] nsx = entry.getValue();
            if (!this.cells.contains(BlockPos.asLong(nx, nsx[0], n2x))) {
               return true;
            } else {
               int n3x = nsx[0];

               while ((n3x < nsx[1] || nsx.length > 2 && nsx[2] == 1) && this.cells.contains(BlockPos.asLong(nx, n3x + 1, n2x))) {
                  n3x++;
               }

               nsx[1] = n3x;
               return false;
            }
         });
         this.moveExitStairToSideStep();
         this.rebuildReachableComponent();
         if (this.component.size() >= 64 && this.layerAccessTowerBaseY != Integer.MIN_VALUE && pos.getY() - 1 >= this.layerAccessTowerBaseY) {
            for (long l3 : this.cells) {
               BlockPos blockPos = BlockPos.fromLong(l3);
               if (!this.cells.contains(blockPos.up().asLong()) && isDirtOrGrassBlock(mc.world.getBlockState(blockPos))) {
                  BlockPos down = blockPos;

                  int n4;
                  for (n4 = 1; this.cells.contains(down.down().asLong()); n4++) {
                     down = down.down();
                  }

                  boolean flag = this.layerAccessFloorY != Integer.MIN_VALUE
                     && this.layerPlanFloorY != Integer.MAX_VALUE
                     && down.getY() <= this.layerPlanFloorY + 1;
                  int n5 = flag ? 3 : 6;
                  if (n4 >= n5 && down.getY() <= pos.getY() - n5 && (this.canDownCollision(down) || this.canReachDescentPoint(down, pos.getY() - 1))) {
                      BlockPos pillarTopPos = blockPos.up();
                     boolean flag2 = false;

                     for (int n3 = -1; n3 <= 1 && !flag2; n3++) {
                        for (int n2 = -1; n2 <= 1 && !flag2; n2++) {
                           for (int n = -1; n <= 1 && !flag2; n++) {
                               if (this.component.contains(pillarTopPos.add(n3, n, n2).asLong())) {
                                 flag2 = true;
                              }
                           }
                        }
                     }

                     if (flag2) {
                        long long2 = BlockPos.asLong(blockPos.getX(), 0, blockPos.getZ());
                        int[] ns = this.unpackCellsIntArrayMap.get(long2);
                        if (ns == null || ns.length <= 2) {
                           boolean flag3 = this.waitFullPass != Integer.MIN_VALUE
                              && this.removeTempAfter.isEnabled()
                              && down.getY() <= this.waitFullPass - 4
                              && blockPos.getY() >= this.waitFullPass - 1
                              && pos.getY() >= this.waitFullPass
                              && Math.abs(blockPos.getX() - pos.getX()) <= 1
                              && Math.abs(blockPos.getZ() - pos.getZ()) <= 1;
                           if (flag3) {
                              for (long l : this.completionMissionMap.keySet()) {
                                 if (BlockPos.unpackLongY(l) < pos.getY() - 1 && !this.machineArmedSet.contains(l)) {
                                    flag3 = false;
                                    break;
                                 }
                              }
                           }

                           int[] put = this.unpackCellsIntArrayMap.put(long2, flag3 ? new int[]{down.getY(), blockPos.getY(), 1} : new int[]{down.getY(), blockPos.getY()});
                           if (flag3) {
                              this.waitFullPass = Integer.MIN_VALUE;
                              this.logDebugMessage(
                                 "\u00a7b[Lifeline]\u00a7r exit stair kept "
                                    + down.toShortString()
                                    + " .. "
                                    + blockPos.toShortString()
                                    + " ("
                                    + n4
                                    + " high) - the climb out of the finished pocket grows with the floor beside it and the final cleanup digs it down"
                              );
                           }
                        }
                     }
                  }
               }
            }
         }
      }
   }

