   private boolean isPlayerStandingOnLedgeCell(BlockPos ledgePos, BlockPos standPos) {
      if (mc.player != null
         && mc.world != null
         && mc.player.isOnGround()
          && standPos.getY() == ledgePos.getY()
          && !standPos.equals(ledgePos)) {
          if (mc.world.getBlockState(ledgePos.down()).getCollisionShape(mc.world, ledgePos.down()).isEmpty()
             && WalkRouteFinder.isStandable(mc.world, standPos)) {
            double d = mc.player.getX();
             double playerZ = mc.player.getZ();
             double ledgeMargin = 0.3;
             return d + ledgeMargin > standPos.getX() && d - ledgeMargin < standPos.getX() + 1 && playerZ + ledgeMargin > standPos.getZ() && playerZ - ledgeMargin < standPos.getZ() + 1;
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

