   private boolean isPlacedStateAcceptable(BlockPos pos, BlockState state) {
      BlockState placedState = mc.world.getBlockState(pos);
      if (placedState.getBlock() != state.getBlock()) {
         return false;
      } else if (hasFluidState(state) && !placedState.getFluidState().isStill()) {
         return false;
      } else if (this.isRelaxedBlockShortCell(pos)) {
         return true;
      } else if ((this.builtChangeSet.contains(pos.asLong()) || this.directionalStateSet.contains(pos.asLong())) && isRailBlockState(placedState)) {
         return true;
      } else if (this.isRelaxedFacingCell(pos) && placedState.contains(Properties.CHEST_TYPE) && placedState.get(Properties.CHEST_TYPE) != ChestType.SINGLE) {
         return true;
      } else if (this.relaxFacingWhenStuck.isEnabled()
         && state.contains(Properties.CHEST_TYPE)
         && placedState.contains(Properties.CHEST_TYPE)
         && state.contains(Properties.HORIZONTAL_FACING)
         && placedState.contains(Properties.HORIZONTAL_FACING)
         && SouthNorthUtilsFormat.canSingle(
            state.get(Properties.HORIZONTAL_FACING).asString(),
            state.get(Properties.CHEST_TYPE).asString(),
            placedState.get(Properties.HORIZONTAL_FACING).asString(),
            placedState.get(Properties.CHEST_TYPE).asString()
         )) {
         if (this.stateBlockSet.add(pos.asLong() ^ 61723L)) {
            this.logDebugMessage(
               "\u00a7b[RelaxFacing]\u00a7r " + pos.toShortString() + " accepted as a MERGED double chest built the opposite way (functionally identical)"
            );
         }

         return true;
      } else {
         return this.isChestPartnerMissing(pos, state)
               && state.contains(Properties.CHEST_TYPE)
               && placedState.contains(Properties.CHEST_TYPE)
               && SouthNorthUtilsFormat.canSingle(
                  formatPropertyValue(Properties.CHEST_TYPE, state.get(Properties.CHEST_TYPE)),
                  formatPropertyValue(Properties.CHEST_TYPE, placedState.get(Properties.CHEST_TYPE)),
                  false
               )
            ? true
            : this.computeBlockStateMismatch(pos, state).empty;
      }
   }

   private List<BlockPos> getCachedPath(BlockPos startPos, BlockPos destinationPos) {
      if (startPos.asLong() != this.longChanged || changedPlanCount != this.changedPlanCountChanged) {
         this.longChanged = startPos.asLong();
         this.changedPlanCountChanged = changedPlanCount;
         this.changedListMap.clear();
         this.changedPositionSet.clear();
      }

      long l = destinationPos.asLong();
      List<BlockPos> list = this.changedListMap.get(l);
      if (list != null) {
         return list;
      } else if (this.changedPositionSet.contains(l)) {
         return null;
      } else {
         long nowNanos = System.nanoTime();
         if (this.changedCount <= 0 && (this.changedValue == Long.MIN_VALUE || nowNanos - this.changedValue >= 250000000L)) {
            this.changedCount = 1;
            this.changedValue = nowNanos;
         }

         if (this.changedCount <= 0) {
            this.catwalkWalkFlag = true;
            return null;
         } else {
            this.changedCount--;
            List<BlockPos> goPath = this.findGoPath(startPos, destinationPos);
            if (goPath != null && !goPath.isEmpty()) {
               this.changedListMap.put(l, goPath);
            } else {
               this.changedPositionSet.add(l);
            }

            return goPath;
         }
      }
   }

