   private FloorBuildPlanner.Pick choosePlacementPick(
      List<FloorBuildPlanner.Pick> placementPicks, Map<FloorBuildPlanner.Pick, AutoBuilder.MissionPlacement> placementByPick
   ) {
      ArrayList<Candidate> arrayList = new ArrayList<>();
      long l = placementPicks.get(0).stand();

      for (FloorBuildPlanner.Pick pick : placementPicks) {
         if (pick.stand() == l && placementByPick.get(pick) != null) {
            arrayList.add(this.buildClickCandidate(pick, placementByPick.get(pick)));
         }
      }

      String string = mc.player.getMainHandStack().isEmpty() ? this.materialCycleDeck : getItemIdPath(mc.player.getMainHandStack().getItem());
      List<Candidate> targetTier = TierBuilderUtils.getTargetTier(arrayList, mc.player.getYaw(), mc.player.getPitch(), string, this.faceCycleDeck);
      this.copyOfDroppedPlaced = TierBuilderUtils.getCopyOf(targetTier);
      if (targetTier.isEmpty()) {
         return placementPicks.get(0);
      } else {
         long chosenTargetKey = targetTier.get(0).target();
         if (placementPicks.get(0).standDist() == 0) {
            HashMap<Long, Boolean> hashMap = new HashMap<>();

            for (Entry<FloorBuildPlanner.Pick, AutoBuilder.MissionPlacement> entry : placementByPick.entrySet()) {
               if (entry.getValue() != null && entry.getValue().cert() != null) {
                  hashMap.put(entry.getKey().cell(), entry.getValue().cert().sneak());
               }
            }

            this.recordRunPlacements(l, targetTier, hashMap);
            if (this.droppedPlaced != null && this.droppedPlaced.getPeek() != null && this.droppedPlaced.getPeek().cell() == chosenTargetKey) {
               this.droppedPlaced.getPoll();
            }
         }

         return placementPicks.stream().filter(pickx -> pickx.cell() == chosenTargetKey && pickx.stand() == l).findFirst().orElseThrow();
      }
   }

