   private long computeCellsStateHash() {
      long[] ls = new long[this.cells.size()];
      int n = 0;

      for (long l : this.cells) {
         ls[n++] = l;
      }

      Arrays.sort(ls);
      long cellsHash = -3750763034362895579L;

      for (long cellKey : ls) {
         cellsHash = (cellsHash ^ cellKey) * 1099511628211L;
      }

      long unknownCellsValue = (cellsHash ^ this.compoundCompleteValue) * 1099511628211L;
      long stateHash = (unknownCellsValue ^ (this.unknown == null ? 0L : this.unknown.getReusableDescentTime())) * 1099511628211L;
      long leasesHash = 0L;

      for (long leaseKey : this.retainedLeaseSet) {
         leasesHash ^= leaseKey * -7046029254386353131L;
      }

      return (stateHash ^ leasesHash) * 1099511628211L;
   }

   public void updateRestockDestroyed() {
      long l = System.currentTimeMillis();
      if (!this.copyOnWriteArrayList.isEmpty()) {
         this.copyOnWriteArrayList.removeIf(fadingRestock -> l - fadingRestock.startMs() >= 600L);
      }

      if (mc.world != null && l - this.restockDestroyedValue >= 500L) {
         this.restockDestroyedValue = l;
         List<DimensionPosData> list = this.restockSources.removeStaleEntriesInLoadedChunks(mc.world);
         if (!list.isEmpty()) {
            for (DimensionPosData dimensionPosData : list) {
               this.copyOnWriteArrayList.add(new AutoBuilder.FadingRestock(dimensionPosData.pos(), dimensionPosData.dimension(), dimensionPosData.type(), l));
               this.restockSourceMap.remove(formatDimensionPosKey(dimensionPosData.dimension(), dimensionPosData.pos()));
            }

            ModuleConfigAutosave.updateFlag2();
            DisabledEnabled.getInstance()
               .handleDisabledEnabled("Restock", list.size() == 1 ? "Restock container destroyed" : list.size() + " restock containers destroyed", false);
         }
      }
   }

