   private long[] getMissingCellsNear(BlockPos pos, int blockSchematicValue) {
      byte blockSchematicValue2 = 4;
      ArrayList<Long> arrayList = new ArrayList<>();

      for (int n = 0; n < this.schematicCells.size(); n++) {
         BlockPos blockPos = this.schematicCells.get(n);
         if (Math.abs(blockPos.getX() - pos.getX()) <= 4
            && Math.abs(blockPos.getZ() - pos.getZ()) <= 4
            && blockPos.getY() >= pos.getY() - 1 - 1
            && blockPos.getY() <= blockSchematicValue + 3
            && this.isInsideTemporaryRegion(blockPos)) {
            BlockState blockState = this.targetFluidItems.get(n);
            BlockState worldState = mc.world.getBlockState(blockPos);
            if (worldState.getBlock() != blockState.getBlock()
               && (worldState.isAir() || worldState.isReplaceable())
               && !hasFluidState(blockState)
               && !isFlaggedBlockState(blockState)
               && !this.isCellBlockedByTemporaryNeighbors(blockPos)
               && this.canObtainItemForPlacement(getItemForBlockState(blockState))) {
               arrayList.add(ProofSupportUtils.getTime(blockPos.getX(), blockPos.getY(), blockPos.getZ()));
            }
         }
      }

      long[] ls = new long[arrayList.size()];

      for (int resultIndex = 0; resultIndex < ls.length; resultIndex++) {
         ls[resultIndex] = arrayList.get(resultIndex);
      }

      return ls;
   }

