   private void pasteSchematicIntoWorld() {
      RegistryMin registryMin = this.registryMin;
      if (registryMin != null) {
         registryMin.updateFlag();
      } else if (mc.player != null && mc.world != null) {
         if (mc.isInSingleplayer() && mc.getServer() != null) {
            ElseBuilder loadedSchematic = this.schematicBuilder.getLoadedSchematic();
            if (loadedSchematic == null) {
               DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Select a schematic first", false);
            } else {
               if (!this.folderOpenFlag) {
                  this.captureOriginPosition();
               }

               if (!this.blockStateHelper.canFlag(loadedSchematic, this.originX, this.originY, this.originZ, this.rotationEnumFolder.getCurrentIndex(), this.enumHelper.getCurrentIndex())) {
                  DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Schematic has no blocks", false);
               } else {
                  if (this.isEnabled()) {
                     this.setEnabled(false);
                  }

                  List<BlockPos> list = List.copyOf(this.blockStateHelper.getItems());
                  List<BlockState> schematicStates = List.copyOf(this.blockStateHelper.getCameraBlockStateList());
                  HashMap<Long, Integer> hashMap = new HashMap<>();
                  if (this.blockStateHelper.getValue() > 0) {
                     for (BlockPos blockPos : list) {
                        Integer integer = this.blockStateHelper.getNumber(blockPos.asLong());
                        if (integer != null) {
                           hashMap.put(blockPos.asLong(), integer);
                        }
                     }
                  }

                  this.registryMin = new RegistryMin(list, schematicStates, hashMap, mc.world.getRegistryKey());
                  DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Pasting " + list.size() + " blocks...", true);
                  this.sendPlayerChatMessage(
                     "\u00a7b[Auto Builder]\u00a7r pasting \u00a7f"
                        + loadedSchematic.orElse
                        + "\u00a7r - "
                        + list.size()
                        + " block(s) at "
                        + this.originX
                        + ","
                        + this.originY
                        + ","
                        + this.originZ
                        + " rot="
                        + this.rotationEnumFolder.getCurrentOption()
                        + " mirror="
                        + this.enumHelper.getCurrentOption()
                        + "."
                  );
                  if (this.blockStateHelper.isBlockActive()) {
                     this.sendPlayerChatMessage(
                        "\u00a7e[Auto Builder]\u00a7r this schematic is larger than the placement cache, so only its first "
                           + list.size()
                           + " cells are pasted - the rest has to be built."
                     );
                  }
               }
            }
         } else {
            DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Singleplayer only", false);
            this.sendPlayerChatMessage(
               "\u00a7e[Auto Builder]\u00a7r 'Paste Schematic' writes blocks straight into the world, which only your own singleplayer world lets a client do - on a server they would be ghost blocks that revert on the next chunk update. Turn the module on to BUILD the schematic there instead."
            );
         }
      }
   }

   private boolean tryDryLayerPour(int unpackShortValue) {
      if (!this.containsPositionSet.isEmpty() && mc.world != null && mc.player != null && unpackShortValue != Integer.MIN_VALUE) {
         long attemptKey = unpackShortValue * -7046029254386353131L ^ this.confirms;
         if (attemptKey == this.unpackShortValue) {
            return false;
         } else {
            BlockPos feetBlockPos = this.getFeetBlockPos();
            BlockPos longValue = null;
            double squaredDistance = Double.MAX_VALUE;

            for (long l : this.containsPositionSet) {
               int n = BlockPos.unpackLongY(l);
               if ((n == unpackShortValue || n == unpackShortValue - 1) && !this.excludedTargets.canFingerprintCells(l, this::getRawBlockStateIdAt)) {
                  BlockPos blockPos = BlockPos.fromLong(l);
                  double d = feetBlockPos.getSquaredDistance(blockPos);
                  if (d < squaredDistance && this.isPlacedWaterNotStill(blockPos)) {
                     squaredDistance = d;
                     longValue = blockPos;
                  }
               }
            }

            if (longValue != null
               && this.canFiniteBlocked(
                  "foot layer " + unpackShortValue + ": dry layer pour " + longValue.toShortString() + " - poured from the ring tops before the layer is left"
               )) {
               this.unpackShortValue = attemptKey;
               this.longFiniteBlocked = longValue.asLong();
               return true;
            } else {
               return false;
            }
         }
      } else {
         return false;
      }
   }

