   private AutoBuilder.OrientedAim findOrientedPlacementAim(BlockPos pos, BlockState state, Vec3d vec, double playerPitchFactor, ItemStack stack) {
      if (mc.player != null && mc.world != null && stack != null && !stack.isEmpty()) {
         double maxReachSquared = playerPitchFactor * playerPitchFactor;
         float f = mc.player.getYaw();
         float originalPitch = mc.player.getPitch();
         double[] ds = new double[]{0.5, 0.35, 0.65, 0.25, 0.75};

         try {
            for (Direction supportDirection : Direction.values()) {
               BlockPos blockPos = pos.offset(supportDirection);
               BlockState supportState = mc.world.getBlockState(blockPos);
               if (!supportState.isAir() && !supportState.isReplaceable()) {
                  boolean flag = supportDirection == Direction.DOWN
                     && BlockStateUtilsView.canWireIterator(supportState)
                     && this.getRequiredSupportDirection(pos, state) == Direction.DOWN;
                  if ((!supportState.getCollisionShape(mc.world, blockPos).isEmpty() || flag) && (!this.placeOrientedFlag || !isFlaggedBlockState(supportState))
                     )
                   {
                     Direction direction = supportDirection.getOpposite();
                     long l = hashPosAndDirection(pos, direction);
                     Integer integer = this.faceParityMap.get(l);
                     if (integer == null || this.moduleTick >= integer) {
                        List<Vec3d> list = flag ? BlockStateUtilsView.getBoxesMax(mc.world, supportState, blockPos) : List.of();
                        int sampleCount = flag ? list.size() : ds.length * ds.length;

                        for (int n = 0; n < sampleCount; n++) {
                           Vec3d vec3d = flag ? list.get(n) : this.getFaceAimPointInRange(supportState, blockPos, direction, ds[n / ds.length], ds[n % ds.length]);
                           if (vec3d != null && !(vec.squaredDistanceTo(vec3d) > maxReachSquared)) {
                              float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d);
                              BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec, fs[0], fs[1], playerPitchFactor);
                              if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                                 && blockHitResult.getBlockPos().equals(blockPos)
                                 && blockHitResult.getSide() == direction) {
                                 mc.player.setYaw(fs[0]);
                                 mc.player.setPitch(fs[1]);
                                 BlockState blockState = PlacementBlockUtils.getPlacementState(mc.player, Hand.MAIN_HAND, stack, blockHitResult);
                                 if (blockState != null
                                    && blockState.getBlock() == state.getBlock()
                                    && BottleLevelUtils.getEmpty(getBlockStatePropertyMap(state), getBlockStatePropertyMap(blockState), getIgnoredStairProperties(state)).empty) {
                                    return new AutoBuilder.OrientedAim(blockHitResult, fs[0], fs[1]);
                                 }
                              }
                           }
                        }
                     }
                  }
               }
            }

            return null;
         } finally {
            mc.player.setYaw(f);
            mc.player.setPitch(originalPitch);
         }
      } else {
         return null;
      }
   }

   public static void recordTickedBlockState(BlockPos pos, BlockState state) {
      if (pos != null && state != null) {
         if (TICKED_BUCKET_MAP.size() > 4096) {
            TICKED_BUCKET_MAP.clear();
         }

         BlockState previousState = TICKED_BUCKET_MAP.put(pos.asLong(), state);
         if (previousState != state) {
            changedPlanCount++;
            SHARED_HASH_OPEN.markCellOpen(pos.getX(), pos.getY(), pos.getZ());
            if (previousState != null && classifyBlockPassability(previousState, pos) != classifyBlockPassability(state, pos)) {
               SHARED_HASH_OPEN.recordPositionHit(pos.getX(), pos.getY(), pos.getZ());
            }
         }
      }
   }

