   private boolean tryReplanUnsolvedTail(SupportStandUtils.Mission mission) {
      if (this.held > 0) {
         return false;
      } else {
         for (SupportStandUtils.Cell cell : mission.unsolved()) {
            BlockPos blockPos = toBlockPos(cell);
            BlockState blockState = this.completionMissionMap.get(blockPos.asLong());
            if (blockState != null) {
               Direction down = this.getRequiredSupportDirection(blockPos, blockState);
               if (down == null && isRedstoneComponentBlock(blockState)) {
                  down = Direction.DOWN;
               }

               if (down != null) {
                  BlockPos supportPos = blockPos.offset(down);
                  if (this.completionMissionMap.containsKey(supportPos.asLong())
                     && !mission.unsolved().contains(getDataForBlockPos(supportPos))
                     && !this.isObserverPowered(supportPos)
                     && this.isMachineArmedAt(supportPos)
                     && this.getRedstoneDeferralReason(supportPos) == null
                     && supportPos.asLong() * 31L + this.confirms != this.unsolvedCompletionValue) {
                     this.unsolvedCompletionValue = supportPos.asLong() * 31L + this.confirms;
                     this.unsolvedCompletionTick = this.moduleTick;
                     this.logDebugMessage(
                        "\u00a7e[CompletionMission]\u00a7r steps=0 on "
                           + mission.unsolved().size()
                           + " cell(s) whose support "
                           + supportPos.toShortString()
                           + " was held out of the plan by an arming hold that has cleared since - re-planning once before the tail is called unsolvable"
                     );
                     return true;
                  }

                  if (this.completionMissionMap.containsKey(supportPos.asLong())
                     && !mission.unsolved().contains(getDataForBlockPos(supportPos))
                     && this.isObserverPowered(supportPos)) {
                     long l = supportPos.asLong() * 31L + this.confirms;
                     if (l == this.unsolvedCompletionValue) {
                        return false;
                     }

                     this.unsolvedCompletionValue = l;
                     this.longUnsolvedCompletion = supportPos.asLong();
                     this.lastTickUnsolvedCompletion = this.moduleTick;
                     this.lastNanoTimeUnsolvedCompleti = System.nanoTime();
                     this.unsolvedCompletionTick = this.moduleTick;
                     this.logDebugMessage(
                        "\u00a7e[CompletionMission]\u00a7r steps=0 on "
                           + mission.unsolved().size()
                           + " cell(s) whose support "
                           + supportPos.toShortString()
                           + " is an observer output in its arming quiet window - holding until it settles before the tail is called unsolvable"
                     );
                     return true;
                  }
               }
            }
         }

         return false;
      }
   }

