   private boolean tryInteractBlock(BlockPos pos) {
      Vec3d eyePos = mc.player.getEyePos();
      double reachDistance = this.reachSetting.getValue();
      double reachDistanceSquared = reachDistance * reachDistance;
      BlockState blockState = mc.world.getBlockState(pos);
      Direction[] directions = new Direction[]{Direction.UP, Direction.NORTH, Direction.SOUTH, Direction.WEST, Direction.EAST, Direction.DOWN};
      double[] ds = new double[]{0.5, 0.3, 0.7, 0.15, 0.85};

      for (Direction direction : directions) {
         if (this.getFaceAimPoint(blockState, pos, direction) != null) {
            for (double faceU : ds) {
               for (double d : ds) {
                  Vec3d vec3d = this.getFaceAimPointInRange(blockState, pos, direction, faceU, d);
                  if (vec3d != null && !(eyePos.squaredDistanceTo(vec3d) > reachDistanceSquared)) {
                     float[] fs = MathClampUtils.getWrapDegrees(eyePos, vec3d);
                     BlockHitResult blockHitResult = this.raycastBlockSideForAim(eyePos, fs[0], fs[1], reachDistance);
                     if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
                        float[] adjustedRotation = this.computeAimRotation(fs[0], fs[1]);
                        BlockHitResult adjustedHit = this.raycastBlockSideForAim(eyePos, adjustedRotation[0], adjustedRotation[1], reachDistance);
                        if (adjustedHit.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && adjustedHit.getBlockPos().equals(pos)) {
                           this.recordHitForCurrentTarget(adjustedHit);
                           this.performBlockInteraction(adjustedHit);
                           if (this.swing.isEnabled()) {
                              mc.player.swingHand(Hand.MAIN_HAND);
                           }

                           return true;
                        }

                        return false;
                     }
                  }
               }
            }
         }
      }

      return false;
   }

   private boolean hasUnbuiltCellAtOrBelow(Terrain terrain, BlockPos candidatePos, BlockPos targetPos, boolean solidSchematicFlag, boolean requireSolidCheck) {
      int horizontalDistance = Math.max(Math.abs(candidatePos.getX() - targetPos.getX()), Math.abs(candidatePos.getZ() - targetPos.getZ()));
      boolean sameLevelAtRadiusThree = horizontalDistance == 3 && candidatePos.getY() == targetPos.getY();
      if (horizontalDistance <= 3
         && (candidatePos.getY() == targetPos.getY() - 1 || sameLevelAtRadiusThree)
         && this.getSchematicCells(targetPos.down()) >= 0
         && this.schematicCells != null
         && this.targetFluidItems != null
         && mc.world != null) {
         int candidateX = candidatePos.getX();
         int candidateY = candidatePos.getY();
         int candidateZ = candidatePos.getZ();
         if (!requireSolidCheck
            || !terrain.solid(candidateX, candidateY, candidateZ)
               && !terrain.solid(candidateX, candidateY + 1, candidateZ)
               && (
                  sameLevelAtRadiusThree
                     ? !terrain.solid(candidateX, candidateY - 1, candidateZ)
                     : terrain.canStandOn(candidateX, candidateY - 1, candidateZ)
                        || !terrain.solid(candidateX, candidateY - 1, candidateZ)
                           && (terrain.canStandOn(candidateX, candidateY - 2, candidateZ) || !terrain.solid(candidateX, candidateY - 2, candidateZ) && terrain.canStandOn(candidateX, candidateY - 3, candidateZ))
               )) {
            int reachabilityThreshold = 160;
            if (WalkableRegionAnalyzer.countReachableCells(
                     WalkableRegionAnalyzer.getHandlerForTerrainInt(terrain, candidateX, candidateY, candidateZ, solidSchematicFlag), targetPos.getX(), targetPos.getY(), targetPos.getZ(), reachabilityThreshold
                  )
                  < reachabilityThreshold
               && WalkableRegionAnalyzer.countReachableCells(terrain, targetPos.getX(), targetPos.getY(), targetPos.getZ(), reachabilityThreshold) >= reachabilityThreshold) {
               for (int n = 0; n < this.schematicCells.size(); n++) {
                  BlockPos blockPos = this.schematicCells.get(n);
                  BlockState blockState = this.targetFluidItems.get(n);
                  if (blockPos.getY() <= candidateY
                     && blockPos.getManhattanDistance(candidatePos) > 1
                     && !isNonWaterloggableFluid(blockState)
                     && !this.machineArmedSet.contains(blockPos.asLong())) {
                     BlockState worldState = mc.world.getBlockState(blockPos);
                     if (worldState.getBlock() != blockState.getBlock()
                        && !areBlocksEquivalentVariants(blockState, worldState)
                        && (worldState.isAir() || worldState.isReplaceable())
                        && !this.isReplaceableCellEnclosedByFullCubes(blockPos)
                        && !this.isSupportCellEmptyAir(blockPos, blockState)) {
                        return true;
                     }
                  }
               }

               return false;
            } else {
               return false;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

   private void breakNearbyTemporaryBlock() {
      Vec3d vec3d = mc.player.getEyePos();
      double d = this.reachSetting.getValue() * this.reachSetting.getValue();
      BlockPos feetBlockPos = this.getFeetBlockPos();
      Long next = null;

      for (long l : this.cells) {
         BlockPos blockPos = BlockPos.fromLong(l);
         if (mc.world.getBlockState(blockPos).isAir()) {
            next = l;
            break;
         }

         if (!blockPos.equals(feetBlockPos.down()) && vec3d.squaredDistanceTo(Vec3d.ofCenter(blockPos)) <= d) {
            next = l;
            break;
         }
      }

      if (next == null) {
         for (long l2 : this.cells) {
            if (vec3d.squaredDistanceTo(Vec3d.ofCenter(BlockPos.fromLong(l2))) <= d) {
               next = l2;
               break;
            }
         }
      }

      if (next == null) {
         this.updatePressedOptions2();
      } else {
         BlockPos fromLong = BlockPos.fromLong(next);
         if (mc.world.getBlockState(fromLong).isAir()) {
            this.forgetTemporaryCell(next);
         } else {
            float[] fs = MathClampUtils.getWrapDegrees(vec3d, Vec3d.ofCenter(fromLong));
            float[] aimRotation2 = this.computeAimRotation(fs[0], fs[1]);
            BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d, aimRotation2[0], aimRotation2[1], this.reachSetting.getValue());
            if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(fromLong)) {
               this.mineBlockStep(fromLong, Direction.UP, false);
               mc.player.swingHand(Hand.MAIN_HAND);
               if (mc.world.getBlockState(fromLong).isAir()) {
                  this.forgetTemporaryCell(next);
               }
            }
         }
      }
   }

   private long getPositionStateHash(BlockPos pos) {
      return this.computeProgressSignature() ^ (pos == null ? 0L : SHARED_HASH_OPEN.hashOpenCellsInRadius(pos.getX(), pos.getY(), pos.getZ(), 3));
   }

   private long[] getPlacementFootprintCells(EyePoseData placementPose) {
      BlockPos blockPos = BlockPos.fromLong(placementPose.stand());
      BlockPos fromLong = BlockPos.fromLong(placementPose.target());
      BlockPos supportPos = BlockPos.fromLong(placementPose.hit().support());
      LinkedHashSet<Long> linkedHashSet = new LinkedHashSet<>();
      linkedHashSet.add(blockPos.down().asLong());
      linkedHashSet.add(blockPos.asLong());
      linkedHashSet.add(blockPos.up().asLong());
      linkedHashSet.add(supportPos.asLong());
      linkedHashSet.add(fromLong.asLong());

      for (Direction direction : Direction.values()) {
         linkedHashSet.add(fromLong.offset(direction).asLong());
      }

      Vec3d vec3d = new Vec3d(placementPose.eyeX(), placementPose.eyeY(), placementPose.eyeZ());
      Vec3d eyeToHitDelta = new Vec3d(placementPose.hit().x(), placementPose.hit().y(), placementPose.hit().z()).subtract(vec3d);
      int sampleCount = Math.min(64, (int)Math.ceil(eyeToHitDelta.length() / 0.1));

      for (int n = 0; n <= sampleCount; n++) {
         linkedHashSet.add(BlockPos.ofFloored(vec3d.add(eyeToHitDelta.multiply(sampleCount == 0 ? 0.0 : (double)n / sampleCount))).asLong());
      }

      long[] ls = new long[linkedHashSet.size()];
      int resultIndex = 0;

      for (long l : linkedHashSet) {
         ls[resultIndex++] = l;
      }

      return ls;
   }

   private double computeSlideDistance(double autoBuilderFactor) {
      double frictionFactor = Math.min(0.995, this.getSlipperiness() * 0.91);
      return autoBuilderFactor * frictionFactor / (1.0 - frictionFactor);
   }

   private boolean isWaterAdjacentPourCandidate(BlockPos basePos, BlockPos abovePos) {
      if (this.containsPositionSet.isEmpty()
         || abovePos.getY() != basePos.getY() + 1
         || this.schematicCells == null
         || this.targetFluidItems == null
         || mc.world == null) {
         return false;
      } else if (this.getSchematicCells(abovePos.down()) >= 0 && !this.cells.contains(abovePos.down().asLong())) {
         int schematicIndex = this.getSchematicCells(basePos);
         if (schematicIndex >= 0 && this.targetFluidItems.get(schematicIndex).getFluidState().isEmpty() && !isFlaggedBlockState(this.targetFluidItems.get(schematicIndex))) {
            boolean flag = false;

            for (Direction direction : Type.HORIZONTAL) {
               BlockPos blockPos = basePos.offset(direction);
               if (this.containsPositionSet.contains(blockPos.asLong())
                  && this.containsPositionSet.contains(blockPos.down().asLong())
                  && !mc.world.getBlockState(blockPos).getFluidState().isStill()
                  && mc.world.getBlockState(blockPos.down()).getFluidState().isStill()) {
                  flag = true;
                  break;
               }
            }

            if (!flag) {
               return false;
            } else {
               for (int n = 0; n < this.schematicCells.size(); n++) {
                  BlockPos otherSchematicPos = this.schematicCells.get(n);
                  if (otherSchematicPos.getY() <= basePos.getY()
                     && !otherSchematicPos.equals(basePos)
                     && !(this.targetFluidItems.get(n).getBlock() instanceof FluidBlock)
                     && mc.world.getBlockState(otherSchematicPos).getBlock() != this.targetFluidItems.get(n).getBlock()) {
                     return false;
                  }
               }

               return true;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

