   private boolean needsWaterPlacement(BlockPos pos) {
      BlockState blockState = this.completionMissionMap.get(pos.asLong());
      return blockState != null
         && blockState.isOf(Blocks.WATER)
         && !this.waterPositionSet.contains(pos.asLong())
         && !mc.world.getBlockState(pos).getFluidState().isStill()
         && this.canObtainItemForPlacement(getItemForBlockState(blockState))
         && this.isCellInFluidFloodSet(pos)
         && this.positionSet.contains(pos.asLong());
   }

   private void markCellReclassified(BlockPos pos) {
      if (this.reclassifiedOffsetIntegerMap.size() > 16384) {
         this.reclassifiedOffsetIntegerMap.clear();
         this.reclassifiedOffsetPositionMa.clear();
      }

      this.reclassifiedOffsetIntegerMap.put(pos.asLong(), this.moduleTick);
      this.reclassifiedOffsetPositionMa.put(pos.asLong(), System.nanoTime());
      if (this.selectReclassified != null && this.builderReclassifiedIntegerMa != null && this.schematicCells == this.layerAccessBlockPosList) {
         this.markReclassifiedDirty(pos.asLong());

         for (Direction direction : Direction.values()) {
            this.markReclassifiedDirty(pos.offset(direction).asLong());
         }
      }
   }

