   private void recordRepairFailure(BlockPos pos, String repairPathText) {
      AutoBuilder.FailReason failReason = this.parseFailReason(repairPathText);
      boolean flag = failReason == AutoBuilder.FailReason.NO_PATH_TO_STAND || failReason == AutoBuilder.FailReason.NO_PATH_TO_COLUMN;
      long[] ls = null;
      long[] expandedExhaustedCells = flag ? this.getExpandedExhausted() : null;
      String string;
      if (expandedExhaustedCells != null) {
         ls = expandedExhaustedCells;
         string = "route:component_exhausted(" + expandedExhaustedCells.length + ")";
      } else if (flag) {
         this.rebuildReachableComponent();
         ls = this.component.stream().mapToLong(Long::longValue).toArray();
         string = "route:no_path/component(" + ls.length + ")";
      } else {
         string = failReason == null ? "execution:" + repairPathText.replace(' ', '_') : "stand:" + failReason.name().toLowerCase(Locale.ROOT);
      }

      Dependency dependency = new Dependency(this.computeCellHash(pos), this.getLocalCellsHash(pos), ls);
      this.noneRepair.handle(pos.asLong(), failReason == null ? repairPathText.replace(' ', '_') : failReason.name(), string, dependency);
      com.corz.client.utils.NoneRepair.Ticket ticket = this.noneRepair.getNoneForLong(pos.asLong());
   }

   private static BlockPos toBlockPos(SupportStandUtils.Cell cell) {
      return new BlockPos(cell.x(), cell.y(), cell.z());
   }

   private boolean tryBuyTempDirt() {
      if (this.buyMaterialsFlag && this.showedBuyText == null && this.complete == AutoBuilder.BuyMode.NONE && this.getTempDirtPurchaseRequest() != null) {
         if (this.countEmptyInventorySlots() > this.spaceFreeValue && "no free inventory space".equals(this.spaceFreeMap.get(Items.DIRT))) {
            this.freeInventoryMap.remove(Items.DIRT);
         }

         Integer integer = this.freeInventoryMap.get(Items.DIRT);
         if (integer != null && this.moduleTick < integer) {
            return false;
         } else if (!this.canBuyAuto(AutoBuilder.LayerBuyTrigger.RESCUE, "out of temporary dirt")) {
            return false;
         } else {
            this.resetPillarTracking();
            return true;
         }
      } else {
         return false;
      }
   }

   private void invalidatePlacementAction(PlacementExplicit<AutoBuilder.MissionPlacement> action, String actionEgressText) {
      if (action.isPlacementMove()
         && action.owner != Owner.DECK
         && "ACTION_NO_CONFIRMATION".equals(actionEgressText)
         && this.ticksProgress.getLifetimeProgressTicks() == 0
         && this.ticksProgress.getProgressRunTicks() == 0) {
         this.recordExecutorArrivalFailure(
            BlockPos.fromLong(action.actionTargetPos), BlockPos.fromLong(action.egressActionTime), "ACTION_TIMEOUT_NO_PROGRESS"
         );
      }

      if (action.isPlacementMove()
         && action.owner != Owner.DECK
         && actionEgressText != null
         && (actionEgressText.startsWith("EXECUTOR_PROOF_INVALID") || actionEgressText.startsWith("STAND_BODY_ILLEGAL"))) {
         BlockPos blockPos = BlockPos.fromLong(action.actionTargetPos);
         BlockPos fromLong = BlockPos.fromLong(action.egressActionTime);
         int n = this.shouldCrouchForSafeSneak(fromLong, blockPos) ? 2 : 1;
         this.proofExecutor
            .canExecutorArrival(
               action.actionTargetPos,
               action.egressActionTime,
               n,
               -1,
               actionEgressText,
               this.computeNoSupportFaceKey(blockPos, fromLong),
               this.moduleTick
            );
      }

      if (action.isPlacementMove()
         && action.owner != Owner.DECK
         && ("EGRESS_CHANGED".equals(actionEgressText) || "egress: placement deferred".equals(actionEgressText))) {
         BlockPos egressStandPos = BlockPos.fromLong(action.egressActionTime);
         if (this.egressDeferredMap.size() > 4096) {
            this.egressDeferredMap.clear();
         }

         this.egressDeferredMap
            .put(
               getTimeForBlockPos(BlockPos.fromLong(action.actionTargetPos), egressStandPos),
               SHARED_HASH_OPEN.hashOpenCellsInRadius(egressStandPos.getX(), egressStandPos.getY(), egressStandPos.getZ(), 24)
            );
         this.sealsPlacementCount++;
         if (this.mountedElsewhere == null && mc.player != null && this.cells.contains(this.getFeetBlockPos().down().asLong())) {
            this.mountedElsewhere = "the stand's placement seals the builder in";
            this.mountedMountValue = this.confirms;
            this.nanoTimeMountedElsewhere = System.nanoTime();
         }
      }

      if (this.reason != null
         && this.reason.isPinnedDispatched()
         && action.isPlacementMove()
         && action.actionTargetPos == this.reason.getUnassignedMembersUnassignedMembersData()
         && !"ROI_REDIRECT".equals(actionEgressText)) {
         this.onRouteRedirectInvalidated("executor: " + actionEgressText);
      }

      if (action.owner == Owner.DECK) {
         this.deckMicroMoves.redirectRoiMap.merge(actionEgressText, 1, Integer::sum);
         FloorBuildPlanner.Pick pick = action.isPlacementMove() ? action.executorUnavailableObject.deckPick() : null;
         boolean flag = actionEgressText.startsWith("EXECUTOR_")
            || actionEgressText.startsWith("LOCAL_")
            || actionEgressText.equals("ACTION_NO_CONFIRMATION")
            || actionEgressText.equals("STAND_UNSAFE")
            || actionEgressText.equals("SUPPORT_DISAPPEARED")
            || actionEgressText.equals("EGRESS_CHANGED");
         if (flag && pick != null && mc.player != null && mc.world != null) {
            this.excludePickTarget(pick, actionEgressText);
         }
      }

      this.setBudgetExhaustedReason(actionEgressText);
      this.logDebugMessage(
         "\u00a7e[MissionAction]\u00a7r invalidated owner="
            + action.owner
            + " mission="
            + action.actionMissionTime
            + " type="
            + action.actionType
            + " target="
            + (action.isPlacementMove() ? BlockPos.fromLong(action.actionTargetPos).toShortString() : "none")
            + " stand="
            + BlockPos.fromLong(action.egressActionTime).toShortString()
            + " reason="
            + actionEgressText
      );
      this.placementExplicit = null;
      this.blockPosBlockersStep = null;
      this.reachedCoverFlag = false;
      this.deckLocalFlag = false;
      this.intervalReportBlockPos = null;
      if (action.actionType == com.corz.client.utils.PlacementExplicit.Type.MOVE_TO_SUPPORT) {
         this.arrivedSupportFlag = false;
      }

      if (this.intervalReportCertificate != null) {
         this.adjustEdge.recordEdgeAdjustResult(this.intervalAdjustCount, false);
         this.intervalReportCertificate = null;
      }

      this.intervalParityFlag = false;
      this.missionPlacement = null;
      this.actionEgressActive = false;
      if (this.droppedPlaced != null && action.isPlacementMove() && action.owner == Owner.DECK) {
         this.droppedPlaced.isRemoveIf(action.actionTargetPos);
      }
   }

