   private BlockPos findDescentStandCell(BlockPos ceilingPos, BlockPos fromPos) {
      if (mc.world == null) {
         return null;
      } else {
         this.rebuildReachableComponent();
         double d = this.reachSetting.getValue();
         String string = this.prefixSupportText("TEMP_SUPPORT");
         World world = this.createReachabilityWorldView();
         BlockPos down2 = null;
         BlockPos down3 = null;
         int value = -1;
         int elevatedHeadroom2 = -1;

         for (Direction direction : Type.HORIZONTAL) {
            BlockPos down = fromPos.offset(direction);
            if (!WalkRouteFinder.isStandable(mc.world, down) && WalkRouteFinder.isStandable(mc.world, down.down())) {
               down = down.down();
            }

            while (
               !WalkRouteFinder.isStandable(mc.world, down)
                  && fromPos.getY() - down.getY() < 8
                  && this.cells.contains(fromPos.down(fromPos.getY() - down.getY() + 1).asLong())
                  && mc.world.getBlockState(down.down()).getCollisionShape(mc.world, down.down()).isEmpty()
            ) {
               down = down.down();
            }

            if (this.isReachableWalkingCell(down) && WalkRouteFinder.isStandable(mc.world, down)) {
               boolean flag = true;

               for (int n = down.getY(); n <= ceilingPos.getY() && flag; n++) {
                  BlockPos blockPos = new BlockPos(down.getX(), n, down.getZ());
                  BlockState blockState = mc.world.getBlockState(blockPos);
                  if (!blockState.isAir() && !blockState.isReplaceable()) {
                     flag = false;
                  } else if (n < ceilingPos.getY() && this.getSchematicCells(blockPos) >= 0) {
                     flag = false;
                  }
               }

               if (flag) {
                  boolean columnsBanned = false;

                  for (int columnY = down.getY(); columnY < ceilingPos.getY() && !columnsBanned; columnY++) {
                     columnsBanned = this.canColumnsBanned(new BlockPos(down.getX(), columnY, down.getZ()));
                  }

                  if (!columnsBanned
                     && ClearanceHeadroomUtils.measureHeadroom(world, down.getX(), down.getY(), down.getZ(), ceilingPos.getY() - 1)
                        >= Math.max(0, ceilingPos.getY() - 1 - down.getY())) {
                     if (fromPos.getY() - down.getY() >= 2) {
                        BlockPos elevatedStandPos = new BlockPos(down.getX(), fromPos.getY() - 1, down.getZ());
                        int elevatedHeadroom = this.chooseTempSupportFace(fromPos, elevatedStandPos, getStandingEyePos(elevatedStandPos), d, string, false) == null
                           ? -1
                           : ClearanceHeadroomUtils.measureHeadroom(world, down.getX(), ceilingPos.getY() - 1, down.getZ(), ceilingPos.getY() + 6);
                        if (elevatedHeadroom > elevatedHeadroom2) {
                           elevatedHeadroom2 = elevatedHeadroom;
                           down3 = down;
                        }
                     } else if (this.chooseTempSupportFace(fromPos, down, getStandingEyePos(down), d, string, false) != null) {
                        int directHeadroom = ClearanceHeadroomUtils.measureHeadroom(world, down.getX(), ceilingPos.getY() - 1, down.getZ(), ceilingPos.getY() + 6);
                        if (directHeadroom > value) {
                           value = directHeadroom;
                           down2 = down;
                        }
                     }
                  }
               }
            }
         }

         if (down2 == null) {
            down2 = down3;
         }

         return down2;
      }
   }

   private Vec3d getOutlineCenter(BlockPos pos, BlockState state) {
      VoxelShape voxelShape = state.getOutlineShape(mc.world, pos);
      if (voxelShape.isEmpty()) {
         return Vec3d.ofCenter(pos);
      } else {
         Box box = voxelShape.getBoundingBox();
         return new Vec3d(
            pos.getX() + (box.minX + box.maxX) / 2.0, pos.getY() + (box.minY + box.maxY) / 2.0, pos.getZ() + (box.minZ + box.maxZ) / 2.0
         );
      }
   }

   private boolean isSelfDefeatingBoundaryPlan(PosesBoundaryUtils.Plan plan) {
      if (plan != null && plan.mission() != null && plan.boundary() != null) {
         HashSet<Long> hashSet = new HashSet<>();

         for (SupportStandUtils.Step step : plan.mission().steps()) {
            SupportStandUtils.Op op = step.op();
            if (op != SupportStandUtils.Op.WALK) {
               if (step.cell() == null) {
                  return false;
               }

               BlockPos blockPos = toBlockPos(step.cell());
               if (op == SupportStandUtils.Op.PILLAR) {
                  for (int n = 0; n < step.count(); n++) {
                     hashSet.add(blockPos.up(n).asLong());
                  }
               } else if (op != SupportStandUtils.Op.DIRT) {
                  if (op != SupportStandUtils.Op.DIG_DOWN || !hashSet.remove(blockPos.asLong())) {
                     return false;
                  }
               } else {
                  hashSet.add(blockPos.asLong());
               }
            }
         }

         if (!hashSet.isEmpty()) {
            return false;
         } else {
            BlockPos boundaryPos = toBlockPos(plan.boundary());
            if (this.isPartialHeightFloorSafe(boundaryPos) && this.isTransitionCertified(boundaryPos)) {
               this.logDebugMessage(
                  "\u00a7e[ServiceAccess]\u00a7r CONNECT refused for family "
                     + FamilyGained.formatPositionText(this.serviceAccessTime)
                     + ": boundary "
                     + boundaryPos.toShortString()
                     + " is walk-reachable and stands sunk in its floor, its eye sees no face of the cell(s) it serves and the mission digs back every block it lays - it ends where the ALREADY_CONNECTED refutation stood; "
                     + this.standProveType
                     + " is NO_CANDIDATE and the ladder advances"
               );
               return true;
            } else {
               return false;
            }
         }
      } else {
         return false;
      }
   }

