   private List<Integer> getSchematicIndicesNear(Vec3d vec, double floorSchematicFactor) {
      ArrayList<Integer> nearbyIndices = new ArrayList<>();
      if (this.schematicCells == null) {
         return nearbyIndices;
      } else {
         this.getSchematicCells(BlockPos.ORIGIN);
         if (this.schematicCellsArrayListMap == null) {
            return nearbyIndices;
         } else {
            int minX = MathHelper.floor(vec.x - floorSchematicFactor);
            int maxX = MathHelper.floor(vec.x + floorSchematicFactor);
            int minY = MathHelper.floor(vec.y - floorSchematicFactor);
            int maxY = MathHelper.floor(vec.y + floorSchematicFactor);
            int minZ = MathHelper.floor(vec.z - floorSchematicFactor);
            int maxZ = MathHelper.floor(vec.z + floorSchematicFactor);
            double radiusSquared = floorSchematicFactor * floorSchematicFactor;

            for (int chunkX = minX >> 3; chunkX <= maxX >> 3; chunkX++) {
               for (int chunkY = minY >> 3; chunkY <= maxY >> 3; chunkY++) {
                  for (int chunkZ = minZ >> 3; chunkZ <= maxZ >> 3; chunkZ++) {
                     ArrayList<Integer> arrayList = this.schematicCellsArrayListMap.get((chunkX & 16777215L) << 40 | (chunkY & 65535L) << 24 | chunkZ & 16777215L);
                     if (arrayList != null) {
                        for (int n : arrayList) {
                           if (vec.squaredDistanceTo(Vec3d.ofCenter(this.schematicCells.get(n))) <= radiusSquared) {
                              nearbyIndices.add(n);
                           }
                        }
                     }
                  }
               }
            }

            return nearbyIndices;
         }
      }
   }

