   private BlockPos findAdjacentWalkableCell(BlockPos pos) {
      boolean insideSmallOrKnownComponent = this.isInsideSmallOrKnownComponent();

      for (Direction direction : Type.HORIZONTAL) {
         BlockPos blockPos = pos.offset(direction);
         boolean flag = insideSmallOrKnownComponent || !this.cellTemporarySet.contains(blockPos.asLong()) && !this.cellTemporarySet.contains(blockPos.up().asLong());
         if (flag && WalkRouteFinder.isStandable(mc.world, blockPos)) {
            return blockPos;
         }

         BlockPos upperNeighborPos = blockPos.up();
         boolean upperAllowed = insideSmallOrKnownComponent || !this.cellTemporarySet.contains(upperNeighborPos.asLong()) && !this.cellTemporarySet.contains(upperNeighborPos.up().asLong());
         if (upperAllowed && WalkRouteFinder.isStandable(mc.world, upperNeighborPos)) {
            return upperNeighborPos;
         }
      }

      return null;
   }

