   private boolean tryTempBlockForBlockUpdate(BlockPos pos, BlockPos pos2) {
      if (this.useTemporaryBlocks.isEnabled() && this.getHotbarDirtSlot() != -1 && mc.player != null) {
         Integer lastUpdateTick = this.shortExplicitIntegerMap.get(pos2.asLong());
         if (lastUpdateTick != null && this.moduleTick - lastUpdateTick < 100) {
            return false;
         } else {
            BlockPos offset = null;
            int bestScore = Integer.MAX_VALUE;

            for (Direction direction : Direction.values()) {
               BlockPos blockPos = pos2.offset(direction);
               if (this.isFreeCellOutsidePlayer(blockPos) && this.describeObserverPulseHazard(blockPos) == null && this.formatBlockShort(blockPos) == null) {
                  Integer integer = this.shortExplicitIntegerMap.get(blockPos.asLong());
                  if (integer == null || this.moduleTick - integer >= 600) {
                     BlockState blockState = mc.world.getBlockState(blockPos.down());
                     int n = (direction.getAxis().isHorizontal() ? 0 : 10)
                        + (blockState.isSideSolidFullSquare(mc.world, blockPos.down(), Direction.UP) ? 0 : 5);
                     if (n < bestScore) {
                        bestScore = n;
                        offset = blockPos;
                     }
                  }
               }
            }

            if (offset == null) {
               return false;
            } else {
               this.shortExplicitIntegerMap.put(pos2.asLong(), this.moduleTick);
               this.shortExplicitIntegerMap.put(offset.asLong(), this.moduleTick);
               if (this.placementExplicit != null && this.placementExplicit.actionTargetPos == pos.asLong()) {
                  this.placementExplicit = null;
                  this.blockPosBlockersStep = null;
                  this.reachedCoverFlag = false;
                  this.deckLocalFlag = false;
               }

               this.logDebugMessage(
                  "\u00a7b[RedstoneSafety]\u00a7r "
                     + pos2.toShortString()
                     + " needs a block update before "
                     + pos.toShortString()
                     + " is armed - temp at "
                     + offset.toShortString()
               );
               return this.startSixWayTempSupport(pos, offset, "a block update for " + pos2.toShortString());
            }
         }
      } else {
         return false;
      }
   }

   private void tickInventorySwap() {
      this.updatePressedOptions2();
      this.setOwnerSneak(false);
      mc.player.setSprinting(false);
      if (this.staleCount >= 3 && !(mc.player.getVelocity().horizontalLengthSquared() > 1.0E-4)) {
         boolean tempRefill = this.swapEvictableItem != null;
         if (tempRefill || this.bucket != null || this.currentTargetPos != null && this.supportAccessValue >= 0 && this.supportAccessValue < this.targetFluidItems.size()
            )
          {
            Item requiredItem = tempRefill ? this.swapEvictableItem : (this.bucket != null ? this.bucket : getItemForBlockState(this.targetFluidItems.get(this.supportAccessValue)));
            if (!this.materialSwapFlag) {
               Item item = this.getSelectedMaterialItem();
               boolean flag = this.visibleInventoryGui.isEnabled() && !mc.player.getAbilities().creativeMode;
               Begin begin = this.swapEvictableStackInventoryS.getInstanceAbsent(requiredItem, this.getProtectedHotbarSlots(), this.protectSelectedSlot.isEnabled(), requiredItem, item, flag);
               if (begin == Begin.BUSY) {
                  return;
               }

               this.materialSwapFlag = true;
               String swapEvictableText = mc.player.getAbilities().creativeMode ? "creative" : "survival";
               switch (begin) {
                  case ITEM_ABSENT:
                  case TRANSACTION_REJECTED:
                     this.bucket = null;
                     if (tempRefill) {
                        this.failTempDirtRefill("item_missing");
                        return;
                     }

                     String string = begin == Begin.TRANSACTION_REJECTED ? "transaction_rollback_unchanged" : "item_missing";
                     this.deferTargetBriefly(this.currentTargetPos, string);
                     this.transitionToState(AutoBuilder.State.SELECT_TARGET, "swap: " + string);
                     return;
                  case NO_SLOT:
                     if (this.bucket != null) {
                        this.bucket = null;
                        this.transitionToState(AutoBuilder.State.SELECT_TARGET, "run stock: no free slot");
                        return;
                     }

                     if (tempRefill) {
                        this.failTempDirtRefill("no_evictable_slot");
                        return;
                     }

                     this.deferTargetBriefly(this.currentTargetPos, "no_evictable_slot");
                     this.transitionToState(AutoBuilder.State.SELECT_TARGET, "swap: no evictable slot");
                     return;
                  case STARTED:
               }
            }

            boolean onGround = mc.player.isOnGround();
            boolean falling = !onGround && mc.player.getVelocity().y < -0.08;
            Status status = this.swapEvictableStackInventoryS.getSwapWait(onGround, falling, false, false, false, false);
            if (status == Status.DONE) {
               int n = this.swapEvictableStackInventoryS.getValueDamageableSelected();
               boolean selectedSlotHasItem = n >= 0 && mc.player.getInventory().getStack(n).isOf(requiredItem);
               boolean swapConfirmed = this.swapEvictableStackInventoryS.isFlag();
               boolean verifiedSwap = selectedSlotHasItem && swapConfirmed && SelectedInventoryUtils.getValue(requiredItem) >= 0;
               if (verifiedSwap) {
                  this.selectHotbarSlot(this.bucket != null && this.selectedSlot >= 0 ? this.selectedSlot : n);
               }

               this.builderCancelledFlag = true;
               if (verifiedSwap) {
                  this.completeSwapMap.clear();
                  this.completeSwapValue = -1;
                  AutoBuilder.State state = this.state2UpcomingStock;
                  this.bucket = null;
                  this.swapEvictableItem = null;
                  this.transitionToState(state, tempRefill ? "temp refill complete - resume climb" : "swap complete");
               } else if (tempRefill) {
                  this.failTempDirtRefill("swap_unverified");
               } else {
                  this.bucket = null;
                  this.deferTargetBriefly(this.currentTargetPos, "swap_unverified");
                  this.transitionToState(AutoBuilder.State.SELECT_TARGET, "swap unverified");
               }
            } else if (status == Status.FAILED) {
               if (tempRefill) {
                  this.failTempDirtRefill("swap_" + this.swapEvictableStackInventoryS.getTimeoutUnsafeType());
                  return;
               }

               this.bucket = null;
               this.deferTargetBriefly(this.currentTargetPos, "swap_" + this.swapEvictableStackInventoryS.getTimeoutUnsafeType());
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "swap failed");
            }
         } else {
            this.swapEvictableStackInventoryS.updateSwapWait();
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "swap: target vanished");
         }
      }
   }

   private long findNearestMissingCell(BlockPos pos, int blockFluidLimit) {
      long longValue = 0L;
      double squaredDistance = Double.MAX_VALUE;

      for (int n : this.getSchematicIndicesNear(Vec3d.ofCenter(pos), blockFluidLimit * 1.74 + 0.5)) {
         BlockPos blockPos = this.schematicCells.get(n);
         if (Math.abs(blockPos.getX() - pos.getX()) <= blockFluidLimit
            && Math.abs(blockPos.getY() - pos.getY()) <= blockFluidLimit
            && Math.abs(blockPos.getZ() - pos.getZ()) <= blockFluidLimit) {
            BlockState blockState = mc.world.getBlockState(blockPos);
            if (blockState.getBlock() != this.targetFluidItems.get(n).getBlock()
               && !areBlocksEquivalentVariants(this.targetFluidItems.get(n), blockState)
               && (blockState.isAir() || blockState.isReplaceable())) {
               Integer integer = this.cooldown.get(blockPos.asLong());
               if (integer == null || this.moduleTick >= integer) {
                  double d = blockPos.getSquaredDistance(pos);
                  if (d < squaredDistance) {
                     squaredDistance = d;
                     longValue = blockPos.asLong();
                  }
               }
            }
         }
      }

      return longValue;
   }

   private boolean isSafeDropAboveFullCube(BlockPos pos) {
      if (mc.world.getBlockState(pos).isAir()
         && mc.world.getBlockState(pos.up()).isAir()
         && this.getSchematicCells(pos) < 0
         && this.getSchematicCells(pos.up()) < 0) {
         for (int n = 1; n <= 8; n++) {
            BlockPos blockPos = pos.down(n);
            if (!mc.world.getBlockState(blockPos).isAir()
               || this.getSchematicCells(blockPos) >= 0
               || this.cellTemporarySet.contains(blockPos.asLong())) {
               return false;
            }

            BlockPos floorPos = blockPos.down();
            if (!mc.world.getBlockState(floorPos).getCollisionShape(mc.world, floorPos).isEmpty()) {
               return Block.isShapeFullCube(mc.world.getBlockState(floorPos).getCollisionShape(mc.world, floorPos));
            }
         }

         return false;
      } else {
         return false;
      }
   }

