   private boolean startFloatingCellSideSeed(BlockPos longValue, BlockPos offset) {
      if (this.epoch == this.eventsFamilies.getFamiliesEpochTime()) {
         this.facelessSeedValue = this.moduleTick;
         return false;
      } else if (this.churnRefunds.canMax(abcdefghjkmnpqrstuvwxyzSeedTime, longValue.asLong(), this.moduleTick)) {
         this.facelessSeedValue = this.moduleTick;
         return false;
      } else {
         int n = this.maxLiveTempBlocks.getValue();
         int currentTempCount = this.countTempTowerCells();
         if (currentTempCount + 1 > n) {
            this.canRecycleDebtOnce(currentTempCount);
            if (this.state2Builder == AutoBuilder.State.CLEANUP_TEMP) {
               return true;
            }

            if (this.countTempTowerCells() + 1 > n) {
               return false;
            }
         }

         this.islandHandover.put(longValue.asLong(), this.moduleTick);
         this.islandHandoverMap.merge(longValue.asLong(), 1, Integer::sum);
         this.supportFloorMap.put(offset.asLong(), longValue.asLong());
         this.blockPos3SupportConstructive = offset;
         this.blockPos2SupportConstructive = longValue;
         this.supportFloorValue = 0;
         this.name = "SUPPORT_FLOOR";
         this.currentTargetPos = longValue;
         this.supportAccessValue = this.getSchematicCells(longValue);
         this.updatePlacementRecipeForTarget(longValue, this.targetFluidItems.get(this.supportAccessValue));
         this.setSupportText("TEMP_SUPPORT", "side seed " + longValue.toShortString());
         this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.SUPPORT, 1);
         this.transitionToState(AutoBuilder.State.TEMP_SUPPORT, "floating cell side seed");
         return true;
      }
   }

   private void readmitCooledDownCells(String reachableStandText) {
      if (!this.cooldown.isEmpty()) {
         long activeComponentKey = this.getActiveComponentKey();
         int n = 0;
         if (!this.proofLayerMap.isEmpty()) {
            Iterator<Entry<Long, long[]>> iterator = this.proofLayerMap.entrySet().iterator();

            while (iterator.hasNext()) {
               Entry<Long, long[]> entry = iterator.next();
               long l = entry.getKey();
               if (!this.cooldown.containsKey(l)) {
                  iterator.remove();
                  this.standReachable.handleReadmittedStamps(l);
               } else {
                  BlockPos blockPos = BlockPos.fromLong(l);
                  com.corz.client.utils.StandReachable.Verdict verdict = StandReachable.getReadmitFloor(
                     new Stamp(0, entry.getValue()[0], entry.getValue()[1], FailureKind.ACCESS), this.moduleTick, 160, activeComponentKey, this.hashPosVariantEight(blockPos)
                  );
                  if (this.sessionActive
                     || verdict == com.corz.client.utils.StandReachable.Verdict.READMIT_TOPOLOGY_CHANGED
                     || verdict == com.corz.client.utils.StandReachable.Verdict.READMIT_GEOMETRY_CHANGED) {
                     iterator.remove();
                     this.cooldown.remove(l);
                     this.layerPlanMap.remove(l);
                     this.standReachable.handleReadmittedStamps(l);
                     n++;
                  }
               }
            }
         }

         if (this.standReachable.getReadmittedStamps() > 0) {
            Iterator<Entry<Long, Integer>> cooldownIterator = this.cooldown.entrySet().iterator();

            while (cooldownIterator.hasNext()) {
               Entry<Long, Integer> cooldownEntry = cooldownIterator.next();
               if (!this.proofLayerMap.containsKey(cooldownEntry.getKey()) && this.standReachable.isContainsKey(cooldownEntry.getKey())) {
                  BlockPos fromLong = BlockPos.fromLong(cooldownEntry.getKey());
                  Stamp stamp = this.standReachable.getReadmittedStamps(cooldownEntry.getKey());
                  com.corz.client.utils.StandReachable.Verdict readmittedStamps = this.standReachable
                     .getReadmittedStamps(cooldownEntry.getKey(), this.moduleTick, 160, activeComponentKey, this.hashPosVariantEight(fromLong));
                  boolean flag = readmittedStamps == com.corz.client.utils.StandReachable.Verdict.READMIT_GEOMETRY_CHANGED
                     || readmittedStamps == com.corz.client.utils.StandReachable.Verdict.READMIT_TOPOLOGY_CHANGED && stamp != null && stamp.kind() == FailureKind.ACCESS;
                  if (flag) {
                     cooldownIterator.remove();
                     this.layerPlanMap.remove(cooldownEntry.getKey());
                     this.standReachable.handleReadmittedStamps(cooldownEntry.getKey());
                     n++;
                  }
               }
            }
         }

         if (n > 0) {
            this.watchdogAdmitValue += n;
            this.handleWakeRev("readmit:" + reachableStandText);
         }
      }
   }

   private boolean isCellFarFromPowerSources(BlockPos pos) {
      if (this.schematicCells != null && this.targetFluidItems != null) {
         if (this.containsCachedCells != this.schematicCells) {
            this.containsCachedCells = this.schematicCells;
            this.containsCachedPositions.clear();
            HashSet<Long> hashSet = new HashSet<>();

            for (int n = 0; n < this.schematicCells.size(); n++) {
               BlockState blockState = this.targetFluidItems.get(n);
               if (isRedstoneRelevantBlock(blockState)) {
                  hashSet.add(this.schematicCells.get(n).asLong());
               }
            }

            for (int cellIndex = 0; cellIndex < this.schematicCells.size(); cellIndex++) {
               BlockState candidateState = this.targetFluidItems.get(cellIndex);
               if (!isRedstoneRelevantBlock(candidateState) && !hasFluidState(candidateState)) {
                  BlockPos blockPos = this.schematicCells.get(cellIndex);
                  boolean flag = false;

                  for (int deltaX = -3; deltaX <= 3 && !flag; deltaX++) {
                     for (int deltaY = -3; deltaY <= 3 && !flag; deltaY++) {
                        for (int deltaZ = -3; deltaZ <= 3; deltaZ++) {
                           if (hashSet.contains(BlockPos.asLong(blockPos.getX() + deltaX, blockPos.getY() + deltaY, blockPos.getZ() + deltaZ))) {
                              flag = true;
                              break;
                           }
                        }
                     }
                  }

                  if (!flag) {
                     this.containsCachedPositions.add(blockPos.asLong());
                  }
               }
            }
         }

         return this.containsCachedPositions.contains(pos.asLong());
      } else {
         return false;
      }
   }

