   private boolean shouldRefuseBoundaryPlan(PosesBoundaryUtils.Plan plan) {
      if (this.isSelfDefeatingBoundaryPlan(plan)) {
         return true;
      } else if (mc.world != null
         && mc.player != null
         && this.targetFluidItems != null
         && plan != null
         && plan.mission() != null
         && plan.boundary() != null
         && plan.why().contains("future-stand boundary")) {
         BlockPos boundaryPos = toBlockPos(plan.boundary());
         final HashSet<Long> hashSet = new HashSet<>();
         final HashSet<Long> removedCells = new HashSet<>();
         int digExitY = Integer.MIN_VALUE;

         for (SupportStandUtils.Step step : plan.mission().steps()) {
            if (step.cell() != null) {
               BlockPos blockPos = toBlockPos(step.cell());
               if (step.op() == SupportStandUtils.Op.PILLAR) {
                  for (int n = 0; n < step.count(); n++) {
                     hashSet.add(blockPos.up(n).asLong());
                     removedCells.remove(blockPos.up(n).asLong());
                  }
               } else if (step.op() == SupportStandUtils.Op.DIRT) {
                  hashSet.add(blockPos.asLong());
                  removedCells.remove(blockPos.asLong());
               } else if (step.op() == SupportStandUtils.Op.DIG_DOWN) {
                  removedCells.add(blockPos.asLong());
                  hashSet.remove(blockPos.asLong());
                  digExitY = blockPos.getY() + 1;
               }
            }
         }

         if (digExitY != Integer.MIN_VALUE && boundaryPos.getY() < digExitY) {
            final HashMap<Long, BlockState> hashMap = new HashMap<>();
            int reachRadius = (int)Math.ceil(this.reachSetting.getValue());
            double effectiveReach = Math.max(1.0, this.reachSetting.getValue() - 0.6);
            double standEyeX = boundaryPos.getX() + 0.5;
            double standEyeY = boundaryPos.getY() + 1.62;
            double standEyeZ = boundaryPos.getZ() + 0.5;

            for (long l : this.serviceBuiltItems.isEmpty() ? this.lapsesRetriedItems : this.serviceBuiltItems) {
               BlockPos fromLong = BlockPos.fromLong(l);
               int schematicIndex = this.getSchematicCells(fromLong);
               if (schematicIndex >= 0
                  && this.completionMissionMap.containsKey(l)
                  && !fromLong.equals(boundaryPos)
                  && !fromLong.equals(boundaryPos.up())
                  && Math.abs(fromLong.getX() - boundaryPos.getX()) <= reachRadius
                  && Math.abs(fromLong.getZ() - boundaryPos.getZ()) <= reachRadius
                  && boundaryPos.getY() >= fromLong.getY() - 3
                  && boundaryPos.getY() <= fromLong.getY() + 2) {
                  double d = standEyeX - (fromLong.getX() + 0.5);
                  double deltaY = standEyeY - (fromLong.getY() + 0.5);
                  double deltaZ = standEyeZ - (fromLong.getZ() + 0.5);
                  if (d * d + deltaY * deltaY + deltaZ * deltaZ <= effectiveReach * effectiveReach) {
                     hashMap.put(l, this.targetFluidItems.get(schematicIndex));
                  }
               }
            }

            final Terrain terrain = WalkRouteFinder.createTerrainView(mc.world);
            Terrain plannedTerrain = new Terrain() {
               @Override
               public boolean canStandOn(int mutableValue, int candidateY, int candidateZ) {
                  long candidateKey = BlockPos.asLong(mutableValue, candidateY, candidateZ);
                  if (removedCells.contains(candidateKey)) {
                     return false;
                  } else if (hashSet.contains(candidateKey)) {
                     return true;
                  } else {
                     BlockState hashmap = hashMap.get(candidateKey);
                     return hashmap == null
                        ? terrain.canStandOn(mutableValue, candidateY, candidateZ)
                        : !WalkRouteFinder.isBambooOrDoor(hashmap)
                           && (!WalkRouteFinder.isHazardBlock(hashmap) || !hashmap.getFluidState().isEmpty())
                           && (!WalkRouteFinder.isPartialHeightBlock(hashmap) || hashmap.getBlock() instanceof HopperBlock)
                           && this.solid(mutableValue, candidateY, candidateZ);
                  }
               }

               @Override
               public boolean solid(int candidateX, int candidateY, int candidateZ) {
                  long candidateKey = BlockPos.asLong(candidateX, candidateY, candidateZ);
                  if (removedCells.contains(candidateKey)) {
                     return false;
                  } else if (hashSet.contains(candidateKey)) {
                     return true;
                  } else {
                     BlockState plannedState = hashMap.get(candidateKey);
                     return plannedState == null
                        ? terrain.solid(candidateX, candidateY, candidateZ)
                        : WalkRouteFinder.isHazardBlock(plannedState)
                           || WalkRouteFinder.isPartialHeightBlock(plannedState)
                           || !plannedState.getCollisionShape(Module.mc.world, new BlockPos(candidateX, candidateY, candidateZ)).isEmpty();
                  }
               }
            };
            if (!WalkableRegionAnalyzer.canStandAt(plannedTerrain, boundaryPos.getX(), boundaryPos.getY(), boundaryPos.getZ())) {
               return false;
            } else {
               BlockPos feetBlockPos = this.getFeetBlockPos();
               int reachableCellLimit = 40;
               int currentReachableCells = WalkableRegionAnalyzer.countReachableCells(terrain, feetBlockPos.getX(), feetBlockPos.getY(), feetBlockPos.getZ(), reachableCellLimit);
               int plannedReachableCells = WalkableRegionAnalyzer.countReachableCells(plannedTerrain, boundaryPos.getX(), boundaryPos.getY(), boundaryPos.getZ(), reachableCellLimit);
               boolean flag = currentReachableCells < reachableCellLimit ? plannedReachableCells < currentReachableCells && plannedReachableCells <= 12 : plannedReachableCells < reachableCellLimit;
               if (flag) {
                  this.logDebugMessage(
                     "\u00a7e[ServiceAccess]\u00a7r CONNECT refused for family "
                        + FamilyGained.formatPositionText(this.serviceAccessTime)
                        + ": future-stand boundary "
                        + boundaryPos.toShortString()
                        + " is reached by digging down an own column (from y="
                        + digExitY
                        + ") and with "
                        + hashMap.size()
                        + " served member(s) placed the body's component there is "
                        + plannedReachableCells
                        + " cell(s) (from "
                        + currentReachableCells
                        + ") - a pocket with no way back; "
                        + this.standProveType
                        + " is NO_CANDIDATE and the ladder advances"
                  );
               }

               return flag;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

   private boolean isRepairAlreadyHandled(long repairNoneValue) {
      BlockPos blockPos = BlockPos.fromLong(repairNoneValue);
      return this.noneRepair.canDispatchedCompleted(repairNoneValue, this.computeCellHash(blockPos), () -> this.getLocalCellsHash(blockPos), this.getFeetBlockPos().asLong());
   }

   private void retryPlacementOnSameFace(BlockPos pos, Direction face) {
      if (pos != null && face != null && this.schematicCells != null && this.targetFluidItems != null) {
         BlockPos retryTargetPos = pos.offset(face);
         int n = this.getSchematicCells(retryTargetPos);
         if (n >= 0 && n < this.targetFluidItems.size()) {
            this.currentTargetPos = retryTargetPos;
            this.supportAccessValue = n;
            this.blockHitResultEgressStand = null;
            this.sideRunValue = 0;
            this.standRouteCount = 0;
            this.partnerClickFlag = false;
            this.sneakEgressFlag = false;
            this.sneakOwner = AutoBuilder.SneakOwner.NONE;
            this.discoveryConcreteFlag = isPlaceableWithoutSpecialSneak(this.targetFluidItems.get(n));
            this.solverUnavailableDirection = null;
            this.blockHitResult = null;
            this.resetCameraPredictionTimes();
            this.updatePlacementRecipeForTarget(retryTargetPos, this.targetFluidItems.get(n));
            this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "retry sneak placement on the same face (long hold)");
         }
      }
   }

   private void placeScaffoldingBase(int scaffoldScaffoldingValue) {
      ClientWorld clientWorld = mc.world;
      BlockPos feetBlockPos = this.getFeetBlockPos();
      if (this.columnDirtY == Integer.MIN_VALUE) {
         this.columnDirtY = feetBlockPos.getY();
         this.columnDirtX = feetBlockPos.getX();
         this.columnDirtZ = feetBlockPos.getZ();
         this.columnDirtValue = feetBlockPos.getY() - 1;
      }

      BlockPos scaffoldBasePos = new BlockPos(this.columnDirtX, this.columnDirtY, this.columnDirtZ);
      if (this.cellTemporarySet.contains(scaffoldBasePos.asLong())) {
         this.resetPillarTracking();
         this.handleBlockDefer("scaffold base is a schematic cell");
      } else {
         Vec3d playerPos = mc.player.getEntityPos();
         int scaffoldTopY = Integer.MIN_VALUE;

         for (int n = this.columnDirtY; n <= this.columnDirtY + this.maxVerticalAccess.getValue(); n++) {
            if (clientWorld.getBlockState(new BlockPos(this.columnDirtX, n, this.columnDirtZ)).getBlock() == Blocks.SCAFFOLDING) {
               scaffoldTopY = n;
            } else if (scaffoldTopY != Integer.MIN_VALUE) {
               break;
            }
         }

         double d = this.columnDirtX + 0.5 - playerPos.x;
         double zOffset = this.columnDirtZ + 0.5 - playerPos.z;
         double horizontalDistance = Math.sqrt(d * d + zOffset * zOffset);
         this.setOwnerSneak(false);
         mc.player.setSprinting(false);
         mc.options.backKey.setPressed(false);
         mc.options.leftKey.setPressed(false);
         mc.options.rightKey.setPressed(false);
         if (horizontalDistance > 0.2) {
            this.adjustPitchTowardTarget((float)Math.toDegrees(Math.atan2(-d, zOffset)));
            mc.options.forwardKey.setPressed(true);
         } else {
            mc.options.forwardKey.setPressed(false);
         }

         if (scaffoldTopY == Integer.MIN_VALUE) {
            mc.options.jumpKey.setPressed(false);
            BlockPos blockPos = scaffoldBasePos.down();
            BlockState blockState = clientWorld.getBlockState(blockPos);
            if (!blockState.isAir() && !blockState.isReplaceable()) {
               if (blockState.getBlock() == Blocks.SCAFFOLDING) {
                  this.banColumnForReason(scaffoldBasePos, "floor is scaffolding - item auto-advance is unpredictable");
                  this.updatePressedOptions2();
                  this.resetPillarTracking();
                  this.handleBlockDefer("scaffold-on-scaffold column banned");
               } else {
                  Vec3d vec3d = new Vec3d(blockPos.getX() + 0.5, blockPos.getY() + 1.0, blockPos.getZ() + 0.5);
                  float[] fs = MathClampUtils.getWrapDegrees(mc.player.getEyePos(), vec3d);
                  float[] adjustedRotation = this.computeAimRotation(fs[0], fs[1]);
                  BlockHitResult blockHitResult = this.raycastBlockSideForAim(mc.player.getEyePos(), adjustedRotation[0], adjustedRotation[1], this.reachSetting.getValue());
                  if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                     && blockHitResult.getBlockPos().equals(blockPos)
                     && blockHitResult.getSide() == Direction.UP) {
                     if (this.moduleTick - this.scaffoldingScaffoldValue >= 10) {
                        if (this.scaffoldScaffoldingValue > 0 && this.isNextToForeignScaffolding(scaffoldBasePos)) {
                           this.banColumnForReason(scaffoldBasePos, "scaffold item auto-advanced (misplaced) - scaffolding DISABLED this session");
                           this.updatePressedOptions2();
                           this.resetPillarTracking();
                           this.scaffoldScaffoldingValue = 0;
                           this.handleBlockDefer("scaffolding unreliable - falling back to solid temp blocks");
                        } else if (++this.scaffoldScaffoldingValue > 4) {
                           this.banColumnForReason(scaffoldBasePos, "base placement never confirmed (" + this.scaffoldScaffoldingValue + " tries)");
                           this.updatePressedOptions2();
                           this.resetPillarTracking();
                           this.scaffoldScaffoldingValue = 0;
                           this.handleBlockDefer("scaffold base won't place - column banned");
                        } else if (isFlaggedBlockState(blockState)) {
                           this.banColumnForReason(scaffoldBasePos, "floor is a container - scaffold base would open it");
                           this.updatePressedOptions2();
                           this.resetPillarTracking();
                           this.scaffoldScaffoldingValue = 0;
                           this.handleBlockDefer("scaffold base on a container floor - column banned");
                        } else {
                           this.selectHotbarSlot(scaffoldScaffoldingValue);
                           this.recordHitForCurrentTarget(blockHitResult);
                           this.performBlockInteraction(blockHitResult);
                           mc.player.swingHand(Hand.MAIN_HAND);
                           this.scaffoldingScaffoldValue = this.moduleTick;
                           if (clientWorld.getBlockState(scaffoldBasePos).getBlock() == Blocks.SCAFFOLDING) {
                              if (this.confirmTemporaryDirtPlacement(scaffoldBasePos)) {
                                 this.tempPlaced++;
                              }

                              this.scaffoldScaffoldingValue = 0;
                           }
                        }
                     }
                  }
               }
            } else {
               this.resetPillarTracking();
               this.handleBlockDefer("no floor under scaffold column");
            }
         } else {
            this.scaffoldScaffoldingValue = 0;
            boolean flag = horizontalDistance < 0.35;
            this.runGapRoute(flag);
         }
      }
   }

   private boolean runIslandChainStep() {
      if (this.islandAbort != 0L && mc.player != null && mc.world != null && this.schematicCells != null) {
         BlockPos fromLong = BlockPos.fromLong(this.islandAbort);
         BlockPos feetBlockPos = this.getFeetBlockPos();
         if (this.longIslandSeed == 0L) {
            this.onIslandAborted("no stand column");
            return false;
         } else if (this.islandExitCandidate != null) {
            this.transitionToState(AutoBuilder.State.ISLAND_MIGRATE, "island stand migration in progress");
            return true;
         } else {
            BlockPos islandColumnPos = BlockPos.fromLong(this.longIslandSeed);
            if (feetBlockPos.getX() == islandColumnPos.getX() && feetBlockPos.getZ() == islandColumnPos.getZ()) {
               if (this.longAirborneChain != 0L) {
                  BlockPos blockPos = BlockPos.fromLong(this.longAirborneChain);
                  int n = this.getSchematicCells(blockPos);
                  if (n >= 0 && mc.world.getBlockState(blockPos).getBlock() == this.targetFluidItems.get(n).getBlock()) {
                     this.workRowCount++;
                     this.airborneChainCount = 0;
                     this.airborneChainFromPos = 0L;
                     this.airborneChainRepeatCount = 0;
                  }

                  this.longAirborneChain = 0L;
               }

               Vec3d eyePos = mc.player.getEyePos();
               double reachDistance = this.reachSetting.getValue();
               double reachDistanceSquared = reachDistance * reachDistance;
               int upperSearchY = fromLong.getY() + 6;
               boolean hasHeadroom = ClearanceHeadroomUtils.formatClearanceHeadroom(this.createReachabilityWorldView(), feetBlockPos.getX(), feetBlockPos.getY(), feetBlockPos.getZ(), upperSearchY)
                     == null
                  && !this.canColumnsBanned(feetBlockPos);
               int y = Integer.MAX_VALUE;

               for (int schematicIndex = 0; schematicIndex < this.schematicCells.size(); schematicIndex++) {
                  BlockPos missingCellPos = this.schematicCells.get(schematicIndex);
                  if (missingCellPos.getY() < y
                     && missingCellPos.getY() >= fromLong.getY()
                     && missingCellPos.getY() <= upperSearchY + 2
                     && this.isInsideTemporaryRegion(missingCellPos)
                     && this.cooldown.getOrDefault(missingCellPos.asLong(), 0) <= this.moduleTick) {
                     BlockState blockState = this.targetFluidItems.get(schematicIndex);
                     BlockState worldState = mc.world.getBlockState(missingCellPos);
                     if (worldState.getBlock() != blockState.getBlock()
                        && (worldState.isAir() || worldState.isReplaceable())
                        && !hasFluidState(blockState)
                        && !isFlaggedBlockState(blockState)
                        && !this.isCellBlockedByTemporaryNeighbors(missingCellPos)
                        && this.hasSolidNeighborToPlaceOn(missingCellPos)
                        && this.canObtainItemForPlacement(getItemForBlockState(blockState))) {
                        y = missingCellPos.getY();
                     }
                  }
               }

               BlockPos possibleStandPos = y == Integer.MAX_VALUE ? null : new BlockPos(feetBlockPos.getX(), y, feetBlockPos.getZ());
               boolean hasBuiltNeighbor = false;
               if (possibleStandPos != null
                  && this.getSchematicCells(possibleStandPos) < 0
                  && mc.world.getBlockState(possibleStandPos).getCollisionShape(mc.world, possibleStandPos).isEmpty()) {
                  for (int[] ns : new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                     BlockPos neighborPos = possibleStandPos.add(ns[0], 0, ns[1]);
                     int neighborIndex = this.getSchematicCells(neighborPos);
                     if (neighborIndex >= 0 && mc.world.getBlockState(neighborPos).getBlock() == this.targetFluidItems.get(neighborIndex).getBlock()) {
                        hasBuiltNeighbor = true;
                        break;
                     }
                  }
               }

               BlockPos chosenTargetPos = null;
               int chosenTargetIndex = -1;
               double distanceTo = Double.MAX_VALUE;
               BlockPos higherTargetPos = null;
               int higherTargetY = Integer.MAX_VALUE;

               for (int candidateIndex = 0; candidateIndex < this.schematicCells.size(); candidateIndex++) {
                  BlockPos candidateTargetPos = this.schematicCells.get(candidateIndex);
                  if (ClearanceHeadroomUtils.isWithinHeadroomBoundsStrict(
                        feetBlockPos.getX(), feetBlockPos.getY(), feetBlockPos.getZ(), candidateTargetPos.getX(), candidateTargetPos.getY(), candidateTargetPos.getZ(), hasHeadroom
                     )
                     && this.isInsideTemporaryRegion(candidateTargetPos)
                     && this.cooldown.getOrDefault(candidateTargetPos.asLong(), 0) <= this.moduleTick
                     && this.bannedStandPairs.getOrDefault(getTimeForBlockPos(candidateTargetPos, feetBlockPos), 0) <= this.moduleTick
                     && (!this.hasFluidNearBelowCell(candidateTargetPos) || this.isPositionStalled(candidateTargetPos))) {
                     BlockState targetState = this.targetFluidItems.get(candidateIndex);
                     BlockState candidateWorldState = mc.world.getBlockState(candidateTargetPos);
                     if (candidateWorldState.getBlock() != targetState.getBlock()
                        && (candidateWorldState.isAir() || candidateWorldState.isReplaceable())
                        && !hasFluidState(targetState)
                        && !isFlaggedBlockState(targetState)
                        && this.hasSolidNeighborToPlaceOn(candidateTargetPos)
                        && !this.isCellBlockedByTemporaryNeighbors(candidateTargetPos)
                        && this.canObtainItemForPlacement(getItemForBlockState(targetState))) {
                        Vec3d vec3d = this.getAimPointForSneakState(feetBlockPos, candidateTargetPos, eyePos, true);
                        double distanceSquared = vec3d.squaredDistanceTo(Vec3d.ofCenter(candidateTargetPos));
                        if (candidateTargetPos.getY() == y
                           && distanceSquared <= reachDistanceSquared
                           && this.canPlaceFromEyePosition(candidateTargetPos, targetState, vec3d, reachDistance, this.shouldCrouchForSafeSneak(feetBlockPos, candidateTargetPos))
                           && !this.isAirborneChainRepeated(candidateTargetPos, feetBlockPos)) {
                           double d = possibleStandPos != null && Math.abs(candidateTargetPos.getX() - possibleStandPos.getX()) + Math.abs(candidateTargetPos.getZ() - possibleStandPos.getZ()) == 1
                              ? distanceSquared - 1000000.0
                              : distanceSquared;
                           if (d < distanceTo) {
                              distanceTo = d;
                              chosenTargetPos = candidateTargetPos;
                              chosenTargetIndex = candidateIndex;
                           }
                        } else if (y >= feetBlockPos.getY() + 2
                           && candidateTargetPos.getY() >= feetBlockPos.getY() + 2
                           && (candidateTargetPos.getX() != feetBlockPos.getX() || candidateTargetPos.getZ() != feetBlockPos.getZ())
                           && Math.max(Math.abs(candidateTargetPos.getX() - feetBlockPos.getX()), Math.abs(candidateTargetPos.getZ() - feetBlockPos.getZ())) <= 2
                           && candidateTargetPos.getY() < higherTargetY) {
                           higherTargetY = candidateTargetPos.getY();
                           higherTargetPos = candidateTargetPos;
                        }
                     }
                  }
               }

               if (chosenTargetPos != null) {
                  if (this.canNone(chosenTargetPos, feetBlockPos)) {
                     return this.parkIslandAndCheckExit("EGRESS_DEFERRED " + chosenTargetPos.toShortString() + " from " + feetBlockPos.toShortString());
                  } else {
                     this.setTransferTarget(chosenTargetPos, "island_chain");
                     if (this.canPlanContinuation(chosenTargetPos, chosenTargetIndex, this.targetFluidItems.get(chosenTargetIndex))) {
                        this.airborneChainValue = 0;
                        this.chainIslandValue++;
                        this.longAirborneChain = chosenTargetPos.asLong();
                        this.trackAirborneChainRepeat(chosenTargetPos, feetBlockPos);
                        return true;
                     } else {
                        return ++this.airborneChainValue > 60
                           ? this.parkIslandAndCheckExit("COMMIT_REFUSED " + this.airborneChainValue + " passes at " + chosenTargetPos.toShortString())
                           : true;
                     }
                  }
               } else if (higherTargetPos != null && this.tryRaiseStandOnIslandSeed(higherTargetPos, fromLong.getY() + 6)) {
                  return true;
               } else if (higherTargetPos != null && "airborne".equals(this.airborne)) {
                  return true;
               } else if (higherTargetPos != null && ClearanceHeadroomUtils.canClearanceRaise(this.airborne)) {
                  boolean flag = "feet_is_schematic".equals(this.airborne);
                  return this.startIslandStandMigration(fromLong, feetBlockPos, upperSearchY, flag ? "feet_cell_is_schematic" : this.airborne, flag ? feetBlockPos : feetBlockPos.up());
               } else if (higherTargetPos == null) {
                  if (this.countMissingBlocksNearIsland() == 0) {
                     return this.completeIslandMission();
                  } else {
                     return y != Integer.MAX_VALUE && this.workRowCount >= 2 && this.deckMode.isEnabled() && hasBuiltNeighbor
                        ? this.handIslandToDeck("layer " + y + " frontier out of reach after " + this.workRowCount + " chained cell(s)")
                        : this.startIslandStandMigration(fromLong, feetBlockPos, upperSearchY, "no_work_in_reach", feetBlockPos);
                  }
               } else {
                  return higherTargetPos != null && "at_owner_row".equals(this.airborne)
                     ? this.startIslandStandMigration(fromLong, feetBlockPos, upperSearchY, "rise_cap", feetBlockPos.up())
                     : this.parkIslandAndCheckExit("RAISE_REFUSED_" + this.airborne.toUpperCase(Locale.ROOT) + " at " + feetBlockPos.toShortString());
               }
            } else {
               this.onIslandAborted("body left the stand column");
               return false;
            }
         }
      } else {
         return false;
      }
   }

   private void resolveAccessMission(boolean declaredAccessFlag, String declaredAccessText) {
      if (this.supersededByNewMission) {
         long l = this.supersededMissionTime;
         long ownerKey = this.supersededUnknownValue;
         com.corz.client.utils.DescentReusable.Kind kind = this.descentStairType;
         int n = this.moduleTick - this.declaredProgressValue;
         BlockPos blockPos = BlockPos.fromLong(ownerKey);
         this.updateSupersededMission();
         int targetIndex = this.getSchematicCells(blockPos);
         if (!declaredAccessFlag && targetIndex >= 0 && this.isPlacedStateAcceptable(blockPos, this.targetFluidItems.get(targetIndex))) {
            declaredAccessFlag = true;
         }

         if (declaredAccessFlag) {
            this.islandCompoundText = "access mission " + l + " (" + kind + ") confirmed owner " + blockPos.toShortString();
         } else {
            this.blockDeferCount++;
            int failureCount = this.deferCount.merge(ownerKey, 1, Integer::sum);
            int cooldownUntilTick = this.moduleTick + (160 << Math.min(failureCount - 1, 6));
            this.setCellCooldown(ownerKey, Math.max(this.cooldown.getOrDefault(ownerKey, 0), cooldownUntilTick));
            if (ProgressDeclaredUtils.canProgressSupersed(declaredAccessText)) {
               this.handleGeometryEmergency(blockPos, "access reached but no declared target progressed");
               this.banAccessFamilyKind(getDescentKindPriority(kind), this.getLowestCellForMission(l, blockPos), blockPos, declaredAccessText);
            }

            if (this.unknown != null && this.unknown.getReusableDescentTime() == l) {
               this.releaseSupersededOwnerTemp(this.unknown, "access proof failed: " + declaredAccessText);
            }

            this.logDebugMessage(
               "\u00a7e[AccessResult]\u00a7r failed mission="
                  + l
                  + " kind="
                  + kind
                  + " target="
                  + blockPos.toShortString()
                  + " reason="
                  + declaredAccessText
                  + " - parked until relevant geometry changes; continuing other work"
            );
            if (this.currentTargetPos != null && this.currentTargetPos.asLong() == ownerKey) {
               this.updatePressedOptions2();
               this.path.clear();
               this.resetPillarTracking();
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "access mission produced no declared work");
            }
         }
      }
   }

   private void updateNodePathJumpKey() {
      if (mc.player == null) {
         this.nodePathActive = false;
      } else if (this.builderFlag) {
         this.nodePathRecoveryNone.updateFlagRecovery();
      } else {
         boolean flag = this.nodePathRecoveryNone.isAboveHead();
         if (this.nodePathRecoveryNone.isFlagNoneNoneActive()) {
            this.nodePathUpdateCount++;
            if (!this.path.isEmpty() && this.indexNodeTransition > 0 && this.indexNodeTransition < this.path.size()) {
               long l = this.path.get(this.indexNodeTransition - 1).asLong();
               long nextNodeKey = this.path.get(this.indexNodeTransition).asLong();
               if (this.nodeTransitionVetoUntil.canVetoUntil(l, nextNodeKey, this.transition.ordinal(), this.moduleTick)) {
                  this.repeatedlyRoutingActive = true;
               }
            }
         }

         boolean jumpStarted = flag && !this.nodePathActive;
         if (jumpStarted) {
            this.sinceTicksValue = this.moduleTick;
            this.nodePathCount++;
         }

         ElytraAutoUtils.handleRawPressed(mc.options.jumpKey, flag);
         this.nodePathActive = flag;
         this.nodePathRecoveryNone.updateFlagRecovery();
      }
   }

   private void clearBlueprintCachesIfLarge() {
      if (this.blueprintPositionMap.size() > 512) {
         this.blueprintPositionMap.clear();
         this.blueprintSet.clear();
         this.blueprintPositionSet.clear();
      }
   }

   private void playCompletionSound() {
      if (mc.player != null) {
         mc.player.playSound(soundEvent, (float)this.completionSoundVolume.getValue(), 1.0F);
      }
   }

   private void pageAuctionListings() {
      if (!this.isBuyAutoScreenSynced()) {
         this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SEARCH, "board lost while paging");
      } else if (this.moduleTick - this.deliveryAwaitingValue >= this.searchDialogValue) {
         int n = this.findNextPageSlotIndex();
         int boardContentsHash = this.hashOpenContainerContents();
         if (n >= 0
            && this.complete == AutoBuilder.BuyMode.BUY
            && this.pageListingValue == 0
            && this.listingWordingValue + 1 >= this.maxAhPages.getValue()
            && boardContentsHash == this.boardListingValue) {
            if (this.moduleTick - this.deliveryAwaitingValue < 40) {
               return;
            }

            n = -1;
         }

         this.boardListingValue = boardContentsHash;
         if (n >= 0) {
            mc.interactionManager.clickSlot(mc.player.currentScreenHandler.syncId, n, 0, SlotActionType.PICKUP, mc.player);
            this.deliveryAwaitingValue = this.moduleTick;
            this.listingWordingValue++;
            this.listingVanishedSet.clear();
            this.queueSlotTotalPriceData = null;
            this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SCAN, "paged to " + (this.listingWordingValue + 1));
         } else {
            if (this.complete == AutoBuilder.BuyMode.ESTIMATE) {
               this.estimateBuyMap.putIfAbsent(this.affordablePagesItem, -1L);
               this.advanceToNextBuyItem();
            } else if (this.pageListingValue == 0 && this.hasNextSearchWording()) {
               this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SEARCH, "no listings under that wording - trying '" + this.formatItemWithDefaultCount(this.affordablePagesItem) + "'");
            } else if (this.listingShowedFlag && this.listingAffordableFlag) {
               this.deferBuyForNoInventorySpace();
            } else {
               this.handleBuyItemFailure(this.pageListingValue == 0 ? "no listing under any wording" : "no more pages");
            }
         }
      }
   }

   private boolean isWithinSchematicCellDistance(BlockPos pos, int schematicCellsLimit) {
      if (this.schematicCells != null && mc.world != null) {
         if (this.changedPlanCountSchematicCel != changedPlanCount || this.schematicCellsValueSchematic != pos.getY() || this.lastSeenSchematicCells != this.schematicCells) {
            this.buildLayerSupportDistanceMap(pos.getY());
         }

         Integer integer = this.schematicCellsIntegerMap.get(pos.asLong());
         return integer != null && integer > 0 && integer <= schematicCellsLimit;
      } else {
         return false;
      }
   }

   private long getLocalCellsHash(BlockPos pos) {
      return CellsFingerprint.getTime(getCubeCellKeys(pos, 3), this::getRawBlockStateIdAt)
         ^ Long.rotateLeft(this.hashOpenHashOpenDefault.hashOpenCellsInRadius(pos.getX(), pos.getY(), pos.getZ(), 8), 29);
   }

   private void cancelSchematicPreview() {
      boolean flag = this.schematicBuilder.getLoadedSchematic() != null
         || this.schematicBuilder.getLoadedFileName() != null && !this.schematicBuilder.getLoadedFileName().isBlank();
      if (!flag) {
         DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "No preview to cancel", false);
      } else {
         if (this.isEnabled()) {
            this.setEnabled(false);
         }

         this.schematicBuilder.clearLoadedSchematic();
         this.blockStateHelper.updateHashOpenElseActive();
         this.availableLow = null;
         this.builderCancelledFlag = true;
         DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Preview cancelled", true);
      }
   }

   private List<SupportStandUtils.Step> getAllBlockerSteps() {
      List<SupportStandUtils.Step> steps = this.blockers.steps();
      SupportStandUtils.PlanStream planStream = this.planStream;
      if (planStream != null && this.isCompletionMissionActiveWithFuture()) {
         List<SupportStandUtils.Step> list = planStream.getCopyOf();
         if (list.size() > steps.size()) {
            return list;
         }
      }

      return steps;
   }

   private boolean canPlaceSupersededTargetOnLayer(BlockPos pos, Vec3d vec, double layerSupersededValue, double layerSupersededLimit) {
      if (!this.isCompletionPhaseActive() && !this.hasActiveBlockersStep()) {
         if (!this.sessionReset || this.layer != Integer.MIN_VALUE && (pos.getY() == this.layer || pos.getY() == this.layer + 1)) {
            if (mc.player != null && !mc.player.isOnGround()) {
               return false;
            } else {
               if (this.hasActiveCompoundCompletion()) {
                  BlockPos blockPos = this.getRecentCompletionTarget();
                  if (blockPos != null && vec.squaredDistanceTo(Vec3d.ofCenter(blockPos)) <= layerSupersededLimit) {
                     return false;
                  }
               }

               if (this.layerSupersededCount >= 24) {
                  return false;
               } else if (this.layer == Integer.MIN_VALUE) {
                  return false;
               } else {
                  if (this.superseded != null && this.superseded.layer() == this.layer) {
                     for (long l : this.sortCellsByDistancePreferHotbar(this.superseded.targets(), vec)) {
                        BlockPos fromLong = BlockPos.fromLong(l);
                        int n = this.getSchematicCells(fromLong);
                        if (n >= 0) {
                           BlockState blockState = this.targetFluidItems.get(n);
                           BlockState worldState = mc.world.getBlockState(fromLong);
                           if (!isPlaceableWithoutSpecialSneak(blockState)
                              && this.passesPlacementGates(fromLong, blockState, worldState, pos, vec, layerSupersededLimit)
                              && this.getBlockHitResultNoSneakOverride(
                                    fromLong,
                                    this.getAimPointForSneakState(pos, fromLong, vec, true),
                                    layerSupersededValue,
                                    this.getRequiredSupportDirection(fromLong, blockState),
                                    this.getPlacementFacing(fromLong, blockState),
                                    this.getPlacementFloatHint(fromLong, blockState),
                                    this.isRelaxedBlockShortCell(fromLong) ? null : getAxis(blockState)
                                 )
                                 != null
                              && this.canPlaceTrapdoorState(fromLong, blockState, this.getAimPointForSneakState(pos, fromLong, vec, true), layerSupersededValue)) {
                              if (!this.canPlanContinuation(fromLong, n, blockState)) {
                                 return false;
                              }

                              this.layerSupersededCount++;
                              this.selectPasses.handleTimes(Counter.FAST_CONTINUES);
                              return true;
                           }
                        }
                     }
                  }

                  return this.trySweepLocalLayerPlacement(pos, vec, layerSupersededValue, layerSupersededLimit);
               }
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

   private boolean replaceUnneededSlotWithCreativeStack(PlayerInventory inventory, Item replacementItem) {
      HashSet<Item> hashSet = new HashSet<>();
      hashSet.add(Items.DIRT);

      for (BlockState blockState : this.completionMissionMap.values()) {
         hashSet.add(getItemForBlockState(blockState));
      }

      if (this.schematicCells != null && this.targetFluidItems != null && mc.world != null && !this.completedDeferredFlag) {
         for (int n = 0; n < this.schematicCells.size(); n++) {
            if (mc.world.getBlockState(this.schematicCells.get(n)).getBlock() != this.targetFluidItems.get(n).getBlock()) {
               hashSet.add(getItemForBlockState(this.targetFluidItems.get(n)));
            }
         }
      }

      int selectedSlot = inventory.getSelectedSlot();

      for (int passIndex = 0; passIndex < 2; passIndex++) {
         for (int slotIndex = passIndex == 0 ? 9 : 0; slotIndex <= (passIndex == 0 ? 35 : 8); slotIndex++) {
            if (slotIndex != selectedSlot) {
               ItemStack itemStack = inventory.getStack(slotIndex);
               if (!itemStack.isEmpty() && !hashSet.contains(itemStack.getItem())) {
                  ItemStack replacementStack = new ItemStack(replacementItem);
                  replacementStack.setCount(replacementStack.getMaxCount());
                  inventory.setStack(slotIndex, replacementStack.copy());
                  mc.interactionManager.clickCreativeStack(replacementStack.copy(), slotIndex <= 8 ? slotIndex + 36 : slotIndex);
                  return true;
               }
            }
         }
      }

      return false;
   }

   private void resetExpectedConfirms(String confirmsExpectedText) {
      if (this.expectedConfirms != null) {
         this.confirmsExpectedCount++;
         if (this.confirms == this.sessionStartConfirms && !this.expectedConfirms.getCopyOf().isEmpty()) {
            long l = this.expectedConfirms.getCopyOf().get(0).target();
            this.confirmsExpectedValue = l == this.lastConfirmsExpectedKey ? Math.min(this.confirmsExpectedValue + 1, 5) : 1;
            this.lastConfirmsExpectedKey = l;
            this.confirmsExpectedDeadlineTick = this.moduleTick + 40 * (1 << this.confirmsExpectedValue);
         }

         this.recordProgramEnd(this.expectedConfirms.getCopyOf().size(), this.cursor, this.confirms - this.sessionStartConfirms, parseLostAccessYield(confirmsExpectedText));
         this.expectedConfirms = null;
         this.cursor = 0;
         this.programDispatchableValue = 0;
         this.selectPassesReadyTick = this.moduleTick + 40;
      }
   }

   private boolean stepTowardSettlePoint(BlockPos pos, double settleModuleValue, double d2, Vec3d vec) {
      Interval interval = Interval.createCentered(pos.getX() + 0.5, pos.getZ() + 0.5, 0.2);
      Decision decision = SlidingPulseUtils.decideSlidingAction(interval, settleModuleValue, d2, vec.x, vec.z, this.getSlipperiness());
      switch (decision.action()) {
         case DRIVE:
            if (this.intervalReportTimer.canTime(this.moduleTick)) {
               this.handlePressedOptions(interval.settleX(), interval.settleZ(), false);
            }
            break;
         case BRAKE:
            if (!this.applyCounterStrafeKeys(0.004)) {
               this.releaseMovementKeys();
            }
            break;
         case SETTLED:
            this.releaseMovementKeys();
            return true;
         default:
            this.releaseMovementKeys();
      }

      return false;
   }

   private boolean isFiniteBlockedWithinLimit() {
      return this.finiteBlockedLastLimit > 0 && this.finiteBlockedValue <= this.finiteBlockedLastLimit;
   }

   private boolean hasAdjacentUnplacedSpecialBlock(BlockPos pos) {
      for (Direction direction : Direction.values()) {
         BlockPos blockPos = pos.offset(direction);
         int n = this.getSchematicCells(blockPos);
         if (n >= 0) {
            BlockState blockState = this.targetFluidItems.get(n);
            if (isFlaggedBlockState(blockState) && mc.world.getBlockState(blockPos).getBlock() != blockState.getBlock()) {
               return true;
            }
         }
      }

      return false;
   }

