   private ArrayList<SupportStandUtils.Target> collectCompletionTargets() {
      long startNanos = this.selectPasses.getNanoTime();

      ArrayList completionShort;
      try {
         ArrayList<SupportStandUtils.Target> arrayList = new ArrayList<>();
         HashSet<Long> hashSet = new HashSet<>();

         for (long l : this.finiteBlockedActive && this.completionMissionMap.size() > 32
            ? this.getCompletionTargets(this.getFeetBlockPos())
            : new ArrayList<>(this.completionMissionMap.keySet())) {
            BlockState targetState = this.completionMissionMap.get(l);
            if (targetState != null) {
               BlockPos blockPos = BlockPos.fromLong(l);
               if (!this.excludedTargets.canFingerprintCells(l, this::getRawBlockStateIdAt)
                  && hashSet.add(l)
                  && this.canObtainItemForPlacement(getItemForBlockState(targetState))
                  && this.getRedstoneDeferralReason(blockPos) == null
                  && this.getPrerequisiteSupportCell(blockPos, targetState) == null
                  && !this.isFiniteFluidBlocked(blockPos, targetState)
                  && !this.canMachineDownForced(blockPos)
                  && !this.hasFluidNearBelowCell(blockPos)
                  && (!this.needsFillForOpenNeighbor(blockPos) || this.isPositionStalled(blockPos))
                  && (!this.isAirCellSplittingNeighbors(blockPos) || this.isPositionStalled(blockPos))
                  && (!this.isCampfireTargetFacingPos(blockPos) || this.isPositionStalled(blockPos))) {
                  BlockPos rotateYcounterclockwise = this.getRotateYcounterclockwise(blockPos, targetState);
                  BlockState pairedState = null;
                  boolean flag = false;
                  if (rotateYcounterclockwise != null
                     && !this.completionMissionMap.containsKey(rotateYcounterclockwise.asLong())
                     && !this.excludedTargets.canFingerprintCells(rotateYcounterclockwise.asLong(), this::getRawBlockStateIdAt)
                     && !this.isRepairAlreadyHandled(rotateYcounterclockwise.asLong())) {
                     int n = this.getSchematicCells(rotateYcounterclockwise);
                     pairedState = n >= 0 ? this.targetFluidItems.get(n) : null;
                     BlockState blockState = mc.world.getBlockState(rotateYcounterclockwise);
                     Direction targetFacing = getDirectionForBlockState(targetState);
                     if (pairedState != null
                        && targetFacing != null
                        && blockState.getBlock() == pairedState.getBlock()
                        && this.hasWantedTargetAt(rotateYcounterclockwise)
                        && blockState.contains(Properties.HORIZONTAL_FACING)
                        && blockState.contains(Properties.CHEST_TYPE)
                        && blockState.get(Properties.CHEST_TYPE) == ChestType.SINGLE) {
                        Direction direction = blockState.get(Properties.HORIZONTAL_FACING);
                        Direction opposite = targetFacing.getOpposite();
                        if (direction == opposite) {
                           if (this.completionShortPositionSet.remove(blockPos.asLong()) | this.completionShortPositionSet.remove(rotateYcounterclockwise.asLong())) {
                              this.logDebugMessage(
                                 "\u00a7b[CompletionMission]\u00a7r un-relaxing pair "
                                    + blockPos.toShortString()
                                    + "/"
                                    + rotateYcounterclockwise.toShortString()
                                    + ": the placed half already faces the recorded way ("
                                    + direction
                                    + ")"
                              );
                           }
                        } else if (direction == targetFacing) {
                           this.completionShortPositionSet.add(blockPos.asLong());
                           this.completionShortPositionSet.add(rotateYcounterclockwise.asLong());
                        } else {
                           flag = true;
                           this.completionShortPositionSet.remove(blockPos.asLong());
                           this.completionShortPositionSet.remove(rotateYcounterclockwise.asLong());
                           this.logDebugMessage(
                              "\u00a7b[CompletionMission]\u00a7r pair "
                                 + blockPos.toShortString()
                                 + "/"
                                 + rotateYcounterclockwise.toShortString()
                                 + ": the placed half faces "
                                 + direction
                                 + " and can never merge - it will be broken and both halves rebuilt as recorded"
                           );
                        }
                     }
                  }

                  SupportStandUtils.Target primaryTarget = this.buildSupportTarget(blockPos, targetState);
                  if (primaryTarget != null) {
                     arrayList.add(primaryTarget);
                     if (flag && hashSet.add(rotateYcounterclockwise.asLong())) {
                        SupportStandUtils.Target target = this.buildSupportTarget(rotateYcounterclockwise, pairedState);
                        if (target != null) {
                           arrayList.add(target);
                        }
                     }
                  }
               }
            }
         }

         completionShort = arrayList;
      } finally {
         this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.COMPLETION_INDEX, startNanos);
      }

      return completionShort;
   }

