   private static String formatFacingOrientation(BlockState state) {
      if (state == null) {
         return "null";
      } else if (state.contains(Properties.FACING)) {
         return "facing=" + state.get(Properties.FACING);
      } else if (state.contains(Properties.HORIZONTAL_FACING)) {
         return "facing=" + state.get(Properties.HORIZONTAL_FACING);
      } else if (state.contains(Properties.HOPPER_FACING)) {
         return "facing=" + state.get(Properties.HOPPER_FACING);
      } else if (state.contains(Properties.ORIENTATION)) {
         Orientation orientation = state.get(Properties.ORIENTATION);
         return "orientation=" + orientation + "(front=" + orientation.getFacing() + ",top=" + orientation.getRotation() + ")";
      } else {
         return state.contains(Properties.AXIS) ? "axis=" + state.get(Properties.AXIS) : "none";
      }
   }

