   private void runConstructiveSupportPlanStep(String pressedSupportText) {
      Plan plan = this.dirtFeet;
      if (plan != null) {
         if (this.moduleTick - this.planSupportValue > 400) {
            this.abortConstructivePlan("plan_timeout");
         } else if (this.stepNoProgress >= plan.steps().size()) {
            this.dirtFeet = null;
            this.stepNoProgress = 0;
            this.supportPlanValue = 0;
            this.planSupportValue = -100000;
            this.supportEndedValue = -100000;
            this.path.clear();
            this.updatePressedOptions2();
            this.staleCount = 0;
         } else {
            com.corz.client.utils.RequestSouthUtils.Step step = plan.steps().get(this.stepNoProgress);
            BlockPos toPos = getBlockPos(step.from());
            BlockPos blockPos2 = getBlockPos(step.to());
            BlockPos feetBlockPos = this.getFeetBlockPos();
            if (FlagMarkUtils.canFlagMarkLimitAlternate(this.moduleTick, this.supportEndedValue, this.supportPlanValue)) {
               this.abortConstructivePlan("step_no_progress:" + this.stepNoProgress + ":" + blockPos2.toShortString());
            } else if (step.action() == com.corz.client.utils.RequestSouthUtils.Action.PLACE_DIRT) {
               BlockPos blockPos = getBlockPos(step.dirtTarget());
               BlockPos pos = getBlockPos(step.support());
               if (step.jumpPlacement() || !feetBlockPos.equals(toPos) || mc.player.isOnGround() || this.unstableRecenterChangedTimeo != null && this.unstableRecenterChangedTimeo.isFlag()) {
                  if (this.unstableRecenterChangedTimeo != null && this.isUnstableTargetCell(blockPos)) {
                     if (step.jumpPlacement() && !this.unstableRecenterChangedTimeo.isFlag() && mc.player.getBoundingBox().intersects(new Box(blockPos))) {
                        mc.options.forwardKey.setPressed(false);
                        mc.options.backKey.setPressed(false);
                        mc.options.leftKey.setPressed(false);
                        mc.options.rightKey.setPressed(false);
                        if (mc.player.isOnGround()) {
                           this.handleNoneAbove(mc.player.isOnGround(), true, com.corz.client.utils.RecoveryNone.Owner.ACCESS);
                        }
                     } else {
                        AutoBuilder.TempDriveResult tempDriveResult = this.driveTempPlacement(pressedSupportText + "/CONSTRUCTIVE", blockPos, null, false);
                        if (tempDriveResult == AutoBuilder.TempDriveResult.CONFIRMED) {
                           this.recordStepNoProgress();
                        } else if (tempDriveResult == AutoBuilder.TempDriveResult.FAILED) {
                           this.abortConstructivePlan("transaction:" + this.transaction);
                        }
                     }
                  } else if (this.cells.contains(blockPos.asLong()) && isDirtOrGrassBlock(mc.world.getBlockState(blockPos))) {
                     this.recordStepNoProgress();
                  } else {
                     BlockState blockState = mc.world.getBlockState(blockPos);
                     BlockState blockState2 = mc.world.getBlockState(pos);
                     if (this.getSchematicCells(blockPos) < 0 && (blockState.isAir() || blockState.isReplaceable())) {
                        Direction direction;
                        try {
                           direction = Direction.valueOf(step.supportFace());
                        } catch (IllegalArgumentException e) {
                           this.abortConstructivePlan("bad_support_face");
                           return;
                        }

                        if (!pos.offset(direction).equals(blockPos)
                           || blockState2.isAir()
                           || blockState2.isReplaceable()
                           || blockState2.getCollisionShape(mc.world, pos).isEmpty()) {
                           this.abortConstructivePlan("support_changed:" + pos.toShortString());
                        } else if (!step.jumpPlacement() && !feetBlockPos.equals(toPos)) {
                           if (this.stepNoProgress == 0 && !this.path.isEmpty()) {
                              this.updateStuckDetection();
                           } else {
                              if (this.stepNoProgress == 0 && this.supportPlanValue < 2 && mc.player.isOnGround()) {
                                 List<BlockPos> list = this.findGoPath(feetBlockPos, toPos);
                                 this.supportPlanValue++;
                                 if (list != null
                                    && !list.isEmpty()
                                    && this.tryFollowMovementRoute(list, toPos, this.createMovementMission(Purpose.TEMP_SUPPORT_APPROACH, toPos, null))) {
                                    this.arrivedSupportFlag = true;
                                    this.standClimbFlag = false;
                                    this.routeStandValue = 0;
                                    this.standRouteValue = 0;
                                    this.lastNodeTransitionIndex = -1;
                                    this.standWalkValue = 0;
                                    this.standRouteAmount = Double.MAX_VALUE;
                                    this.updateStuckDetection();
                                    return;
                                 }
                              }

                              this.abortConstructivePlan("stand_changed:" + feetBlockPos.toShortString());
                           }
                        } else {
                           if (step.jumpPlacement()) {
                              if (isFlaggedBlockState(blockState2)) {
                                 this.abortConstructivePlan("jump_support_requires_sneak:" + pos.toShortString());
                                 return;
                              }

                              mc.options.forwardKey.setPressed(false);
                              mc.options.backKey.setPressed(false);
                              mc.options.leftKey.setPressed(false);
                              mc.options.rightKey.setPressed(false);
                              this.setOwnerSneak(false);
                              mc.player.setSprinting(false);
                              this.handleNoneAbove(mc.player.isOnGround(), true, com.corz.client.utils.RecoveryNone.Owner.ACCESS);
                              if (mc.player.getBoundingBox().intersects(new Box(blockPos))) {
                                 return;
                              }
                           }

                           int n = this.getHotbarDirtSlot();
                           if (n == -1) {
                              this.handleReportedUnsolvable(
                                 "missing dirt (constructive access)",
                                 "Missing dirt (put dirt in the hotbar)",
                                 "\u00a7cAuto Builder paused:\u00a7r constructive access requires DIRT; add dirt and re-enable."
                              );
                           } else {
                              this.selectHotbarSlot(n);
                              Vec3d vec3d = this.getFaceAimPoint(blockState2, pos, direction);
                              if (vec3d == null) {
                                 this.abortConstructivePlan("support_has_no_face_shape");
                              } else {
                                 AutoBuilder.TempDriveResult driveTempPlacement2 = this.driveTempPlacement(
                                    pressedSupportText + "/CONSTRUCTIVE", blockPos, new BlockHitResult(vec3d, direction, pos, false), false
                                 );
                                 if (driveTempPlacement2 == AutoBuilder.TempDriveResult.CONFIRMED) {
                                    this.recordStepNoProgress();
                                 } else if (driveTempPlacement2 == AutoBuilder.TempDriveResult.FAILED) {
                                    this.abortConstructivePlan("transaction:" + this.transaction);
                                 }
                              }
                           }
                        }
                     } else {
                        this.abortConstructivePlan("target_changed_or_protected:" + blockPos.toShortString());
                     }
                  }
               } else {
                  mc.options.forwardKey.setPressed(false);
                  mc.options.backKey.setPressed(false);
                  mc.options.leftKey.setPressed(false);
                  mc.options.rightKey.setPressed(false);
               }
            } else if (feetBlockPos.equals(blockPos2) && mc.player.isOnGround()) {
               this.recordStepNoProgress();
               this.path.clear();
               this.releaseMovementKeys();
            } else if (step.action() == com.corz.client.utils.RequestSouthUtils.Action.JUMP_MOUNT) {
               this.updatePressedOptions2();
               if (this.moduleTick - this.supportEndedValue > 120) {
                  this.abortConstructivePlan("jump_mount_timeout:" + blockPos2.toShortString());
               }
            } else if (!this.path.isEmpty()) {
               this.updateStuckDetection();
            } else if (!mc.player.isOnGround() && this.moduleTick - this.supportEndedValue < 60) {
               mc.options.forwardKey.setPressed(false);
               mc.options.backKey.setPressed(false);
               mc.options.leftKey.setPressed(false);
               mc.options.rightKey.setPressed(false);
            } else {
               boolean flag = feetBlockPos.equals(toPos)
                  && Math.abs(blockPos2.getX() - toPos.getX()) <= 1
                  && Math.abs(blockPos2.getZ() - toPos.getZ()) <= 1
                  && Math.abs(blockPos2.getY() - toPos.getY()) <= 1;
               List<BlockPos> goPath = flag ? List.of(feetBlockPos, blockPos2) : this.findGoPath(feetBlockPos, blockPos2);
               this.supportPlanValue++;
               if (FlagMarkUtils.canFlagMarkLimitAlternate(this.moduleTick, this.supportEndedValue, this.supportPlanValue)) {
                  this.intentRepeatedMap.put(blockPos2.asLong(), this.moduleTick + 2400);
                  this.abortConstructivePlan("repeated_step_route:" + blockPos2.toShortString());
               } else if (goPath != null
                  && !goPath.isEmpty()
                  && this.tryFollowMovementRoute(goPath, blockPos2, this.createMovementMission(Purpose.TEMP_SUPPORT_APPROACH, blockPos2, null))) {
                  this.arrivedSupportFlag = true;
                  this.standClimbFlag = false;
                  this.routeStandValue = 0;
                  this.standRouteValue = 0;
                  this.lastNodeTransitionIndex = -1;
                  this.standWalkValue = 0;
                  this.standRouteAmount = Double.MAX_VALUE;
                  this.updateStuckDetection();
               } else {
                  this.intentRepeatedMap.put(blockPos2.asLong(), this.moduleTick + 2400);
                  this.abortConstructivePlan("confirmed_dirt_route_failed:" + blockPos2.toShortString());
               }
            }
         }
      }
   }

   private void recordAccessLostProgram(BlockPos targetPos, BlockPos standPos, int lostProgramValue, List<BlockPos> route) {
      long[] ls = standPos == null ? this.collectSightlineCellKeys(targetPos, targetPos) : this.collectSightlineCellKeys(targetPos, standPos);
      ArrayList<Long> arrayList = new ArrayList<>();
      if (route != null) {
         for (BlockPos blockPos : route) {
            arrayList.add(blockPos.asLong());
         }
      }

      ScopeAssetsData scopeAssetsData = ScopeAssetsData.getScopeAssetsData(targetPos.asLong(), arrayList, temporaryCellKey -> this.cells.contains(temporaryCellKey));
      this.lostProgramListMap.put(targetPos.asLong(), arrayList);
      Obligation obligation = this.candidateDurableScopeCaused
         .getOpen(targetPos.asLong(), standPos == null ? 0L : standPos.asLong(), lostProgramValue, ls, this::getRawBlockStateIdAt, scopeAssetsData, this.moduleTick);
      this.programLostCount++;
      if (this.currentTargetPos != null && this.currentTargetPos.equals(targetPos)) {
         this.resetCameraPredictionTimes();
         this.currentTargetPos = null;
      }

      if (this.expectedConfirms != null) {
         this.resetExpectedConfirms("access lost under the program's target");
      }

      if (this.placementExplicit != null
         && this.placementExplicit.getIllegalAction() != null
         && this.placementExplicit.getIllegalAction() == targetPos.asLong()) {
         this.placementExplicit.handleFailureExplicit("ACCESS_LOST");
      }

      this.logDebugMessage(
         "\u00a7c[AccessRecovery]\u00a7r raised " + obligation.getFormat() + " - placements that would consume this workspace wait; unrelated work continues"
      );
      this.updateDurableObligations();
   }

   private static long getRunEndpointsHash(LaneRowUtils.Run run) {
      long l = run.members().get(0).target();
      long lastTargetKey = run.members().get(run.getMembers() - 1).target();
      long lowerEndpointKey = Math.min(l, lastTargetKey);
      long upperEndpointKey = Math.max(l, lastTargetKey);
      return lowerEndpointKey ^ Long.rotateLeft(upperEndpointKey, 31);
   }

