   private BlockPos getFirstUnbuiltNonPlaceStepPos() {
      if (this.expectedConfirms == null) {
         return null;
      } else {
         for (Step step : this.expectedConfirms.getCopyOf()) {
            if (!step.isPlaceKind() && !this.builtCellSet.contains(step.target())) {
               return BlockPos.fromLong(step.target());
            }
         }

         return null;
      }
   }

   private static long getRegionHashKey(BlockPos pos) {
      long l = Math.floorDiv(pos.getX(), 8);
      long regionZ = Math.floorDiv(pos.getZ(), 8);
      long regionY = Math.floorDiv(pos.getY(), 2);
      return l * -7046029254386353131L ^ Long.rotateLeft(regionZ * -4417276706812531889L, 21) ^ regionY * 1609587929392839161L;
   }

   private boolean evaluateAccessPostcondition(BlockPos pos) {
      if (this.cellsUnpackWorkspaceReturn != null) {
         return this.tryWalkBackToAnchor(pos);
      } else {
         if (this.islandCompoundText == null && this.mountedElsewhere != null) {
            if (this.confirms != this.mountedMountValue) {
               this.mountedMountValue = this.confirms;
               this.nanoTimeMountedElsewhere = System.nanoTime();
            }

            if (System.nanoTime() - this.nanoTimeMountedElsewhere < 1000000000L) {
               return false;
            }

            String string = this.mountedElsewhere + " without a confirmation for 1s";
            this.mountedElsewhere = null;
            this.rebuildReachableComponent();
            boolean flag = this.cells.contains(pos.down().asLong());
            BlockPos blockPos = flag ? null : this.findNearestOpenCellTop(pos);
            int n = this.floats == Integer.MAX_VALUE ? Math.max(1, this.iteratorCenterPositionSet.size()) : Math.max(1, this.floats);
            this.reachableElsewhereData = new Situation(0, flag, blockPos != null, n, this.component.size());
            this.blockPosMountedElsewhere = blockPos;
            Verdict verdict = DescendReturnUtils.getOwnReachable(this.reachableElsewhereData);
            if (DescendReturnUtils.canDescendReturn(verdict)) {
               this.recordColumnTopForUnknownOwner();
               return this.tryReturnToWorkspace(verdict, string);
            }
         }

         if (this.islandCompoundText == null) {
            return false;
         } else if (this.islandAbort != 0L) {
            return false;
         } else {
            String islandExitReason = this.islandCompoundText;
            this.islandCompoundText = null;
            if (this.schematicCells != null && mc.player != null && !this.deckMicroMoves.isProbingExitingConfirmed() && !this.hasActiveBlockersStep()) {
               this.postconditionAccessCount++;
               Verdict descendVerdict = this.getDescendVerdict();
               this.logDebugMessage(
                  "\u00a7b[AccessPostcondition]\u00a7r "
                     + islandExitReason
                     + " \u2192 "
                     + descendVerdict
                     + " {"
                     + this.reachableElsewhereData.getFormat()
                     + "}"
                     + (this.unknown == null ? "" : " contract{" + this.unknown.getReusableDescentData().getFormat() + "}")
               );
               if (!DescendReturnUtils.canDescendReturn(descendVerdict)) {
                  if (islandExitReason.startsWith("surface exit: frontier exhausted")) {
                     this.mountedElsewhere = islandExitReason;
                     this.mountedMountValue = this.confirms;
                     this.nanoTimeMountedElsewhere = System.nanoTime();
                  }

                  return false;
               } else {
                  this.recordColumnTopForUnknownOwner();
                  return this.tryReturnToWorkspace(descendVerdict, islandExitReason);
               }
            } else {
               return false;
            }
         }
      }
   }

