   private boolean escapeEnclosedByTempBlocks(BlockPos pos) {
      for (Direction direction : Type.HORIZONTAL) {
         BlockPos blockPos = pos.offset(direction);
         if (WalkRouteFinder.isStandable(mc.world, blockPos) || WalkRouteFinder.isStandable(mc.world, blockPos.up())) {
            return false;
         }
      }

      BlockPos up = null;

      label98:
      for (Direction wallDirection : Type.HORIZONTAL) {
         for (int n = 0; n <= 1; n++) {
            BlockPos wallPos = pos.offset(wallDirection).up(n);
            if (this.cells.contains(wallPos.asLong()) && !this.isCellCoveredOrBlocked(wallPos.asLong())) {
               if (up == null) {
                  up = wallPos;
               }

               if (this.isWithinReachFromEye(wallPos)) {
                  up = wallPos;
                  break label98;
               }
            }
         }
      }

      if (up != null) {
         this.blockPos2Exit = up;
         this.cleanupExitFlag = true;
         this.logDebugMessage("\u00a7e[Escape]\u00a7r enclosed by own temp blocks - mining " + up.toShortString() + " to get out");
         this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "escape: mine own temp wall");
         return true;
      } else {
         Direction next = null;
         float lowestBreakCost = Float.MAX_VALUE;
         boolean iteratorWorldFlag = false;
         boolean iteratorWorldFlag2 = false;

         for (Direction exitDirection : Type.HORIZONTAL) {
            BlockPos offsetPos = pos.offset(exitDirection);
            BlockPos offsetAbovePos = offsetPos.up();
            boolean flag = this.isSchematicBlockPlacedAt(offsetPos) && !this.isCellCoveredOrBlocked(offsetPos.asLong());
            boolean upperPlaced = this.isSchematicBlockPlacedAt(offsetAbovePos) && !this.isCellCoveredOrBlocked(offsetAbovePos.asLong());
            boolean empty = mc.world.getBlockState(offsetPos).getCollisionShape(mc.world, offsetPos).isEmpty();
            boolean upperEmpty = mc.world.getBlockState(offsetAbovePos).getCollisionShape(mc.world, offsetAbovePos).isEmpty();
            if ((flag || empty) && (upperPlaced || upperEmpty) && (flag || upperPlaced)) {
               float f = (flag ? this.getHardness(offsetPos) : 0.0F) + (upperPlaced ? this.getHardness(offsetAbovePos) : 0.0F);
               if (f < lowestBreakCost) {
                  lowestBreakCost = f;
                  next = exitDirection;
               }
            }
         }

         if (next != null) {
         }

         return false;
      }
   }

