   private boolean rejectPlacementFaceCertificate(BlockHitResult blockHitResult2) {
      if (this.currentTargetPos == null || blockHitResult2 == null) {
         return false;
      } else if (!this.isRollbackFingerprintRefused(this.currentTargetPos, blockHitResult2)) {
         return false;
      } else {
         int[] ns = this.faceRequiredMap.computeIfAbsent(this.currentTargetPos.asLong(), longValue -> new int[]{0, this.moduleTick});
         if (this.moduleTick - ns[1] > 200) {
            ns[0] = 0;
         }

         ns[0]++;
         ns[1] = this.moduleTick;
         if (ns[0] >= 2) {
            this.faceParityMap.put(hashPosAndDirection(this.currentTargetPos, blockHitResult2.getSide()), this.moduleTick + 100);
         }

         if (this.faceRequiredMap.size() > 256) {
            this.faceRequiredMap.clear();
         }

         this.resetCameraPredictionTimes();
         this.transitionToState(
            AutoBuilder.State.ALIGN_ROTATION,
            "interaction certificate refused - a different face, hit or pose is required" + (ns[0] >= 2 ? " (face banned: second refusal)" : "")
         );
         return true;
      }
   }

