   private boolean activateDeckMission(FloorBuildPlanner.Deck remaining, int deckSupersedesValue, BlockPos pos, Vec3d vec, double deckRemainingValue, double reachLimit) {
      boolean flag = remaining.containsCell(pos.asLong());
      BlockPos blockPos2 = flag ? null : this.getNearestCandidateCell(remaining);
      this.candidateSearch = this.deckPlanning.validateCandidateSearch(deckSupersedesValue, flag, blockPos2 != null);
      String string = flag
         ? "on-deck"
         : (
            blockPos2 != null
               ? "walk-on:" + blockPos2.toShortString()
               : (
                  this.candidateSearch != null
                     ? "pillar:base=" + BlockPos.fromLong(this.candidateSearch.base()).toShortString() + ",climb=" + this.candidateSearch.climb() + ",cost=" + this.candidateSearch.cost()
                     : "NONE"
               )
         );
      this.remaining = remaining;
      this.noneSupersedesTime = this.candidateSearch != null ? Long.MIN_VALUE : changedPlanCount;
      this.noneSupersedesValue = this.moduleTick;
      this.deckNoneValue = this.cooldown.size();
      this.deckSupersedesValue = deckSupersedesValue;
      this.deckMicroMoves.onNoneSignum(this.remaining, pos.asLong());
      if (this.invalidNone.isLegacyConstruction()) {
         this.invalidNone.finishLegacyConstruction("deck activation supersedes");
      }

      this.invalidNone.beginReplacementYield(Owner.DECK, this.deckMicroMoves.getNoneCount());
      this.handleAccessRoute("deck_mission");
      Summary summary = this.deckMission.getDataForIntLong(pos.getX(), pos.getY(), pos.getZ(), this.remaining.connectedExtraCount, 0L, this.moduleTick);
      if (summary != null) {
         this.logDebugMessage("\u00a7b[ConstructionMission]\u00a7r end " + summary.getFormat());
      }

      this.logDebugMessage(
         "\u00a7b[DeckMission]\u00a7r activated deckY="
            + deckSupersedesValue
            + " walkable="
            + this.remaining.getCellCount()
            + " frontier="
            + this.remaining.getFrontierCount()
            + " remaining="
            + this.remaining.connectedExtraCount
            + " futureBodyCells="
            + FloorBuildPlanner.getCellsWithOpenAbove(this.supersedesRemainingProbe, this.remaining).size()
            + " phase="
            + this.deckMicroMoves.getProbingExitingType()
            + " entry="
            + string
            + " feet="
            + pos.toShortString()
            + " "
            + this.effectiveLowestData.getFormat()
      );
      if (this.candidateSearch != null) {
         this.logDeckEntry("activated with the proven entry");
      }

      return this.canDeckFrontier(pos, vec, deckRemainingValue, reachLimit);
   }

