      this.autoBuilderCollisionTop = (x2, y2, z2) -> {
         BlockPos blockPos = new BlockPos(x2, y2, z2);
         BlockState blockState = mc.world.getBlockState(blockPos);
         if (blockState.getBlock() instanceof HopperBlock) {
            return 0.6875;
         } else if (blockState.isOf(Blocks.PISTON_HEAD) && blockState.contains(Properties.FACING) && blockState.get(Properties.FACING).getAxis() != Axis.Y) {
            return 0.625;
         } else {
            VoxelShape voxelShape = blockState.getCollisionShape(mc.world, blockPos);
            return voxelShape.isEmpty() ? 0.0 : voxelShape.getMax(Axis.Y);
         }
      };
