      this.apiAutoPolicy = new Policy() {
         @Override
         public boolean checkPositionPair(BlockPos pos, BlockPos pos2) {
            return AutoBuilder.this.isNeighborFacingAcceptable(pos, pos2);
         }

         @Override
         public boolean isOrientedPlace() {
            return AutoBuilder.this.placeOrientedFlag;
         }

         @Override
         public void countRaycast() {
            AutoBuilder.this.selectPasses.handleTimes(Counter.RAYCASTS);
         }

         @Override
         public boolean isRoutePlanTarget(BlockPos pos3) {
            return AutoBuilder.this.routePlanFlag && pos3.equals(AutoBuilder.this.currentTargetPos) && AutoBuilder.this.isPairedBlockPlaced(pos3);
         }

         @Override
         public boolean isRoutePlanTargetPlaceable(BlockPos pos4) {
            if (AutoBuilder.this.routePlanFlag && pos4.equals(AutoBuilder.this.currentTargetPos)) {
               int schematicCells = AutoBuilder.this.getSchematicCells(pos4);
               return schematicCells >= 0
                  && AutoBuilder.this.hasBuiltChestPartner(pos4, AutoBuilder.this.targetFluidItems.get(schematicCells))
                  && AutoBuilder.this.isChestPairTypeMismatched(pos4, AutoBuilder.this.targetFluidItems.get(schematicCells));
            } else {
               return false;
            }
         }

         @Override
         public boolean isFaceCooldownActive(BlockPos pos5, Direction direction) {
            Integer faceparitymap = AutoBuilder.this.faceParityMap.get(AutoBuilder.hashPosAndDirection(pos5, direction));
            return faceparitymap != null && AutoBuilder.this.moduleTick < faceparitymap;
         }
      };
