   private boolean isSessionReset() {
      long l = this.computeBuildStateHash();
      if (this.wakeRevValue >= 0 && l == this.layerHash) {
         this.sessionResetTotal++;
         return true;
      } else {
         if (this.wakeRevValue >= 0 && l != this.layerHash) {
            this.first = this.formatChangedDefer(l);
         }

         return false;
      }
   }

   private void showStatusMessage(String autoBuilderText, boolean autoBuilderFlag, boolean familyReconsideredFlag) {
      this.wakeDeferredFamilies(autoBuilderText, autoBuilderFlag, familyReconsideredFlag, false);
   }

   private String formatPlainMultiface(BlockPos pos) {
      BlockState blockState = this.completionMissionMap.get(pos.asLong());
      if (blockState == null) {
         int n = this.getSchematicCells(pos);
         blockState = n >= 0 ? this.targetFluidItems.get(n) : null;
      }

      if (blockState == null) {
         return "PLAIN";
      } else if (this.getRotateYcounterclockwise(pos, blockState) != null) {
         return "CHEST";
      } else if (isPlaceableWithoutSpecialSneak(blockState)) {
         return "6WAY";
      } else {
         return matchesBlockStateRule(blockState) ? "MULTIFACE" : "PLAIN";
      }
   }

   private boolean isBoardScreen() {
      if (this.boardScreenScreen == null) {
         return false;
      } else if (mc.currentScreen != this.boardScreenScreen && this.isAuctionScreenOpen()) {
         this.boardScreenScreen = null;
         this.boardFlag = true;
         this.boardValue = this.moduleTick;
         return false;
      } else {
         if (this.getTicksSinceBoard() > 60) {
            this.onAuctionSearchSignFailed("no result board");
         }

         return true;
      }
   }

   private static com.corz.client.utils.SupportSnapshot.Cell toSupportCell(BlockPos pos) {
      return new com.corz.client.utils.SupportSnapshot.Cell(pos.getX(), pos.getY(), pos.getZ());
   }

   private String formatSelectedMaterialsSummary() {
      if (this.availableLow == null) {
         return "";
      } else {
         ArrayList<String> arrayList = new ArrayList<>();

         for (MaxMaterialsUtils.Row<Item> row : this.availableLow.readSelectedItems) {
            if (row.maxCount > 0) {
               arrayList.add(getItemIdPath(row.next) + "\u00d7" + row.maxCount);
            }

            if (arrayList.size() >= 6) {
               break;
            }
         }

         return String.join(", ", arrayList);
      }
   }

   private void keepExitStairPillars(SupportStandUtils.Mission mission) {
      if (mission != null
         && mc.player != null
         && this.waitFullPass != Integer.MIN_VALUE
         && this.removeTempAfter.isEnabled()
         && this.useTemporaryBlocks.isEnabled()) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         BlockPos stairTopPos = null;
         int min = Integer.MAX_VALUE;
         ArrayList<BlockPos> arrayList = new ArrayList<>();

         for (SupportStandUtils.Step step : mission.steps()) {
            if (step.op() == SupportStandUtils.Op.PILLAR && step.stand() != null) {
               min = Math.min(min, step.cell().y());
               stairTopPos = toBlockPos(step.stand()).down();
               arrayList.add(stairTopPos);
            } else if (step.op() == SupportStandUtils.Op.DIRT) {
               stairTopPos = toBlockPos(step.cell());
            }
         }

         if (stairTopPos != null && feetBlockPos.getY() >= this.waitFullPass - 2 && this.cells.contains(stairTopPos.asLong())) {
            BlockPos stairBasePos = stairTopPos;

            while (this.cells.contains(stairBasePos.down().asLong())) {
               stairBasePos = stairBasePos.down();
            }

            if (min != Integer.MAX_VALUE && Math.min(min, stairBasePos.getY()) <= this.waitFullPass - 4) {
               for (long l : this.completionMissionMap.keySet()) {
                  if (BlockPos.unpackLongY(l) < feetBlockPos.getY() - 1 && !this.machineArmedSet.contains(l)) {
                     return;
                  }
               }

               this.waitFullPass = Integer.MIN_VALUE;
               this.unpackCellsIntArrayMap.put(BlockPos.asLong(stairTopPos.getX(), 0, stairTopPos.getZ()), new int[]{stairBasePos.getY(), stairTopPos.getY(), 1});

               for (BlockPos blockPos : arrayList) {
                  long columnKey = BlockPos.asLong(blockPos.getX(), 0, blockPos.getZ());
                  int[] ns = this.unpackCellsIntArrayMap.get(columnKey);
                  if (this.cells.contains(blockPos.asLong()) && (ns == null || ns.length <= 2)) {
                     BlockPos down = blockPos;
                     BlockPos up = blockPos;

                     while (this.cells.contains(down.down().asLong())) {
                        down = down.down();
                     }

                     while (this.cells.contains(up.up().asLong())) {
                        up = up.up();
                     }

                     this.unpackCellsIntArrayMap.put(columnKey, new int[]{down.getY(), up.getY(), 2});
                     this.logDebugMessage(
                        "\u00a7b[Lifeline]\u00a7r exit stair foot kept "
                           + down.toShortString()
                           + " .. "
                           + up.toShortString()
                           + " - the climb pillar under the stair's side step stays until the final cleanup"
                     );
                  }
               }

               this.logDebugMessage(
                  "\u00a7b[Lifeline]\u00a7r exit stair kept "
                     + stairBasePos.toShortString()
                     + " .. "
                     + stairTopPos.toShortString()
                     + " - the climb out of the finished pocket grows with the floor beside it and the final cleanup digs it down"
               );
            }
         }
      }
   }

