   private boolean isNoteBlockSafeFromObservers(BlockPos pos, BlockState state) {
      if (state.getBlock() instanceof NoteBlock && mc.world != null) {
         for (Direction direction : Direction.values()) {
            BlockPos blockPos = pos.offset(direction);
            int n = this.getSchematicCells(blockPos);
            if (n >= 0) {
               BlockState blockState = this.targetFluidItems.get(n);
               if (blockState.getBlock() instanceof ObserverBlock
                  && blockState.contains(Properties.FACING)
                  && blockState.get(Properties.FACING) == direction.getOpposite()
                  && mc.world.getBlockState(blockPos).getBlock() instanceof ObserverBlock) {
                  return false;
               }
            }
         }

         return true;
      } else {
         return false;
      }
   }

   private void recomputeMaterialPricing() {
      AutoBuilder.BuyMode buyMode = this.complete;
      this.updateMaterialAvailability();
      this.pricingMaterialItems.clear();
      this.costBuyMap.clear();
      HashMap<Item, Integer> hashMap = new HashMap<>();
      if (this.availableLow != null) {
         for (MaxMaterialsUtils.Row<Item> row : this.availableLow.readSelectedItems) {
            if (row.maxCount > 0 && row.next != Items.AIR) {
               hashMap.put(row.next, row.maxCount);
            }
         }
      }

      Map<Item, Integer> map = (Map<Item, Integer>)(this.stockpileInChests.isEnabled() ? this.getRestockItemCounts() : Map.of());
      LinkedHashMap<Item, Integer> linkedHashMap = CountsLateUtils.getCounts(this.getCachedMissingLayers(), hashMap, map);

      for (Entry<Item, Integer> entry : linkedHashMap.entrySet()) {
         this.pricingMaterialItems.add(entry.getKey());
         this.costBuyMap.put(entry.getKey(), entry.getValue());
      }

      if (this.buyTempDirt.getValue() > 0 && this.useTemporaryBlocks.isEnabled() && this.availableLow != null) {
         int pricingMaterialValue2 = 0;

         for (MaxMaterialsUtils.Row<Item> row2 : this.availableLow.readSelectedItems) {
            if (row2.next == Items.DIRT) {
               pricingMaterialValue2 = row2.pricingMaterialValue;
               break;
            }
         }

         int n = Math.max(0, pricingMaterialValue2 + this.buyTempDirt.getValue() - this.countItemInInventory(Items.DIRT) - map.getOrDefault(Items.DIRT, 0));
         if (n > 0) {
            if (!this.costBuyMap.containsKey(Items.DIRT)) {
               this.pricingMaterialItems.add(Items.DIRT);
            }

            this.costBuyMap.put(Items.DIRT, n);
         }
      }

      if (this.pricingMaterialItems.isEmpty()) {
         if (buyMode == AutoBuilder.BuyMode.ESTIMATE) {
            this.openMaterialsScreen();
         }

         this.showToggleNotification(
            "Auto Buy",
            buyMode == AutoBuilder.BuyMode.ESTIMATE
               ? "Nothing missing - cost is $0"
               : (map.isEmpty() ? "You already have every material" : "Everything is carried or stockpiled already"),
            true
         );
         boolean flag = this.everythingStockpiledFlag;
         this.resetBuyState();
         if (flag && this.isEnabled()) {
            this.setEnabled(false);
         }
      } else {
         int n2 = 0;

         for (Item item : hashMap.keySet()) {
            if (map.getOrDefault(item, 0) > 0) {
               n2++;
            }
         }

         this.showToggleNotification(
            "Auto Buy",
            (buyMode == AutoBuilder.BuyMode.BUY ? "Buying " : "Pricing ")
               + this.pricingMaterialItems.size()
               + " material"
               + (this.pricingMaterialItems.size() == 1 ? "" : "s")
               + (n2 > 0 ? " (" + n2 + " partly stockpiled)" : "")
               + "...",
            true
         );
         this.advanceToNextBuyItem();
      }
   }

