               int n3 = Math.abs(n - pos.getX()) + Math.abs(unpackLongZ2 - pos.getZ());
               BlockPos blockPos = new BlockPos(n, ns[1], unpackLongZ2);
               BlockPos blockPos2 = new BlockPos(n, ns[0], unpackLongZ2);
