   private boolean tryPlacePerchReconnectBridge(BlockPos pos) {
      if (this.useTemporaryBlocks.isEnabled() && this.getHotbarDirtSlot() != -1 && mc.world != null) {
         BlockPos down = pos.down();
         if (mc.world.getBlockState(down).getCollisionShape(mc.world, down).isEmpty()) {
            return false;
         } else {
            BlockPos offset = null;
            int minValue2 = Integer.MIN_VALUE;

            for (Direction direction2 : Type.HORIZONTAL) {
               BlockPos downOffset = down.offset(direction2);
               BlockPos downOffsetAbove = downOffset.up();
               if (this.getSchematicCells(downOffset) < 0
                  && mc.world.getBlockState(downOffset).isAir()
                  && mc.world.getBlockState(downOffsetAbove).getCollisionShape(mc.world, downOffsetAbove).isEmpty()
                  && mc.world.getBlockState(downOffsetAbove.up()).getCollisionShape(mc.world, downOffsetAbove.up()).isEmpty()
                  && this.describeObserverPulseHazard(downOffset) == null
                  && !this.isFacedByPiston(downOffset)) {
                  Integer integer = this.worldBridgeIntegerMap.get(downOffset.asLong());
                  if (integer == null || this.moduleTick - integer >= 2400) {
                     int n = 0;

                     for (Direction direction : Type.HORIZONTAL) {
                        BlockPos blockPos = downOffsetAbove.offset(direction);
                        if (!blockPos.equals(pos)
                           && (
                              WalkRouteFinder.isStandable(mc.world, blockPos)
                                 || WalkRouteFinder.isStandable(mc.world, blockPos.up())
                                 || WalkRouteFinder.isStandable(mc.world, blockPos.down())
                           )) {
                           n += 10;
                        }
                     }

                     if (n != 0 && n > minValue2) {
                        minValue2 = n;
                        offset = downOffset;
                     }
                  }
               }
            }

            if (offset == null) {
               return false;
            } else {
               this.worldBridgeIntegerMap.put(offset.asLong(), this.moduleTick);
               this.pendingBridgeCells.clear();
               this.pendingBridgeCells.add(offset);
               this.bridgeSwapValue = this.moduleTick;
               this.updateBridgeModule();
               this.worldBridgeValue = 160;
               this.elevatedPillarItems.clear();
               this.logDebugMessage(
                  "\u00a7e[Recover]\u00a7r action=PERCH_RECONNECT temp "
                     + offset.toShortString()
                     + " beside the support "
                     + down.toShortString()
                     + " - one step back to walkable ground"
               );
               this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.BRIDGE, 1);
               this.transitionToState(AutoBuilder.State.TEMP_BRIDGE, "perch reconnect");
               return true;
            }
         }
      } else {
         return false;
      }
   }

   private boolean canReachDescentPoint(BlockPos pos, int cellsDownLimit) {
      ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
      HashSet<Long> hashSet = new HashSet<>();
      arrayDeque.add(pos);
      hashSet.add(pos.asLong());

      while (!arrayDeque.isEmpty() && hashSet.size() <= 96) {
         BlockPos poll2 = arrayDeque.poll();
         if (poll2.getY() < cellsDownLimit && !this.cells.contains(poll2.down().asLong()) && this.canDownCollision(poll2)) {
            return true;
         }

         for (Direction direction : Direction.values()) {
            BlockPos blockPos = poll2.offset(direction);
            if (this.cells.contains(blockPos.asLong()) && hashSet.add(blockPos.asLong())) {
               arrayDeque.add(blockPos);
            }
         }
      }

      return false;
   }

