   private List<CountsLateUtils.Layer<Item>> getMissingMaterialLayers() {
      if (this.schematicCells != null && this.targetFluidItems != null && mc.world != null) {
         if (this.builderReclassifiedObject == this.schematicCells && this.cellsSchematicValue == this.confirmSlowCount && this.moduleTick - this.lastTickCellsSchematic < 200) {
            return this.cellsSchematicLayerList;
         } else {
            TreeMap<Integer, HashMap<Item, Integer>> treeMap = new TreeMap<>();
            boolean flag = this.multiplayer.isEnabled() && this.multiLeaving.isHostMulti8();
            int min2 = Math.min(this.schematicCells.size(), this.targetFluidItems.size());

            for (int n = 0; n < min2; n++) {
               BlockState blockState = this.targetFluidItems.get(n);
               Item item = getItemForBlockState(blockState);
               if (item != Items.AIR) {
                  BlockPos blockPos = this.schematicCells.get(n);
                  BlockState blockState2 = mc.world.getBlockState(blockPos);
                  if ((
                        blockState2.getBlock() == blockState.getBlock()
                           ? !this.isPlacedStateAcceptable(blockPos, blockState)
                           : blockState2.isAir() || blockState2.isReplaceable() || this.cells.contains(blockPos.asLong())
                     )
                     && (!flag || this.multiLeaving.canHostMulti(blockPos.getX(), blockPos.getY(), blockPos.getZ()))) {
                     treeMap.computeIfAbsent(blockPos.getY(), integer -> new HashMap<>()).merge(item, 1, Integer::sum);
                  }
               }
            }

            ArrayList<CountsLateUtils.Layer<Item>> arrayList = new ArrayList<>(treeMap.size());

            for (Entry<Integer, HashMap<Item, Integer>> entry : treeMap.entrySet()) {
               arrayList.add(new CountsLateUtils.Layer<>(entry.getKey(), entry.getValue()));
            }

            this.cellsSchematicLayerList = arrayList;
            this.lastTickCellsSchematic = this.moduleTick;
            this.cellsSchematicValue = this.confirmSlowCount;
            this.builderReclassifiedObject = this.schematicCells;
            return arrayList;
         }
      } else {
         return List.of();
      }
   }

   private boolean isAdjacentToEnclosedFluid(BlockPos pos) {
      if (this.schematicCells != null && this.targetFluidItems != null) {
         if (this.cachedSchematicCells != this.schematicCells || this.cachedBlockValue != this.blockValue) {
            this.cachedSchematicCells = this.schematicCells;
            this.cachedBlockValue = this.blockValue;
            this.autoBuilderFlags = null;
            int min = Integer.MAX_VALUE;
            int maxValue2 = Integer.MAX_VALUE;
            int intersectsCenterBound = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            int minValue2 = Integer.MIN_VALUE;
            int aggroPreemptBound = Integer.MIN_VALUE;

            for (BlockPos blockPos : this.schematicCells) {
               min = Math.min(min, blockPos.getX());
               maxValue2 = Math.min(maxValue2, blockPos.getY());
               intersectsCenterBound = Math.min(intersectsCenterBound, blockPos.getZ());
               max = Math.max(max, blockPos.getX());
               minValue2 = Math.max(minValue2, blockPos.getY());
               aggroPreemptBound = Math.max(aggroPreemptBound, blockPos.getZ());
            }

            if (min > max) {
               return false;
            }

            min--;
            intersectsCenterBound--;
            max++;
            minValue2++;
            aggroPreemptBound++;
            int n5 = minValue2 - maxValue2 + 1;
            int n6 = aggroPreemptBound - intersectsCenterBound + 1;
            long l = (long)(max - min + 1) * n5 * n6;
            if (l > 1000000L) {
               return false;
            }

            boolean[] flags = new boolean[(int)l];
            ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();

            for (int min3 = min; min3 <= max; min3++) {
               for (int n2 = maxValue2; n2 <= minValue2; n2++) {
                  for (int n = intersectsCenterBound; n <= aggroPreemptBound; n++) {
                     if (min3 == min || min3 == max || n == intersectsCenterBound || n == aggroPreemptBound || n2 == minValue2) {
                        BlockPos blockPos2 = new BlockPos(min3, n2, n);
                        if (this.isFluidTargetBlock(blockPos2)) {
                           flags[((min3 - min) * n5 + (n2 - maxValue2)) * n6 + (n - intersectsCenterBound)] = true;
                           arrayDeque.add(blockPos2);
                        }
                     }
                  }
               }
            }

            while (!arrayDeque.isEmpty()) {
               BlockPos poll4 = arrayDeque.poll();

               for (Direction direction : Direction.values()) {
                  BlockPos offset3 = poll4.offset(direction);
                  if (offset3.getX() >= min
                     && offset3.getX() <= max
                     && offset3.getY() >= maxValue2
                     && offset3.getY() <= minValue2
                     && offset3.getZ() >= intersectsCenterBound
                     && offset3.getZ() <= aggroPreemptBound) {
                     int n4 = ((offset3.getX() - min) * n5 + (offset3.getY() - maxValue2)) * n6 + (offset3.getZ() - intersectsCenterBound);
                     if (!flags[n4] && this.isFluidTargetBlock(offset3)) {
                        flags[n4] = true;
                        arrayDeque.add(offset3);
                     }
                  }
               }
            }

            this.autoBuilderFlags = flags;
            this.schematicMinX = min;
            this.schematicMinY = maxValue2;
            this.boundsMinZ = intersectsCenterBound;
            this.boundsMaxX = max;
            this.schematicMaxY = minValue2;
            this.schematicMaxZ = aggroPreemptBound;
         }

         if (this.autoBuilderFlags == null) {
            return false;
         } else {
            int n7 = this.schematicMaxY - this.schematicMinY + 1;
            int n8 = this.schematicMaxZ - this.boundsMinZ + 1;
            boolean flag = false;

            for (Direction direction2 : Direction.values()) {
               BlockPos offsetPos = pos.offset(direction2);
               if (this.isFluidTargetBlock(offsetPos)) {
                  if (offsetPos.getX() < this.schematicMinX
                     || offsetPos.getX() > this.boundsMaxX
                     || offsetPos.getY() < this.schematicMinY
                     || offsetPos.getY() > this.schematicMaxY
                     || offsetPos.getZ() < this.boundsMinZ
                     || offsetPos.getZ() > this.schematicMaxZ
                     || this.autoBuilderFlags[((offsetPos.getX() - this.schematicMinX) * n7 + (offsetPos.getY() - this.schematicMinY)) * n8 + (offsetPos.getZ() - this.boundsMinZ)]) {
                     return false;
                  }

                  flag = true;
               }
            }

            return flag;
         }
      } else {
         return false;
      }
   }

   private boolean canStartCatwalkAtLevel(int value) {
      if (this.useTemporaryBlocks.isEnabled()
         && this.schematicCells != null
         && mc.world != null
         && mc.player != null
         && value != Integer.MIN_VALUE) {
         if (this.layerAccessTowerBaseY != Integer.MIN_VALUE && !this.deckMicroMoves.isProbingExitingConfirmed() && !this.hasActiveBlockersStep()) {
            long familiesEpochTime55 = this.eventsFamilies.getFamiliesEpochTime();
            if (this.schematicScanIndex > 0 && this.autoBuilderValue != this.schematicScanStamp) {
               value = this.schematicLastMinValue;
               familiesEpochTime55 = this.schematicScanStamp;
            }

            if (this.autoBuilderValue == familiesEpochTime55 && this.schematicLastMinValue == value) {
               return false;
            } else {
               BlockPos feetBlockPos = this.getFeetBlockPos();
               if (this.schematicScanStamp != familiesEpochTime55 || this.schematicLastMinValue != value) {
                  this.schematicScanStamp = familiesEpochTime55;
                  this.schematicLastMinValue = value;
                  this.schematicScanIndex = 0;
                  this.schematicBlockPosList.clear();
                  this.schematicDoubleMap.clear();
               }

               if (this.schematicScanIndex < this.schematicCells.size()) {
                  int min2 = Math.min(this.schematicCells.size(), this.schematicScanIndex + 256);

                  for (int n = this.schematicScanIndex; n < min2; n++) {
                     BlockPos pos = this.schematicCells.get(n);
                     if (this.completionMissionMap.containsKey(pos.asLong())
                        && pos.getY() <= value
                        && pos.getY() >= value - 3
                        && this.isOpenCompletionCellAboveBase(pos)) {
                        List<BlockPos> list = this.getSortedHorizontalCandidates(pos, feetBlockPos);
                        if (!list.isEmpty()) {
                           this.schematicBlockPosList.add(pos);
                           this.schematicDoubleMap.put(pos.asLong(), list.get(0).up().getSquaredDistance(feetBlockPos));
                           this.schematicBlockPosList.sort(Comparator.comparingDouble(blockPosx -> this.schematicDoubleMap.get(blockPosx.asLong())));

                           while (this.schematicBlockPosList.size() > 4) {
                              BlockPos blockPos = this.schematicBlockPosList.remove(this.schematicBlockPosList.size() - 1);
                              this.schematicDoubleMap.remove(blockPos.asLong());
                           }
                        }
                     }
                  }

                  this.schematicScanIndex = min2;
                  if (this.schematicScanIndex < this.schematicCells.size()) {
                     return false;
                  }
               }

               boolean flag = false;

               for (int n3 = 0; n3 < this.schematicBlockPosList.size(); n3++) {
                  if (this.canCatwalkWalk(this.schematicBlockPosList.get(n3), feetBlockPos, n3 == 0)) {
                     this.autoBuilderValue = familiesEpochTime55;
                     return true;
                  }

                  flag |= this.catwalkWalkFlag;
               }

               if (flag) {
                  return false;
               } else {
                  this.autoBuilderValue = familiesEpochTime55;
                  return false;
               }
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

