   private void selectStaticStandBatch(BlockPos pos, BlockPos pos2) {
      if (mc.world != null && this.schematicCells != null && this.moduleTick >= this.selectPassesReadyTick) {
         long l = this.selectPasses.getNanoTime();

         try {
            BlockViewHelper blockViewHelper = new BlockViewHelper(mc.world);
            BlockStateUtilsNodes.WorkSource workSource = this.getCachedWorkSource();
            Nodes nodes = BlockStateUtilsNodes.getDirBatch(blockViewHelper, workSource, pos2.asLong());
            if (nodes == null || nodes.getValue() < 2) {
               return;
            }

            ArrayList<Step> arrayList = new ArrayList<>();
            arrayList.add(new Step(pos2.asLong(), pos.asLong()));

            for (Step step : nodes.getCopyOf()) {
               if (step.target() != pos.asLong() && !this.builtCellSet.contains(step.target())) {
                  arrayList.add(step);
               }
            }

            if (arrayList.size() >= 2) {
               this.expectedConfirms = new Nodes(
                  com.corz.client.utils.Nodes.Kind.STATIC_STAND_BATCH, arrayList, List.of(), 0, BlockStateUtilsNodes.getDistance3d(arrayList.size(), 0, 0)
               );
               this.cursor = 0;
               this.programDispatchableValue = 0;
               this.sessionStartConfirms = this.confirms;
               this.confirmsValue = this.moduleTick;
               this.confirmsCount++;
               this.maxConfirmsSeen = Math.max(this.maxConfirmsSeen, arrayList.size());
               this.handleProgramsEnded(this.confirmsValue, this.expectedConfirms.getRunSideType().name(), arrayList.size());
               this.logDebugMessage(
                  "\u00a7a[ProgramSelect]\u00a7r id="
                     + this.confirmsValue
                     + " kind="
                     + this.expectedConfirms.getRunSideType()
                     + " members="
                     + arrayList.size()
                     + " entryStand="
                     + pos2.toShortString()
                     + " expectedConfirms="
                     + this.expectedConfirms.getValue()
                     + " expectedSeconds="
                     + String.format("%.1f", this.expectedConfirms.getAmount())
               );
               return;
            }
         } finally {
            this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.SELECT_TOTAL, l);
         }
      }
   }

