   @Override
   protected void onReset() {
      this.moduleTick++;
      this.updateAggressiveRotationState();
      if (!this.worthUnlocksMap.isEmpty() && mc.world != null) {
         this.worthUnlocksMap.entrySet().removeIf(entry -> {
            if (this.moduleTick - entry.getValue() > 40) {
               this.worthFewerMap.remove(entry.getKey());
               return true;
            } else {
               BlockPos blockPos = BlockPos.fromLong(entry.getKey());
               if (mc.world.getBlockState(blockPos).getBlock() != Blocks.DIRT) {
                  return false;
               } else {
                  this.confirmTemporaryDirtPlacement(blockPos);
                  return true;
               }
            }
         });
      }

      needSneakFlag = this.silentPistonPlace.isEnabled();
      iIiActive = !this.isIntegratedServerActive();
      this.eventsFamilies.recordNonEvent(NonEvent.TICK);
      corzGapActive = false;
      this.ownerSneakActive = false;
      this.iIiSneakOwner = AutoBuilder.SneakOwner.NONE;
      long nanoTime5 = System.nanoTime();
      this.plannerTicks.handleCatchupPlanner(nanoTime5, this.sessionResetValue);
      this.sessionResetValue = 0;
      long nanoTime6 = this.selectPasses.getNanoTime();

      try {
         this.tickBuilder();
      } finally {
         this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.TICK_TOTAL, nanoTime6);
         this.updateSilentAimRotation();
         this.updateSneakOwnership();
         this.updateNodePathJumpKey();
         long nanoTime3 = System.nanoTime();
         this.plannerTicks.handleMaxTime(nanoTime3);
         this.slowTickTime = this.slowTickTime + Math.max(0L, nanoTime3 - nanoTime5);
         long l4 = (nanoTime3 - nanoTime5) / 1000000L;
         if (l4 >= 25L && this.moduleTick - this.slowTickValue > 5) {
            this.slowTickValue = this.moduleTick;
            this.logDebugMessage(
               "\u00a7c[SlowTick]\u00a7r "
                  + l4
                  + "ms state="
                  + this.state2Builder
                  + " placed="
                  + this.confirmSlowCount
                  + "/"
                  + this.slowCellsValue
                  + " cells="
                  + (this.schematicCells == null ? 0 : this.schematicCells.size())
                  + " catchup="
                  + this.plannerTicks.isCatchupPlannerActive()
            );
         }

         if ((this.plannerTicks.isCatchupPlannerActive() || l4 >= 25L) && this.moduleTick - this.catchupNoneValue >= 20) {
            this.catchupNoneValue = this.moduleTick;
            this.logDebugMessage(
               "\u00a78[TickDiscipline]\u00a7r " + this.plannerTicks.formatRootFlag(this.intervalReportTimer.getTime(this.moduleTick), 0, this.iIiCount, this.getStateDebugLabel())
            );
         }

         if ((this.iIiCount > 1 || this.plannerTicks.isTimeFlag() || this.moduleTick - this.lastTickSinceJump <= 40) && this.moduleTick - this.lastTickIIi >= 10) {
            this.lastTickIIi = this.moduleTick;
            this.logDebugMessage(
               "\u00a78[MovementCadence]\u00a7r "
                  + this.plannerTicks.formatRootFlag(this.iIiCount, 0, this.moduleTick - this.lastTickSinceJump, this.correctionServerAmount)
            );
         }

         if (this.iIiCount > 0) {
            this.obfuscatedCallCount++;
            this.tickDisciplineTotal = this.tickDisciplineTotal + this.iIiCount;
         }

         if (this.iIiCount > this.iIiValue) {
            this.iIiValue = this.iIiCount;
         }

         this.iIiCount = 0;
      }
   }

   private void tickPerchDrop() {
      if (mc.player != null && this.moduleTick - this.recoverPerchValue <= 160) {
         BlockPos blockPos = this.getFeetBlockPos();
         if (blockPos.getY() < this.perchDropBlockPos.getY()) {
            this.updatePressedOptions2();
            if (mc.player.isOnGround()) {
               this.offset = null;
               this.perchDropBlockPos = null;
               this.handleRetiredCell(Event.REACHABLE_COMPONENT_EXPANDED);
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "perch drop landed");
            }
         } else {
            boolean flag = blockPos.equals(this.perchDropBlockPos);
            BlockPos blockPos2 = flag ? this.offset : this.perchDropBlockPos;
            double d = blockPos2.getX() + 0.5 - mc.player.getX();
            double d2 = blockPos2.getZ() + 0.5 - mc.player.getZ();
            this.applyYawOffsetRotation((float)Math.toDegrees(Math.atan2(-d, d2)), this.getSinePulseValue());
            this.setOwnerSneak(!flag);
            mc.player.setSprinting(false);
            mc.options.forwardKey.setPressed(true);
         }
      } else {
         this.logDebugMessage("\u00a7e[Recover]\u00a7r perch drop timed out");
         this.offset = null;
         this.perchDropBlockPos = null;
         this.updatePressedOptions2();
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "perch drop timeout");
      }
   }

