   private BlockPos getCachedBlueprintPosition(BlockPos pos, BlockState state, double blueprintValue) {
      this.clearBlueprintCachesIfLarge();
      long l = this.getSealsPlacement(pos, 6510615555426900570L);
      Long longValue = this.blueprintPositionMap.get(l);
      if (longValue != null) {
         this.containsLong = this.blueprintSet.contains(l);
         this.containsBlueprint = this.blueprintPositionSet.contains(l);
         return longValue == Long.MIN_VALUE ? null : BlockPos.fromLong(longValue);
      } else {
         this.containsLong = false;
         this.containsBlueprint = false;
         BlockPos squaredDistance = this.getSquaredDistance(pos, state, blueprintValue);
         this.blueprintPositionMap.put(l, squaredDistance == null ? Long.MIN_VALUE : squaredDistance.asLong());
         if (this.containsLong) {
            this.blueprintSet.add(l);
         }

         if (this.containsBlueprint) {
            this.blueprintPositionSet.add(l);
         }

         return squaredDistance;
      }
   }

