   private void tickOrientedBlockPlacement(BlockState state) {
      mc.options.forwardKey.setPressed(false);
      mc.options.backKey.setPressed(false);
      mc.options.leftKey.setPressed(false);
      mc.options.rightKey.setPressed(false);
      mc.player.setSprinting(false);
      if (this.staleCount <= 40 && this.isOnNonSlipperyGround() && this.applyCounterStrafeKeys(0.03)) {
         this.setOwnerSneak(this.bodyYieldsFlag);
      } else {
         switch (this.getBodyClearance(this.currentTargetPos)) {
            case NUDGING:
               return;
            case ILLEGAL:
               this.rejectPoseNoLineOfSight(null, "STAND_BODY_ILLEGAL: target overlaps body - stepping away");
               return;
            default:
               boolean flag = this.safeSneak.isEnabled()
                  && (WalkRouteFinder.hasOpenNeighborInWorld(this.getFeetBlockPos()) || this.currentTargetPos.getY() < this.getFeetBlockPos().getY());
               this.setOwnerSneak(flag || this.partnerClickFlag);
               Vec3d vec3d = mc.player.getEyePos();
               double d = this.reachSetting.getValue();
               double d2 = d * d;
               if (vec3d.squaredDistanceTo(Vec3d.ofCenter(this.currentTargetPos)) > d2) {
                  this.onExecutorOutOfReach(vec3d, d);
               } else {
                  this.reachExecutorValue = 0;
                  AutoBuilder.OrientedAim orientedAim = this.getAimForInventoryItem(this.currentTargetPos, state, vec3d, d);
                  if (orientedAim == null) {
                     if (this.staleCount > 20) {
                        this.rejectPoseNoLineOfSight(null, "no oriented aim yields the wanted state from here");
                     }
                  } else {
                     boolean flaggedBlockState = isFlaggedBlockState(mc.world.getBlockState(orientedAim.hit().getBlockPos()));
                     this.partnerClickFlag = flaggedBlockState;
                     this.bodyYieldsFlag = flaggedBlockState || flag;
                     this.setOwnerSneak(this.bodyYieldsFlag);
                     this.setSneakOwner(flaggedBlockState ? AutoBuilder.SneakOwner.CONTAINER_GUARD : AutoBuilder.SneakOwner.NONE);
                     if (!flaggedBlockState || this.builderValue >= 2) {
                        float[] fs = this.computeAimRotation(orientedAim.yaw(), orientedAim.pitch());
                        float f = fs[0];
                        float f2 = fs[1];
                        float max3 = Math.max(Math.abs(MathHelper.wrapDegrees(f - orientedAim.yaw())), Math.abs(f2 - orientedAim.pitch()));
                        if (max3 > this.rotationAlignTolerance.getValue()) {
                           if (this.staleCount > 40) {
                              this.handleBlockDefer("can't face oriented block - skipping for now");
                           }
                        } else if (this.staleCount >= this.rotationSettleTicks.getValue()) {
                           if (vec3d.squaredDistanceTo(this.eyePos) > this.getMovementEpsilon()) {
                              this.eyePos = vec3d;
                              if (this.staleCount > 40) {
                                 this.handleBlockDefer("eye never settled - skipping for now");
                              }
                           } else {
                              this.eyePos = vec3d;
                              BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d, f, f2, d);
                              boolean flag3 = blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                                 && blockHitResult.getBlockPos().equals(orientedAim.hit().getBlockPos())
                                 && blockHitResult.getSide() == orientedAim.hit().getSide();
                              if (this.strictRaytrace.isEnabled() && !flag3) {
                                 if (this.staleCount > 20) {
                                    this.rejectPoseNoLineOfSight(orientedAim.hit().getSide(), "no line of sight to oriented face");
                                 }
                              } else {
                                 this.blockHitResultEgressStand = flag3 ? blockHitResult : orientedAim.hit();
                                 this.transitionToState(
                                    isFlaggedBlockState(mc.world.getBlockState(this.blockHitResultEgressStand.getBlockPos()))
                                       ? AutoBuilder.State.SNEAK_SETTLE
                                       : AutoBuilder.State.PLACE_BLOCK,
                                    "oriented aligned"
                                 );
                              }
                           }
                        }
                     }
                  }
               }
         }
      }
   }

   public void handleChestPlayer(TickProgress tickProgress) {
      if (this.showRestockContainers.isEnabled() && this.showRestockLabels.isEnabled() && mc.world != null && mc.player != null) {
         List<DimensionPosData> list = this.restockSources.getEntriesSnapshot();
         if (!list.isEmpty()) {
            String dimensionPosText = mc.world.getRegistryKey().getValue().toString();
            double d7 = this.restockRenderDistance.getValue() * this.restockRenderDistance.getValue();
            double d8 = mc.player.getX();
            double d9 = mc.player.getY();
            double d10 = mc.player.getZ();
            MatrixStack matrixStack = new MatrixStack();
            CorzClient.fontManager.setMatrixStack(matrixStack);
            Set<Long> set = this.getPositionsForDimension(list, dimensionPosText);

            for (DimensionPosData dimensionPosData : list) {
               if (dimensionPosData.dimension().equals(dimensionPosText)) {
                  AutoBuilder.RestockDraw restockDraw = this.getChestTrapped(dimensionPosData, set);
                  if (restockDraw != null) {
                     BlockPos blockPos = restockDraw.lo();
                     BlockPos hi2 = restockDraw.hi();
                     double d = (blockPos.getX() + hi2.getX()) / 2.0 + 0.5;
                     double d2 = (blockPos.getZ() + hi2.getZ()) / 2.0 + 0.5;
                     double d3 = d - d8;
                     double d4 = blockPos.getY() + 0.5 - d9;
                     double d5 = d2 - d10;
                     double d6 = d3 * d3 + d4 * d4 + d5 * d5;
                     if (!(d6 > d7)) {
                        Vec3d vec3d = VertexConsumerUtilsVector.getWindowFramebuffer(new Vec3d(d, blockPos.getY() + 1.2, d2));
                        if (vec3d != null && !(vec3d.z < 0.0) && !(vec3d.z > 1.0)) {
                           String string = restockDraw.doubleChest() ? "Double Chest" : dimensionPosData.type().displayName;
                           this.renderRestockContainerLabel(matrixStack, string, (float)vec3d.x, (float)vec3d.y, Math.sqrt(d6));
                        }
                     }
                  }
               }
            }
         }
      }
   }

