   private BlockPos findFreeNeighborTowardTarget(BlockPos pos, BlockPos pos2) {
      if (Math.abs(pos.getY() - pos2.getY()) <= 5
         && Math.abs(pos.getX() - pos2.getX()) <= 8
         && Math.abs(pos.getZ() - pos2.getZ()) <= 8) {
         BlockPos offset = null;
         double maxValue2 = Double.MAX_VALUE;

         for (Direction direction : Type.HORIZONTAL) {
            BlockPos blockPos = pos.offset(direction);
            if (this.getSchematicCells(blockPos) < 0
               && !this.cellTemporarySet.contains(blockPos.asLong())
               && !blockPos.equals(pos2)
               && !blockPos.equals(pos2.up())) {
               BlockState blockState = mc.world.getBlockState(blockPos);
               if ((blockState.isAir() || blockState.isReplaceable())
                  && !this.hasSolidNeighborToPlaceOn(blockPos)
                  && this.describeObserverPulseHazard(blockPos) == null
                  && !this.isFacedByPiston(blockPos)
                  && !this.isSequenceRecentlyAttempted(pos, blockPos)) {
                  double d = blockPos.getSquaredDistance(pos2);
                  if (blockPos.getX() == pos2.getX() && blockPos.getZ() == pos2.getZ()) {
                     d += 16.0;
                  }

                  if (d < maxValue2) {
                     maxValue2 = d;
                     offset = blockPos;
                  }
               }
            }
         }

         return offset;
      } else {
         return null;
      }
   }

