   private int getInteractionStepsToMatch(BlockPos pos, BlockState state) {
      BlockState blockState2 = mc.world.getBlockState(pos);
      if (!blockState2.isOf(state.getBlock())) {
         return 0;
      } else {
         IntProperty intProperty = Properties.DELAY;
         EnumProperty<ComparatorMode> enumProperty = Properties.COMPARATOR_MODE;
         if (state.getBlock() instanceof RepeaterBlock && blockState2.contains(intProperty) && state.contains(intProperty)) {
            return BuilderAutoUtils.getCyclicDifferenceModForInt(blockState2.get(intProperty), state.get(intProperty));
         } else if (state.getBlock() instanceof ComparatorBlock && blockState2.contains(enumProperty) && state.contains(enumProperty)) {
            return BuilderAutoUtils.getMismatchBit(blockState2.get(enumProperty) == ComparatorMode.SUBTRACT, state.get(enumProperty) == ComparatorMode.SUBTRACT);
         } else {
            BooleanProperty booleanProperty = Properties.OPEN;
            BooleanProperty powered2 = Properties.POWERED;
            if (!(state.getBlock() instanceof FenceGateBlock)
               || !blockState2.contains(booleanProperty)
               || !state.contains(booleanProperty)
               || blockState2.contains(powered2) && blockState2.get(powered2)) {
               if (state.getBlock() instanceof LeverBlock && blockState2.contains(powered2) && state.contains(powered2)) {
                  return BuilderAutoUtils.getInequalityBit(blockState2.get(powered2), state.get(powered2));
               } else {
                  IntProperty candles = Properties.CANDLES;
                  return state.getBlock() instanceof CandleBlock
                        && blockState2.contains(candles)
                        && state.contains(candles)
                        && mc.player != null
                        && mc.player.getMainHandStack().isOf(state.getBlock().asItem())
                     ? Math.max(0, state.get(candles) - blockState2.get(candles))
                     : 0;
               }
            } else {
               return BuilderAutoUtils.getDifferenceBit(blockState2.get(booleanProperty), state.get(booleanProperty));
            }
         }
      }
   }

