   private boolean isPlainFullCubeBlock(BlockPos pos, BlockState state) {
      if (state == null) {
         return false;
      } else {
         Block block = state.getBlock();
         if (isStateSensitiveBlock(state) || matchesBlockStateRule(state) || hasFluidState(state) || isFlaggedBlockState(state)) {
            return false;
         } else if (block instanceof AbstractSignBlock || block instanceof ChestBlock) {
            return false;
         } else if (getDirectionForBlockState(state) != null || getFacingDirectionOrNull(state) != null || getBlockRotationValue(state) != null || getAxis(state) != null) {
            return false;
         } else if (isPlaceableWithoutSpecialSneak(state) || isSneakRequiredBlock(state) || isOrientationDependentBlock(state) || this.getRotateYcounterclockwise(pos, state) != null) {
            return false;
         } else if (state != block.getDefaultState()) {
            return false;
         } else {
            VoxelShape voxelShape = state.getCollisionShape(mc.world, pos);
            return !voxelShape.isEmpty()
               && voxelShape.getMin(Axis.X) <= 1.0E-4
               && voxelShape.getMax(Axis.X) >= 0.9999
               && voxelShape.getMin(Axis.Y) <= 1.0E-4
               && voxelShape.getMax(Axis.Y) >= 0.9999
               && voxelShape.getMin(Axis.Z) <= 1.0E-4
               && voxelShape.getMax(Axis.Z) >= 0.9999;
         }
      }
   }

