   private boolean tryRunRemainingSideStrategy(BlockPos pos, Vec3d vec, double remainingChangedValue) {
      if (this.sideRuns.isEnabled() && this.sideRunSkippedDraining == null && !this.arrivedLaneFlag && this.remaining != null) {
         if (this.moduleTick - this.lastTickRemainingChanged < 40 && this.changedPlanCountRemainingCha == changedPlanCount) {
            return false;
         } else {
            this.lastTickRemainingChanged = this.moduleTick;
            this.changedPlanCountRemainingCha = changedPlanCount;
            ArrayList<MaterialVisibleUtils.Candidate> arrayList = new ArrayList<>();

            for (long l : this.remaining.frontiersByCell.keySet()) {
               arrayList.add(new MaterialVisibleUtils.Candidate(l, pos.asLong(), 0, 0.0, 0, 0, 0, 0, false, 0L, false));
            }

            LaneRowUtils.Run run = this.findBestLaneRun(pos, null, arrayList);
            if (run == null) {
               return false;
            } else {
               LaneRowUtils.Run laneEnd = this.orientLaneRunToward(run, pos);
               com.corz.client.utils.HeavyBatchUtils.Decision decision = this.chooseRunPlacementDecision(laneEnd, pos, 0, true);
               this.logDebugMessage(
                  "\u00a7d[BuildStrategy]\u00a7r cluster="
                     + BlockPos.fromLong(laneEnd.members().get(0).target()).toShortString()
                     + " deckActive=true "
                     + decision.describeDecision()
               );
               if (decision.selected() != null && HeavyBatchUtils.canRunSide(decision.selected().kind())) {
                  List<BlockPos> list = this.getPathToLaneStart(laneEnd, pos);
                  if (list == null) {
                     return false;
                  } else if (!this.evaluateRunPreflight(laneEnd, decision).isFlag()) {
                     return false;
                  } else {
                     this.exitDeckMission("strategy: " + decision.selected().kind() + " wins the frontier (" + laneEnd.getMembers() + " members)");
                     if (!this.commitSideRun(laneEnd, pos, decision, list)) {
                        return false;
                     } else {
                        this.remainingChangedCount++;
                        this.remainingChangedAmount = this.remainingChangedAmount + decision.ticksSaved();
                        return true;
                     }
                  }
               } else {
                  return false;
               }
            }
         }
      } else {
         return false;
      }
   }

   private long computeBuildStateHash() {
      BlockPos blockPos = this.getFeetBlockPos();
      long l = SHARED_HASH_OPEN.hashOpenCellsInRadius(blockPos.getX(), blockPos.getY(), blockPos.getZ(), 32) * 31L
         + SHARED_HASH_OPEN.hashOpenCellsInRadius(blockPos.getX(), this.layer, blockPos.getZ(), 32);
      long layerHashValue = l * 31L + this.packLayerStats();
      return HeldStayUtils.hashLayerState(
         layerHashValue,
         this.layer,
         this.anchor,
         blockPos.asLong(),
         this.cooldown,
         this.moduleTick,
         this.deferCount.size(),
         this.entries.size(),
         this.moduleTick < this.elevatedDeckValue,
         this.computeInventoryHash(),
         this.cells.size()
      );
   }

   private boolean executeCompletionStep(SupportStandUtils.Step step4, BlockPos longValue, Vec3d vec, double missionShortValue, double missionShortLimit) {
      BlockPos blockPos6 = step4.stand() == null ? null : toBlockPos(step4.stand());
      BlockPos blockPos7 = toBlockPos(step4.cell());
      switch (step4.op()) {
         case DIRT:
            SupportStandUtils.Step nextPlaceOrRemoveStep = this.getNextPlaceOrRemoveStep();
            BlockPos pos = nextPlaceOrRemoveStep != null ? toBlockPos(nextPlaceOrRemoveStep.cell()) : blockPos7;
            this.blockPos3SupportConstructive = blockPos7;
            this.blockPos2SupportConstructive = pos;
            this.supportFloorValue = 0;
            if (step4.intent() != null) {
               SupportStandUtils.Intent intent = step4.intent();
               this.missionShortBlockHitResult = new BlockHitResult(
                  new Vec3d(intent.hx(), intent.hy(), intent.hz()),
                  Direction.values()[Math.max(0, Math.min(5, intent.face()))],
                  toBlockPos(intent.support()),
                  false
               );
               this.executingSupportFlag = intent.sneak();
               this.blockPosMissionShort = toBlockPos(intent.stand());
            } else {
               this.missionShortBlockHitResult = null;
               this.blockPosMissionShort = null;
            }

            this.name = "MISSION_SUPPORT";
            if (!this.supportMissionMap.containsKey(blockPos7.asLong())) {
               long l = ++this.supportAttachmentTime;
               this.supportMissionMap
                  .put(blockPos7.asLong(), new DepPurpose(l, com.corz.client.utils.DepPurpose.Purpose.ATTACHMENT, pos.asLong(), blockPos7.asLong(), this.moduleTick));
            }

            this.currentTargetPos = pos;
            this.supportAccessValue = this.getSchematicCells(pos);
            this.oppositeAxis = null;
            this.direction = null;
            this.floatValue = null;
            this.missionShortAxis = null;
            this.path.clear();
            this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.SUPPORT, 1);
            this.setSupportText("COMPLETION_MISSION", "dirt " + blockPos7.toShortString() + " (" + step4.why() + ")");
            this.transitionToState(AutoBuilder.State.TEMP_SUPPORT, "mission dirt");
            return true;
         case PILLAR:
            if (this.canColumnsBanned(blockPos7)) {
               this.onMissionStepFailed(step4, "pillar base " + blockPos7.toShortString() + " is banned in the shared column ledger");
               return true;
            } else {
               if (!longValue.equals(blockPos7)) {
                  return this.startCompletionMissionMove(blockPos7, longValue, "walk to pillar base");
               }

               this.blockPos3BridgeCell = longValue;
               this.resetPillarTracking();
               this.elevatedPillarItems.clear();
               this.pillarTargetY = blockPos6.getY();
               this.missionShortValue = blockPos6.getY();
               this.pillarDirtValue = blockPos6.getY();
               this.standClimbFlag = false;
               SupportStandUtils.Step step = this.getNextPlaceOrRemoveStep();
               if (step != null) {
                  this.currentTargetPos = toBlockPos(step.cell());
                  this.supportAccessValue = this.getSchematicCells(this.currentTargetPos);
               }

               this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.PILLAR, 1);
               this.setSupportText("COMPLETION_MISSION", "pillar x" + step4.count() + " to " + blockPos6.toShortString());
               this.transitionToState(AutoBuilder.State.SCAFFOLD_UP, "mission pillar");
               return true;
            }
         case REMOVE_DIRT:
            if (blockPos6 == null || longValue.equals(blockPos6) || vec.squaredDistanceTo(Vec3d.ofCenter(blockPos7)) <= missionShortLimit && this.isWithinReachFromEye(blockPos7)) {
               this.blockPos2Exit = blockPos7;
               this.cleanupStaleItems = null;
               this.cleanupExitFlag = false;
               this.setSupportText(this.isCompletionPhaseActive() ? "COMPLETION_MISSION" : "CLEANUP_PASS", "remove dirt " + blockPos7.toShortString());
               this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "mission remove dirt");
               return true;
            } else {
               return this.startCompletionMissionMove(blockPos6, longValue, "walk to remove " + blockPos7.toShortString());
            }
         case DIG_DOWN:
            BlockPos up4 = blockPos7.up();
            if (!longValue.equals(up4)) {
               return this.startCompletionMissionMove(up4, longValue, "walk onto own column");
            } else {
               if (mc.player.isOnGround() && this.missionShortLastPosKey != blockPos7.asLong() && this.cells.contains(blockPos7.asLong())) {
                  boolean flag2 = false;

                  for (int n2 = -1; n2 <= 1 && !flag2; n2++) {
                     for (int n = -1; n <= 1 && !flag2; n++) {
                        BlockPos add3 = blockPos7.add(n2, 0, n);
                        flag2 = (n2 != 0 || n != 0)
                           && this.isInsidePlayerFootprint(add3)
                           && !mc.world.getBlockState(add3).getCollisionShape(mc.world, add3).isEmpty();
                     }
                  }

                  if (flag2) {
                     if (this.longMissionShort != blockPos7.asLong()) {
                        this.longMissionShort = blockPos7.asLong();
                        this.workingPlayerValue = Long.MIN_VALUE;
                     }

                     AutoBuilder.Recentre recentre = this.centrePlayerOnBlock(up4);
                     if (recentre == AutoBuilder.Recentre.WORKING) {
                        if (!this.digMissionFlag) {
                           this.transitionToState(AutoBuilder.State.SELECT_TARGET, "mission dig-down");
                        }

                        return true;
                     }

                     if (recentre == AutoBuilder.Recentre.FAILED) {
                        this.missionShortLastPosKey = blockPos7.asLong();
                     }
                  }
               }

               if (!this.tryDescendThroughOwnedDirt()) {
                  this.setBudgetExhaustedReason("dig-down refused at " + blockPos7.toShortString());
                  return false;
               }

               if (!this.digMissionFlag) {
                  this.transitionToState(AutoBuilder.State.SELECT_TARGET, "mission dig-down");
               }

               return true;
            }
         case WALK:
            boolean missionShortFlag;
            label140: {
               this.rebuildReachableComponent();
               if (this.stepIndex > 0 && this.blockers != null && this.stepIndex - 1 < this.blockers.steps().size()) {
                  switch (this.blockers.steps().get(this.stepIndex - 1).op()) {
                     case DIRT:
                     case PILLAR:
                     case DIG_DOWN:
                        missionShortFlag = true;
                        break label140;
                     case REMOVE_DIRT:
                  }
               }

               missionShortFlag = false;
            }

            boolean flag = missionShortFlag;
            if (blockPos6 != null && !flag && this.standRouteTextUnmodifiable.hasEntry(blockPos6.asLong(), this.componentKey)) {
               this.onMissionStepFailed(
                  step4, "no path to planned stand " + blockPos6.toShortString() + " (route certificate FAIL for this component - suppressed before dispatch)"
               );
               return true;
            }

            return this.startCompletionMissionMove(blockPos6, longValue, "walk to stand");
         case BREAK:
            if (this.isRepairAlreadyHandled(blockPos7.asLong())) {
               this.setBudgetExhaustedReason("repair parked: ticket blocked by unchanged dependencies at " + blockPos7.toShortString());
               return false;
            } else {
               com.corz.client.utils.NoneRepair.Decision decision = this.getNoneRepairDecision(
                  blockPos7,
                  "mission_break",
                  mc.world.getBlockState(blockPos7),
                  mc.world.getBlockState(blockPos7),
                  com.corz.client.utils.NoneRepair.Kind.MISSION_BREAK,
                  "MISSION"
               );
               if (!isDispatchOrReopenedDecision(decision)) {
                  this.setBudgetExhaustedReason("repair " + decision + " (blocked) at " + blockPos7.toShortString());
                  return false;
               } else if (vec.squaredDistanceTo(Vec3d.ofCenter(blockPos7)) <= missionShortLimit && this.isWithinReachFromEye(blockPos7)) {
                  this.setRepairTargetPos(blockPos7);
                  this.currentTargetPos = blockPos7;
                  this.supportAccessValue = this.getSchematicCells(blockPos7);
                  this.setSupportText("COMPLETION_MISSION", "break wrong block " + blockPos7.toShortString());
                  this.transitionToState(AutoBuilder.State.STATE_REPAIR, "mission: break wrong block");
                  return true;
               } else {
                  BlockPos blockPos = WalkRouteFinder.findStandPositionWithOffsets(
                     blockPos7,
                     missionShortValue,
                     this.cellTemporarySet,
                     blockPos2x -> this.isWithinReachFromStand(blockPos7, blockPos2x),
                     new WalkRouteFinder.StandStats(),
                     WalkRouteFinder.STAND_Y_OFFSETS_NARROW
                  );
                  if (blockPos != null && !blockPos.equals(longValue)) {
                     return this.startCompletionMissionMove(blockPos, longValue, "walk to break " + blockPos7.toShortString());
                  }

                  this.setBudgetExhaustedReason("no stand can ray-hit " + blockPos7.toShortString());
                  return false;
               }
            }
         case PLACE:
            return this.startPlannedMission(blockPos7, blockPos6, step4.intent(), longValue, vec, missionShortValue, missionShortLimit);
         default:
            return false;
      }
   }

