   private boolean shouldBuyDirt() {
      if (this.complete != AutoBuilder.BuyMode.NONE
         || this.showedBuyText != null
         || this.moduleTick < this.buyAutoValue
         || this.moduleTick < this.buyAutoValues[AutoBuilder.LayerBuyTrigger.DIRT.ordinal()]) {
         return false;
      } else if (this.moduleTick - this.lastModuleTickRunTick < 20) {
         return false;
      } else {
         this.lastModuleTickRunTick = this.moduleTick;
         if (this.getTempDirtPurchaseRequest() == null) {
            return false;
         } else {
            Integer integer = this.freeInventoryMap.get(Items.DIRT);
            if (integer != null && this.moduleTick < integer) {
               return false;
            } else {
               int n = this.buyTempDirt.getValue();
               int min2 = Math.min(n, Math.max(8, Math.min(this.maxLiveTempBlocks.getValue(), n / 2)));
               return this.countItemInInventory(Items.DIRT) < min2;
            }
         }
      }
   }

   private static String getBlockRegistryPath(BlockState state) {
      try {
         return Registries.BLOCK.getId(state.getBlock()).getPath();
      } catch (Exception e) {
         return String.valueOf(state.getBlock());
      }
   }

   private int getMissingItemCount(Item unknownValue) {
      if (this.listingShowedFlag) {
         return Math.max(0, this.buyAutoIntegerMap.getOrDefault(unknownValue, 0) - this.countItemInInventory(unknownValue));
      } else {
         this.updateMaterialAvailability();
         int max = 0;
         int pricingMaterialValue2 = 0;
         if (this.availableLow != null) {
            for (MaxMaterialsUtils.Row<Item> row : this.availableLow.readSelectedItems) {
               if (row.next == unknownValue) {
                  max = row.maxCount;
                  pricingMaterialValue2 = row.pricingMaterialValue;
                  break;
               }
            }
         }

         int n = this.stockpileInChests.isEnabled() ? this.getRestockItemCounts().getOrDefault(unknownValue, 0) : 0;
         int aggroPreemptBound = Math.max(0, max - n);
         if (unknownValue == Items.DIRT && this.buyTempDirt.getValue() > 0 && this.useTemporaryBlocks.isEnabled()) {
            aggroPreemptBound = Math.max(aggroPreemptBound, Math.max(0, pricingMaterialValue2 + this.buyTempDirt.getValue() - this.countItemInInventory(Items.DIRT) - n));
         }

         return aggroPreemptBound;
      }
   }

   private int countUnarmedCompletionCells() {
      int n = 0;

      for (long l : this.completionMissionMap.keySet()) {
         if (!this.machineArmedSet.contains(l)) {
            if (++n > 40) {
               return 0;
            }
         }
      }

      return n;
   }

   private boolean removeNearbyTempBlock(BlockPos pos) {
      if (this.removeTempAfter.isEnabled()
         && this.useTemporaryBlocks.isEnabled()
         && !this.digMissionFlag
         && this.fallRecoveryValue == Integer.MIN_VALUE
         && mc.player != null
         && this.hasUsableBlockItem()) {
         Vec3d vec3d2 = mc.player.getEyePos();
         double d2 = this.reachSetting.getValue();
         double distanceTo = (d2 + 1.0) * (d2 + 1.0);
         double d3 = mc.player.getY();
         BlockPos longValue = null;
         Vec3d offsetMin = null;

         for (long l : this.cells) {
            BlockPos fromLong = BlockPos.fromLong(l);
            if (fromLong.getY() >= pos.getY()
               && !(fromLong.getY() < d3 - 0.5)
               && (fromLong.getX() != pos.getX() || fromLong.getZ() != pos.getZ())
               && !this.cells.contains(fromLong.up().asLong())) {
               double d = l == this.longBlockWorld ? -1.0 : vec3d2.squaredDistanceTo(Vec3d.ofCenter(fromLong));
               if (!(d >= distanceTo)
                  && !this.isCellCoveredOrBlocked(l)
                  && !this.isMissionOwnedCell(l)
                  && !this.isNearIslandAbortColumn(l)
                  && !this.hasAdjacentAirOrObserver(fromLong)
                  && isDirtOrGrassBlock(mc.world.getBlockState(fromLong))) {
                  DepPurpose depPurpose = this.supportMissionMap.get(l);
                  if ((depPurpose == null || this.passesChestFacingCheckAt(depPurpose.owner))
                     && (
                        !this.hasActiveBlockersStep()
                           || !this.getRemainingBlockerSteps()
                              .stream()
                              .anyMatch(
                                 step -> step.intent() != null && step.intent().support() != null && toBlockPos(step.intent().support()).asLong() == l
                                    || step.stand() != null && toBlockPos(step.stand()).down().asLong() == l
                              )
                     )) {
                     int n = 0;
                     BlockPos down2 = fromLong.down();
                     if (this.getSchematicCells(down2) >= 0
                        && !this.cells.contains(down2.asLong())
                        && !mc.world.getBlockState(down2).getCollisionShape(mc.world, down2).isEmpty()
                        && mc.world.getBlockState(down2.down()).getCollisionShape(mc.world, down2.down()).isEmpty()) {
                        down2 = down2.down();
                     }

                     for (BlockPos down = down2;
                        n < 4
                           && (
                              this.cells.contains(down.asLong())
                                 || mc.world.getBlockState(down).getCollisionShape(mc.world, down).isEmpty()
                           );
                        down = down.down()
                     ) {
                        n++;
                     }

                     if (n >= 4) {
                        boolean flag = false;

                        for (Direction direction : Direction.values()) {
                           BlockPos blockPos = fromLong.offset(direction);
                           if (this.getSchematicCells(blockPos) >= 0) {
                              BlockState blockState = mc.world.getBlockState(blockPos);
                              if (!this.passesChestFacingCheckAt(blockPos.asLong())
                                 || !blockState.isFullCube(mc.world, blockPos)
                                 || blockState.getBlock() instanceof FallingBlock) {
                                 flag = true;
                                 break;
                              }
                           }
                        }

                        if (!flag) {
                           Vec3d vec3d = this.findReachablePointOnBlock(fromLong, vec3d2, d2);
                           if (vec3d != null) {
                              longValue = fromLong;
                              offsetMin = vec3d;
                              distanceTo = d;
                           }
                        }
                     }
                  }
               }
            }
         }

         if (longValue == null) {
            return false;
         } else {
            if (this.longBlockWorld == longValue.asLong() && this.moduleTick - this.blockWorldValue <= 10) {
               if (this.moduleTick - this.lastBlockWorldTick > 80) {
                  this.markNoValidStandBackoff(longValue);
                  this.longBlockWorld = Long.MIN_VALUE;
                  return false;
               }
            } else {
               this.longBlockWorld = longValue.asLong();
               this.lastBlockWorldTick = this.moduleTick;
            }

            this.blockWorldValue = this.moduleTick;
            this.lastTickBlockWorld = this.moduleTick;
            this.updatePressedOptions2();
            float[] fs = MathClampUtils.getWrapDegrees(vec3d2, offsetMin);
            float[] aimRotation2 = this.computeAimRotation(fs[0], fs[1]);
            BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d2, aimRotation2[0], aimRotation2[1], d2);
            if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(longValue)) {
               this.pocketCleanupFlag = true;

               try {
                  this.mineBlockStep(longValue, blockHitResult.getSide(), false);
               } finally {
                  this.pocketCleanupFlag = false;
               }

               mc.player.swingHand(Hand.MAIN_HAND);
            }

            if (mc.world.getBlockState(longValue).isAir()) {
               this.forgetTemporaryCell(longValue.asLong());
               this.kindsUnsolvableCount++;
               this.towerDebtCount = 0;
               this.longBlockWorld = Long.MIN_VALUE;
            }

            return true;
         }
      } else {
         return false;
      }
   }

   private boolean tryReclaimTempBesideCircuit(BlockPos longValue, BlockPos pos) {
      Integer integer = this.coverBodyMap.get(longValue.asLong());
      if (this.cells.contains(longValue.asLong())
         && (integer == null || this.moduleTick >= integer)
         && this.reclaimCircuitIntegerMap.merge(pos.asLong(), 1, Integer::sum) <= 4) {
         this.logDebugMessage("\u00a7b[RedstoneSafety]\u00a7r reclaiming temp " + longValue.toShortString() + " before arming " + pos.toShortString());
         if (this.placementExplicit != null && this.placementExplicit.actionTargetPos == pos.asLong()) {
            this.placementExplicit = null;
            this.blockPosBlockersStep = null;
            this.reachedCoverFlag = false;
            this.deckLocalFlag = false;
         }

         this.blockPos2Exit = longValue;
         this.cleanupStaleItems = null;
         this.reclaimDebtFlag = false;
         this.reclaimCircuitActive = false;
         this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "redstone safety: reclaim the temp beside the circuit");
         return true;
      } else {
         return false;
      }
   }

