      this.lethalBesideValue++;
      this.stepBesideCount++;
      this.recoveryLocalValue = this.moduleTick + 10;
      this.routeStandValue = 0;
      this.standWalkValue = 0;
      this.standRouteAmount = Double.MAX_VALUE;
      this.nodeTransitionValue = -1;
