   private void aimAtCurrentTargetFace() {
      if (this.currentTargetPos != null
         && mc.player != null
         && mc.world != null
         && mc.currentScreen == null
         && this.skippingSettledValue != this.moduleTick
         && this.lastTickUnknownYaw != this.moduleTick
         && this.intervalReportCertificate == null
         && !this.hasActiveBlockersStep()) {
         int n = this.getSchematicCells(this.currentTargetPos);
         if (n >= 0) {
            BlockState blockState = this.targetFluidItems.get(n);
            if (!isPlaceableWithoutSpecialSneak(blockState)
               && (this.isRelaxedBlockShortCell(this.currentTargetPos) || !isOrientationDependentBlock(blockState))
               && !isSneakRequiredBlock(blockState)
               && SelectedInventoryUtils.getValue(getItemForBlockState(blockState)) != -1) {
               Vec3d vec3d = mc.player.getEyePos();
               if (this.deckMicroMoves.isProbingExitingLatched()) {
                  BlockHitResult blockHitResult = this.raycastBlockSideForAim(
                     vec3d, mc.player.getYaw(), mc.player.getPitch(), this.reachSetting.getValue()
                  );
                  if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                     && blockHitResult.getBlockPos().offset(blockHitResult.getSide()).equals(this.currentTargetPos)
                     && this.isHitAllowedForYaw(blockHitResult, mc.player.getYaw())
                     && this.isHitUsableForPlacement(blockHitResult)) {
                     return;
                  }
               }

               BlockHitResult placementHit = this.findPlacementHit(this.currentTargetPos, vec3d, this.reachSetting.getValue());
               if (placementHit != null) {
                  float[] fs = MathClampUtils.getWrapDegrees(vec3d, placementHit.getPos());
                  this.computeAimRotation(fs[0], fs[1]);
                  this.blacklistedFaceCount++;
               }
            }
         }
      }
   }

