   private boolean startSchematicBridge(BlockPos pos) {
      if (this.currentTargetPos != null && mc.world != null) {
         BlockPos down = pos.down();
         if (this.currentTargetPos.getY() != down.getY()) {
            return false;
         } else if (mc.world.getBlockState(down).getCollisionShape(mc.world, down).isEmpty()) {
            return false;
         } else {
            int n2 = this.currentTargetPos.getX() - down.getX();
            int n3 = this.currentTargetPos.getZ() - down.getZ();
            if (n2 != 0 && n3 != 0) {
               return false;
            } else {
               int n4 = Math.abs(n2) + Math.abs(n3);
               if (n4 >= 1 && n4 <= 4) {
                  Direction direction = n2 > 0 ? Direction.EAST : (n2 < 0 ? Direction.WEST : (n3 > 0 ? Direction.SOUTH : Direction.NORTH));
                  ArrayList<BlockPos> arrayList = new ArrayList<>();

                  for (int n = 1; n <= n4; n++) {
                     BlockPos blockPos = down.offset(direction, n);
                     if (!mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
                        if (n == n4 || !WalkRouteFinder.isStandable(mc.world, blockPos.up())) {
                           return false;
                        }
                     } else {
                        if (this.cellTemporarySet.contains(blockPos.asLong())
                           && !this.isPlainFullCubeMissionBlock(blockPos)
                           && !this.bridgeTimeoutSet.contains(blockPos.asLong())) {
                           return false;
                        }

                        if (this.cellTemporarySet.contains(blockPos.asLong()) && this.hasFluidNearBelowCell(blockPos) && !this.isPositionStalled(blockPos)) {
                           return false;
                        }

                        if (!this.cellTemporarySet.contains(blockPos.asLong()) && this.getHotbarDirtSlot() == -1) {
                           return false;
                        }

                        BlockPos blockAbovePos = blockPos.up();
                        BlockPos up3 = blockPos.up(2);
                        if (!mc.world.getBlockState(blockAbovePos).getCollisionShape(mc.world, blockAbovePos).isEmpty()) {
                           return false;
                        }

                        if (!mc.world.getBlockState(up3).getCollisionShape(mc.world, up3).isEmpty()) {
                           return false;
                        }

                        arrayList.add(blockPos);
                     }
                  }

                  if (arrayList.isEmpty()) {
                     return false;
                  } else {
                     this.pendingBridgeCells.clear();
                     this.pendingBridgeCells.addAll(arrayList);
                     this.bridgeSwapValue = this.moduleTick;
                     this.updateBridgeModule();
                     this.worldBridgeValue = 160;
                     this.elevatedPillarItems.clear();
                     this.logDebugMessage(
                        "\u00a7b[SchematicBridge]\u00a7r start target="
                           + this.currentTargetPos.toShortString()
                           + " cells="
                           + arrayList.size()
                           + " dir="
                           + direction
                           + " (crouch-paving the floor forward)"
                     );
                     this.setSupportText("SCHEMATIC_BRIDGE", "paving floor row toward " + this.currentTargetPos.toShortString());
                     this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.BRIDGE, Math.max(1, this.pendingBridgeCells.size()));
                     this.transitionToState(AutoBuilder.State.TEMP_BRIDGE, "schematic bridge to floor target");
                     return true;
                  }
               } else {
                  return false;
               }
            }
         }
      } else {
         return false;
      }
   }

