   private String getDeckLeaveRefusalReason(SupportStandUtils.Step step3, BlockPos pos) {
      boolean flag = step3.op() == SupportStandUtils.Op.WALK;
      if (step3.stand() != null && (flag || step3.op() == SupportStandUtils.Op.PLACE)) {
         BlockPos blockPos4 = toBlockPos(step3.stand());
         BlockPos down = blockPos4.down();
         if (pos.getY() < blockPos4.getY() + 2) {
            return null;
         } else if (this.blockers != null
            && !this.isServiceAccessMission(this.blockers)
            && !this.digMissionFlag
            && this.cleanupMissionValue == Integer.MIN_VALUE
            && this.finiteBlockedActive
            && this.floats > 10
            && this.finiteBlockedPlacedCount > 0
            && this.confirms != this.backHandValue
            && this.schematicCells != null
            && mc.world != null) {
            if (this.cellsUnpackObject != this.schematicCells) {
               int min = Integer.MAX_VALUE;

               for (BlockPos blockPos : this.schematicCells) {
                  min = Math.min(min, blockPos.getY());
               }

               this.schematicLimitY = min;
               this.cellsUnpackObject = this.schematicCells;
            }

            if (blockPos4.getY() <= this.schematicLimitY && this.getSchematicCells(down) < 0 && !this.cells.contains(down.asLong())) {
               List<SupportStandUtils.Step> list = this.blockers.steps();
               HashSet<Long> hashSet = new HashSet<>();
               int y = Integer.MIN_VALUE;
               int n = flag ? this.stepIndex + 1 : this.stepIndex;

               while (n < list.size()) {
                  SupportStandUtils.Step step = list.get(n);
                  if (step.op() == SupportStandUtils.Op.PLACE && step.stand() != null && toBlockPos(step.stand()).equals(blockPos4)) {
                     BlockPos blockPos2 = toBlockPos(step.cell());
                     if (blockPos2.getY() >= blockPos4.getY() + 2
                        && blockPos2.getY() >= pos.getY() - 1
                        && blockPos2.getY() <= pos.getY()
                        && (y == Integer.MIN_VALUE || blockPos2.getY() == y)) {
                        y = blockPos2.getY();
                        hashSet.add(blockPos2.asLong());
                        n++;
                        continue;
                     }

                     return null;
                  }
                  break;
               }

               if (hashSet.isEmpty()) {
                  return null;
               } else {
                  int n2 = 0;

                  for (long l : this.completionMissionMap.keySet()) {
                     if (BlockPos.unpackLongY(l) == y
                        && !hashSet.contains(l)
                        && Math.abs(BlockPos.unpackLongX(l) - pos.getX()) <= 12
                        && Math.abs(BlockPos.unpackLongZ(l) - pos.getZ()) <= 12) {
                        if (++n2 >= 8) {
                           break;
                        }
                     }
                  }

                  if (n2 < 8) {
                     return null;
                  } else {
                     Terrain terrain = WalkRouteFinder.createTerrainView(mc.world);
                     com.corz.client.utils.SolidUnknownUtils.Report report = SolidUnknownUtils.analyzePlateau(
                        terrain, blockPos4.getY(), pos.getX(), pos.getY(), pos.getZ(), 2500
                     );
                     if (report.verdict() == com.corz.client.utils.SolidUnknownUtils.Verdict.UNREACHABLE_FROM_BELOW && report.plateauCells() >= 64) {
                        HashSet<Long> hashSet2 = new HashSet<>();
                        return this.canFloodFillEscape(terrain, blockPos4.getY(), pos, hashSet2)
                           ? null
                           : "body "
                              + pos.toShortString()
                              + " on a "
                              + report.plateauCells()
                              + "-cell deck would leave it for the natural ground "
                              + blockPos4.toShortString()
                              + " to set "
                              + hashSet.size()
                              + " cell(s) of layer "
                              + y
                              + " from below: no walk back up (UNREACHABLE_FROM_BELOW) and none of "
                              + hashSet2.size()
                              + " entry column(s) beside the deck is a reclaimable climb, while "
                              + n2
                              + "+ cell(s) of that layer remain near the body";
                     } else {
                        return null;
                     }
                  }
               }
            } else {
               return null;
            }
         } else {
            return null;
         }
      } else {
         return null;
      }
   }

