   private LiveCell classifyFluidCell(int x, int y, int z, int x2, int y2, int z2) {
      BlockPos blockPos = new BlockPos(x2, y2, z2);
      BlockState blockState = mc.world.getBlockState(blockPos);
      if (blockState.getBlock() instanceof ObserverBlock && blockPos.offset(blockState.get(Properties.FACING)).equals(new BlockPos(x, y, z))) {
         return LiveCell.WATCHED;
      } else if (this.cells.contains(blockPos.asLong())) {
         return LiveCell.BLOCKED;
      } else if (!(blockState.getBlock() instanceof FluidFillable)
         && (!blockState.getFluidState().isEmpty() || blockState.isAir() || blockState.isReplaceable() || !blockState.isSolid())) {
         int schematicCells7 = this.getSchematicCells(blockPos);
         boolean flag = schematicCells7 >= 0 && this.targetFluidItems.get(schematicCells7).getBlock() instanceof FluidBlock;
         if (flag || schematicCells7 < 0 && this.fluidPositionSet.contains(blockPos.asLong())) {
            if (!blockState.getFluidState().isEmpty() && !blockState.getFluidState().isIn(FluidTags.WATER)) {
               return LiveCell.BLOCKED;
            } else if (blockState.getFluidState().isStill()) {
               return LiveCell.SETTLED;
            } else {
               return flag && hasFluidState(this.targetFluidItems.get(schematicCells7)) ? LiveCell.SOURCE : LiveCell.FLOW;
            }
         } else {
            return LiveCell.BLOCKED;
         }
      } else {
         return LiveCell.WALL;
      }
   }

