   private float[] applyHumanizedRotation(float clampPlayerValue, float pitchLimit) {
      if (mc.player == null) {
         return new float[]{clampPlayerValue, pitchLimit};
      } else if (this.skippingSettledValue == this.moduleTick) {
         return new float[]{this.yawClampPlayer, this.pitchClampPlayer};
      } else {
         this.skippingSettledValue = this.moduleTick;
         this.yawClampMaxPitch.resetSteps();
         this.clampPlayerAmountBuilder.resetOffsets();
         float yaw3 = mc.player.getYaw();
         float pitch4 = mc.player.getPitch();
         this.yawShortest.handleShortestYaw(yaw3, clampPlayerValue, ShortestYawUtils.getAmount(yaw3, clampPlayerValue));
         float[] fs = this.egressStandHumanAim.computeHumanizedRotation(yaw3, pitch4, clampPlayerValue, pitchLimit, ClampMath.getSensitivityMouse());
         this.yawClampPlayer = fs[0];
         this.pitchClampPlayer = MathHelper.clamp(fs[1], -90.0F, 90.0F);
         mc.player.setYaw(this.yawClampPlayer);
         mc.player.setPitch(this.pitchClampPlayer);
         this.recordRotationRequest(yaw3, pitch4, this.yawClampPlayer, this.pitchClampPlayer);
         this.unknownYawSideMax
            .addSample(
               new com.corz.client.utils.SideMax.Sample(
                  this.moduleTick,
                  this.yawClampPlayer,
                  this.pitchClampPlayer,
                  mc.player.getVelocity().horizontalLengthSquared() > 1.0E-4,
                  mc.player.isSprinting(),
                  mc.player.isSneaking()
               )
            );
         return new float[]{this.yawClampPlayer, this.pitchClampPlayer};
      }
   }

