   private List<BlockPos> findPathToAnyTarget(BlockPos pos, Collection<BlockPos> collection) {
      long l = this.selectPasses.getNanoTime();
      this.rebuildReachableComponent();
      boolean equals = pos.equals(this.getFeetBlockPos());
      long l2 = equals ? this.componentKey : pos.asLong();
      ArrayList<BlockPos> arrayList = new ArrayList<>();

      for (BlockPos blockPos : collection) {
         if (blockPos.equals(pos)) {
            this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.GO_PATH, l);
            return new ArrayList<>(List.of(pos));
         }

         boolean flag = Math.abs(blockPos.getX() - pos.getX()) <= 20 && Math.abs(blockPos.getZ() - pos.getZ()) <= 20;
         if (equals && flag && !this.componentChangedActive && this.component.size() < 600 && !this.component.contains(blockPos.asLong())) {
            this.selectPasses.handleTimes(Counter.PATH_PRECHECK_SKIPS);
            this.noteChangedPlan(blockPos, l2);
         } else if (this.isPositionOrNeighborInChangedPlan(blockPos, l2)) {
            this.selectPasses.handleTimes(Counter.PATH_NEG_HITS);
         } else if (blockPos.getY() >= pos.getY() + 2 && WalkRouteFinder.isUnreachableFromBelow(pos, blockPos, 1500)) {
            this.passesSelectCount++;
            this.selectPasses.handleTimes(Counter.ELEVATION_PRECHECK_SKIPS);
            this.noteChangedPlan(blockPos, l2);
         } else {
            arrayList.add(blockPos);
         }
      }

      if (arrayList.isEmpty()) {
         WalkRouteFinder.setDistanceDiagnostics(pos, pos);
         this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.GO_PATH, l);
         return null;
      } else {
         this.selectPasses.handleTimes(Counter.ASTAR_RUNS);
         this.selectPasses.handleTimes(Counter.MULTIGOAL_SEARCHES);
         List<BlockPos> list = WalkRouteFinder.findPathToAny(pos, arrayList);
         this.selectPasses.handleTimes(Counter.ASTAR_NODES, WalkRouteFinder.getLastPathDiagnostics().expanded());
         if (list == null || list.isEmpty()) {
            long[] ls = WalkRouteFinder.getLastFailedFootprint();

            for (BlockPos arrayItem : arrayList) {
               this.recordChangedPlanFootprint(arrayItem, l2, ls);
            }
         }

         this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.GO_PATH, l);
         return list;
      }
   }

   private void trackStateDispatchBudget(AutoBuilder.State state2, String churnRefundsText) {
      if (state2 == AutoBuilder.State.GO_TO_POSITION
         || state2 == AutoBuilder.State.SCAFFOLD_UP
         || state2 == AutoBuilder.State.TEMP_SUPPORT
         || state2 == AutoBuilder.State.STATE_REPAIR) {
         if (this.currentTargetPos != null
            && this.state2Builder != AutoBuilder.State.DONE
            && !this.digMissionFlag
            && this.unsolvableTailTexts == null
            && !this.isMachineArmedAt(this.currentTargetPos)) {
            this.churnRefunds.canRefundsTime(this.confirms, this.hashCellSet());
            long l = DispatchBudget.getTime(state2.name(), churnRefundsText);
            long long2 = this.currentTargetPos.asLong();
            int n = state2 != AutoBuilder.State.SCAFFOLD_UP && state2 != AutoBuilder.State.STATE_REPAIR ? 32 : 12;
            com.corz.client.utils.ParkMerge.DispatchBudget.Verdict verdict = this.churnRefunds.getParkedHits(l, long2, n, this.moduleTick);
            if (verdict == com.corz.client.utils.ParkMerge.DispatchBudget.Verdict.EXHAUSTED) {
               this.logDebugMessage(
                  "\u00a7e[CycleBudget]\u00a7r "
                     + state2
                     + " ("
                     + churnRefundsText
                     + ") at "
                     + this.currentTargetPos.toShortString()
                     + " dispatched "
                     + n
                     + "x without a confirm or a new temp - the target is backed off "
                     + DispatchBudget.getMin(this.churnRefunds.getValue(l, long2))
                     + " ticks"
               );
            } else if (verdict == com.corz.client.utils.ParkMerge.DispatchBudget.Verdict.PARKED && this.cycleDispatchedValue == Long.MIN_VALUE) {
               this.cycleDispatchedValue = long2;
               this.dispatchedCycleText = state2 + " (" + churnRefundsText + ") re-dispatched at " + this.currentTargetPos.toShortString() + " during its back-off";
            }

            if (l == abcdefghjkmnpqrstuvwxyzSeedTime
               && this.churnRefunds.getParkedHitsForLongInt(l, long2, 20, this.moduleTick) == com.corz.client.utils.ParkMerge.DispatchBudget.Verdict.EXHAUSTED) {
               this.logDebugMessage(
                  "\u00a7e[CycleBudget]\u00a7r side seeds failed on 20 owners without a confirm or a new temp - side seeding is backed off "
                     + DispatchBudget.getMin(this.churnRefunds.getValue(l))
                     + " ticks"
               );
            }
         }
      }
   }

