   private boolean doesPlayerOverlapFluidCells(BlockPos pos) {
      if (mc.player != null && mc.world != null) {
         HashSet<Long> hashSet = this.computeWaterFlowCells(pos);
         Box box = mc.player.getBoundingBox();

         for (int floor3 = (int)Math.floor(box.minX + 1.0E-4); floor3 <= (int)Math.floor(box.maxX - 1.0E-4); floor3++) {
            for (int floor2 = (int)Math.floor(box.minZ + 1.0E-4); floor2 <= (int)Math.floor(box.maxZ - 1.0E-4); floor2++) {
               for (int n = (int)Math.floor(box.minY + 1.0E-4); n <= (int)Math.floor(box.maxY - 1.0E-4); n++) {
                  if (hashSet.contains(BlockPos.asLong(floor3, n, floor2))) {
                     return true;
                  }
               }
            }
         }

         return false;
      } else {
         return false;
      }
   }

   private boolean isIslandStandViable(BlockPos pos, BlockPos pos2) {
      if (mc.world != null
         && pos2 != null
         && !pos.equals(pos2)
         && !pos.equals(pos2.up())
         && !pos.equals(pos2.down())) {
         if (this.islandAbort != 0L
            && pos.getX() == BlockPos.unpackLongX(this.islandAbort)
            && pos.getZ() == BlockPos.unpackLongZ(this.islandAbort)
            && pos.getY() < BlockPos.unpackLongY(this.islandAbort)
            && this.isNearIslandAbortColumn(pos.asLong())
            && this.isNearIslandAbortColumn(pos2.down().asLong())
            && this.hasTempColumnBelow(pos2)) {
            return false;
         } else {
            com.corz.client.utils.WalkableRegionAnalyzer.Result result = WalkableRegionAnalyzer.evaluatePocketSealingStandable(
               WalkRouteFinder.createTerrainView(mc.world),
               pos2.getX(),
               pos2.getY(),
               pos2.getZ(),
               pos.getX(),
               pos.getY(),
               pos.getZ()
            );
            return result.componentBefore() >= 40
               && (
                  result.componentAfter() < 12
                     || this.hasUnbuiltCellAtOrBelow(
                        WalkRouteFinder.createPartialHeightTerrain(mc.world, WalkRouteFinder.createTerrainView(mc.world)),
                        pos,
                        pos2,
                        true,
                        false
                     )
               );
         }
      } else {
         return false;
      }
   }

