   private float[] computeAimRotation(float yawModuleValue, float pitchLimit) {
      if (this.v2speed.isEnabled()) {
         return this.applyHumanizedRotation(yawModuleValue, pitchLimit);
      } else if (this.deckMicroMoves.isProbingExitingLatched()) {
         if (this.yawModuleValue == this.moduleTick) {
            return new float[]{mc.player.getYaw(), mc.player.getPitch()};
         } else {
            this.yawModuleValue = this.moduleTick;
            float[] fs = this.clampPlayerAmountBuilder
               .computeSmoothedAim(
                  mc.player.getYaw(),
                  mc.player.getPitch(),
                  yawModuleValue,
                  pitchLimit,
                  (float)this.turnSpeed.getValue(),
                  WrapDegreesUtils.getWobbleOffset(this.moduleTick, 0.2F, 0),
                  WrapDegreesUtils.getWobbleOffset(this.moduleTick, 0.12F, 1)
               );
            this.yawShortest.handleShortestYaw(mc.player.getYaw(), yawModuleValue, ShortestYawUtils.getAmount(mc.player.getYaw(), yawModuleValue));
            mc.player.setYaw(fs[0]);
            mc.player.setPitch(fs[1]);
            this.skippingSettledValue = this.moduleTick;
            this.yawClampPlayer = fs[0];
            this.pitchClampPlayer = fs[1];
            this.unknownYawSideMax
               .addSample(
                  new com.corz.client.utils.SideMax.Sample(
                     this.moduleTick,
                     fs[0],
                     fs[1],
                     mc.player.getVelocity().horizontalLengthSquared() > 1.0E-4,
                     mc.player.isSprinting(),
                     mc.player.isSneaking()
                  )
               );
            return fs;
         }
      } else {
         float wobbleOffset3 = WrapDegreesUtils.getWobbleOffset(this.moduleTick, 0.2F, 0);
         float wobbleOffset4 = WrapDegreesUtils.getWobbleOffset(this.moduleTick, 0.12F, 1);
         return this.applyClampedRotation(yawModuleValue, pitchLimit, wobbleOffset3, wobbleOffset4);
      }
   }

