   private boolean canAimAtBlockFace(BlockPos pos, BlockState state, Vec3d vec, double blockHorizontalFactor) {
      if (mc.world == null) {
         return false;
      } else {
         BlockState blockState2 = mc.world.getBlockState(pos);
         if (state.getBlock() instanceof LeverBlock) {
            VoxelShape voxelShape = blockState2.getOutlineShape(mc.world, pos);
            if (voxelShape.isEmpty()) {
               return false;
            } else {
               Vec3d vec3d = voxelShape.getBoundingBox().getCenter().add(pos.getX(), pos.getY(), pos.getZ());
               if (vec.squaredDistanceTo(vec3d) <= blockHorizontalFactor * blockHorizontalFactor) {
                  float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d);
                  BlockHitResult blockHitResult = this.raycastFromEye(vec, fs[0], fs[1], blockHorizontalFactor);
                  if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
                     return true;
                  }
               }

               return this.findVisibleShapePoint(vec, pos, voxelShape, blockHorizontalFactor) != null;
            }
         } else {
            boolean flag = !blockState2.contains(Properties.OPEN) || !blockState2.get(Properties.OPEN);
            Direction direction2 = state.contains(Properties.HORIZONTAL_FACING) ? state.get(Properties.HORIZONTAL_FACING) : null;

            for (Direction direction : Direction.values()) {
               Vec3d vec3d2 = this.getFaceAimPoint(blockState2, pos, direction);
               if (vec3d2 != null && !(vec.squaredDistanceTo(vec3d2) > blockHorizontalFactor * blockHorizontalFactor)) {
                  float[] wrapDegrees2 = MathClampUtils.getWrapDegrees(vec, vec3d2);
                  BlockHitResult raycastBlockSideForAim2 = this.raycastBlockSideForAim(vec, wrapDegrees2[0], wrapDegrees2[1], blockHorizontalFactor);
                  if (raycastBlockSideForAim2.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                     && raycastBlockSideForAim2.getBlockPos().equals(pos)
                     && (!flag || direction2 == null || direction2 != Direction.fromHorizontalDegrees(wrapDegrees2[0]).getOpposite())) {
                     return true;
                  }
               }
            }

            return false;
         }
      }
   }

