   private boolean tryPillarUpToElevatedWork(BlockPos longValue, BlockPos pos) {
      if (this.moduleTick >= this.elevatedDeckValue && this.hasUsableBlockItem()) {
         if (pos.getY() <= longValue.getY()) {
            return false;
         } else if (this.canColumnsBanned(longValue)) {
            return false;
         } else {
            int n5 = this.currentTargetPos == null ? -1 : this.getSchematicCells(this.currentTargetPos);
            if (n5 >= 0) {
               BlockState blockState = this.targetFluidItems.get(n5);
               boolean flag = false;
               int min2 = Math.min(this.maxVerticalAccess.getValue(), Math.max(1, pos.getY() - longValue.getY()) + 1);

               for (int n = 1; n <= min2 && !flag; n++) {
                  flag = this.canPlaceFromEyePosition(this.currentTargetPos, blockState, getStandingEyePos(longValue.up(n)), this.reachSetting.getValue(), false);
               }

               if (!flag) {
                  return false;
               }
            }

            for (int n3 = 1; n3 <= 2; n3++) {
               BlockPos blockPos = longValue.up(n3);
               if (this.cellTemporarySet.contains(blockPos.asLong())) {
                  return false;
               }

               if (!mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
                  return false;
               }
            }

            int max = 0;

            for (int n4 = 1; n4 <= Math.max(1, pos.getY() - longValue.getY()) && max == 0; n4++) {
               max = Math.max(max, this.getCachedPreviewScore(longValue, n4));
            }

            if (max <= 0) {
               return false;
            } else {
               this.blockPos3BridgeCell = longValue;
               this.resetPillarTracking();
               this.elevatedPillarItems.clear();
               this.pillarTargetY = pos.getY();
               this.missionShortValue = pos.getY();
               this.standClimbFlag = false;
               this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.PILLAR, max);
               this.setSupportText("PILLAR_UP_IN_PLACE", "no ground route to elevated work - pillaring up from here");
               this.transitionToState(AutoBuilder.State.SCAFFOLD_UP, "pillar up in place to reach elevated work");
               return true;
            }
         }
      } else {
         return false;
      }
   }

