   private void scheduleLowPocketCleanup(BlockPos pos) {
      int n = this.blockersMissionValue;
      if (this.waitFullPass != n && !this.digMissionFlag && this.removeTempAfter.isEnabled()) {
         if (pos.getY() - 1 > n - 4
            && this.cleanupMissionValue == Integer.MIN_VALUE
            && this.islandAbort == 0L
            && !this.deckMicroMoves.isProbingExitingConfirmed()
            && this.submitCompletionMission == null
            && (this.blockers == null || !this.isServiceAccessMission(this.blockers))
            && this.hasUsableBlockItem()) {
            for (long l : this.completionMissionMap.keySet()) {
               if (BlockPos.unpackLongY(l) < n) {
                  return;
               }
            }

            this.blockersMissionValue = Integer.MIN_VALUE;
            boolean flag = false;

            for (long l2 : this.cells) {
               if (BlockPos.unpackLongY(l2) < n) {
                  flag = true;
                  break;
               }
            }

            if (flag) {
               if (this.blockers != null) {
                  this.blockers = null;
                  this.stepIndex = -1;
                  this.budgetExhaustedText = null;
                  this.stepsTimeBudget.updateTimeMax();
               }

               this.cleanupMissionValue = n;
               this.logDebugMessage(
                  "\u00a7b[PocketSweep]\u00a7r the pocket below y="
                     + n
                     + " was finished after the climb out - the cleanup planner reclaims its temps before the floors above close it in"
               );
            }
         }
      } else {
         this.blockersMissionValue = Integer.MIN_VALUE;
      }
   }

