   private Column getColumnFingerprint(BlockPos pos, BlockPos pos2) {
      int min3 = Math.min(8, this.maxVerticalAccess.getValue());
      long l = -7046029254386353131L;
      long l2 = 0L;

      for (int n = pos.getY() - min3; n <= pos.getY(); n++) {
         BlockPos blockPos = new BlockPos(pos.getX(), n, pos.getZ());
         if (this.cells.contains(blockPos.asLong())) {
            l2 ^= ChangedCapability.getTime(blockPos.asLong());
         } else {
            boolean flag = !mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty();
            l ^= ChangedCapability.getTime(blockPos.asLong() * 2L + (flag ? 1L : 0L));
         }
      }

      long packCellKey3 = HashOpenDefault.packCellKey(pos.getX(), pos.getY() - min3, pos.getZ());
      long packCellKey4 = HashOpenDefault.packCellKey(pos.getX(), pos.getY(), pos.getZ());
      long[] ls = packCellKey3 == packCellKey4 ? new long[]{packCellKey3} : new long[]{packCellKey3, packCellKey4};
      long[] ls2 = new long[ls.length];

      for (int n2 = 0; n2 < ls.length; n2++) {
         ls2[n2] = SHARED_HASH_OPEN.getCellXorHash(ls[n2]);
      }

      return new Column(l, l2, ls, ls2);
   }

