   private boolean tryRaiseStandOnIslandSeed(BlockPos pos, int raiseAirborneValue) {
      if (this.islandAbort != 0L && mc.player != null) {
         BlockPos fromLong = BlockPos.fromLong(this.islandAbort);
         BlockPos playerFootprintCell = this.getPlayerFootprintCell(this.getFeetBlockPos());
         if (pos.getY() < playerFootprintCell.getY() + 2) {
            this.airborne = "face_below_eye";
            return false;
         } else {
            int abs3 = Math.abs(playerFootprintCell.getX() - pos.getX());
            int abs4 = Math.abs(playerFootprintCell.getZ() - pos.getZ());
            if (!mc.player.isOnGround()) {
               this.airborne = "airborne";
               return false;
            } else {
               String string = ClearanceHeadroomUtils.formatClearanceHeadroom(this.createReachabilityWorldView(), playerFootprintCell.getX(), playerFootprintCell.getY(), playerFootprintCell.getZ(), raiseAirborneValue);
               if (string != null) {
                  this.airborne = string;
                  return false;
               } else if (this.canColumnsBanned(playerFootprintCell)) {
                  this.airborne = "column_banned";
                  return false;
               } else if (Math.max(abs3, abs4) <= 2 && (abs3 != 0 || abs4 != 0)) {
                  if (this.longIslandSeed != 0L) {
                     BlockPos blockPos = BlockPos.fromLong(this.longIslandSeed);
                     if (blockPos.getX() != playerFootprintCell.getX() || blockPos.getZ() != playerFootprintCell.getZ()) {
                        int n = Math.max(0, fromLong.getY() - 1 - playerFootprintCell.getY());
                        if (ClearanceHeadroomUtils.measureHeadroom(this.createReachabilityWorldView(), playerFootprintCell.getX(), playerFootprintCell.getY(), playerFootprintCell.getZ(), fromLong.getY() - 1) < n) {
                           this.airborne = "column_not_admitted";
                           return false;
                        }

                        this.admittedColumnItems.add(new long[]{playerFootprintCell.getX(), playerFootprintCell.getZ(), playerFootprintCell.getY() - 1, fromLong.getY() + 6 + 2});
                        this.longIslandSeed = playerFootprintCell.asLong();
                        this.riseRaiseItems.add(playerFootprintCell.asLong());
                     }
                  }

                  if (playerFootprintCell.asLong() == this.longRaiseAirborne) {
                     if (this.riseRaiseValue >= 3) {
                        this.airborne = "raise_did_not_rise";
                        return false;
                     }

                     this.riseRaiseValue++;
                  } else {
                     this.longRaiseAirborne = playerFootprintCell.asLong();
                     this.riseRaiseValue = 1;
                  }

                  this.airborne = "";
                  this.resetPillarTracking();
                  this.blockPos3BridgeCell = playerFootprintCell;
                  this.pillarDirtValue = playerFootprintCell.getY() + 1;
                  this.currentTargetPos = fromLong;
                  this.supportAccessValue = this.getSchematicCells(fromLong);
                  this.setSupportText("TEMP_SUPPORT", "island seed " + fromLong.toShortString() + " - raise stand");
                  this.transitionToState(AutoBuilder.State.SCAFFOLD_UP, "island seed - raise stand");
                  return true;
               } else {
                  this.airborne = "not_beside_column";
                  return false;
               }
            }
         }
      } else {
         return false;
      }
   }

   private void finishBuyCycle(String buyAutoText) {
      int n = this.buyAutoPurchasedCount - this.buyAutoCountSnapshot;
      long l = this.buyAutoTime - this.lastBuyAutoTime;
      if (this.maxTotalSpend.getValue() > 0 && this.buyAutoTime >= this.maxTotalSpend.getValue()) {
         this.showedBuyText = "Max Total Spend reached";
      }

      boolean flag = "complete".equals(buyAutoText);
      if (!flag && this.showedBuyText == null && this.affordablePagesItem != null && this.buyQuantity > 0) {
         this.recordNoFreeSpaceForItem(this.affordablePagesItem, buyAutoText, this.getBuyRetryDelayTicks(this.affordablePagesItem));
      }

      if (n <= 0 && !flag) {
         this.buyAutoRetryCount++;
         this.buyAutoValue = this.moduleTick + LateCountsUtils.getValue(this.buyAutoRetryCount, 1200, 12000);
         this.buyAutoCooldownUntilTick = this.buyAutoValue;
      } else {
         if (n > 0) {
            this.buyAutoRetryCount = 0;
            this.dirtBuyAttemptCount = 0;
         } else if (this.layerBuyTrigger == AutoBuilder.LayerBuyTrigger.DIRT) {
            this.buyAutoValues[AutoBuilder.LayerBuyTrigger.DIRT.ordinal()] = this.moduleTick + LateCountsUtils.getValue(++this.dirtBuyAttemptCount, 600, 12000);
         }

         this.buyAutoCooldownUntilTick = -100000;
         this.buyAutoValue = this.moduleTick + 100;
      }

      if (this.buyNotifications.isEnabled()) {
         if (n > 0) {
            this.sendPlayerChatMessage(
               "\u00a7b[AutoBuy]\u00a7r restock #"
                  + this.buyAutoCount
                  + " done - \u00a7f"
                  + n
                  + "\u00a7r block"
                  + (n == 1 ? "" : "s")
                  + " for \u00a7f"
                  + BuyerAppendUtils.formatText(l)
                  + "\u00a7r \u00a77("
                  + BuyerAppendUtils.formatText(this.buyAutoTime)
                  + " so far, "
                  + buyAutoText
                  + ")\u00a7r - back to building"
            );
         } else if (flag) {
            this.sendPlayerChatMessage(
               "\u00a7e[AutoBuy]\u00a7r restock #" + this.buyAutoCount + " could not buy anything right now - building on with what is in hand"
            );
         } else {
            this.sendPlayerChatMessage(
               "\u00a7e[AutoBuy]\u00a7r restock #"
                  + this.buyAutoCount
                  + " got nothing \u00a77("
                  + buyAutoText
                  + ")\u00a7r - next try in ~"
                  + Math.max(1, (this.buyAutoValue - this.moduleTick) / 20)
                  + "s"
            );
         }

         if (this.showedBuyText != null) {
            this.sendPlayerChatMessage("\u00a7c[AutoBuy]\u00a7r " + this.showedBuyText + " - no more auction purchases for this build (press Buy to go on)");
         }
      }

      this.resetBuyState();
      this.layersNeedValue = -1;
   }

   private boolean canRaycastAnyFaceSample(BlockPos pos, Vec3d vec, double blockSquaredFactor) {
      BlockState blockState = mc.world.getBlockState(pos);
      if (!(blockState.getBlock() instanceof LeverBlock) && !(blockState.getBlock() instanceof FenceGateBlock)) {
         double d4 = blockSquaredFactor * blockSquaredFactor;
         double[] ds = new double[]{0.5, 0.3, 0.7, 0.15, 0.85};

         for (Direction direction : Direction.values()) {
            if (this.getFaceAimPoint(blockState, pos, direction) != null) {
               for (double d2 : ds) {
                  for (double d : ds) {
                     Vec3d vec3d = this.getFaceAimPointInRange(blockState, pos, direction, d2, d);
                     if (vec3d != null && !(vec.squaredDistanceTo(vec3d) > d4)) {
                        float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d);
                        BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec, fs[0], fs[1], blockSquaredFactor);
                        if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
                           return true;
                        }
                     }
                  }
               }
            }
         }

         return false;
      } else {
         return false;
      }
   }

