   private long[] collectIntentPathCells(SupportStandUtils.Intent intent) {
      BlockPos blockPos = toBlockPos(intent.stand());
      BlockPos blockPos2 = toBlockPos(intent.support());
      BlockPos pos2 = toBlockPos(intent.target());
      LinkedHashSet<Long> linkedHashSet = new LinkedHashSet<>();
      linkedHashSet.add(blockPos.down().asLong());
      linkedHashSet.add(blockPos.asLong());
      linkedHashSet.add(blockPos.up().asLong());
      linkedHashSet.add(blockPos2.asLong());
      linkedHashSet.add(pos2.asLong());
      Vec3d vec3d2 = !intent.sneak() && !this.shouldCrouchForSafeSneak(blockPos, pos2) ? getStandingEyePos(blockPos) : getLoweredTargetPoint(blockPos);
      Vec3d vec3d3 = new Vec3d(intent.hx(), intent.hy(), intent.hz());
      Vec3d vec3d4 = vec3d3.subtract(vec3d2);
      double d = vec3d4.length();
      int min2 = Math.min(64, (int)Math.ceil(d / 0.1));

      for (int n = 0; n <= min2; n++) {
         Vec3d vec3d = vec3d2.add(vec3d4.multiply(min2 == 0 ? 0.0 : (double)n / min2));
         linkedHashSet.add(BlockPos.ofFloored(vec3d).asLong());
      }

      long[] ls = new long[linkedHashSet.size()];
      int n3 = 0;

      for (long l : linkedHashSet) {
         ls[n3++] = l;
      }

      return ls;
   }

