   private AutoBuilder.FailReason parseFailReason(String standMountText) {
      String lowerCase2 = standMountText.toLowerCase();
      if (lowerCase2.contains("support face")) {
         return AutoBuilder.FailReason.NO_SUPPORT_FACE;
      } else if (lowerCase2.contains("no legal camera aim")) {
         return AutoBuilder.FailReason.NO_LEGAL_AIM;
      } else if (lowerCase2.contains("no visible standing") || lowerCase2.contains("no stand exists")) {
         return AutoBuilder.FailReason.NO_VALID_STAND;
      } else if (lowerCase2.contains("mount didn't yield a stand")) {
         return AutoBuilder.FailReason.NO_VALID_STAND;
      } else if (lowerCase2.contains("no path to any stand")) {
         return AutoBuilder.FailReason.NO_PATH_TO_STAND;
      } else if (lowerCase2.contains("all mount/column paths")) {
         return AutoBuilder.FailReason.NO_PATH_TO_COLUMN;
      } else {
         return lowerCase2.contains("access reached but no declared target progressed") ? AutoBuilder.FailReason.ACCESS_NO_PROGRESS : null;
      }
   }

