   private Transition applyFamilyStrategyTransition(long retriedLapsesValue, Strategy strategy, StrategyResult strategyResult, com.corz.client.utils.FamilyGained.Dependency missionBanType, long l6) {
      Transition transition = this.handBack.getTerminalExecutingTransitionDetailed(retriedLapsesValue, strategy, strategyResult, missionBanType, l6, this.eventsFamilies.getFamiliesEpochTime());
      this.logDebugMessage("\u00a7b[AccessQueue]\u00a7r " + this.handBack.getAppendText());
      if (transition != null && transition.to() == FamilyGained.State.TERMINAL_IMPOSSIBLE) {
         int n = this.lapsesRetriedMap.getOrDefault(retriedLapsesValue, -1);
         this.lapsesRetriedMap.remove(retriedLapsesValue);
         if (n > this.moduleTick
            && this.handBack.getReopensTerminal(retriedLapsesValue, n, "the ladder ran while a pillar column was banned - retried when the ban lapses") != null) {
            this.serviceIslandValue = Math.max(this.serviceIslandValue, n);
            this.logDebugMessage("\u00a7e[AccessQueue]\u00a7r " + this.handBack.getAppendText());
            return transition;
         }
      }

      if (transition != null && transition.to() == FamilyGained.State.TERMINAL_IMPOSSIBLE) {
         this.parkFamilyAsAccessImpossible(retriedLapsesValue, this.lapsesRetriedItems, transition.why());
         this.logDebugMessage("\u00a7c[AccessQueue]\u00a7r terminal family=" + FamilyGained.formatPositionText(retriedLapsesValue) + " result=IMPOSSIBLE");
      } else if (transition != null && transition.to() == FamilyGained.State.TERMINAL_REACHABLE) {
         this.logDebugMessage("\u00a7a[AccessQueue]\u00a7r terminal family=" + FamilyGained.formatPositionText(retriedLapsesValue) + " result=REACHABLE");
      } else if (transition != null && transition.to() == FamilyGained.State.QUEUED) {
         this.handleWakeRev("access_next_strategy");
      }

      return transition;
   }

