   private boolean hasFluidEscapePath(BlockPos pos) {
      BlockState blockState2 = mc.world.getBlockState(pos);
      VoxelShape voxelShape = blockState2.getBlock() instanceof FluidFillable ? blockState2.getCollisionShape(mc.world, pos) : null;
      ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
      HashSet<Long> hashSet = new HashSet<>();
      arrayDeque.add(pos);
      hashSet.add(pos.asLong());

      while (!arrayDeque.isEmpty()) {
         BlockPos poll2 = arrayDeque.poll();
         if (voxelShape == null || !poll2.equals(pos)) {
            for (int n3 = -1; n3 <= 1; n3++) {
               for (int n2 = -1; n2 <= 0; n2++) {
                  for (int n = -1; n <= 1; n++) {
                     if ((n3 | n2 | n) != 0 && this.isTargetCellMissingAndReplaceable(poll2.add(n3, n2, n))) {
                        return true;
                     }
                  }
               }
            }
         }

         for (Direction direction : Direction.values()) {
            BlockPos blockPos = poll2.offset(direction);
            if (direction != Direction.UP
               && (voxelShape == null || !poll2.equals(pos) || !Block.isFaceFullSquare(voxelShape, direction))
               && hashSet.add(blockPos.asLong())) {
               BlockState blockState = mc.world.getBlockState(blockPos);
               if (this.cells.contains(blockPos.asLong())
                  || !(blockState.getBlock() instanceof FluidFillable)
                     && (!blockState.getFluidState().isEmpty() || blockState.isAir() || blockState.isReplaceable() || !blockState.isSolid())) {
                  int schematicCells4 = this.getSchematicCells(blockPos);
                  if (schematicCells4 < 0 || !(this.targetFluidItems.get(schematicCells4).getBlock() instanceof FluidBlock) || hashSet.size() > 256) {
                     return true;
                  }

                  arrayDeque.add(blockPos);
               }
            }
         }
      }

      return false;
   }

   private boolean floodFillReachesOpenArea(BlockPos pos, BlockPos pos2, HashSet<Long> hashSet) {
      ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
      hashSet.add(pos.asLong());
      arrayDeque.add(pos);

      while (!arrayDeque.isEmpty()) {
         BlockPos poll2 = arrayDeque.poll();

         for (Direction direction : Type.HORIZONTAL) {
            BlockPos blockPos = poll2.offset(direction);
            if (!blockPos.equals(pos2) && !hashSet.contains(blockPos.asLong())) {
               if (this.isValidSupportedPosition(blockPos, pos2)) {
                  hashSet.add(blockPos.asLong());
                  if (hashSet.size() >= 40) {
                     return true;
                  }

                  arrayDeque.add(blockPos);
               } else if (this.canStepOntoAdjacentCell(poll2, blockPos)) {
                  return true;
               }
            }
         }
      }

      return false;
   }

