   private boolean isDropWithinLimit(Set<Long> hashSet, int downCollisionLimit) {
      BlockPos longValue = null;

      for (long l : hashSet) {
         BlockPos blockPos = BlockPos.fromLong(l);
         if (longValue == null || blockPos.getY() < longValue.getY()) {
            longValue = blockPos;
         }
      }

      if (longValue == null) {
         return false;
      } else {
         int n2 = 0;

         for (BlockPos down = longValue.down();
            n2 <= downCollisionLimit + 1 && mc.world.getBlockState(down).getCollisionShape(mc.world, down).isEmpty();
            down = down.down()
         ) {
            n2++;
         }

         return 1 + n2 <= downCollisionLimit;
      }
   }

