   private static boolean isNonDefaultInteractState(BlockState state) {
      Block block = state.getBlock();
      if (block instanceof RepeaterBlock) {
         return state.contains(Properties.DELAY) && state.get(Properties.DELAY) != 1;
      } else if (block instanceof ComparatorBlock) {
         return state.contains(Properties.COMPARATOR_MODE) && state.get(Properties.COMPARATOR_MODE) == ComparatorMode.SUBTRACT;
      } else if (block instanceof FenceGateBlock) {
         return state.contains(Properties.OPEN) && state.get(Properties.OPEN);
      } else if (block instanceof LeverBlock) {
         return state.contains(Properties.POWERED) && state.get(Properties.POWERED);
      } else {
         return !(block instanceof CandleBlock) ? false : state.contains(Properties.CANDLES) && state.get(Properties.CANDLES) > 1;
      }
   }

