   private boolean tryClutchDescent(BlockPos pos) {
      BlockPos down = pos.down();
      if (!this.cells.contains(down.asLong())) {
         return false;
      } else if (this.isNearIslandAbortColumn(down.asLong())) {
         return false;
      } else {
         BlockPos downBelow = down.down();
         if (mc.world.getBlockState(downBelow).getCollisionShape(mc.world, downBelow).isEmpty()) {
            return false;
         } else {
            boolean flag = false;

            for (long l : this.cellTemporarySet) {
               BlockPos blockPos = BlockPos.fromLong(l);
               if (blockPos.getY() >= this.layerAccessFloorY
                  && blockPos.getY() <= pos.getY() - 3
                  && (blockPos.getX() != pos.getX() || blockPos.getZ() != pos.getZ())) {
                  flag = true;
                  break;
               }
            }

            if (!flag) {
               return false;
            } else {
               boolean empty = mc.world.getBlockState(pos.up(2)).getCollisionShape(mc.world, pos.up(2)).isEmpty();

               for (Direction direction : Type.HORIZONTAL) {
                  BlockPos offsetPos = pos.offset(direction);
                  if (empty && WalkRouteFinder.isStandable(mc.world, offsetPos.up())) {
                     return false;
                  }

                  for (int n = 0; n <= 2; n++) {
                     BlockPos offsetBelowPos = offsetPos.down(n);
                     if (WalkRouteFinder.isStandable(mc.world, offsetBelowPos)) {
                        return false;
                     }

                     if (!mc.world.getBlockState(offsetBelowPos).getCollisionShape(mc.world, offsetBelowPos).isEmpty()) {
                        break;
                     }
                  }
               }

               this.materialDoorwayMap.put(down.asLong(), this.moduleTick + 600);
               this.materialDoorwayMap.put(pos.asLong(), this.moduleTick + 600);
               this.recoveryEscalationMap.put(down.asLong(), this.moduleTick);
               this.blockPos2Exit = down;
               this.longClutchDescent = down.asLong();
               this.recoveryRecoverValue = 0;
               this.x = pos.getX();
               this.blockPosValue = pos.getZ();
               this.clutchDescentValue = this.moduleTick;
               this.logDebugMessage(
                  "\u00a7e[Clutch]\u00a7r stranded high - mining down through own column at "
                     + down.toShortString()
                     + " (1-block drops, no fall damage; rebuilt later)"
               );
               this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "clutch descent: mine block under feet");
               return true;
            }
         }
      }
   }

