   private Vec3d findVisibleShapePoint(Vec3d vec, BlockPos pos, VoxelShape voxelShape, double autoBuilderFactor) {
      Box box = voxelShape.getBoundingBox().offset(pos.getX(), pos.getY(), pos.getZ());
      double[] ds = new double[]{0.5, 0.3, 0.7, 0.15, 0.85};

      for (Direction direction : new Direction[]{Direction.UP, Direction.NORTH, Direction.SOUTH, Direction.WEST, Direction.EAST, Direction.DOWN}) {
         for (double d5 : ds) {
            for (double d4 : ds) {
               double d = box.minX + (box.maxX - box.minX) * d5;
               double d2 = box.minZ + (box.maxZ - box.minZ) * d4;
               double d3 = box.minY + (box.maxY - box.minY) * (direction.getAxis() == Axis.X ? d5 : d4);

               Vec3d vec3d = switch (direction) {
                  case UP -> new Vec3d(d, box.maxY, d2);
                  case DOWN -> new Vec3d(d, box.minY, d2);
                  case NORTH -> new Vec3d(d, d3, box.minZ);
                  case SOUTH -> new Vec3d(d, d3, box.maxZ);
                  case WEST -> new Vec3d(box.minX, d3, d2);
                  case EAST -> new Vec3d(box.maxX, d3, d2);
               };
               if (!(vec.squaredDistanceTo(vec3d) > autoBuilderFactor * autoBuilderFactor)) {
                  float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d);
                  BlockHitResult blockHitResult = this.raycastFromEye(vec, fs[0], fs[1], autoBuilderFactor);
                  if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
                     return vec3d;
                  }
               }
            }
         }
      }

      return null;
   }

   private Map<Long, long[]> getRailJoinOrderMap() {
      if (this.schematicCells == null || this.targetFluidItems == null) {
         return Map.of();
      } else if (this.schematicCellsLongArrayMap != null && this.autoBuilderObject == this.schematicCells && this.schematicCellsLastBlockCount == this.blockValue) {
         return this.schematicCellsLongArrayMap;
      } else {
         this.autoBuilderObject = this.schematicCells;
         this.schematicCellsLastBlockCount = this.blockValue;
         this.schematicCellsPositionSet.clear();
         ArrayList<SouthNorthUtilsFormat.RailOrder.Rail> arrayList = new ArrayList<>();

         for (int n = 0; n < this.schematicCells.size() && n < this.targetFluidItems.size(); n++) {
            BlockState blockState = this.targetFluidItems.get(n);
            if (blockState.getBlock() instanceof AbstractRailBlock abstractRailBlock && blockState.contains(abstractRailBlock.getShapeProperty())) {
               BlockPos blockPos = this.schematicCells.get(n);
               arrayList.add(
                  new SouthNorthUtilsFormat.RailOrder.Rail(
                     blockPos.asLong(),
                     blockPos.getX(),
                     blockPos.getY(),
                     blockPos.getZ(),
                     blockState.getBlock() instanceof RailBlock,
                     SouthNorthUtilsFormat.RailOrder.getSouthNorth(blockState.get(abstractRailBlock.getShapeProperty()).asString())
                  )
               );
            }
         }

         try {
            this.schematicCellsLongArrayMap = SouthNorthUtilsFormat.RailOrder.getMap(arrayList);
         } catch (RuntimeException e) {
            this.schematicCellsLongArrayMap = Map.of();
            this.logDebugMessage("\u00a7e[RailOrder]\u00a7r no join order (" + e + ") - rails keep today's order");
         }

         if (!this.schematicCellsLongArrayMap.isEmpty()) {
            this.logDebugMessage(
               "\u00a7b[RailOrder]\u00a7r "
                  + this.schematicCellsLongArrayMap.size()
                  + " of "
                  + arrayList.size()
                  + " rails go in a vanilla join order - a rail joins every side rail with a free end, so each waits for the rails before it within 3 blocks"
            );
         }

         return this.schematicCellsLongArrayMap;
      }
   }

