   private static boolean matchesFacingState(BlockState state, BlockState placementStateForSlot) {
      if (placementStateForSlot == null || placementStateForSlot.getBlock() != state.getBlock()) {
         return false;
      } else if (requiresSneakToPlace(state)) {
         return true;
      } else {
         for (Property property : new Property[]{
            Properties.FACING, Properties.HORIZONTAL_FACING, Properties.HOPPER_FACING, Properties.ORIENTATION, Properties.AXIS
         }) {
            if (state.contains(property) && (!placementStateForSlot.contains(property) || !placementStateForSlot.get(property).equals(state.get(property)))) {
               return false;
            }
         }

         return true;
      }
   }

