   private boolean retryRelaxedFacingCell() {
      if (this.relaxFacingWhenStuck.isEnabled() && !this.blockShortPositionSet.isEmpty()) {
         for (Long longValue : new ArrayList<>(this.blockShortPositionSet)) {
            if (!this.blockShortSeenPositions.contains(longValue)) {
               BlockPos blockPos = BlockPos.fromLong(longValue);
               int n = this.getSchematicCells(blockPos);
               BlockState blockState = n >= 0 ? this.targetFluidItems.get(n) : null;
               this.blockShortSeenPositions.add(longValue);
               if (blockState != null
                  && this.hasWantedTargetAt(blockPos)
                  && mc.world.getBlockState(blockPos).getBlock() == blockState.getBlock()
                  && !this.computeBlockStateMismatch(blockPos, blockState).empty) {
                  this.blockShortPositionSet.remove(longValue);
                  this.blueprintPositionMap.remove(this.getSealsPlacement(blockPos, 0L));
                  this.blueprintPositionMap.remove(this.getSealsPlacement(blockPos, 6510615555426900570L));
                  BlockPos cachedRelaxedStand = this.getCachedRelaxedStand(blockPos);
                  if (cachedRelaxedStand != null) {
                     this.directionalFacingMap.remove(longValue);
                     this.deferCount.remove(longValue);
                     this.cooldown.remove(longValue);
                     this.entries.remove(longValue);
                     this.logDebugMessage(
                        "\u00a7b[RelaxFacing]\u00a7r "
                           + blockPos.toShortString()
                           + " "
                           + getBlockRegistryPath(blockState)
                           + " - build complete and a stand with the exact facing exists now: retrying it properly (fix-up pass)"
                     );
                     return true;
                  }

                  this.blockShortPositionSet.add(longValue);
               }
            }
         }

         return false;
      } else {
         return false;
      }
   }

