   private void giveCreativeMaterials() {
      if (mc.player != null && mc.interactionManager != null) {
         if (!mc.player.getAbilities().creativeMode) {
            DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Creative singleplayer only", false);
            this.sendPlayerChatMessage(
               "\u00a7e[Auto Builder]\u00a7r 'Creative Materials Get' only works in a creative world - it uses the creative set-slot packet, which the server ignores in survival/on a real server."
            );
         } else {
            ElseBuilder loadedSchematic = this.schematicBuilder.getLoadedSchematic();
            if (loadedSchematic == null) {
               DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Select a schematic first", false);
            } else {
               LinkedHashMap<Item, Integer> linkedHashMap = new LinkedHashMap<>();

               for (Entry<Block, Integer> entry : loadedSchematic.builderSelectMap.entrySet()) {
                  Item item = getItemForBlockState(entry.getKey() == Blocks.BUBBLE_COLUMN ? Blocks.WATER.getDefaultState() : entry.getKey().getDefaultState());
                  if (item != Items.AIR) {
                     linkedHashMap.merge(item, entry.getValue(), Integer::sum);
                  }
               }

               if (linkedHashMap.isEmpty()) {
                  DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Nothing required", false);
               } else {
                  PlayerInventory playerInventory = mc.player.getInventory();
                  int n2 = 0;
                  int n3 = 0;
                  int n4 = 0;

                  for (Entry<Item, Integer> entryItem : linkedHashMap.entrySet()) {
                     Item item2 = entryItem.getKey();
                     int n = Math.min(entryItem.getValue(), new ItemStack(item2).getMaxCount());
                     if (getStack(playerInventory, item2) >= n) {
                        n3++;
                     } else if (this.giveCreativeStackToEmptySlot(playerInventory, item2)) {
                        n2++;
                     } else {
                        this.dropCreativeStackOf(item2);
                        n4++;
                     }
                  }

                  if (getStack(playerInventory, Items.DIRT) < 64) {
                     if (this.giveCreativeStackToEmptySlot(playerInventory, Items.DIRT)) {
                        n2++;
                     } else {
                        this.dropCreativeStackOf(Items.DIRT);
                        n4++;
                     }
                  }

                  DisabledEnabled.getInstance()
                     .handleDisabledEnabled(
                        "Auto Builder", "Gave " + n2 + " material" + (n2 == 1 ? "" : "s") + (n4 > 0 ? " (+" + n4 + " dropped)" : ""), n2 > 0 || n4 > 0
                     );
                  this.sendPlayerChatMessage(
                     "\u00a7a[Auto Builder]\u00a7r creative give: "
                        + n2
                        + " type(s) added, "
                        + n3
                        + " already carried"
                        + (n4 > 0 ? ", \u00a7e" + n4 + " dropped on the ground (inventory full)" : "")
                        + "."
                  );
               }
            }
         }
      }
   }

   private boolean areNeighborStairsOrientedCorrectly(BlockPos pos) {
      for (Direction direction : Type.HORIZONTAL) {
         BlockPos blockPos = pos.offset(direction);
         int n = this.getSchematicCells(blockPos);
         if (n >= 0) {
            BlockState blockState = this.targetFluidItems.get(n);
            if (blockState != null && blockState.getBlock() instanceof StairsBlock) {
               BlockState blockState2 = mc.world.getBlockState(blockPos);
               if (!(blockState2.getBlock() instanceof StairsBlock)) {
                  return false;
               }

               EnumProperty<Direction> enumProperty = Properties.HORIZONTAL_FACING;
               EnumProperty<BlockHalf> blockHalf = Properties.BLOCK_HALF;
               if (blockState.contains(enumProperty) && blockState2.contains(enumProperty) && blockState.get(enumProperty) != blockState2.get(enumProperty)) {
                  return false;
               }

               if (blockState.contains(blockHalf) && blockState2.contains(blockHalf) && blockState.get(blockHalf) != blockState2.get(blockHalf)
                  )
                {
                  return false;
               }
            }
         }
      }

      return true;
   }

   private boolean hasSolidSchematicSideCellAbove(BlockPos pos, int schematicCellsValue) {
      if (this.cellsSchematicObject != this.schematicCells) {
         int max = Integer.MIN_VALUE;

         for (BlockPos blockPos : this.schematicCells) {
            max = Math.max(max, blockPos.getY());
         }

         this.schematicTopY = max;
         this.cellsSchematicObject = this.schematicCells;
      }

      int n4 = pos.getY() + 1;

      while (n4 <= this.schematicTopY && this.getSchematicCells(new BlockPos(pos.getX(), n4, pos.getZ())) < 0) {
         n4++;
      }

      int min5 = Math.min(n4 - 1, pos.getY() + schematicCellsValue);

      for (Direction direction : Type.HORIZONTAL) {
         BlockPos offsetPos = pos.offset(direction);

         for (int n2 = pos.getY() + 1; n2 <= min5; n2++) {
            BlockPos blockPos2 = new BlockPos(offsetPos.getX(), n2, offsetPos.getZ());
            int n = this.getSchematicCells(blockPos2);
            if (n >= 0 && !this.targetFluidItems.get(n).getCollisionShape(mc.world, blockPos2).isEmpty()) {
               return true;
            }
         }
      }

      return false;
   }

