   private com.corz.client.utils.PlannedLiveUtils.Certificate getPlannedStepCertificate(BlockPos pos) {
      if (this.blockers == null) {
         return null;
      } else {
         for (SupportStandUtils.Step step : this.blockers.steps()) {
            if (step.op() == SupportStandUtils.Op.PLACE && step.intent() != null) {
               SupportStandUtils.Cell cell = step.cell();
               if (cell.x() == pos.getX() && cell.y() == pos.getY() && cell.z() == pos.getZ()) {
                  SupportStandUtils.Cell stand = step.intent().stand();
                  return new com.corz.client.utils.PlannedLiveUtils.Certificate(
                     ProofSupportUtils.getTime(cell.x(), cell.y(), cell.z()),
                     ProofSupportUtils.getTime(stand.x(), stand.y(), stand.z()),
                     step.intent().sneak(),
                     this.budgetExhaustedTime
                  );
               }
            }
         }

         return null;
      }
   }

   private long hashPositionPair(BlockPos pos, BlockPos pos2) {
      return SHARED_HASH_OPEN.hashOpenCellsInRadius(pos.getX(), pos.getY(), pos.getZ(), 4)
         ^ SHARED_HASH_OPEN.hashOpenCellsInRadius(pos2.getX(), pos2.getY(), pos2.getZ(), 4) * 31L;
   }

   private void rebuildUnreachableCellMap(boolean unpackFlag) {
      if (this.completedDeferredFlag) {
         this.rebuildReachableComponent();
         long l3 = this.getActiveComponentKey() * -7046029254386353131L ^ (long)this.completionMissionMap.size() << 40 ^ this.unpackValue;
         if (l3 != this.unpackLastKey) {
            if (!unpackFlag && this.lastTickUnpack > -100000 && this.moduleTick - this.lastTickUnpack < 100) {
               if (this.unpackValue != this.lastSeenUnpackTime) {
                  this.unpackActive = true;
               }
            } else {
               this.unpackLastKey = l3;
               this.lastTickUnpack = this.moduleTick;
               this.lastSeenUnpackTime = this.unpackValue;
               this.unpackPositionMap.clear();
               this.unpackArrayListMap.clear();
               if (!this.completionMissionMap.isEmpty() && mc.world != null) {
                  int ceil7 = (int)Math.ceil(this.reachSetting.getValue());
                  HashSet<Long> hashSet = new HashSet<>(Math.min(131072, Math.max(1024, this.component.size() * 320)));
                  double max2 = Math.max(1.0, this.reachSetting.getValue() - 0.6);
                  double d3 = max2 * max2;

                  for (long l : this.component) {
                     int unpackLongX4 = BlockPos.unpackLongX(l);
                     int unpackLongY5 = BlockPos.unpackLongY(l);
                     int unpackLongZ6 = BlockPos.unpackLongZ(l);

                     for (int n3 = -ceil7; n3 <= ceil7; n3++) {
                        for (int n2 = -ceil7; n2 <= ceil7; n2++) {
                           for (int n = -2; n <= 2; n++) {
                              double d = n - 1.12;
                              if (!(n3 * n3 + d * d + n2 * n2 > d3)) {
                                 hashSet.add(BlockPos.asLong(unpackLongX4 + n3, unpackLongY5 + n, unpackLongZ6 + n2));
                              }
                           }
                        }
                     }
                  }

                  ArrayList<Long> arrayList = new ArrayList<>();

                  for (long l2 : this.completionMissionMap.keySet()) {
                     if (!hashSet.contains(l2)) {
                        arrayList.add(l2);
                     }
                  }

                  this.unpackPositionMap = new HashMap<>(Failures.getPositionMapWithBound(arrayList, 1));

                  for (Entry<Long, Long> entry : this.unpackPositionMap.entrySet()) {
                     this.unpackArrayListMap.computeIfAbsent(entry.getValue(), longValue -> new ArrayList<>()).add(entry.getKey());
                  }
               }
            }
         }
      }
   }

