   public static boolean areBlocksEquivalentVariants(BlockState state, BlockState worldState) {
      Block block = state.getBlock();
      Block block2 = worldState.getBlock();
      return block == Blocks.DIRT && block2 == Blocks.GRASS_BLOCK
         || block == Blocks.WATER && block2 == Blocks.BUBBLE_COLUMN
         || block == Blocks.GRASS_BLOCK && block2 == Blocks.DIRT
         || block == Blocks.TWISTING_VINES_PLANT && block2 == Blocks.TWISTING_VINES
         || block == Blocks.WEEPING_VINES_PLANT && block2 == Blocks.WEEPING_VINES
         || block == Blocks.BAMBOO && block2 == Blocks.BAMBOO_SAPLING
         || block == Blocks.BAMBOO_SAPLING && block2 == Blocks.BAMBOO;
   }

   private BlockHitResult raycastFromEyeAngles(Vec3d vec, float degrees, float degrees2, double raycastRaycastsValue) {
      this.selectPasses.handleTimes(Counter.RAYCASTS);
      double radians2 = Math.toRadians(degrees);
      double radians3 = Math.toRadians(degrees2);
      Vec3d vec3d2 = new Vec3d(-Math.sin(radians2) * Math.cos(radians3), -Math.sin(radians3), Math.cos(radians2) * Math.cos(radians3));
      Vec3d vec3d3 = vec.add(vec3d2.multiply(raycastRaycastsValue));
      return mc.world.raycast(new RaycastContext(vec, vec3d3, ShapeType.OUTLINE, FluidHandling.SOURCE_ONLY, mc.player));
   }

   private void handleBuyItemFailure(String affordablePagesText) {
      if (!this.affordablePagesFlag
         || this.snipesFreshValue >= 8
         || this.complete != AutoBuilder.BuyMode.BUY
         || this.affordablePagesItem == null
         || this.buyQuantity <= 0
         || !affordablePagesText.startsWith("no affordable listing") && !affordablePagesText.startsWith("no more pages")) {
         if (this.affordablePagesItem != null && (affordablePagesText.startsWith("no affordable listing") || affordablePagesText.startsWith("no more pages"))) {
            if (this.listingPageValue >= 0L) {
               affordablePagesText = "cheapest listing " + BuyerAppendUtils.formatText(this.listingPageValue) + " each is " + this.getBuySpendingLimit(this.affordablePagesItem).formatLimitUnit();
            } else if (this.affordablePagesActive) {
               affordablePagesText = "every listing costs more than " + BuyerAppendUtils.formatText(this.getRemainingBuyBudget()) + " (Spending Limit Per Buy / Max Total Spend)";
            }
         }

         if (this.listingShowedFlag && this.affordablePagesItem != null) {
            int n = this.getBuyRetryDelayTicks(this.affordablePagesItem);
            this.recordNoFreeSpaceForItem(this.affordablePagesItem, affordablePagesText, n);
            if (this.buyNotifications.isEnabled()) {
               this.sendPlayerChatMessage(
                  "\u00a7e[AutoBuy]\u00a7r skipped "
                     + Math.max(0, this.buyQuantity)
                     + "\u00d7 "
                     + getItemIdPath(this.affordablePagesItem)
                     + " \u00a77("
                     + affordablePagesText
                     + ")\u00a7r - building on, next try in ~"
                     + n / 20
                     + "s"
               );
            }

            this.advanceToNextBuyItem();
         } else {
            if (this.complete == AutoBuilder.BuyMode.BUY && this.affordablePagesItem != null && this.buyQuantity > 0) {
               int merge3 = this.affordablePagesIntegerMap.merge(this.affordablePagesItem, 1, Integer::sum);
               if (merge3 <= 4) {
                  int n2 = 900 + ThreadLocalRandom.current().nextInt(300);
                  this.screenModuleIntegerMap.put(this.affordablePagesItem, this.moduleTick + n2);
                  this.pricingMaterialItems.add(this.affordablePagesItem);
                  if (this.buyNotifications.isEnabled()) {
                     this.sendPlayerChatMessage(
                        "\u00a7e[AutoBuy]\u00a7r nothing affordable for "
                           + Math.max(0, this.buyQuantity)
                           + "\u00d7 "
                           + getItemIdPath(this.affordablePagesItem)
                           + " right now \u00a77("
                           + affordablePagesText
                           + ") - trying again in ~"
                           + n2 / 20
                           + "s ("
                           + merge3
                           + "/"
                           + 4
                           + ")"
                     );
                  }

                  this.advanceToNextBuyItem();
                  return;
               }
            }

            if (this.buyNotifications.isEnabled()) {
               this.sendPlayerChatMessage(
                  "\u00a7c[AutoBuy]\u00a7r couldn't buy "
                     + Math.max(0, this.buyQuantity)
                     + "\u00d7 "
                     + getItemIdPath(this.affordablePagesItem)
                     + " \u00a77("
                     + affordablePagesText
                     + ") - giving up on it"
               );
            }

            this.advanceToNextBuyItem();
         }
      } else {
         this.affordablePagesFlag = false;
         this.boardSnipesFlag = true;
         this.listingPageValue = -1L;
         this.affordablePagesActive = false;
         this.listingAffordableFlag = false;
         this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SEARCH, "board went stale (bought/sniped listings) - fresh search for " + getItemIdPath(this.affordablePagesItem));
      }
   }

