   private boolean doesSlotPlacementMatchState(BlockState state, int slabHalfValue, BlockHitResult blockHitResult2) {
      EnumProperty<SlabType> enumProperty = Properties.SLAB_TYPE;
      EnumProperty<BlockHalf> blockHalf = Properties.BLOCK_HALF;
      boolean flag = state.contains(enumProperty) || state.contains(blockHalf);
      if (!hasOrientationProperty(state) && !flag) {
         return true;
      } else {
         BlockState placementStateForSlot = this.getPlacementStateForSlot(slabHalfValue, blockHitResult2);
         if (placementStateForSlot == null) {
            return !flag;
         } else {
            boolean flag2 = (
                  !state.contains(enumProperty) || placementStateForSlot.contains(enumProperty) && placementStateForSlot.get(enumProperty) == state.get(enumProperty)
               )
               && (
                  !state.contains(blockHalf) || placementStateForSlot.contains(blockHalf) && placementStateForSlot.get(blockHalf) == state.get(blockHalf)
               );
            return BoolImpliesLogic.doesImply(true, flag2 && (!hasOrientationProperty(state) || matchesFacingState(state, placementStateForSlot)));
         }
      }
   }

