   private int countMissingCellsNearby(BlockPos pos, int blockFluidLimit, int blockFluidValue) {
      int n4 = 0;

      for (int n : this.getSchematicIndicesNear(Vec3d.ofCenter(pos), blockFluidLimit * 1.74 + 0.5)) {
         BlockPos blockPos = this.schematicCells.get(n);
         if (Math.abs(blockPos.getX() - pos.getX()) <= blockFluidLimit
            && Math.abs(blockPos.getY() - pos.getY()) <= blockFluidLimit
            && Math.abs(blockPos.getZ() - pos.getZ()) <= blockFluidLimit) {
            BlockState blockState = mc.world.getBlockState(blockPos);
            if (blockState.getBlock() != this.targetFluidItems.get(n).getBlock()
               && !areBlocksEquivalentVariants(this.targetFluidItems.get(n), blockState)
               && (blockState.isAir() || blockState.isReplaceable())) {
               Integer integer = this.cooldown.get(blockPos.asLong());
               if (integer == null || this.moduleTick >= integer) {
                  if (++n4 >= blockFluidValue) {
                     break;
                  }
               }
            }
         }
      }

      return n4;
   }

   private void startAutoBuyScan() {
      if (mc.player.getAbilities().creativeMode) {
         this.showToggleNotification("Auto Buy", "Creative mode needs no materials", false);
      } else {
         boolean flag = this.isEnabled();
         if (!flag) {
            this.setEnabled(true);
         }

         this.loadSchematicCellsIfMissing();
         this.updateMaterialAvailability();
         if (this.availableLow != null && !this.availableLow.readSelectedItems.isEmpty()) {
            List<CountsLateUtils.Layer<Item>> list = this.getMissingMaterialLayers();
            int n = 0;

            for (CountsLateUtils.Layer<Item> layer : list) {
               n += layer.getCounts();
            }

            if (n == 0) {
               this.showToggleNotification("Auto Buy", "Nothing left to buy - no placeable block is missing", true);
               this.resetBuyAutoState();
               if (!flag) {
                  this.setEnabled(false);
               }
            } else {
               if (!this.buyMaterialsFlag) {
                  this.buyAutoTime = 0L;
                  this.buyAutoPurchasedCount = 0;
                  this.buyAutoCount = 0;
               }

               this.buyMaterialsFlag = true;
               this.showedBuyText = null;
               this.buyAutoRetryCount = 0;
               this.dirtBuyAttemptCount = 0;
               this.buyAutoValue = this.moduleTick;
               this.buyAutoCooldownUntilTick = -100000;
               this.layersNeedValue = -1;
               Arrays.fill(this.buyAutoValues, -100000);
               this.freeInventoryMap.clear();
               this.buyShowedIntegerMap.clear();
               this.spaceFreeMap.clear();
               this.buyAutoMap.clear();
               this.spaceFreeValue = 0;
               if (this.buyNotifications.isEnabled()) {
                  this.sendPlayerChatMessage(
                     "\u00a7b[AutoBuy]\u00a7r scanned the schematic: \u00a7f"
                        + n
                        + "\u00a7r block"
                        + (n == 1 ? "" : "s")
                        + " left in \u00a7f"
                        + list.size()
                        + "\u00a7r layer"
                        + (list.size() == 1 ? "" : "s")
                        + " - buying the lowest layers first, the rest as the build climbs"
                  );
               }

               boolean flag2 = this.state2Builder == AutoBuilder.State.IDLE
                  || this.state2Builder == AutoBuilder.State.SELECT_TARGET
                  || this.state2Builder == AutoBuilder.State.PAUSED
                  || this.state2Builder == AutoBuilder.State.FAILED_NO_MATERIALS
                  || this.state2Builder == AutoBuilder.State.FAILED_UNSUPPORTED;
               if (!flag2 || !this.canBuyAuto(AutoBuilder.LayerBuyTrigger.MANUAL, "first layers")) {
                  this.showToggleNotification("Auto Buy", "Auction restock is on - the next layers are bought when the bot runs out", true);
               }
            }
         } else {
            this.showToggleNotification("Auto Buy", "Couldn't read the schematic - is one selected?", false);
            if (!flag) {
               this.setEnabled(false);
            }
         }
      }
   }

