   private boolean tryExecuteMissionPick(FloorBuildPlanner.Pick pick, AutoBuilder.MissionPlacement missionPlacement2, BlockPos pos) {
      Signature signature = new Signature(
         this.deckMicroMoves.getNoneCount(),
         pick.cell(),
         pick.stand(),
         "CHOOSE",
         this.remaining.floorCells.hashCode(),
         this.deckMicroMoves.surfacePlacementsCount,
         pos.asLong(),
         this.getCellStand(pick),
         this.cells.hashCode()
      );
      int n = this.cycleDeckRevisionSurface.getRevisionSurface(signature, this.moduleTick);
      if (n > 1) {
         this.deckMicroMoves.cycleMissionCount++;
         this.excludePickTarget(pick, "MISSION_CYCLE");
         this.logDebugMessage(
            "\u00a7e[MissionCycle]\u00a7r mission="
               + this.deckMicroMoves.getNoneCount()
               + " signature="
               + signature
               + " repeats="
               + n
               + " lastProgressTicks="
               + this.cycleDeckRevisionSurface.getMax(this.moduleTick)
               + " action=REPLAN_DIFFERENT_FRONTIER"
         );
         return true;
      } else {
         BlockPos fromLong = BlockPos.fromLong(pick.cell());
         BlockPos fromLong3 = BlockPos.fromLong(pick.stand());
         if (!this.tryCommitPlacement(Owner.DECK, this.deckMicroMoves.getNoneCount(), fromLong, fromLong3, missionPlacement2)) {
            return true;
         } else {
            this.missionPlacement2ExecutorUna = missionPlacement2;
            this.egressChangedValue = this.moduleTick;
            boolean flag = missionPlacement2.cert() != null && missionPlacement2.cert().isExecutableWithAdjust();
            this.actionEgressActive = flag && missionPlacement2.cert().sneak() && this.droppedPlaced != null && this.droppedPlaced.isRemainingTier();
            Candidate candidate = this.buildClickCandidate(pick, missionPlacement2);
            float f = Math.abs(TierBuilderUtils.getAmount(this.faceCycleDeck == null ? mc.player.getYaw() : this.cycleDeckLastYaw, candidate.yaw()));
            this.cycleDeckAccumulated += f;
            this.cycleDeckAmount = this.cycleDeckAmount + Math.abs(mc.player.getPitch() - candidate.pitch());
            this.cycleDeckFloatList.add(f);
            if (f > 90.0F) {
               this.cycleDeckStepCount++;
            }

            if (candidate.face().equals(this.faceCycleDeck)) {
               this.cycleDeckSkipCount++;
            }

            if (candidate.material().equals(this.materialCycleDeck)) {
               this.cycleDeckRetryCount++;
            }

            if (this.faceCycleDeck != null && Math.abs(TierBuilderUtils.getAmount(this.cycleDeckLastYaw, candidate.yaw())) < 20.0F) {
               this.cycleDeckCount++;
            }

            this.faceCycleDeck = candidate.face();
            this.materialCycleDeck = candidate.material();
            this.cycleDeckLastYaw = candidate.yaw();
            if (fromLong3.equals(pos)) {
               this.updateMissionArrival();
            } else {
               this.startDeckSurfaceMove(fromLong3, fromLong, pos);
            }

            return true;
         }
      }
   }

