   private boolean hasReachableStandForTarget(BlockPos pos, BlockPos pos2) {
      this.rebuildReachableComponent();
      long l = this.getProgressSignature();
      long time2 = this.passesSelectTimeHandle.getTime(pos.asLong(), l);
      if (time2 == Long.MIN_VALUE) {
         this.selectPasses.handleTimes(Counter.PROOF_CACHE_HITS);
         return false;
      } else if (time2 != -9223372036854775807L) {
         this.selectPasses.handleTimes(Counter.PROOF_CACHE_HITS);
         return true;
      } else {
         this.selectPasses.handleTimes(Counter.PROOF_CACHE_MISSES);
         this.selectPasses.handleTimes(Counter.STAND_SCANS);
         BlockPos nearestStandPosition = WalkRouteFinder.findNearestStandPosition(
            pos,
            this.reachSetting.getValue(),
            blockPos2x -> !FlagPoseUtils.canFlagPosePair(pos.asLong(), blockPos2x.asLong()) && this.isWithinReachFromStand(pos, blockPos2x)
         );
         if (nearestStandPosition == null) {
            this.passesSelectTimeHandle.handleTime(pos.asLong(), l, Long.MIN_VALUE);
            return false;
         } else {
            boolean flag;
            if (nearestStandPosition.equals(pos2)) {
               flag = true;
            } else {
               this.selectPasses.handleTimes(Counter.ASTAR_RUNS);
               List<BlockPos> list = this.findGoPath(pos2, nearestStandPosition);
               this.selectPasses.handleTimes(Counter.ASTAR_NODES, WalkRouteFinder.getLastPathDiagnostics().expanded());
               flag = list != null && !list.isEmpty();
            }

            this.passesSelectTimeHandle.handleTime(pos.asLong(), l, flag ? nearestStandPosition.asLong() : Long.MIN_VALUE);
            return flag;
         }
      }
   }

   private long[] collectSightlineCellKeys(BlockPos pos, BlockPos pos2) {
      LinkedHashSet<Long> linkedHashSet = new LinkedHashSet<>();
      linkedHashSet.add(pos2.down().asLong());
      linkedHashSet.add(pos2.asLong());
      linkedHashSet.add(pos2.up().asLong());

      for (Direction direction : Type.HORIZONTAL) {
         linkedHashSet.add(pos2.offset(direction).asLong());
      }

      linkedHashSet.add(pos.asLong());

      for (Direction direction2 : Direction.values()) {
         linkedHashSet.add(pos.offset(direction2).asLong());
      }

      Vec3d vec3d = this.shouldCrouchForSafeSneak(pos2, pos) ? getLoweredTargetPoint(pos2) : getStandingEyePos(pos2);
      Vec3d vec3d2 = Vec3d.ofCenter(pos);
      Vec3d vec3d3 = vec3d2.subtract(vec3d);
      int min2 = Math.min(64, (int)Math.ceil(vec3d3.length() / 0.25));

      for (int n = 0; n <= min2; n++) {
         linkedHashSet.add(BlockPos.ofFloored(vec3d.add(vec3d3.multiply(min2 == 0 ? 0.0 : (double)n / min2))).asLong());
      }

      long[] ls = new long[linkedHashSet.size()];
      int n3 = 0;

      for (long l : linkedHashSet) {
         ls[n3++] = l;
      }

      return ls;
   }

   private boolean beginFiniteBlockedFluidPour() {
      if (mc.player != null
         && mc.world != null
         && this.schematicCells != null
         && this.finiteBlockedValue > 0
         && this.finiteBlockedValue != Integer.MAX_VALUE
         && this.finiteBlockedLastConfirms != this.confirms) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         long key = Long.MIN_VALUE;
         int max = Integer.MAX_VALUE;

         for (Entry<Long, BlockState> entry : this.completionMissionMap.entrySet()) {
            long l = entry.getKey();
            int n = Math.max(Math.abs(BlockPos.unpackLongX(l) - feetBlockPos.getX()), Math.abs(BlockPos.unpackLongZ(l) - feetBlockPos.getZ()));
            if ((
                  !this.excludedTargets.canFingerprintCells(l, this::getRawBlockStateIdAt)
                     || this.shouldPlaceWaterAt(BlockPos.fromLong(l), entry.getValue()) && this.excludedTargets.hasBan(l)
               )
               && n < max) {
               BlockPos blockPos = BlockPos.fromLong(l);
               if (!mc.world.getBlockState(blockPos).getFluidState().isStill() && this.shouldPlaceWaterAt(blockPos, entry.getValue())) {
                  key = l;
                  max = n;
               }
            }
         }

         if (key == Long.MIN_VALUE) {
            return false;
         } else {
            this.finiteBlockedLastConfirms = this.confirms;
            this.finiteBlockedLastLimit = this.finiteBlockedValue;
            this.logDebugMessage(
               "\u00a7e[FluidSafety]\u00a7r terminal stall with "
                  + this.finiteBlockedValue
                  + " non-fluid block(s) left - the contained source(s) that wet no stand (nearest "
                  + BlockPos.fromLong(key).toShortString()
                  + ") are poured before any pause; the parked cells are retried after them"
            );
            this.finiteBlockedText = "finite blocked list";
            this.finiteBlockedTime = Long.MIN_VALUE;
            this.finiteBlockedActive = true;
            this.finiteBlockedPlacedCount = 0;
            this.next = Long.MIN_VALUE;
            this.longFiniteBlocked = key;
            this.blockers = null;
            this.stepIndex = -1;
            this.stepsTimeBudget.updateTimeMax();
            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "terminal stall: contained sources poured before any pause");
            return true;
         }
      } else {
         return false;
      }
   }

