   private HashSet<Long> floodFillReplaceableCells(BlockPos pos) {
      HashMap<Long, Integer> hashMap = new HashMap<>();
      ArrayDeque<long[]> arrayDeque = new ArrayDeque<>();
      hashMap.put(pos.asLong(), 4);
      arrayDeque.add(new long[]{pos.asLong(), 4L});
      int n2 = 0;

      while (!arrayDeque.isEmpty() && n2++ < 400 && hashMap.size() < 256) {
         long[] ls = arrayDeque.poll();
         BlockPos fromLong = BlockPos.fromLong(ls[0]);
         BlockPos down = fromLong.down();
         if (this.isReplaceable(down)) {
            Integer integer = hashMap.get(down.asLong());
            if (integer == null || integer < 4) {
               hashMap.put(down.asLong(), 4);
               arrayDeque.add(new long[]{down.asLong(), 4L});
            }
         } else {
            int n = (int)ls[1];
            if (n > 0) {
               for (Direction direction : Type.HORIZONTAL) {
                  BlockPos blockPos = fromLong.offset(direction);
                  if (this.isReplaceable(blockPos)) {
                     Integer integer2 = hashMap.get(blockPos.asLong());
                     if (integer2 == null || integer2 < n - 1) {
                        hashMap.put(blockPos.asLong(), n - 1);
                        arrayDeque.add(new long[]{blockPos.asLong(), n - 1});
                     }
                  }
               }
            }
         }
      }

      return new HashSet<>(hashMap.keySet());
   }

   private long fingerprintStepNeighborhood(SupportStandUtils.Step step) {
      if (step.intent() != null) {
         return CellsFingerprint.getTime(this.collectIntentPathCells(step.intent()), this::getRawBlockStateIdAt);
      } else {
         BlockPos blockPos = toBlockPos(step.cell());
         long l = CellsFingerprint.getTime(getCubeCellKeys(blockPos, 1), this::getRawBlockStateIdAt);
         if (step.op() == SupportStandUtils.Op.PILLAR && step.stand() != null) {
            l ^= CellsFingerprint.getTime(getCubeCellKeys(toBlockPos(step.stand()), 1), this::getRawBlockStateIdAt) * 31L;
         }

         return l;
      }
   }

