   private int countGapCellsInRow(BlockPos pos, BlockPos pos2) {
      if (pos.getY() != pos2.getY()) {
         return -1;
      } else {
         int n4 = pos2.getX() - pos.getX();
         int n5 = pos2.getZ() - pos.getZ();
         if ((n4 == 0 || n5 == 0) && (n4 != 0 || n5 != 0)) {
            int n6 = Math.abs(n4) + Math.abs(n5);
            if (n6 <= 4
               && !mc.world.getBlockState(pos).getCollisionShape(mc.world, pos).isEmpty()
               && WalkRouteFinder.isStandable(mc.world, pos.up())) {
               Direction direction = n4 > 0 ? Direction.EAST : (n4 < 0 ? Direction.WEST : (n5 > 0 ? Direction.SOUTH : Direction.NORTH));
               int n7 = 0;

               for (int n3 = 1; n3 <= n6; n3++) {
                  BlockPos offsetPos = pos.offset(direction, n3);
                  if (!mc.world.getBlockState(offsetPos).getCollisionShape(mc.world, offsetPos).isEmpty()) {
                     if (n3 == n6) {
                        return -1;
                     }

                     for (int n = 1; n <= 2; n++) {
                        BlockPos blockPos = offsetPos.up(n);
                        if (!mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
                           return -1;
                        }
                     }

                     if (!WalkRouteFinder.isStandable(mc.world, offsetPos.up())) {
                        return -1;
                     }
                  } else {
                     if (this.cellTemporarySet.contains(offsetPos.asLong())) {
                        if (!this.isPlainFullCubeTarget(offsetPos) || this.isMachineArmedAt(offsetPos) || this.getRedstoneDeferralReason(offsetPos) != null) {
                           return -1;
                        }
                     } else {
                        BlockState blockState = mc.world.getBlockState(offsetPos);
                        if (this.getSchematicCells(offsetPos) >= 0 || !blockState.isAir() && !blockState.isReplaceable()) {
                           return -1;
                        }

                        n7++;
                        if (n7 > 1 || this.describeObserverPulseHazard(offsetPos) != null || this.isFacedByPiston(offsetPos)) {
                           return -1;
                        }
                     }

                     for (int n2 = 1; n2 <= 2; n2++) {
                        BlockPos offsetAbovePos = offsetPos.up(n2);
                        if (!mc.world.getBlockState(offsetAbovePos).getCollisionShape(mc.world, offsetAbovePos).isEmpty()) {
                           return -1;
                        }
                     }
                  }
               }

               return n7;
            } else {
               return -1;
            }
         } else {
            return -1;
         }
      }
   }

   private boolean tickStaffLogoff() {
      if (this.loggingStoppingActive) {
         return true;
      } else {
         if (!this.loggingStoppingFlag) {
            if (!this.stopOnStaffNearby.isEnabled() || !this.isStaffPlayerNearby()) {
               return false;
            }

            this.loggingStoppingFlag = true;
            this.loggingStoppingValue = this.moduleTick + Math.max(0, (int)Math.round(this.logoffDelay.getValue() * 20.0));
            this.stopBuildBecauseStaffNearby();
            DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", "Staff nearby - stopping, logging off", false);
            this.sendPlayerChatMessage(
               "\u00a7c[Auto Builder]\u00a7r staff detected nearby - stopped; logging off in "
                  + String.format(Locale.ROOT, "%.0f", this.logoffDelay.getValue())
                  + "s"
            );
         }

         this.updatePressedOptions2();
         if (this.moduleTick >= this.loggingStoppingValue) {
            this.loggingStoppingActive = true;
            if (mc.getNetworkHandler() != null) {
               mc.getNetworkHandler().getConnection().disconnect(Text.literal(this.logoffMessage.getCurrentText()));
            }
         }

         return true;
      }
   }

