   private BlockPos getValidStandCell(BlockPos pos) {
      BlockPos mirroredPos = this.getMirroredPos(pos);
      if (mirroredPos == null || mirroredPos.equals(pos) || mirroredPos.equals(pos.down())) {
         return null;
      } else if (this.canSealsDeferred(pos, mirroredPos)) {
         return null;
      } else if (WalkRouteFinder.isStandable(mc.world, mirroredPos)) {
         return null;
      } else {
         BlockPos down = mirroredPos.down();
         if (this.getSchematicCells(down) < 0 && !this.cellTemporarySet.contains(down.asLong())) {
            BlockState blockState = mc.world.getBlockState(down);
            if (!blockState.isAir() && !blockState.isReplaceable()) {
               return null;
            } else {
               BlockState blockState2 = mc.world.getBlockState(mirroredPos);
               if (!blockState2.isAir() && !blockState2.isReplaceable()) {
                  return null;
               } else {
                  return !mc.world.getBlockState(mirroredPos.up()).getCollisionShape(mc.world, mirroredPos.up()).isEmpty()
                     ? null
                     : mirroredPos;
               }
            }
         } else {
            return null;
         }
      }
   }

   private List<CountsLateUtils.Layer<Item>> computeMissingMaterialLayers() {
      TreeMap<Integer, HashMap<Item, Integer>> treeMap = new TreeMap<>();
      int min2 = Math.min(this.schematicCells.size(), this.targetFluidItems.size());

      for (int n = 0; n < min2; n++) {
         BlockState blockState = this.targetFluidItems.get(n);
         Item item = getItemForBlockState(blockState);
         if (item != Items.AIR) {
            BlockPos blockPos = this.schematicCells.get(n);
            if (mc.world.getBlockState(blockPos).getBlock() != blockState.getBlock() || !this.isPlacedStateAcceptable(blockPos, blockState)) {
               treeMap.computeIfAbsent(blockPos.getY(), integer -> new HashMap<>()).merge(item, 1, Integer::sum);
            }
         }
      }

      ArrayList<CountsLateUtils.Layer<Item>> arrayList = new ArrayList<>(treeMap.size());

      for (Entry<Integer, HashMap<Item, Integer>> entry : treeMap.entrySet()) {
         arrayList.add(new CountsLateUtils.Layer<>(entry.getKey(), entry.getValue()));
      }

      return arrayList;
   }

