   private String formatSearchTermForItem(Item item2, int displaySpacedBound) {
      String formatText = this.ahSearchBy.getCurrentOption();

      String[] strings = switch (formatText) {
         case "Id" -> new String[]{"Id", "Display", "Spaced"};
         case "Display" -> new String[]{"Display", "Spaced", "Id"};
         default -> new String[]{"Spaced", "Display", "Id"};
      };
      String string = strings[Math.max(0, Math.min(2, displaySpacedBound))];
      String itemIdPath = getItemIdPath(item2);

      return switch (string) {
         case "Id" -> itemIdPath;
         case "Display" -> new ItemStack(item2).getName().getString();
         default -> itemIdPath.replace('_', ' ');
      };
   }

