   private void rejectPoseNoLineOfSight(Direction direction2, String streakLosText) {
      BlockPos feetBlockPos = this.getFeetBlockPos();
      if (this.placementExplicit != null && this.placementExplicit.isRevalidateAlign()) {
         this.failExplicitPlacement("EXECUTOR_PROOF_INVALID: " + streakLosText);
         this.updatePressedOptions2();
         this.path.clear();
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "mission pose explicitly rejected");
      } else if (this.hasActiveBlockersStep() && this.blockPosBlockersStep != null && feetBlockPos.equals(this.blockPosBlockersStep)) {
         this.missionParityCount++;
         this.selectPasses.handleTimes(Counter.COMPLETION_POSE_REJECTS);
         this.setBudgetExhaustedReason("executor rejected planned pose: " + streakLosText);
         this.updatePressedOptions2();
         this.path.clear();
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "mission: pose rejected at planned stand");
      } else {
         if (this.currentTargetPos != null) {
            this.recordBannedStandPair(getTimeForBlockPos(this.currentTargetPos, feetBlockPos), this.moduleTick + 140);
         }

         if (streakLosText == null || !streakLosText.startsWith("no oriented aim")) {
            this.losStreakValue++;
         }

         this.updatePressedOptions2();
         this.path.clear();
         if (this.losStreakValue > 10) {
            this.losStreakValue = 0;
            this.transitionToState(AutoBuilder.State.RECOVER_STUCK, "no-LOS streak - hard replan");
         } else {
            if (this.currentTargetPos != null && ++this.standRouteCount <= 3) {
               BlockPos blockPos = this.getCachedRelaxedStand(this.currentTargetPos);
               if (blockPos != null && !blockPos.equals(feetBlockPos)) {
                  this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "reposition: " + streakLosText);
                  return;
               }
            }

            if (this.currentTargetPos == null || streakLosText == null || !streakLosText.contains("support face") || !this.tryPlaceTempSupport(this.currentTargetPos)) {
               if (direction2 != null && this.currentTargetPos != null) {
                  this.faceParityMap.put(hashPosAndDirection(this.currentTargetPos, direction2), this.moduleTick + 100);
               }

               if (this.currentTargetPos != null && this.isCurrentTransferTarget(this.currentTargetPos.asLong()) && CompoundCompleteUtils.isCompoundLimitReached(++this.noActionableContinuation, 2)) {
                  this.releaseCompoundLease("no_actionable_continuation");
                  this.noActionableContinuation = 0;
               }

               this.handleBlockDefer(streakLosText + " - deferring (no visible stand)");
            }
         }
      }
   }

