   private boolean approveRouteByRoi(List<BlockPos> wordListed, BlockPos pos) {
      if (this.movementMissionData.owner() == Owner.EGRESS
         && this.blockPos2LifelineExtension != null
         && this.movementMissionData.destination() == this.blockPos2LifelineExtension.asLong()
         && this.isKeptExitStairColumn(this.blockPos2LifelineExtension.down().asLong())) {
         this.reasonExtensionCount++;
         this.reasonExtensionMissCount++;
         this.reasonExtensionText = "GO reason=EXIT_STAIR_EXTENSION";
         return true;
      } else if (this.state2Builder == AutoBuilder.State.WATERLOG && this.arrivedStandFlag && wordListed.size() <= 12) {
         this.reasonExtensionCount++;
         this.reasonExtensionMissCount++;
         this.reasonExtensionText = "GO reason=WATERLOG_STAND";
         return true;
      } else if (this.state2Builder == AutoBuilder.State.CLEANUP_TEMP && this.blockPos2Exit != null && this.coverReasonMap.containsKey(this.blockPos2Exit.asLong())) {
         this.reasonExtensionCount++;
         this.reasonExtensionMissCount++;
         this.reasonExtensionText = "GO reason=TEMP_COVER_RECLAIM";
         return true;
      } else {
         int n = this.movementMissionData.isPurposeMove() ? this.getPlannedUsefulBlockCount(pos) : this.movementMissionData.missionExpectedValue();
         boolean flag = this.isCompletionPhaseActive() || this.hasActiveBlockersStep() || this.currentTargetPos != null && this.isCurrentTransferTarget(this.currentTargetPos.asLong());
         int mountClimbHeight2 = this.getMountClimbHeight();
         if (this.reason != null
            && this.reason.isPinnedDispatched()
            && this.movementMissionData.associatedTarget() != null
            && this.movementMissionData.associatedTarget() == this.reason.getUnassignedMembersUnassignedMembersData()) {
            if (pos.asLong() == this.reason.getUnassignedMembers()) {
               this.reasonExtensionCount++;
               this.reasonExtensionMissCount++;
               this.redirectOriginal.arbitrations++;
               this.redirectOriginal.acceptCurrent++;
               this.reasonExtensionText = "GO reason=REDIRECT_EXECUTION redirectId=" + this.reason.getTime();
               return true;
            }

            this.onRouteRedirectInvalidated("claimed stand unreachable - the solver routed to " + pos.toShortString() + " instead");
         }

         List<AlternativeTicket> arrayList = new ArrayList<>();

         for (AlternativeTicket alternativeTicket : this.collectAccessAssetTickets(pos)) {
            if (!alternativeTicket.getAssetRegion().canAlternativeAsset(this.movementMissionData)) {
               arrayList.add(alternativeTicket);
            }
         }

         this.reasonExtensionCount++;
         this.reasonExtensionTotal += n;
         this.reasonExtensionValue = this.reasonExtensionValue + wordListed.size();
         this.selectPasses.handleTimes(Counter.ROI_EVALUATIONS);
         boolean flag2 = true;
         com.corz.client.utils.ValidatedRefusalUtils.Result result = ValidatedRefusalUtils.getAlternativeValidated(
            n, wordListed.size(), 0, flag, mountClimbHeight2, arrayList, this::explainTicketRejection, flag2
         );
         if (result.isDecisionRedirect()) {
            com.corz.client.utils.CostGainUtils.Verdict verdict = this.evaluateStayVersusAlternative(result.alternative(), wordListed.size());
            if (verdict != null && verdict.decision() == com.corz.client.utils.CostGainUtils.Decision.STAY) {
               this.reasonExtensionCheckCount++;
               this.reasonExtensionCount++;
               this.reasonExtensionMissCount++;
               this.redirectOriginal.arbitrations++;
               this.redirectOriginal.acceptCurrent++;
               this.reasonExtensionText = "GO reason=COMMITMENT_PAYS " + verdict.line();
               return true;
            }

            if (verdict != null) {
               this.reasonExtensionHitCount++;
            }
         }

         this.redirectOriginal.handleRedirectsArbitrations(result);
         com.corz.client.utils.LocalUtils.Decision decision = result.roi();
         this.reasonExtensionText = decision.getAppend();

         for (Phantom phantom : result.phantoms()) {
            this.recordDeadlockRefusal(phantom);
         }

         boolean decisionRedirect = result.isDecisionRedirect();
         String string = (
               this.movementMissionData.associatedTarget() == null
                  ? "move:" + BlockPos.fromLong(this.movementMissionData.destination()).toShortString()
                  : "place:" + BlockPos.fromLong(this.movementMissionData.associatedTarget()).toShortString()
            )
            + "/"
            + wordListed.size()
            + "n/"
            + n
            + "b";
         if (decisionRedirect || result.getPhantoms() > 0) {
            this.arbitrationAlternativeValue = this.moduleTick;
            AlternativeTicket alternative = result.alternative();
            this.logDebugMessage(
               "\u00a78[Arbitration]\u00a7r currentAction="
                  + string
                  + " decision="
                  + result.decision()
                  + " alternativeType="
                  + (alternative == null ? "none" : alternative.kind())
                  + " alternativeTarget="
                  + (alternative == null ? "none" : BlockPos.fromLong(alternative.target()).toShortString())
                  + " alternativeStand="
                  + (alternative == null ? "none" : BlockPos.fromLong(alternative.stand()).toShortString())
                  + " alternativeMission="
                  + (alternative == null ? 0L : alternative.missionId())
                  + " alternativeExpected="
                  + (alternative == null ? 0 : alternative.expected())
                  + " alternativeCost="
                  + (alternative == null ? 0 : (int)alternative.cost())
                  + " alternativeProofValid="
                  + decisionRedirect
                  + " redirectId="
                  + (decisionRedirect ? this.roiRedirectCount : (this.reason == null ? 0L : this.reason.getTime()))
                  + " redirectState="
                  + (decisionRedirect ? "PINNING" : (this.reason == null ? "none" : this.reason.getPinnedDispatchedType()))
                  + " phantomRejected="
                  + result.getPhantoms()
                  + " reason="
                  + result.reason()
            );
         }

         if (!decisionRedirect && decision.reason() == com.corz.client.utils.LocalUtils.Reason.UNPROVEN_ABSENCE) {
            this.roiAbsenceCount++;
            this.absenceUnprovenCount++;
            this.selectPasses.handleTimes(Counter.ROI_REFUSALS);
            this.logDebugMessage(
               "\u00a7e[RouteROI]\u00a7r decision=REFUSE_UNPROVEN_ABSENCE current="
                  + string
                  + " len="
                  + wordListed.size()
                  + " expected="
                  + n
                  + " floor="
                  + LocalUtils.getValue(wordListed.size())
                  + " rejectedHigh="
                  + this.rejectedHigh
                  + " - the alternative list was never completed, so its emptiness proves nothing"
            );
            if (this.placementExplicit != null && this.placementExplicit.isRevalidateAlign()) {
               this.failExplicitPlacement("ROI_UNPROVEN_ABSENCE");
            }

            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "ROI refused: the absence was never established");
            return false;
         } else if (decisionRedirect) {
            this.roiAbsenceCount++;
            this.selectPasses.handleTimes(Counter.ROI_REFUSALS);
            AlternativeTicket alternative3 = result.alternative();
            if (this.reason != null && this.reason.isPinnedDispatched()) {
               this.onRouteRedirectInvalidated("superseded by a new refusal");
            }

            this.accessIsolated
               .recordReason(
                  "ROI_REFUSED", this.moduleTick, this.movementMissionData.associatedTarget() == null ? 0L : this.movementMissionData.associatedTarget()
               );
            this.reason = new Reason(
               this.roiRedirectCount++,
               alternative3,
               this.movementMissionData.associatedTarget() == null ? 0L : this.movementMissionData.associatedTarget(),
               wordListed.size(),
               this.moduleTick
            );
            this.logDebugMessage(
               "\u00a7e[RouteROI]\u00a7r decision=REDIRECT current="
                  + string
                  + " alternativeTarget="
                  + BlockPos.fromLong(alternative3.target()).toShortString()
                  + " alternativeStand="
                  + BlockPos.fromLong(alternative3.stand()).toShortString()
                  + " alternativeMission="
                  + alternative3.missionId()
                  + " alternativeType="
                  + alternative3.kind()
                  + " expected="
                  + alternative3.expected()
                  + " cost="
                  + (int)alternative3.cost()
                  + " proof="
                  + (alternative3.stand() == this.getFeetBlockPos().asLong() ? "visible-from-here" : "component-stand+face")
                  + " redirectId="
                  + this.reason.getTime()
                  + " - the refused route is reconsidered once the alternative resolves (not deferred)"
            );
            if (this.placementExplicit != null && this.placementExplicit.isRevalidateAlign()) {
               this.failExplicitPlacement("ROI_REDIRECT");
            }

            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "ROI redirect \u2192 " + BlockPos.fromLong(alternative3.target()).toShortString());
            return false;
         } else {
            this.reasonExtensionMissCount++;
            this.selectPasses.handleTimes(Counter.ROI_ACCEPTED);
            return true;
         }
      }
   }

   private boolean allowAttemptThisConfirm(long confirmsValue) {
      int[] ns = this.confirmsIntArrayMap.computeIfAbsent(confirmsValue, longValue -> new int[]{this.confirms, 0});
      if (ns[0] != this.confirms) {
         ns[0] = this.confirms;
         ns[1] = 0;
      }

      return ++ns[1] <= 2;
   }

   private boolean tickEdgeCreep(BlockPos pos, String creepEdgeText) {
      if (this.unstableRecenterChangedTimeo == null && this.missionShortBlockHitResult != null && this.blockPosMissionShort != null && mc.player != null) {
         BlockPos blockPosMissionShort3 = this.blockPosMissionShort;
         Direction direction = this.missionShortBlockHitResult.getSide();
         if (this.missionShortBlockHitResult.getBlockPos().equals(blockPosMissionShort3.down())
            && direction.getAxis().isHorizontal()
            && blockPosMissionShort3.down().offset(direction).equals(pos)) {
            BlockPos feetBlockPos = this.getFeetBlockPos();
            if (!feetBlockPos.equals(blockPosMissionShort3) && !feetBlockPos.equals(blockPosMissionShort3.offset(direction))) {
               this.creepEdgeCertificate = null;
               return false;
            } else if (mc.player.isOnGround()) {
               long l = ProofSupportUtils.getTime(pos.getX(), pos.getY(), pos.getZ());
               long time2 = ProofSupportUtils.getTime(blockPosMissionShort3.getX(), blockPosMissionShort3.getY(), blockPosMissionShort3.getZ());
               if (this.creepEdgeCertificate != null && (this.creepEdgeCertificate.target() != l || this.creepEdgeCertificate.stand() != time2)) {
                  this.creepEdgeCertificate = null;
               }

               double d3 = mc.player.getX();
               double d4 = mc.player.getZ();
               double d5 = this.reachSetting.getValue();
               Vec3d vec3d = mc.player.getVelocity();
               if (this.creepEdgeCertificate == null) {
                  BlockPos blockPos = blockPosMissionShort3.offset(direction);
                  if (mc.world.getBlockState(blockPos).getBlock() instanceof TripwireBlock
                     || mc.world.getBlockState(blockPos.up()).getBlock() instanceof TripwireBlock) {
                     this.onTempSupportFailed("edge creep: the lean cell " + blockPos.toShortString() + " holds a tripwire string");
                     return true;
                  }

                  double d = direction.getAxis() == Axis.X ? d4 - blockPosMissionShort3.getZ() - 0.5 : d3 - blockPosMissionShort3.getX() - 0.5;
                  if (feetBlockPos.equals(blockPosMissionShort3) && Math.abs(d) > 0.19) {
                     AutoBuilder.Recentre recentre = this.centrePlayerOnBlock(blockPosMissionShort3);
                     if (recentre == AutoBuilder.Recentre.FAILED) {
                        this.onTempSupportFailed("edge creep: the body could not centre on its stand first");
                        return true;
                     }

                     if (recentre == AutoBuilder.Recentre.WORKING) {
                        return true;
                     }
                  }

                  Certificate certificate = CrouchedBodyUtils.computeCertificate(
                     new Request(
                        l, time2, FloorBuildPlanner.Pose.EDGE, true, d3, mc.player.getY(), d4, mc.player.isSneaking(), true, d5
                     ),
                     this.getHandlerForBlockPosDouble(pos, blockPosMissionShort3, d5, creepEdgeText)
                  );
                  if (!certificate.isExecutable()) {
                     this.onTempSupportFailed("no edge pose for the own-floor click: " + certificate.formatStatusLabel());
                     return true;
                  }

                  this.creepEdgeCertificate = certificate;
                  this.creepEdgeValue = 0;
                  this.edgeCreepValue = 0;
                  this.creepEdgeAmount = d3;
                  this.z = d4;
               }

               this.setOwnerSneak(true);
               if (++this.creepEdgeValue > SlidingPulseUtils.getFrictionStepValue(this.getSlipperiness())) {
                  this.creepEdgeCertificate = null;
                  this.onTempSupportFailed("edge creep exceeded the hard cap");
                  return true;
               } else {
                  Interval interval = this.creepEdgeCertificate.interval();
                  if (interval.containsPoint(d3, d4) && IncompleteStand.isNearlyStill(vec3d.horizontalLengthSquared())) {
                     this.releaseMovementKeys();
                     if (this.builderValue < 2) {
                        return true;
                     } else {
                        AutoBuilder.TempSupportChoice tempSupportChoice = this.chooseTempSupportFace(
                           pos, feetBlockPos, mc.player.getEyePos(), d5, creepEdgeText, true
                        );
                        if (tempSupportChoice == null) {
                           return true;
                        } else {
                           int n = this.getHotbarDirtSlot();
                           this.creepEdgeCertificate = null;
                           if (n == -1) {
                              this.onTempSupportFailed("no_dirt_for_support");
                              return true;
                           } else {
                              this.selectHotbarSlot(n);
                              if (this.driveTempPlacement(creepEdgeText, pos, tempSupportChoice.hit(), true) == AutoBuilder.TempDriveResult.FAILED) {
                                 this.onTempSupportFailed(this.transaction);
                              }

                              return true;
                           }
                        }
                     }
                  } else if (this.builderValue < 1) {
                     this.releaseMovementKeys();
                     return true;
                  } else {
                     Decision decision = SlidingPulseUtils.decideSlidingAction(interval, d3, d4, vec3d.x, vec3d.z, this.getSlipperiness());
                     switch (decision.action()) {
                        case DRIVE:
                           if (!this.intervalReportTimer.canTime(this.moduleTick)) {
                              return true;
                           }

                           double hypot2 = Math.hypot(d3 - this.creepEdgeAmount, d4 - this.z);
                           this.creepEdgeAmount = d3;
                           this.z = d4;
                           if (this.creepEdgeValue > 3 && hypot2 < 0.001) {
                              if (++this.edgeCreepValue >= 4) {
                                 this.creepEdgeCertificate = null;
                                 this.onTempSupportFailed("edge creep made no headway short of the edge interval");
                                 return true;
                              }
                           } else {
                              this.edgeCreepValue = 0;
                           }

                           this.handlePressedOptions(interval.settleX(), interval.settleZ(), false);
                           break;
                        case BRAKE:
                           if (!this.applyCounterStrafeKeys(0.004)) {
                              this.releaseMovementKeys();
                           }
                           break;
                        default:
                           this.releaseMovementKeys();
                     }

                     return true;
                  }
               }
            } else if (this.staleCount > 100) {
               this.creepEdgeCertificate = null;
               this.onTempSupportFailed("edge creep: the body never settled on the stand");
               return true;
            } else {
               this.releaseMovementKeys();
               return true;
            }
         } else {
            this.creepEdgeCertificate = null;
            return false;
         }
      } else {
         this.creepEdgeCertificate = null;
         return false;
      }
   }

