   private OpacityColorData buildPreviewRenderSettings() {
      String formatText = this.previewMode.getCurrentOption();

      Mode mode = switch (formatText) {
         case "Missing Only" -> Mode.MISSING_ONLY;
         case "Incorrect Only" -> Mode.WRONG_ONLY;
         case "Missing + Wrong" -> Mode.MISSING_WRONG;
         case "Ghost Only" -> Mode.GHOST_ONLY;
         case "Outlines Only" -> Mode.OUTLINES_ONLY;
         case "Build Box Only" -> Mode.BOX_ONLY;
         default -> Mode.FULL;
      };
      String currentOption = this.interiorClarity.getCurrentOption();

      InteriorClarity interiorClarity = switch (currentOption) {
         case "Off" -> InteriorClarity.OFF;
         case "Hide Camera Cell" -> InteriorClarity.HIDE_CAMERA_CELL;
         case "Cross Section" -> InteriorClarity.CROSS_SECTION;
         default -> InteriorClarity.FADE_NEAR_CAMERA;
      };
      LayerMode plusOne2;
      if ("Layer".equals(this.previewMode.getCurrentOption())) {
         plusOne2 = LayerMode.PLUS_ONE;
      } else {
         String currentOption3 = this.layerMode.getCurrentOption();
         switch (currentOption3) {
            case "Current":
               plusOne2 = LayerMode.CURRENT;
               break;
            case "\u00b11":
               plusOne2 = LayerMode.PLUS_ONE;
               break;
            case "\u00b12":
               plusOne2 = LayerMode.PLUS_TWO;
               break;
            default:
               plusOne2 = LayerMode.ALL;
         }
      }

      LayerMode layerMode = plusOne2;
      int n = mc.player == null ? 0 : (int)Math.floor(mc.player.getY());
      float maximumAmount = (float)this.ghostFill.getValue();
      float amount3 = (float)this.missingOpacity.getValue();
      float amount = (float)this.wrongBlockOpacity.getValue();
      float amount6 = (float)this.wrongStateOpacity.getValue();
      float amount4 = (float)this.doubleHelper.getValue();
      float amount2 = (float)this.interiorFadeRadius.getValue();
      boolean flag = this.renderCorrect.isEnabled();
      boolean enabled = this.outlines.isEnabled();
      String currentOption4 = this.outlineStrength.getCurrentOption();

      float max = switch (currentOption4) {
         case "Subtle" -> 0.45F;
         case "Medium" -> 0.7F;
         case "Maximum" -> 1.0F;
         default -> 0.88F;
      };
      LitematicaInteriorType litematicaInteriorType = LitematicaInteriorType.getPresetBuilding(this.previewPreset.getCurrentOption());
      if (litematicaInteriorType.isCustom()) {
         maximumAmount = litematicaInteriorType.maximumAmount;
         amount3 = litematicaInteriorType.litematicaInteriorAmount;
         amount = litematicaInteriorType.baseFraction;
         amount6 = litematicaInteriorType.missingFloorAmount;
         amount4 = litematicaInteriorType.missingBaseAmount;
         amount2 = litematicaInteriorType.missingAmount;
         flag = litematicaInteriorType.missingActive;
         enabled = true;
         if (litematicaInteriorType.missingPeakAmount > 0.0F) {
            max = Math.max(max, litematicaInteriorType.missingPeakAmount);
         }
      }

      return new OpacityColorData(
         mode,
         interiorClarity,
         layerMode,
         maximumAmount,
         amount3,
         amount,
         amount6,
         amount4,
         amount2,
         flag,
         this.booleanBase.isEnabled(),
         this.renderIncorrect.isEnabled(),
         this.missingThroughWalls.isEnabled(),
         enabled,
         (float)this.outlineWidth.getValue(),
         max,
         (int)this.previewRange.getValue(),
         (int)this.rebuildBudget.getValue(),
         n,
         this.showBuildBox.isEnabled(),
         this.showOriginMarker.isEnabled(),
         this.texturedPreview.isEnabled(),
         3066993,
         3842303,
         15158332,
         16098851,
         13195240,
         litematicaInteriorType.getLitematicaCorz(),
         this.litematicaTranslucentBlocks.isEnabled()
      );
   }

