   private HashMap<Item, Integer> getRestockItemCounts() {
      HashMap<Item, Integer> hashMap = new HashMap<>();
      if (mc.world == null) {
         return hashMap;
      } else {
         String string = mc.world.getRegistryKey().getValue().toString();

         for (DimensionPosData dimensionPosData : this.restockSources.getEntriesSnapshot()) {
            if (dimensionPosData.dimension().equals(string)) {
               AutoBuilder.ContainerView containerView = this.restockSourceMap.get(formatDimensionPosKey(string, dimensionPosData.pos()));
               if (containerView != null) {
                  for (Entry<Item, Integer> entry : containerView.counts().entrySet()) {
                     hashMap.merge(entry.getKey(), entry.getValue(), Integer::sum);
                  }
               }
            }
         }

         return hashMap;
      }
   }

