   private Set<Long> addFluidHazardCellsToSet(Set<Long> downCell, List<SupportStandUtils.Target> list2) {
      if (mc.world == null) {
         return downCell;
      } else {
         HashSet<Long> hashSet = null;

         for (SupportStandUtils.Target target : list2) {
            if (target.isKindFluid() && "lava".equals(target.name())) {
               for (long l : this.floodFillReplaceableCells(toBlockPos(target.cell()))) {
                  if (hashSet == null) {
                     hashSet = new HashSet<>(downCell);
                  }

                  BlockPos fromLong = BlockPos.fromLong(l);

                  for (BlockPos blockPos : new BlockPos[]{fromLong, fromLong.down(), fromLong.down(2)}) {
                     hashSet.add(SupportStandUtils.Options.getTime(target.cell(), getDataForBlockPos(blockPos)));
                  }

                  for (Direction direction : Type.HORIZONTAL) {
                     hashSet.add(SupportStandUtils.Options.getTime(target.cell(), getDataForBlockPos(fromLong.offset(direction))));
                     hashSet.add(SupportStandUtils.Options.getTime(target.cell(), getDataForBlockPos(fromLong.down().offset(direction))));
                  }
               }
            } else if (target.isKindFluid() && "water".equals(target.name())) {
               for (long l2 : this.computeWaterFlowCells(toBlockPos(target.cell()))) {
                  if (hashSet == null) {
                     hashSet = new HashSet<>(downCell);
                  }

                  BlockPos pos = BlockPos.fromLong(l2);
                  hashSet.add(SupportStandUtils.Options.getTime(target.cell(), getDataForBlockPos(pos)));
                  hashSet.add(SupportStandUtils.Options.getTime(target.cell(), getDataForBlockPos(pos.down())));
               }
            }
         }

         return (Set<Long>)(hashSet == null ? downCell : hashSet);
      }
   }

