   private boolean tryReclaimTempDebt() {
      if (!this.removeTempAfter.isEnabled()) {
         return false;
      } else {
         Report report = this.getUnknownOrphaned();
         if (report == null) {
            return false;
         } else {
            this.towerPillarSet.clear();
            this.towerPillarSet.addAll(report.unreachableCells());
            this.towerPillarSet.addAll(report.bannedCells());
            this.cellsSize = this.cells.size();
            this.timeComponent = this.getComponentVersionKey();
            this.lastTickTowerDebt = this.moduleTick;
            int n = this.maxLiveTempBlocks.getValue();
            if (this.moduleTick - this.towerDebtValue > 60) {
               this.towerDebtValue = this.moduleTick;
               this.logDebugMessage("\u00a7e[TempDebt]\u00a7r census " + report.formatSummary() + " cap=" + n);
            }

            int max2 = Math.max(1, this.maxRecycleDebtBound);
            int countTempTowerCells3 = this.countTempTowerCells();
            if (countTempTowerCells3 + max2 <= n) {
               return false;
            } else {
               long componentVersionKey2 = this.getComponentVersionKey();
               if (this.lastTowerDebtKey != componentVersionKey2) {
                  this.lastTowerDebtKey = componentVersionKey2;
                  this.towerDebtCount = 0;
               }

               if (this.towerDebtCount >= 3) {
                  this.towerPillarSet.addAll(report.retireOrder());
                  if (this.moduleTick - this.lastTowerDebtTick >= 600) {
                     this.lastTowerDebtTick = this.moduleTick;
                     this.logDebugMessage(
                        "\u00a7e[TempDebt]\u00a7r reclaim exhausted - "
                           + this.towerDebtCount
                           + " cleanup(s) in a row removed nothing; "
                           + report.retireOrder().size()
                           + " cell(s) stop counting as debt until the region changes (the cap yields to the remaining work)"
                     );
                  }

                  return false;
               } else {
                  BlockPos feetBlockPos = this.getFeetBlockPos();
                  boolean flag2 = !this.digMissionFlag && this.isNearPendingCompletionCell(feetBlockPos);
                  int n4 = report.retireOrder().size() - report.protectedInRetire();
                  int max5 = Math.max(0, report.getActionableDebt() - Math.max(0, n4));
                  HashSet<Long> hashSet = new HashSet<>(report.bottomUpCells());
                  ArrayList<Long> arrayList = new ArrayList<>();
                  int n6 = -1;

                  for (long l : report.retireOrder()) {
                     if (++n6 >= n4 && !CellTierClassifier.isValueBelowLimit(max5, n)) {
                        break;
                     }

                     if (this.cells.contains(l) && !this.isCellCoveredOrBlocked(l) && !this.isMissionOwnedCell(l) && !this.isNearIslandAbortColumn(l)) {
                        BlockPos blockPos = BlockPos.fromLong(l);
                        boolean flag = hashSet.contains(l);
                        BlockPos blockPos2 = flag ? this.getTempColumnBottom(blockPos) : blockPos;
                        if (!flag || !this.isCellCoveredOrBlocked(blockPos2.asLong())) {
                           if (!flag2 || blockPos2.getY() >= feetBlockPos.getY() - 1) {
                              this.blockPos2Exit = blockPos2;
                              this.reclaimCircuitActive = flag;
                              this.reclaimDebtFlag = true;
                              this.debtReclaimCount++;
                              this.accessIsolated.markProgress();
                              this.logDebugMessage(
                                 "\u00a7e[TempDebt]\u00a7r recovery \u2192 reclaim "
                                    + this.blockPos2Exit.toShortString()
                                    + (flag ? " (tower base-up)" : " (pillar top)")
                                    + " actionableDebt="
                                    + report.getActionableDebt()
                                    + " cap="
                                    + n
                              );
                              this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "temp debt recovery: reclaim " + (flag ? "tower base-up" : "pillar top"));
                              return true;
                           }

                           arrayList.add(l);
                        }
                     }
                  }

                  this.towerPillarSet.clear();
                  this.towerPillarSet.addAll(report.unreachableCells());
                  this.towerPillarSet.addAll(report.bannedCells());
                  this.towerPillarSet.addAll(arrayList);
                  this.cellsSize = this.cells.size();
                  this.timeComponent = this.getComponentVersionKey();
                  this.lastTickTowerDebt = this.moduleTick;
                  return false;
               }
            }
         }
      }
   }

