   private BlockHitResult getLastSentRotationHit(BlockHitResult directionAxis, double yawPitchValue) {
      if (mc.player.getYaw() == this.lastSentYaw && mc.player.getPitch() == this.pitchLlI) {
         double d3 = mc.player.getEyeY() - mc.player.getY();
         BlockHitResult blockSide = null;

         for (int n = 0; n < (this.moduleTick - this.lastTickPlannedMission < 2 ? 2 : 1); n++) {
            double d = n == 0 ? d3 : (d3 < 1.45 ? d3 + 0.35 : d3 - 0.35);
            BlockHitResult blockHitResult = this.raycastBlockSideForAim(new Vec3d(this.yawPitchAmount, this.lastSentY + d, this.lastSentZ), this.lastSentYaw, this.pitchLlI, yawPitchValue);
            if (blockHitResult.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK
               || !blockHitResult.getBlockPos().equals(directionAxis.getBlockPos())
               || blockHitResult.getSide() != directionAxis.getSide()
               || !this.isHitAllowedForYaw(blockHitResult, this.lastSentYaw)
               || !this.isHitUsableForPlacement(blockHitResult)) {
               return null;
            }

            if (blockSide == null) {
               blockSide = blockHitResult;
            }
         }

         return blockSide;
      } else {
         return null;
      }
   }

