   private boolean shouldTriggerStallRecovery(BlockPos pos) {
      if (this.moduleTick - this.admitTowerValue < 1800) {
         return false;
      } else if (this.confirms != this.layerAccessPrevConfirms && !this.cooldown.isEmpty()) {
         return false;
      } else if (this.y != Integer.MIN_VALUE && this.moduleTick - this.lastTickSolvableBuildable < 1200) {
         return false;
      } else if (this.layerAccessLowestCellY == Integer.MAX_VALUE
         || (this.lastLayerAccessConfirms != this.confirms || this.moduleTick - this.lastLayerRefreshTick > 2400)
            && (this.moduleTick >= this.layerAccessCooldownUntilTick || this.layerAccessCooldownUntilTick - this.moduleTick >= 1800)) {
         if (mc.player == null
            || mc.world == null
            || this.isLeavingMultiplayer()
            || this.layerPlanFlag
            || this.islandAbort != 0L
            || this.deckMicroMoves.isProbingExitingConfirmed()
            || this.hasActiveBlockersStep()
            || this.submitCompletionMission != null) {
            return false;
         } else if (this.moduleTick >= this.elevatedDeckValue
            && !this.isBackHandBusy()
            && this.handBack.getBanExecuting(com.corz.client.utils.FamilyGained.Dependency.MATERIAL) <= 0) {
            for (int n : this.cooldown.values()) {
               if (n > this.moduleTick && n - this.moduleTick < 268435456) {
                  return false;
               }
            }

            for (AutoBuilder.FailRec failRec : this.entries.values()) {
               if (failRec.emergencyGeometryValue > this.moduleTick && failRec.emergencyGeometryValue - this.moduleTick < 1800) {
                  return false;
               }
            }

            if (this.getStrictStandPosition(pos) != null) {
               return false;
            } else {
               int missionMap = 0;

               for (long l : this.completionMissionMap.keySet()) {
                  if (!this.machineArmedSet.contains(l)) {
                     if (++missionMap > 40) {
                        return true;
                     }
                  }
               }

               if (missionMap == 0 && this.completionMissionMap.size() <= 4) {
                  missionMap = this.completionMissionMap.size();
               }

               return missionMap == 0 || this.confirms == this.completionMissionStableConfirms && this.completionMissionStableTicks >= 20;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

   private com.corz.client.utils.TakeoffRay.Certificate getJumpPlaceCertificate(BlockPos pos, BlockState state) {
      BlockPos down = pos.down();
      BlockState blockState2 = mc.world.getBlockState(down);
      VoxelShape voxelShape = blockState2.getCollisionShape(mc.world, down);
      boolean flag = !voxelShape.isEmpty() && voxelShape.getMax(Axis.Y) >= 0.999;
      boolean materialInHand = mc.world.getBlockState(pos.up()).getCollisionShape(mc.world, pos.up()).isEmpty()
         && mc.world.getBlockState(pos.up(2)).getCollisionShape(mc.world, pos.up(2)).isEmpty();
      boolean equals = this.getFeetBlockPos().equals(pos);
      boolean plainOrExactState = SelectedInventoryUtils.getValue(getItemForBlockState(state)) != -1;
      return com.corz.client.utils.TakeoffRay.Certificate.getProvableHeadroom(pos.asLong(), down.asLong(), flag, materialInHand, equals, plainOrExactState, true);
   }

