   private boolean tryStartTempNeighbourSupport() {
      if (this.useTemporaryBlocks.isEnabled() && this.getHotbarDirtSlot() != -1) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         BlockPos pos5 = null;
         BlockPos offset = null;
         double maxValue3 = Double.MAX_VALUE;
         com.corz.client.utils.DepPurpose.Purpose facing = com.corz.client.utils.DepPurpose.Purpose.ATTACHMENT;

         for (int n = 0; n < this.schematicCells.size(); n++) {
            BlockPos pos = this.schematicCells.get(n);
            BlockState blockState3 = this.targetFluidItems.get(n);
            BlockState blockState4 = mc.world.getBlockState(pos);
            if (blockState4.getBlock() != blockState3.getBlock() && (blockState4.isAir() || blockState4.isReplaceable())) {
               Direction requiredSupportDirection = this.getRequiredSupportDirection(pos, blockState3);
               if (requiredSupportDirection != null) {
                  BlockPos blockPos = pos.offset(requiredSupportDirection);
                  BlockState blockState = mc.world.getBlockState(blockPos);
                  if ((blockState.isAir() || blockState.isReplaceable()) && !this.cellTemporarySet.contains(blockPos.asLong()) && this.hasSolidNeighborToPlaceOn(blockPos)
                     )
                   {
                     double d = feetBlockPos.getSquaredDistance(blockPos) - (this.linkedHashSet.contains(pos.asLong()) ? 1000000.0 : 0.0);
                     if (d < maxValue3) {
                        maxValue3 = d;
                        pos5 = pos;
                        offset = blockPos;
                        facing = com.corz.client.utils.DepPurpose.Purpose.FACING;
                     }
                  }
               } else if (!this.hasSolidNeighborToPlaceOn(pos)) {
                  for (Direction direction : Direction.values()) {
                     BlockPos offsetPos = pos.offset(direction);
                     BlockState blockState2 = mc.world.getBlockState(offsetPos);
                     if ((blockState2.isAir() || blockState2.isReplaceable())
                        && !this.cellTemporarySet.contains(offsetPos.asLong())
                        && this.hasSolidNeighborToPlaceOn(offsetPos)) {
                        double d2 = feetBlockPos.getSquaredDistance(offsetPos) - (this.linkedHashSet.contains(pos.asLong()) ? 1000000.0 : 0.0);
                        if (d2 < maxValue3) {
                           maxValue3 = d2;
                           pos5 = pos;
                           offset = offsetPos;
                           facing = com.corz.client.utils.DepPurpose.Purpose.ATTACHMENT;
                        }
                     }
                  }
               }
            }
         }

         if (offset == null) {
            return false;
         } else {
            this.blockPos3SupportConstructive = offset;
            this.blockPos2SupportConstructive = pos5;
            this.supportFloorValue = 0;
            this.name = facing == com.corz.client.utils.DepPurpose.Purpose.FACING ? "FACING_SUPPORT" : "ATTACHMENT_SUPPORT";
            long l = ++this.supportAttachmentTime;
            this.supportMissionMap.put(offset.asLong(), new DepPurpose(l, facing, pos5.asLong(), offset.asLong(), this.moduleTick));
            this.currentTargetPos = pos5;
            this.supportAccessValue = -1;
            this.oppositeAxis = null;
            this.direction = null;
            this.floatValue = null;
            this.missionShortAxis = null;
            this.setSupportText("TEMP_SUPPORT", "floating block " + pos5.toShortString() + " needs a temporary neighbour");
            this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.SUPPORT, 1);
            this.transitionToState(AutoBuilder.State.TEMP_SUPPORT, "building temp support");
            return true;
         }
      } else {
         return false;
      }
   }

