   private boolean applyTeamPlacement(DimJsonData dimJsonData, String enumFolderText) {
      ElseBuilder loadedSchematic = this.schematicBuilder.getLoadedSchematic();
      if (loadedSchematic != null && dimJsonData != null && dimJsonData.isDimensionPlacement()) {
         if (!dimJsonData.dimension().equals(this.getDimensionId())) {
            return false;
         } else {
            RotMirData rotMirData = dimJsonData.placement();
            int n = this.originX;
            int originY2 = this.originY;
            int originZ3 = this.originZ;
            int currentIndex4 = this.rotationEnumFolder.getCurrentIndex();
            int currentIndex5 = this.enumHelper.getCurrentIndex();
            boolean flag = this.folderOpenFlag;
            this.originX = rotMirData.originX();
            this.originY = rotMirData.originY();
            this.originZ = rotMirData.originZ();
            this.folderOpenFlag = true;
            this.rotationEnumFolder.handle(rotMirData.rotationIndex());
            this.enumHelper.handle(rotMirData.mirrorIndex());
            if (!this.blockStateHelper.canFlag(loadedSchematic, this.originX, this.originY, this.originZ, this.rotationEnumFolder.getCurrentIndex(), this.enumHelper.getCurrentIndex())) {
               this.originX = n;
               this.originY = originY2;
               this.originZ = originZ3;
               this.folderOpenFlag = flag;
               this.rotationEnumFolder.handle(currentIndex4);
               this.enumHelper.handle(currentIndex5);
               this.blockStateHelper.canFlag(loadedSchematic, this.originX, this.originY, this.originZ, currentIndex4, currentIndex5);
               return false;
            } else {
               this.syncSchematicFromHelper();
               this.resetSessionState(true, "PLACEMENT_" + enumFolderText);
               this.hostTeamText = this.getDimensionId();
               this.sendPlayerChatMessage("\u00a7b[MultiBuilder]\u00a7r schematic moved to the team's placement: " + rotMirData.formatOriginMirror());
               return true;
            }
         }
      } else {
         return false;
      }
   }

