   private void checkCompoundOwnerCompletion() {
      if (this.compoundCompleteValue != 0L) {
         BlockPos fromLong = BlockPos.fromLong(this.compoundCompleteValue);
         int schematicCells2 = this.getSchematicCells(fromLong);
         if (schematicCells2 < 0) {
            this.releaseCompoundLease("owner_gone");
         } else {
            boolean flag = this.transferUnknownValue != 0L;
            boolean placedStateAcceptable = this.isPlacedStateAcceptable(fromLong, this.targetFluidItems.get(schematicCells2));
            boolean isCompound = true;
            if (flag) {
               BlockPos blockPos = BlockPos.fromLong(this.transferUnknownValue);
               int n = this.getSchematicCells(blockPos);
               isCompound = n < 0 || this.isPlacedStateAcceptable(blockPos, this.targetFluidItems.get(n));
            }

            switch (CompoundCompleteUtils.getCompleteCompound(
               flag, placedStateAcceptable, isCompound, this.moduleTick - this.transferCompleteValue, this.moduleTick - this.lastTickTransferComplete, 600, 180
            )) {
               case COMPOUND_COMPLETE:
                  this.releaseCompoundLease("compound_complete");
                  break;
               case COMPLETE:
                  if (!this.tryTransferLeaseTarget(fromLong)) {
                     this.releaseCompoundLease("owner_complete");
                  }
                  break;
               case TIMEOUT:
                  this.releaseCompoundLease("lease_timeout");
                  break;
               case NO_PROGRESS:
                  this.releaseCompoundLease("no_progress");
               case NONE:
            }
         }
      }
   }

