   private String getPlannedPoseRejectionReason(SupportStandUtils.Intent intent, BlockPos pos, Vec3d vec) {
      if (intent != null && pos != null && mc.world != null) {
         BlockPos pos2 = toBlockPos(intent.support());
         BlockState blockState = mc.world.getBlockState(pos2);
         boolean flag2 = intent.face() == 1 && BlockStateUtilsView.canWireIterator(blockState);
         if (!blockState.isAir()
            && !blockState.isReplaceable()
            && (!blockState.getCollisionShape(mc.world, pos2).isEmpty() || BlockStateUtilsView.canBlockOpen(blockState) || flag2)) {
            Direction direction3 = Direction.values()[Math.max(0, Math.min(5, intent.face()))];
            if (!pos2.offset(direction3).equals(pos)) {
               return "planned face does not yield the target";
            } else {
               Integer integer = this.faceParityMap.get(hashPosAndDirection(pos, direction3));
               if (integer != null && this.moduleTick < integer) {
                  return "face blacklisted";
               } else {
                  Vec3d vec3d3 = new Vec3d(intent.hx(), intent.hy(), intent.hz());
                  double d = this.reachSetting.getValue();
                  if (vec.squaredDistanceTo(vec3d3) > d * d) {
                     return String.format(Locale.ROOT, "hit out of reach (%.2f)", Math.sqrt(vec.squaredDistanceTo(vec3d3)));
                  } else {
                     float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d3);
                     int n = this.getSchematicCells(pos);
                     BlockState blockState2 = n >= 0 ? this.targetFluidItems.get(n) : null;
                     if (blockState2 != null) {
                        boolean flag = this.isNeighborFacingAcceptable(pos, pos2);
                        Direction direction = this.getPlacementFacing(pos, blockState2);
                        if (!flag && direction != null && Direction.fromHorizontalDegrees(fs[0]) != direction) {
                           return "look " + Direction.fromHorizontalDegrees(fs[0]) + " but the state requires " + direction;
                        }

                        Axis axis = this.isRelaxedBlockShortCell(pos) ? null : getAxis(blockState2);
                        if (axis != null && Direction.fromHorizontalDegrees(fs[0]).getAxis() != axis) {
                           return "yaw off the rail axis " + axis;
                        }

                        if (!flag && !isFloatMatch(fs[0], this.getPlacementFloatHint(pos, blockState2))) {
                           return "yaw sign does not match the required rotation";
                        }

                        Direction requiredSupportDirection = this.getRequiredSupportDirection(pos, blockState2);
                        if (requiredSupportDirection != null && !pos2.equals(pos.offset(requiredSupportDirection))) {
                           return "support is not the required neighbour " + requiredSupportDirection;
                        }
                     }

                     BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec, fs[0], fs[1], d);
                     this.vec3dDoesFace = null;
                     if (blockHitResult.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK
                        || !blockHitResult.getBlockPos().equals(pos2)
                        || blockHitResult.getSide() != direction3) {
                        Vec3d vec3d = this.findBestAimPointOnFace(
                           pos2, direction3, vec, d, vec3d3, blockState2 == null ? null : this.getPlacementFacing(pos, blockState2)
                        );
                        if (vec3d != null) {
                           this.vec3dDoesFace = vec3d;
                           return null;
                        }
                     }

                     if (blockHitResult.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK) {
                        return "ray misses";
                     } else if (!blockHitResult.getBlockPos().equals(pos2) || blockHitResult.getSide() != direction3) {
                        return "ray lands on "
                           + blockHitResult.getBlockPos().toShortString()
                           + "/"
                           + blockHitResult.getSide()
                           + " ("
                           + getBlockRegistryPath(mc.world.getBlockState(blockHitResult.getBlockPos()))
                           + ") not "
                           + pos2.toShortString()
                           + "/"
                           + direction3;
                     } else {
                        return !this.isHitUsableForPlacement(blockHitResult) ? "hopper top hit is not rim/floor" : null;
                     }
                  }
               }
            }
         } else {
            return "support not solid";
         }
      } else {
         return "no intent";
      }
   }

   private void delegateMineOut() {
      this.transitionToState(AutoBuilder.State.IDLE, "mine-out delegated");
      AutoAreaMiner autoAreaMiner = (AutoAreaMiner)ModuleRegistry.getModule(AutoAreaMiner.class);
      if (autoAreaMiner == null) {
         this.updatePressedOptions2();
         if (this.moduleTick % 60 == 0) {
            this.sendPlayerChatMessage("\u00a7c[MineOut]\u00a7r Auto Area Miner module unavailable");
         }
      } else if (AutoYourUtils.isContainsKey(autoAreaMiner)) {
         this.updatePressedOptions2();
         if (this.moduleTick % 60 == 0) {
            this.sendPlayerChatMessage("\u00a7c[MineOut]\u00a7r Auto Area Miner is locked - " + AutoYourUtils.getOrDefaultForIlIllIiIll(autoAreaMiner));
         }
      } else if (autoAreaMiner.isBlockSetFinishedFor("AutoBuilder")) {
         this.updatePressedOptions2();
         if (!this.builderAutoFlag) {
            this.builderAutoFlag = true;
            boolean flag = autoAreaMiner.isBlockSetFailed();
            DisabledEnabled.getInstance().handleDisabledEnabled("Auto Builder", flag ? "Mine out stopped early" : "Schematic mined out", !flag);
         }
      } else {
         if (this.builderAutoItems != this.schematicCells && this.schematicCells != null && this.targetFluidItems != null) {
            ArrayList<BlockPos> arrayList = new ArrayList<>();

            for (int n = 0; n < this.schematicCells.size(); n++) {
               if (!this.targetFluidItems.get(n).isAir()) {
                  arrayList.add(this.schematicCells.get(n));
               }
            }

            autoAreaMiner.startBlockSetMining(arrayList, "AutoBuilder");
            this.builderAutoItems = this.schematicCells;
            this.builderAutoFlag = false;
            DisabledEnabled.getInstance()
               .handleDisabledEnabled(
                  "Auto Builder", arrayList.isEmpty() ? "Schematic has no blocks to mine" : "Mining out " + arrayList.size() + " blocks", !arrayList.isEmpty()
               );
         }

         if (autoAreaMiner.isBlockSetMode() && !autoAreaMiner.isBlockSetFinishedFor("AutoBuilder") && !autoAreaMiner.isEnabled()) {
            autoAreaMiner.setEnabled(true);
            this.autoBuilderActive = true;
         }

         boolean flag2 = autoAreaMiner.isEnabled() && autoAreaMiner.isBlockSetMode() && !autoAreaMiner.isBlockSetFinishedFor("AutoBuilder");
         if (flag2) {
            this.builderFlag = true;
         } else {
            this.updatePressedOptions2();
         }
      }
   }

   private void logRemainingPlanOrder() {
      if (this.floats <= 10 && this.floats != 0) {
         ArrayList<com.corz.client.utils.PrereqsCellUtils.Item> arrayList3 = new ArrayList<>();
         long l = -3750763034362895579L;

         for (Entry<Long, BlockState> entry : this.completionMissionMap.entrySet()) {
            BlockPos fromLong = BlockPos.fromLong(entry.getKey());
            BlockState blockState = entry.getValue();
            ArrayList<Long> arrayList = new ArrayList<>();
            ArrayList<Long> arrayList2 = new ArrayList<>();
            Direction requiredSupportDirection = this.getRequiredSupportDirection(fromLong, blockState);
            if (requiredSupportDirection != null) {
               BlockPos blockPos = fromLong.offset(requiredSupportDirection);
               if (this.completionMissionMap.containsKey(blockPos.asLong())) {
                  arrayList.add(blockPos.asLong());
               } else if (mc.world.getBlockState(blockPos).isAir()) {
                  arrayList2.add(blockPos.asLong());
               }
            }

            if (isPlaceableWithoutSpecialSneak(blockState)) {
               Direction direction = getFacingForOrientedState(blockState);
               if (direction != null && direction.getAxis() == Axis.Y) {
                  BlockPos fromLongOffset = fromLong.offset(direction);
                  if (this.completionMissionMap.containsKey(fromLongOffset.asLong())) {
                     arrayList.add(fromLongOffset.asLong());
                  } else if (mc.world.getBlockState(fromLongOffset).isAir()) {
                     arrayList2.add(fromLongOffset.asLong());
                  }
               }
            }

            arrayList3.add(new com.corz.client.utils.PrereqsCellUtils.Item(entry.getKey(), getBlockRegistryPath(blockState), arrayList, arrayList2));
            l = (l ^ entry.getKey()) * 1099511628211L;
         }

         if (l != this.connectorFloatsValue) {
            this.connectorFloatsValue = l;
            com.corz.client.utils.PrereqsCellUtils.Plan plan = PrereqsCellUtils.getCellPrereqs(arrayList3);
            StringBuilder stringBuilder = new StringBuilder();
            int n = 0;

            for (com.corz.client.utils.PrereqsCellUtils.Item item : plan.ordered()) {
               if (n++ > 0) {
                  stringBuilder.append(" \u2192 ");
               }

               stringBuilder.append(BlockPos.fromLong(item.cell()).toShortString()).append(' ').append(item.kind());
               if (!item.schematicPrereqs().isEmpty()) {
                  stringBuilder.append(" needs").append(item.schematicPrereqs().size()).append("schem");
               }

               if (!item.tempPrereqs().isEmpty()) {
                  stringBuilder.append(" +connector");
               }
            }

            this.logDebugMessage(
               "\u00a7b[RemainingPlan]\u00a7r "
                  + this.floats
                  + " left: "
                  + stringBuilder
                  + (plan.isEmpty() ? "" : " \u00a7c(unsequenced: " + plan.unsequenced().size() + " - ordering contradiction)")
            );
         }
      }
   }

