   private boolean startDeckSurfaceMove(BlockPos longValue, BlockPos fromLong, BlockPos pos) {
      MovementMissionData movementMissionData = this.getMovementMissionDataForced(
         fromLong == null ? Purpose.DECK_ENTRY : Purpose.DECK_LOCAL_MOVE, longValue, fromLong
      );
      this.movementMissionData = movementMissionData;
      if (longValue.equals(pos)) {
         if (this.placementExplicit != null) {
            this.updateMissionArrival();
         }

         return true;
      } else {
         this.blockPos2LayerAccess = null;
         this.blockPosBlockersStep = longValue;
         this.reachedCoverFlag = this.placementExplicit == null;
         this.standClimbFlag = false;
         this.arrivedSupportFlag = false;
         this.abortDroppedAdjustRun(Abort.MOVE_REQUIRED);
         if (fromLong != null) {
            this.currentTargetPos = fromLong;
            this.supportAccessValue = this.getSchematicCells(fromLong);
            if (this.supportAccessValue >= 0) {
               this.updatePlacementRecipeForTarget(fromLong, this.targetFluidItems.get(this.supportAccessValue));
            }
         }

         this.blockHitResultEgressStand = null;
         this.sideRunValue = 0;
         this.partnerClickFlag = false;
         this.sneakEgressFlag = false;
         boolean flag = movementMissionData.purpose() == Purpose.DECK_LOCAL_MOVE;
         List<Long> list2 = flag ? FloorBuildPlanner.getPathBetweenCells(this.remaining, pos.asLong(), longValue.asLong(), this::canWalkFlatBetween) : List.of();
         if (flag && list2.isEmpty()) {
            this.failExplicitPlacement("SURFACE_UNREACHABLE");
            this.updatePressedOptions2();
            this.path.clear();
            this.deckLocalFlag = false;
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "choose reachable surface frontier");
            return true;
         } else {
            if (!list2.isEmpty()) {
               WalkRouteFinder.RoutePreflight routePreflight = WalkRouteFinder.preflightRoute(
                  mc.world, list2.stream().map(BlockPos::fromLong).toList(), this.cells, Set.of(), Hint.NONE
               );
               if (!routePreflight.executable()) {
                  if (!routePreflight.steps().isEmpty()) {
                     WalkRouteFinder.RouteStep routeStep = routePreflight.steps().getLast();
                     Edge edge = this.createWalkEdge(routeStep.from(), routeStep.to(), routeStep.kind(), true);
                     this.bannedEdges.handle(edge, TimeFlat.getTime(edge.from(), edge.to(), this::getRawBlockStateIdAt));
                  }

                  this.remaining = null;
                  this.failExplicitPlacement("SURFACE_GEOMETRY_CHANGED");
                  this.updatePressedOptions2();
                  this.path.clear();
                  this.transitionToState(AutoBuilder.State.SELECT_TARGET, "surface geometry changed");
                  return true;
               }

               this.path.clear();

               for (long l : list2) {
                  this.path.add(BlockPos.fromLong(l));
               }

               this.rejected = this.invalidNone.validateReplacement(movementMissionData, () -> Failure.NONE, () -> {
                  throw new IllegalStateException("local mission step requested global ROI");
               });
               if (this.rejected != Failure.NONE) {
                  this.failExplicitPlacement("MISSION_OWNERSHIP_LOST");
                  this.exitDeckMission("mission ownership lost");
                  return true;
               }

               this.indexNodeTransition = 1;
               this.blockPos3BridgeCell = longValue;
               this.deckLocalFlag = true;
               this.ownershipLoopTime = 0L;
               this.replanningTransitionItems = List.of();
               this.worldDeckSurface = List.of();
               this.takeoffLanding = null;
               this.authoritativeChangedValue = -1;
               this.nodeTransitionMaxGround.handleMaxFlagForInt(this.indexNodeTransition);
               this.surfaceEdgeAmount = Double.MAX_VALUE;
               this.surfaceEdgeValue = this.moduleTick;
               this.deckMicroMoves.deckSurfaceCount++;
               this.deckSurfaceCount++;
            } else {
               List<BlockPos> list = this.findGoPath(pos, longValue);
               if (list == null || list.isEmpty() || !this.tryFollowMovementRoute(list, longValue, movementMissionData)) {
                  if (list == null || list.isEmpty()) {
                     this.rejected = Failure.PATH_INVALID;
                  }

                  if (fromLong == null) {
                     this.onDeckEntryFailure(this.rejected, longValue);
                  } else if (this.rejected.retryDifferentEntry) {
                     this.deckMicroMoves.onSurfaceDeck(longValue.asLong());
                  } else {
                     this.exitDeckMission("movement rejected: " + this.rejected);
                  }

                  this.failExplicitPlacement("SURFACE_ROUTE_FAILED");
                  this.updatePressedOptions2();
                  this.path.clear();
                  this.reachedCoverFlag = false;
                  this.blockPosBlockersStep = null;
                  this.transitionToState(AutoBuilder.State.SELECT_TARGET, "deck route explicitly failed");
                  return true;
               }

               this.deckLocalFlag = false;
               this.deckMicroMoves.deckExplicitlyCount++;
            }

            if (this.deckMicroMoves.isProbingExitingLatched()) {
               if (this.deckLocalFlag) {
                  this.deckMicroMoves.updateMicroSurface();
               } else {
                  this.deckMicroMoves.resetFrontierFlags();
               }
            } else {
               this.deckMicroMoves.updateEnteringProbing();
            }

            this.setSupportText("DECK_MISSION", "move to " + longValue.toShortString());
            this.transitionToState(AutoBuilder.State.GO_TO_POSITION, this.deckLocalFlag ? "deck local step for committed target" : "deck global route");
            return true;
         }
      }
   }

