   private void walkToRestockContainer() {
      if (this.restockContainerBlockPos == null) {
         this.onRestockPurposeFinished("no container");
      } else if (!this.autoMove.isEnabled()) {
         this.onRestockPurposeFinished("auto-move off");
      } else {
         double d = this.reachSetting.getValue() * this.reachSetting.getValue();
         if (!this.containerGoneFlag
            && mc.player.isOnGround()
            && mc.player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(this.restockContainerBlockPos)) <= d) {
            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.RESTOCK_OPEN, "in reach of restock container");
         } else {
            if (this.path.isEmpty()) {
               BlockPos blockPos = this.blockPosRestockContainer != null ? this.blockPosRestockContainer : this.getReachableStandForTarget(this.restockContainerBlockPos);
               if (blockPos == null) {
                  this.markRestockContainerFailed(this.restockContainerBlockPos);
                  this.onRestockPurposeFinished("no stand");
                  return;
               }

               List<BlockPos> list = this.findGoPath(this.getFeetBlockPos(), blockPos);
               if (list == null || list.isEmpty()) {
                  this.markRestockContainerFailed(this.restockContainerBlockPos);
                  this.onRestockPurposeFinished("no path");
                  return;
               }

               this.arrivedRestockFlag = true;
               if (!this.tryFollowMovementRoute(list, blockPos, this.createMovementMission(Purpose.RESTOCK_ROUTE, blockPos, null))) {
                  this.markRestockContainerFailed(this.restockContainerBlockPos);
                  this.onRestockPurposeFinished("route rejected");
                  return;
               }

               this.routeStandValue = 0;
               this.standRouteValue = 0;
               this.lastNodeTransitionIndex = -1;
               this.standWalkValue = 0;
               this.standRouteAmount = Double.MAX_VALUE;
            }

            this.updateStuckDetection();
            if (!this.isRestockState()) {
               this.arrivedRestockFlag = false;
               this.restockContainerBlockPos = null;
               this.blockPosRestockContainer = null;
               InventoryStackUtilsHandle.handle(this);
               if (this.complete != AutoBuilder.BuyMode.NONE) {
                  this.finishBuyAndReportCost("couldn't walk to a restock chest");
               }
            }
         }
      }
   }

