   private boolean isNeighborCellDangerous(BlockPos pos) {
      if (mc.world == null) {
         return false;
      } else {
         for (int n3 = -1; n3 <= 1; n3++) {
            for (int n2 = -1; n2 <= 1; n2++) {
               if (n3 != 0 || n2 != 0) {
                  BlockPos blockPos = pos.add(n3, 0, n2);
                  if (mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
                     BlockPos blockAbovePos = blockPos.up();
                     BlockPos down = blockPos.down();
                     if ((
                           !mc.world.getBlockState(blockAbovePos).getFluidState().isEmpty()
                              || !(mc.world.getBlockState(down).getBlock().getSlipperiness() <= 0.6F)
                              || !WalkRouteFinder.isWaterOverSolidFloor(mc.world, blockPos)
                                 && (
                                    !mc.world.getBlockState(blockPos).isOf(Blocks.WATER)
                                       || !(mc.world.getBlockState(down).getBlock() instanceof HopperBlock)
                                 )
                        )
                        && (
                           !mc.world.getBlockState(blockAbovePos).isFullCube(mc.world, blockAbovePos)
                              || mc.world.getBlockState(down).getCollisionShape(mc.world, down).isEmpty()
                        )) {
                        boolean flag = false;

                        for (int n = 0; n <= 2 && !flag; n++) {
                           if (WalkRouteFinder.isStandable(mc.world, blockPos.down(n))) {
                              flag = n == 0
                                 || WalkableRegionAnalyzer.countReachableCells(
                                       WalkRouteFinder.createTerrainView(mc.world), blockPos.getX(), blockPos.getY() - n, blockPos.getZ(), 2
                                    )
                                    != 1;
                           }
                        }

                        if (!flag) {
                           return true;
                        }
                     }
                  }
               }
            }
         }

         return false;
      }
   }

