   private static boolean isRedstoneFaceAttachable(BlockState state, Direction direction3) {
      Block block = state.getBlock();
      if (block instanceof ObserverBlock) {
         return state.get(Properties.FACING) == direction3;
      } else if (block instanceof AbstractRedstoneGateBlock) {
         return direction3.getAxis().isHorizontal();
      } else if (block instanceof RedstoneWireBlock) {
         if (direction3 == Direction.UP) {
            return true;
         } else {
            return direction3 == Direction.DOWN
               ? false
               : state.get(RedstoneWireBlock.DIRECTION_TO_WIRE_CONNECTION_PROPERTY.get(direction3.getOpposite())) != WireConnection.NONE;
         }
      } else if (block instanceof RedstoneTorchBlock || block instanceof WallRedstoneTorchBlock) {
         return direction3 == Direction.DOWN;
      } else if (!(block instanceof LeverBlock) && !(block instanceof ButtonBlock)) {
         return false;
      } else {
         Direction direction = state.contains(Properties.BLOCK_FACE) && state.get(Properties.BLOCK_FACE) != BlockFace.WALL
            ? (state.get(Properties.BLOCK_FACE) == BlockFace.FLOOR ? Direction.DOWN : Direction.UP)
            : state.get(Properties.HORIZONTAL_FACING).getOpposite();
         return direction == direction3.getOpposite();
      }
   }

