   private Vec3d findReachableLerpedFacePoint(Vec3d vec, BlockPos pos, double lerpFactor) {
      VoxelShape voxelShape = mc.world.getBlockState(pos).getOutlineShape(mc.world, pos);
      if (voxelShape.isEmpty()) {
         return null;
      } else {
         Box box = voxelShape.getBoundingBox().offset(pos);
         double[] ds = new double[]{0.5, 0.25, 0.75};
         ArrayList<Vec3d> arrayList = new ArrayList<>();

         for (double d4 : ds) {
            for (double d3 : ds) {
               double d = MathHelper.lerp(d4, box.minX, box.maxX);
               double lerp2 = MathHelper.lerp(d3, box.minZ, box.maxZ);
               if (vec.y > box.maxY) {
                  arrayList.add(new Vec3d(d, box.maxY, lerp2));
               }

               if (vec.y < box.minY) {
                  arrayList.add(new Vec3d(d, box.minY, lerp2));
               }

               if (vec.x < box.minX || vec.x > box.maxX) {
                  arrayList.add(new Vec3d(vec.x < box.minX ? box.minX : box.maxX, MathHelper.lerp(d4, box.minY, box.maxY), lerp2));
               }

               if (vec.z < box.minZ || vec.z > box.maxZ) {
                  arrayList.add(new Vec3d(d, MathHelper.lerp(d3, box.minY, box.maxY), vec.z < box.minZ ? box.minZ : box.maxZ));
               }
            }
         }

         for (Vec3d vec3d : arrayList) {
            if (vec.squaredDistanceTo(vec3d) <= lerpFactor * lerpFactor && this.isRayHittingBlockAtOffsets(vec, vec3d.subtract(vec), lerpFactor, pos, 0.39999999999999997)) {
               return vec3d;
            }
         }

         return null;
      }
   }

