   private static AutoBuilder.SilentSpec getFacingSpecForState(BlockState state) {
      if (!isContainerLikeBlockState(state)) {
         return null;
      } else {
         Direction facingFromState = BlockStateUtilsView.getFacingFromState(state);
         com.corz.client.utils.PistonStickyUtils.Kind kind = BlockStateUtilsView.getDispenserObserver(state.getBlock());
         if (facingFromState != null && kind != null) {
            Direction direction3 = buildfinishedCorzclientDirections[PistonStickyUtils.getValue(facingFromState.ordinal(), kind)];
            Direction opposite = null;
            if (state.contains(Properties.ORIENTATION)) {
               Direction direction = state.get(Properties.ORIENTATION).getRotation();
               if (direction3.getAxis() == Axis.Y) {
                  if (direction.getAxis() == Axis.Y) {
                     return null;
                  }

                  opposite = direction3 == Direction.DOWN ? direction : direction.getOpposite();
               } else if (direction != Direction.UP) {
                  return null;
               }
            }

            return new AutoBuilder.SilentSpec(direction3, opposite);
         } else {
            return null;
         }
      }
   }

   private boolean holdForRedstoneSafety(BlockPos pos) {
      String string = this.getRedstoneDeferralReason(pos);
      if (string == null) {
         return false;
      } else {
         BlockPos blockPos2ShortPowered2 = this.blockPos2ShortPowered;
         BlockPos pos2 = this.appendBlockPos;
         if (this.moduleTick - this.lastTickPlacedSafety > 100) {
            this.lastTickPlacedSafety = this.moduleTick;
            this.logDebugMessage("\u00a7e[RedstoneSafety]\u00a7r holding " + pos.toShortString() + " - " + string);
         }

         this.updatePressedOptions2();
         if (blockPos2ShortPowered2 != null && this.tryReclaimTempBesideCircuit(blockPos2ShortPowered2, pos)) {
            return true;
         } else if (pos2 != null && this.tryTempBlockForBlockUpdate(pos, pos2)) {
            return true;
         } else if (!string.contains("not placed yet") && !string.contains("not built yet") && !string.contains("not exact")) {
            this.deferTargetBriefly(pos, "redstone safety: " + string);
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "redstone safety hold");
            return true;
         } else {
            if (this.hasActiveBlockersStep()) {
               this.blockers = null;
               this.stepIndex = -1;
               this.stepsTimeBudget.updateTimeMax();
            }

            Long longValue = this.placedExactMap.get(pos.asLong());
            if (longValue != null && string.contains("not placed yet") && this.canFacelessSeed(BlockPos.fromLong(longValue))) {
               return true;
            } else {
               if (longValue != null
                  && string.contains("not placed yet")
                  && this.excludedTargets.canFingerprintCells(longValue, this::getRawBlockStateIdAt)
                  && this.placedMap.getOrDefault(longValue, -1) != this.confirms) {
                  this.placedMap.put(longValue, this.confirms);
                  this.excludedTargets.hasBan(longValue);
                  this.entries.remove(longValue);
                  this.cooldown.remove(longValue);
                  this.layerPlanMap.remove(longValue);
                  this.standReachable.handleReadmittedStamps(longValue);
                  this.proofLayerMap.remove(longValue);
                  this.logDebugMessage(
                     "\u00a7b[RedstoneSafety]\u00a7r re-admitting excluded feeder "
                        + BlockPos.fromLong(longValue).toShortString()
                        + " - "
                        + pos.toShortString()
                        + " waits for it"
                  );
               }

               this.setCellCooldown(pos.asLong(), this.moduleTick + 1600);
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "redstone safety: prerequisite first");
               return true;
            }
         }
      }
   }

   private BlockPos findCertifiedStand(BlockPos pos) {
      this.standAcceptedStand = null;

      for (int n = 0; n < 3; n++) {
         BlockPos blockPos = this.getCachedRelaxedStand(pos);
         if (blockPos == null) {
            if (this.standAcceptedStand == null) {
               this.standAcceptedStand = StandableCertified.getStand("no stand accepted");
            }

            return null;
         }

         com.corz.client.utils.StandableCertified.Verdict verdict = this.getUnboundedStandVerdict(pos, blockPos, this.containsBlueprint);
         this.standableCertified.getDisconnectedConstructible(verdict);
         this.standAcceptedStand = verdict;
         if (verdict.isClsReachable()) {
            return blockPos;
         }

         if (!WalkRouteFinder.isStandable(mc.world, blockPos)) {
            return null;
         }

         this.recordBannedStandPair(getTimeForBlockPos(pos, blockPos), this.moduleTick + 140);
      }

      return null;
   }

   private Vec3d findReachablePointOnBlock(BlockPos pos, Vec3d vec, double offsetFactor) {
      double d10 = offsetFactor * offsetFactor;
      Vec3d vec3d4 = Vec3d.ofCenter(pos);
      if (vec.squaredDistanceTo(vec3d4) <= d10) {
         float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d4);
         if (this.doRaysHitBlock(vec, fs, offsetFactor, pos)) {
            return vec3d4;
         }
      }

      BlockState blockState = mc.world.getBlockState(pos);
      if (!(blockState.getBlock() instanceof TwistingVinesBlock) && !(blockState.getBlock() instanceof TwistingVinesPlantBlock)) {
         if (!blockState.isAir() && !blockState.getCollisionShape(mc.world, pos).isEmpty()) {
            for (Direction face : Direction.values()) {
               for (double[] ds2 : buildfinishedCorzclientAmounts) {
                  Vec3d vec3d2 = ds2 == null
                     ? this.getFaceAimPoint(blockState, pos, face)
                     : this.getFaceAimPointInRange(blockState, pos, face, ds2[0], ds2[1]);
                  if (vec3d2 != null && !(vec.squaredDistanceTo(vec3d2) > d10)) {
                     float[] wrapDegrees3 = MathClampUtils.getWrapDegrees(vec, vec3d2);
                     if (this.doRaysHitBlock(vec, wrapDegrees3, offsetFactor, pos)) {
                        return vec3d2;
                     }
                  }
               }
            }

            return null;
         } else {
            return null;
         }
      } else {
         int n = this.getSchematicCells(pos);
         if (n >= 0 && this.isTwistingVinesTarget(pos, this.targetFluidItems.get(n), blockState)) {
            Box box = blockState.getOutlineShape(mc.world, pos).getBoundingBox();
            double d3 = pos.getX() + (box.minX + box.maxX) / 2.0;
            double d4 = pos.getY() + (box.minY + box.maxY) / 2.0;
            double d5 = pos.getZ() + (box.minZ + box.maxZ) / 2.0;
            double d6 = (box.maxX - box.minX) / 2.0;
            double d7 = (box.maxY - box.minY) / 2.0;
            double d8 = (box.maxZ - box.minZ) / 2.0;
            double[] ds = new double[]{0.0, -0.6, 0.6};

            for (Direction direction : Direction.values()) {
               for (double d2 : ds) {
                  for (double d : ds) {
                     Vec3d vec3d = new Vec3d(
                        d3 + (direction.getOffsetX() != 0 ? direction.getOffsetX() * d6 * 0.98 : d2 * d6),
                        d4 + (direction.getOffsetY() != 0 ? direction.getOffsetY() * d7 * 0.98 : (direction.getOffsetX() != 0 ? d2 : d) * d7),
                        d5 + (direction.getOffsetZ() != 0 ? direction.getOffsetZ() * d8 * 0.98 : d * d8)
                     );
                     if (!(vec.squaredDistanceTo(vec3d) > d10)) {
                        float[] wrapDegrees2 = MathClampUtils.getWrapDegrees(vec, vec3d);
                        BlockHitResult blockHitResult = this.raycastFromEye(vec, wrapDegrees2[0], wrapDegrees2[1], offsetFactor);
                        if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
                           return vec3d;
                        }
                     }
                  }
               }
            }

            return null;
         } else {
            return null;
         }
      }
   }

