   private BlockPos findNearestReachableCell() {
      if (mc.player == null) {
         return null;
      } else {
         Vec3d vec3d = mc.player.getEyePos();
         double d2 = this.reachSetting.getValue();
         BlockPos feetBlockPos = this.getFeetBlockPos();
         BlockPos longValue = null;
         double distanceTo = Double.MAX_VALUE;

         for (long l : this.cells) {
            BlockPos blockPos = BlockPos.fromLong(l);
            double d = vec3d.squaredDistanceTo(Vec3d.ofCenter(blockPos));
            if (!(d > d2 * d2 + 1.0)
               && !(d >= distanceTo)
               && !this.isCellCoveredOrBlocked(l)
               && this.coverBodyMap.getOrDefault(l, 0) <= this.moduleTick
               && !blockPos.equals(feetBlockPos.down())
               && !FlagPoseUtils.canFlagPosePair(l, feetBlockPos.asLong())
               && this.findReachablePointOnBlock(blockPos, vec3d, d2) != null) {
               longValue = blockPos;
               distanceTo = d;
            }
         }

         return longValue;
      }
   }

