   private boolean hasUnbuiltCellNearby(BlockPos pos, int blockReplaceableLimit) {
      for (int n : this.getSchematicIndicesNear(Vec3d.ofCenter(pos), blockReplaceableLimit * 1.74 + 0.5)) {
         BlockPos blockPos = this.schematicCells.get(n);
         if (Math.abs(blockPos.getX() - pos.getX()) <= blockReplaceableLimit
            && Math.abs(blockPos.getY() - pos.getY()) <= blockReplaceableLimit
            && Math.abs(blockPos.getZ() - pos.getZ()) <= blockReplaceableLimit) {
            BlockState blockState = mc.world.getBlockState(blockPos);
            if (blockState.getBlock() != this.targetFluidItems.get(n).getBlock()
               && (blockState.isAir() || blockState.isReplaceable())
               && !this.isExcludedByMachineOrFloor(blockPos)) {
               Integer integer = this.cooldown.get(blockPos.asLong());
               if (integer == null || this.moduleTick >= integer) {
                  return true;
               }
            }
         }
      }

      return false;
   }

   private boolean needsFillForOpenNeighbor(BlockPos pos) {
      if (mc.world != null && !this.completionMissionMap.isEmpty()) {
         for (Direction direction2 : Type.HORIZONTAL) {
            BlockPos offsetPos = pos.offset(direction2);
            if (this.isAirBelowSolidTarget(offsetPos)
               && !this.isCellBlockedByTemporaryNeighbors(offsetPos)
               && !this.excludedTargets.canFingerprintCells(offsetPos.asLong(), this::getRawBlockStateIdAt)) {
               if (this.isAirBelowSolidTarget(pos) || !this.isAirPairAboveSolidFloor(pos) || !this.hasHorizontalSupportNeighbor(pos)) {
                  return false;
               }

               boolean flag = false;
               var iterator = Type.HORIZONTAL.iterator();

               while (true) {
                  if (iterator.hasNext()) {
                     Direction direction = (Direction)iterator.next();
                     BlockPos blockPos = offsetPos.offset(direction);
                     if (blockPos.equals(pos)
                        || this.isAirBelowSolidTarget(blockPos)
                        || !this.isAirPairAboveSolidFloor(blockPos)
                        || !this.hasWalkableSideCell(blockPos) && this.hasWalkableSideCell(pos)) {
                        continue;
                     }

                     flag = true;
                  }

                  if (!flag) {
                     return true;
                  }
                  break;
               }
            }
         }

         BlockPos down = pos.down();
         if (this.isAirBelowSolidTarget(down) && this.isAirOrReplaceable(pos) && this.hasHorizontalSolidNeighbor(down)) {
            for (Direction direction3 : Type.HORIZONTAL) {
               BlockPos downOffset = down.offset(direction3);
               if (this.isAirBelowSolidTarget(downOffset)
                  && !this.hasHorizontalSolidNeighbor(downOffset)
                  && !this.isCellBlockedByTemporaryNeighbors(downOffset)
                  && !this.isCellBlockedByTemporaryNeighbors(downOffset.up())
                  && !this.excludedTargets.canFingerprintCells(downOffset.asLong(), this::getRawBlockStateIdAt)
                  && !this.excludedTargets.canFingerprintCells(downOffset.up().asLong(), this::getRawBlockStateIdAt)
                  && this.hasSolidNeighborToPlaceOn(downOffset.up())) {
                  return true;
               }
            }
         }

         return false;
      } else {
         return false;
      }
   }

   private void pressKeysTowardXZ(double pressedOptionsValue, double pressedOptionsValue2) {
      double d3 = pressedOptionsValue - mc.player.getX();
      double d4 = pressedOptionsValue2 - mc.player.getZ();
      double radians5 = Math.toRadians(mc.player.getYaw());
      double sin6 = -Math.sin(radians5);
      double cos7 = Math.cos(radians5);
      double cos8 = Math.cos(radians5);
      double sin9 = Math.sin(radians5);
      double d10 = d3 * sin6 + d4 * cos7;
      double d11 = d3 * cos8 + d4 * sin9;
      mc.options.forwardKey.setPressed(d10 > 0.05);
      mc.options.backKey.setPressed(d10 < -0.05);
      mc.options.leftKey.setPressed(d11 > 0.05);
      mc.options.rightKey.setPressed(d11 < -0.05);
      mc.player.setSprinting(false);
   }

