   private AutoBuilder.PreparedDeck findPreparedDeckPick(BlockPos pos) {
      if (this.remaining != null && this.remaining.containsCell(pos.asLong()) && this.placementExplicit != null && this.currentTargetPos != null) {
         Vec3d vec3d = mc.player.getEyePos();
         double d = this.reachSetting.getValue();
         Map<Long, FloorBuildPlanner.Pick> map = new HashMap<>();
         Map<Long, AutoBuilder.MissionPlacement> hashMap = new HashMap<>();
         ArrayList<Candidate> arrayList = new ArrayList<>();

         for (long l : new ArrayList<>(this.remaining.frontiersByCell.keySet())) {
            if (l != this.placementExplicit.actionTargetPos) {
               BlockPos blockPos = BlockPos.fromLong(l);
               int n = blockPos.getX() - pos.getX();
               int n2 = blockPos.getZ() - pos.getZ();
               if (Math.max(Math.abs(n), Math.abs(n2)) <= (int)Math.ceil(d)) {
                  FloorBuildPlanner.Pick pick = new FloorBuildPlanner.Pick(
                     l,
                     pos.asLong(),
                     Math.abs(n) + Math.abs(n2) == 1 ? FloorBuildPlanner.Pose.EDGE : FloorBuildPlanner.Pose.DIAGONAL,
                     0,
                     n,
                     n2
                  );
                  AutoBuilder.MissionPlacement missionPlacement = this.planEdgePlacement(pick, pos, vec3d, d, true);
                  if (missionPlacement != null) {
                     map.put(l, pick);
                     hashMap.put(l, missionPlacement);
                     arrayList.add(this.buildClickCandidate(pick, missionPlacement));
                  }
               }
            }
         }

         if (arrayList.isEmpty()) {
            return null;
         } else {
            String string = mc.player.getMainHandStack().isEmpty() ? this.materialCycleDeck : getItemIdPath(mc.player.getMainHandStack().getItem());
            Candidate candidate = TierBuilderUtils.getTargetTier(
                  arrayList, mc.player.getYaw(), mc.player.getPitch(), string, this.faceCycleDeck
               )
               .get(0);
            AutoBuilder.MissionPlacement missionPlacement2 = hashMap.get(candidate.target());
            return candidate.tier() == 0
                  && candidate.hotbar()
                  && missionPlacement2 != null
                  && !missionPlacement2.recipe().longValue.equals(this.currentTargetPos)
                  && !Boolean.TRUE.equals(missionPlacement2.recipe().sneak)
               ? new AutoBuilder.PreparedDeck(map.get(candidate.target()), missionPlacement2, pos.asLong(), this.swapEvictableStackInventoryS.getCodeInstance())
               : null;
         }
      } else {
         return null;
      }
   }

