   private boolean hasBuildableNeighborInRange(BlockPos pos, int fluidTargetLimit) {
      for (int fluidTargetLimit4 = -fluidTargetLimit; fluidTargetLimit4 <= fluidTargetLimit; fluidTargetLimit4++) {
         for (int fluidTargetLimit3 = -fluidTargetLimit; fluidTargetLimit3 <= fluidTargetLimit; fluidTargetLimit3++) {
            for (int fluidTargetLimit2 = -fluidTargetLimit; fluidTargetLimit2 <= fluidTargetLimit; fluidTargetLimit2++) {
               if (fluidTargetLimit4 != 0 || fluidTargetLimit3 != 0 || fluidTargetLimit2 != 0) {
                  BlockPos blockPos = pos.add(fluidTargetLimit4, fluidTargetLimit3, fluidTargetLimit2);
                  int n = this.getSchematicCells(blockPos);
                  if (n >= 0
                     && !this.machineArmedSet.contains(blockPos.asLong())
                     && !isLockedRepeater(this.targetFluidItems.get(n))
                     && !this.isPlacedStateAcceptable(blockPos, this.targetFluidItems.get(n))) {
                     return true;
                  }
               }
            }
         }
      }

      return false;
   }

