   private void toggleLookedAtRestockSource() {
      if (mc.player != null && mc.world != null) {
         if (mc.crosshairTarget instanceof BlockHitResult blockHitResult && blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
            )
          {
            BlockPos pos = blockHitResult.getBlockPos();
            BlockState blockState = mc.world.getBlockState(pos);
            ChestTrappedType chestTrappedType = ChestTrappedType.getChestTrapped(blockState.getBlock());
            if (chestTrappedType == null) {
               DisabledEnabled.getInstance().handleDisabledEnabled("Restock", "Look at a chest, barrel, or shulker box", false);
            } else {
               String string = mc.world.getRegistryKey().getValue().toString();
               BlockPos rotateYcounterclockwise = this.getRotateYcounterclockwise(pos, blockState);
               boolean flag2 = rotateYcounterclockwise != null;
               boolean flag;
               if (flag2) {
                  if (!this.restockSources.containsEntry(pos, string) && !this.restockSources.containsEntry(rotateYcounterclockwise, string)) {
                     BlockPos blockPos = rotateYcounterclockwise.asLong() < pos.asLong() ? rotateYcounterclockwise : pos;
                     this.restockSources.addEntry(blockPos, string, chestTrappedType);
                     flag = true;
                  } else {
                     this.restockSources.removeEntry(pos, string);
                     this.restockSources.removeEntry(rotateYcounterclockwise, string);
                     flag = false;
                  }
               } else {
                  flag = this.restockSources.toggleEntry(pos, string, chestTrappedType);
               }

               if (!flag) {
                  this.restockSourceMap.remove(formatDimensionPosKey(string, pos.asLong()));
                  if (rotateYcounterclockwise != null) {
                     this.restockSourceMap.remove(formatDimensionPosKey(string, rotateYcounterclockwise.asLong()));
                  }
               }

               String string2 = flag2 ? "Double chest source " : "Restock source ";
               DisabledEnabled.getInstance().handleDisabledEnabled("Restock", string2 + (flag ? "added" : "removed"), flag);
               ModuleConfigAutosave.updateFlag2();
            }
         } else {
            DisabledEnabled.getInstance().handleDisabledEnabled("Restock", "Look at a chest, barrel, or shulker box", false);
         }
      }
   }

