   private boolean isPartialHeightFloorSafe(BlockPos pos) {
      if (pos != null && mc.world != null && this.targetFluidItems != null) {
         BlockPos down = pos.down();
         VoxelShape voxelShape = mc.world.getBlockState(down).getCollisionShape(mc.world, down);
         if (voxelShape.isEmpty()) {
            return false;
         } else {
            double max5 = voxelShape.getMax(Axis.Y);
            if (!(max5 <= 0.0) && !(max5 >= 0.999)) {
               int ceil3 = (int)Math.ceil(this.reachSetting.getValue());
               double max6 = Math.max(1.0, this.reachSetting.getValue() - 0.6);
               double d7 = pos.getX() + 0.5;
               double d8 = pos.getZ() + 0.5;
               double d9 = down.getY() + max5 + 1.62;
               double d10 = down.getY() + max5 + 1.27;
               int n4 = 0;

               for (long l : this.serviceBuiltItems.isEmpty() ? this.lapsesRetriedItems : this.serviceBuiltItems) {
                  BlockPos fromLong = BlockPos.fromLong(l);
                  int schematicCells2 = this.getSchematicCells(fromLong);
                  if (schematicCells2 >= 0
                     && this.completionMissionMap.containsKey(l)
                     && !fromLong.equals(pos)
                     && !fromLong.equals(pos.up())
                     && Math.abs(fromLong.getX() - pos.getX()) <= ceil3
                     && Math.abs(fromLong.getZ() - pos.getZ()) <= ceil3
                     && pos.getY() >= fromLong.getY() - 3
                     && pos.getY() <= fromLong.getY() + 2) {
                     double d2 = d7 - (fromLong.getX() + 0.5);
                     double d3 = d9 - (fromLong.getY() + 0.5);
                     double d4 = d8 - (fromLong.getZ() + 0.5);
                     if (!(d2 * d2 + d3 * d3 + d4 * d4 > max6 * max6)) {
                        if (fromLong.getY() != down.getY()
                           || Math.abs(fromLong.getX() - down.getX()) + Math.abs(fromLong.getZ() - down.getZ()) != 1) {
                           return false;
                        }

                        if (this.targetFluidItems.get(schematicCells2).getCollisionShape(mc.world, fromLong).isEmpty()) {
                           return false;
                        }

                        for (Direction direction : Direction.values()) {
                           BlockPos blockPos = fromLong.offset(direction);
                           if (!mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
                              int n = direction.getOffsetX() + direction.getOffsetY() + direction.getOffsetZ();
                              double d = (
                                    direction.getAxis() == Axis.X ? fromLong.getX() : (direction.getAxis() == Axis.Y ? fromLong.getY() : fromLong.getZ())
                                 )
                                 + (n > 0 ? 1 : 0);
                              boolean flag = direction.getAxis() == Axis.X
                                 ? (d7 - d) * -n > 1.0E-4
                                 : (direction.getAxis() == Axis.Y ? (d9 - d) * -n > 1.0E-4 || (d10 - d) * -n > 1.0E-4 : (d8 - d) * -n > 1.0E-4);
                              if (flag) {
                                 return false;
                              }
                           }
                        }

                        n4++;
                     }
                  }
               }

               return n4 > 0;
            } else {
               return false;
            }
         }
      } else {
         return false;
      }
   }

