   private String explainTicketRejection(AlternativeTicket alternativeTicket) {
      if ("DECK_FRONTIER".equals(alternativeTicket.kind())) {
         return "a surface is activated by the scheduler, never claimed by a refusal";
      } else if (this.schematicCells != null && mc.world != null) {
         BlockPos blockPos = BlockPos.fromLong(alternativeTicket.target());
         int n = this.getSchematicCells(blockPos);
         if (n < 0) {
            return "not a schematic cell";
         } else {
            BlockState blockState = this.targetFluidItems.get(n);
            BlockState worldState = mc.world.getBlockState(blockPos);
            if (worldState.getBlock() == blockState.getBlock() || areBlocksEquivalentVariants(blockState, worldState)) {
               return "already built";
            } else if (!worldState.isAir() && !worldState.isReplaceable()) {
               return "occupied";
            } else if (this.layer != Integer.MIN_VALUE && alternativeTicket.layer() != this.layer) {
               return "outside the work horizon (layer " + alternativeTicket.layer() + " vs " + this.layer + ")";
            } else {
               Integer integer = this.cooldown.get(blockPos.asLong());
               if (integer != null && this.moduleTick < integer) {
                  return "deferred";
               } else if (this.isCellBlockedByTemporaryNeighbors(blockPos)) {
                  return "proven dead";
               } else {
                  AutoBuilder.FailRec failRec = this.entries.get(blockPos.asLong());
                  if (failRec != null && this.isFailureRecordStillValid(blockPos, failRec)) {
                     return "failure memory";
                  } else if (!this.canObtainItemForPlacement(getItemForBlockState(blockState))) {
                     return "no material";
                  } else if (this.hasFluidNearBelowCell(blockPos)) {
                     return "caps a dry walled-in source that can be poured now";
                  } else if (this.shouldDeferCompletionCell(blockPos)) {
                     return "would wall in an unbuilt neighbour (interior first)";
                  } else if (this.isDeadlockRefused(blockPos)) {
                     return "phantom at this geometry";
                  } else {
                     String string = this.invalidatedRefusals
                        .lookupRefusalReason(
                           alternativeTicket.target(), alternativeTicket.stand(), this.computeNoSupportFaceKey(blockPos, BlockPos.fromLong(alternativeTicket.stand()))
                        );
                     if (string != null) {
                        return "invalidated ticket: " + string;
                     } else {
                        String formatExecutorProofHits2 = this.formatExecutorProofHits(blockPos, BlockPos.fromLong(alternativeTicket.stand()));
                        if (formatExecutorProofHits2 != null) {
                           return "executor disproved this stand: " + formatExecutorProofHits2;
                        } else {
                           BlockPos feetBlockPos = this.getFeetBlockPos();
                           BlockPos fromLong = BlockPos.fromLong(alternativeTicket.stand());
                           if (this.canPlaceFromStandWithoutSealing(blockPos, feetBlockPos)) {
                              return "would seal egress";
                           } else {
                              if (fromLong.equals(feetBlockPos)) {
                                 if (!this.canPlaceFromEyePos(blockPos, blockState, mc.player.getEyePos(), this.reachSetting.getValue())) {
                                    return "not visible from here";
                                 }
                              } else {
                                 this.rebuildReachableComponent();
                                 if (!this.component.contains(fromLong.asLong())) {
                                    return "stand not in the walkable component";
                                 }

                                 if (this.canSealsDeferred(blockPos, fromLong)) {
                                    return "stand banned";
                                 }

                                 if (!this.canPlaceFromEyePosition(blockPos, blockState, getStandingEyePos(fromLong), this.reachSetting.getValue(), false)) {
                                    return "no support face visible from the stand";
                                 }
                              }

                              return null;
                           }
                        }
                     }
                  }
               }
            }
         }
      } else {
         return "no schematic";
      }
   }

