   private boolean commitSideRun(LaneRowUtils.Run run, BlockPos pos, com.corz.client.utils.HeavyBatchUtils.Decision decision2, List<BlockPos> pathToLaneStart) {
      ProvenAdmittedHandler<LaneRowUtils.Run> provenAdmittedHandler = this.evaluateRunPreflight(run, decision2);
      if (provenAdmittedHandler.plan() == null) {
         return false;
      } else {
         run = provenAdmittedHandler.plan();
         BlockPos fromLong = BlockPos.fromLong(run.laneStart());
         this.sideRunSkippedDraining = new SkippedDraining(run);
         this.sessionResetMap.clear();
         this.sessionResetSet.clear();
         this.runSideCount = 0;
         this.windowWalkingAmount = Double.MAX_VALUE;
         this.laneSideAmount = Double.NaN;
         this.longSideRun = Long.MIN_VALUE;
         this.lanePathTime = this.laneRunSequence++;
         this.laneRunCount++;
         BlockPos fromLong3 = BlockPos.fromLong(run.members().get(0).target());
         this.currentTargetPos = fromLong3;
         this.supportAccessValue = this.getSchematicCells(fromLong3);
         this.blockHitResultEgressStand = null;
         this.blockPos2LayerAccess = null;
         this.sideRunValue = 0;
         this.resetCameraPredictionTimes();
         this.recordTargetSwitch("side_run");
         this.handleAccessRoute("side_run");
         this.setSupportText("SIDE_RUN", decision2.selected().kind() + " " + run.getMembers() + " members");
         this.logDebugMessage(
            "\u00a7b[SideRun]\u00a7r committed "
               + this.sideRunSkippedDraining.getFormat(this.moduleTick)
               + " lane="
               + fromLong.toShortString()
               + "\u2192"
               + BlockPos.fromLong(run.laneEnd()).toShortString()
               + " row="
               + fromLong3.toShortString()
               + " slippery="
               + this.isLaneStartSlippery(run)
         );
         List<BlockPos> goPath = pathToLaneStart != null ? pathToLaneStart : this.getPathToLaneStart(run, pos);
         if (goPath != null && goPath.isEmpty()) {
            int n = this.getSchematicCells(fromLong3);
            if (n >= 0) {
               this.updatePlacementRecipeForTarget(fromLong3, this.targetFluidItems.get(n));
            }

            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.SIDE_RUN, "on the run's lane");
            return true;
         } else if (goPath == null) {
            this.endSideRun("no path to the lane");
            return false;
         } else {
            this.arrivedLaneFlag = true;
            if (this.invalidNone.isLegacyConstruction()) {
               this.invalidNone.finishLegacyConstruction("superseded by side run " + this.lanePathTime);
            }

            this.invalidNone.beginReplacementYield(Owner.CONSTRUCTION, this.lanePathTime);
            this.laneRunFlag = true;
            if (!this.tryFollowMovementRoute(goPath, fromLong, this.createRunEntryMission(fromLong, run.getMembers()))) {
               this.arrivedLaneFlag = false;
               this.endSideRun("route refused");
               return false;
            } else {
               this.routeStandValue = 0;
               this.standRouteValue = 0;
               this.lastNodeTransitionIndex = -1;
               this.standWalkValue = 0;
               this.standRouteAmount = Double.MAX_VALUE;
               this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "walk to the run's lane");
               return true;
            }
         }
      }
   }

