   private void finishStaleCleanup(String staleText) {
      if (this.blockPos2Exit != null) {
         this.markNoValidStandBackoff(this.blockPos2Exit);
         this.passesSelectTimeHandle.handleTime(this.blockPos2Exit.asLong(), this.getProgressSignature(), Long.MIN_VALUE);
         if ("stale cleanup unreachable".equals(staleText)
            && this.hasActiveBlockersStep()
            && this.moduleTick - this.staleUnreachableValue >= 40
            && this.staleUnreachableMap.getOrDefault(this.blockPos2Exit.asLong(), 0) >= 5
            && mc.player.isOnGround()
            && mc.player.getVelocity().horizontalLengthSquared() < 1.0E-6) {
            SupportStandUtils.Step step = this.blockers.steps().get(this.stepIndex);
            if (step.op() == SupportStandUtils.Op.REMOVE_DIRT
               && step.stand() != null
               && toBlockPos(step.cell()).equals(this.blockPos2Exit)
               && this.getFeetBlockPos().equals(toBlockPos(step.stand()))) {
               this.reportCleanupRemovalStalled(this.blockPos2Exit, toBlockPos(step.stand()));
               this.setBudgetExhaustedReason("cleanup no_break at " + this.blockPos2Exit.toShortString());
               this.clearStaleCoverEntries(this.blockPos2Exit.asLong());
               this.wakeRev.handleForcePending("cleanup no_break");
            }
         }
      }

      this.blockPos2Exit = null;
      this.cleanupStaleItems = null;
      this.cleanupExitFlag = false;
      this.blockPos4Stale = null;
      this.reclaimDebtFlag = false;
      this.reclaimCircuitActive = false;
      this.transitionToState(AutoBuilder.State.SELECT_TARGET, staleText);
   }

