   private Surface classifySurfaceBelow(BlockPos pos) {
      if (this.cells.contains(pos.down().asLong())) {
         return Surface.OWNED_DIRT;
      } else {
         BlockState blockState = mc.world.getBlockState(pos.down());
         if (blockState.getBlock() instanceof ChestBlock) {
            return Surface.CHEST;
         } else if (WalkRouteFinder.hasOpenHorizontalNeighbor(mc.world, pos)) {
            return Surface.EDGE;
         } else {
            VoxelShape voxelShape = blockState.getCollisionShape(mc.world, pos.down());
            return !voxelShape.isEmpty() && voxelShape.getMax(Axis.Y) < 0.99 ? Surface.THIN : Surface.FULL;
         }
      }
   }

   private boolean startIslandStandMigration(BlockPos longValue, BlockPos feetBlockPos, int migrationIslandValue, String migrationIslandText, BlockPos pos) {
      if (this.airborneChainCount >= 4) {
         return this.parkIslandAndCheckExit("MIGRATION_LIMIT " + this.airborneChainCount + " handoffs without a placement");
      } else if (this.migratedIslandCount >= 16) {
         return this.parkIslandAndCheckExit("MIGRATION_LIMIT_TOTAL " + this.migratedIslandCount + " handoffs this mission");
      } else {
         this.migrationIslandIntegerMap.put(ClearanceHeadroomUtils.packHeadroomKey(feetBlockPos.getX(), feetBlockPos.getZ()), this.workRowCount);
         HashSet<Long> hashSet = new HashSet<>();

         for (Entry<Long, Integer> entry : this.migrationIslandIntegerMap.entrySet()) {
            if (entry.getValue() == this.workRowCount) {
               hashSet.add(entry.getKey());
            }
         }

         com.corz.client.utils.ClearanceHeadroomUtils.Plan plan = ClearanceHeadroomUtils.planLedgeBlockedRoute(
            this.createReachabilityWorldView(),
            ProofSupportUtils.getTime(feetBlockPos.getX(), feetBlockPos.getY(), feetBlockPos.getZ()),
            migrationIslandValue,
            this.getMissingCellsNear(feetBlockPos, migrationIslandValue),
            hashSet,
            this.reachSetting.getValue()
         );

         for (com.corz.client.utils.ClearanceHeadroomUtils.Candidate candidate : plan.candidates()) {
            candidate.isReject();
         }

         if (!plan.isChosen()) {
            return this.parkIslandAndCheckExit("NO_SAFE_STAND_HANDOFF from " + feetBlockPos.toShortString());
         } else {
            com.corz.client.utils.ClearanceHeadroomUtils.Candidate chosen = plan.chosen();
            BlockPos blockPos4 = new BlockPos(chosen.getFeetCellKey(), feetBlockPos.getY() - 1, chosen.getFeetPos());
            BlockPos blockPos5 = new BlockPos(chosen.getFeetCellKey(), feetBlockPos.getY(), chosen.getFeetPos());
            if (chosen.needsLedge()) {
               int n = this.maxLiveTempBlocks.getValue();
               int max2 = Math.max(0, this.countTempTowerCells() - this.countIslandCells());
               if (max2 + 1 > n && chosen.faced() < RecoverReadmitUtils.getValue(max2, n, 4)) {
                  return this.parkIslandAndCheckExit("TEMP_BUDGET debt=" + max2 + "/" + n + " for the ledge " + blockPos4.toShortString());
               }
            }

            this.islandExitCandidate = chosen;
            this.blockPos6IslandExit = feetBlockPos;
            this.blockPos4IslandExit = blockPos4;
            this.blockPos5IslandExit = blockPos5;
            this.handoffMigrationText = null;
            this.islandExitValue = chosen.needsLedge() ? 0 : 1;
            this.adjustMoveData = null;
            this.migrationIslandCount = this.islandExitCount = this.islandStepValue = 0;
            this.admittedColumnItems.add(new long[]{blockPos5.getX(), blockPos5.getZ(), blockPos4.getY(), migrationIslandValue + 2});
            this.currentTargetPos = longValue;
            this.supportAccessValue = this.getSchematicCells(longValue);
            this.name = "STAND_MIGRATION";
            this.setSupportText("TEMP_SUPPORT", "island seed " + longValue.toShortString() + " - stand migration");
            if (this.unknown == null || this.unknown.getMaxDescentBound() <= 0) {
               this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.SUPPORT, 1);
               this.islandSeedTime = this.unknown == null ? 0L : this.unknown.getReusableDescentTime();
            }

            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.ISLAND_MIGRATE, "island stand migration");
            return true;
         }
      }
   }

