   private BlockPos findTempSupportCell(BlockPos pos) {
      if (!this.unpackCellsIntArrayMap.isEmpty()
         && !this.digMissionFlag
         && this.blockPos2LifelineExtension == null
         && this.moduleTick - this.lifelineTopValue >= 40
         && mc.world != null
         && this.useTemporaryBlocks.isEnabled()
         && this.getHotbarDirtSlot() != -1) {
         for (Entry<Long, int[]> entry : this.unpackCellsIntArrayMap.entrySet()) {
            int[] ns = entry.getValue();
            if (ns.length >= 3 && ns[2] == 1) {
               BlockPos blockPos = new BlockPos(BlockPos.unpackLongX(entry.getKey()), ns[1] + 1, BlockPos.unpackLongZ(entry.getKey()));
               int n = pos.getY() - blockPos.getY();
               if (n >= 1 && n <= 2 && WalkRouteFinder.isStandable(mc.world, blockPos)) {
                  boolean flag = false;

                  for (Direction direction : Type.HORIZONTAL) {
                     if (WalkRouteFinder.isStandable(mc.world, blockPos.up(n).offset(direction))) {
                        flag = true;
                        break;
                     }
                  }

                  if (flag && this.canReplaceableAir(blockPos, pos.getY())) {
                     this.rebuildReachableComponent();
                     if (this.paveFacelessMap.containsKey(blockPos.asLong())) {
                        return blockPos;
                     }
                  }
               }
            }
         }

         return null;
      } else {
         return null;
      }
   }

   private static boolean hasRoomForStackInSlots(ScreenHandler screenHandler, int equalComponentsLimit, ItemStack stack) {
      for (int n = 0; n < equalComponentsLimit; n++) {
         ItemStack itemStack = screenHandler.getSlot(n).getStack();
         if (itemStack.isEmpty()) {
            return true;
         }

         if (itemStack.getCount() < itemStack.getMaxCount() && ItemStack.areItemsAndComponentsEqual(itemStack, stack)) {
            return true;
         }
      }

      return false;
   }

