   private boolean hasSolidNeighborToPlaceOn(BlockPos pos) {
      if (this.schematicCells != null && this.targetFluidItems != null && mc.world != null) {
         int n = this.getSchematicCells(pos);
         if (n >= 0 && isRedstoneComponentBlock(this.targetFluidItems.get(n)) && !this.targetFluidItems.get(n).canPlaceAt(mc.world, pos)) {
            return false;
         }

         if (n >= 0
            && (
               this.targetFluidItems.get(n).getBlock() instanceof HangingMossBlock || this.targetFluidItems.get(n).getBlock() instanceof AbstractPlantPartBlock
            )
            && !this.targetFluidItems.get(n).canPlaceAt(mc.world, pos)) {
            return false;
         }
      }

      for (Direction direction : Direction.values()) {
         BlockPos blockPos = pos.offset(direction);
         BlockState blockState = mc.world.getBlockState(blockPos);
         if (!blockState.isAir()
            && !blockState.isReplaceable()
            && (!blockState.getCollisionShape(mc.world, blockPos).isEmpty() || BlockStateUtilsView.canBlockOpen(blockState))
            && (!this.placeOrientedFlag || !isFlaggedBlockState(blockState))) {
            return true;
         }
      }

      return false;
   }

