   private void updateAlignedPlacementClick() {
      int n = this.getSchematicCells(this.currentTargetPos);
      if (n < 0) {
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "target vanished");
         this.resetCameraPredictionTimes();
      } else if (this.blockHitResult == null) {
         this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "no place hit - realign");
      } else if (!this.hasTrackedPosEntry(this.blockHitResult.getBlockPos())) {
         BlockState blockState = this.targetFluidItems.get(n);
         int n2 = SelectedInventoryUtils.getValue(getItemForBlockState(blockState));
         if (n2 == -1) {
            this.handleStuckProgress("no material");
         } else if (!this.canConstrainedStrand(this.currentTargetPos)) {
            boolean flag = isOrientedPistonNeedingSneak(blockState);
            if (flag && !this.bucketCrouchFlag) {
               this.resetCameraPredictionTimes();
               this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "6-way: the server look is not on the aim - realign");
            } else {
               float f = flag ? this.yaw : mc.player.getYaw();
               float f2 = flag ? this.pitch : mc.player.getPitch();
               if (flag) {
                  this.getSmoothedRotation(f, f2);
               }

               BlockHitResult blockHitResult = this.raycastBlockSideForAim(mc.player.getEyePos(), f, f2, this.reachSetting.getValue());
               if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                  && blockHitResult.getBlockPos().equals(this.blockHitResult.getBlockPos())
                  && blockHitResult.getSide() == this.blockHitResult.getSide()) {
                  this.blockHitResult = blockHitResult;
                  ItemStack itemStack = mc.player.getInventory().getStack(n2);
                  BlockState placementStateForSlot = flag
                     ? this.getPlacementStateWithRotation(itemStack, this.blockHitResult, f, f2)
                     : PlacementBlockUtils.getPlacementState(mc.player, Hand.MAIN_HAND, itemStack, this.blockHitResult);
                  if (!matchesFacingState(blockState, placementStateForSlot)) {
                     this.resetCameraPredictionTimes();
                     this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "prediction drifted before click");
                  } else {
                     boolean flaggedBlockState = isFlaggedBlockState(mc.world.getBlockState(this.blockHitResult.getBlockPos()));
                     if (flaggedBlockState && this.placeOrientedFlag) {
                        this.banFaceHittingGui(this.blockHitResult, "6-way place");
                     } else {
                        if (flaggedBlockState || this.solverRejectedFlag) {
                           this.setOwnerSneak(true);
                           if (this.builderValue < this.getRevertedPlacement()) {
                              this.transitionToState(AutoBuilder.State.SNEAK_SETTLE, "need sneak first");
                              return;
                           }
                        }

                        boolean flag3 = needSneakFlag && isSneakRequiredBlock(blockState);
                        if (!flag3 || !this.trySilentPlacePrime(this.currentTargetPos, blockState)) {
                           if (!flag3 && (this.solverUnavailableDirection == null || this.solverUnavailableDirection.getAxis() != Axis.Y) && !this.canTickMaxForTimes(f, f2, 0.5F)) {
                              this.realignCameraCount++;
                              if (this.staleCount > 200) {
                                 this.resetCameraPredictionTimes();
                                 this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "6-way: the server never held the camera look - realign");
                              }
                           } else if (!flag || this.hasRecentLookNear(f, f2)) {
                              this.selectHotbarSlot(n2);
                              if (!this.rejectPlacementFaceCertificate(this.blockHitResult)) {
                                 this.guardAccessTime = hashPosAndDirection(this.currentTargetPos, this.blockHitResult.getSide());
                                 this.blockHitResultEgressStand = this.blockHitResult;
                                 this.recordHitForCurrentTarget(this.blockHitResult);
                                 if (flag) {
                                    this.crouchVanishedTable = new float[]{f, f2};
                                 }

                                 this.performBlockInteraction(this.blockHitResult);
                                 if (this.swing.isEnabled()) {
                                    mc.player.swingHand(Hand.MAIN_HAND);
                                 }

                                 this.worldBlockMap.put(this.currentTargetPos.asLong(), this.moduleTick);
                                 this.recordPlacementAttempt(this.blockHitResult, blockState);
                                 this.realignHitAutoAggro.restart();
                                 this.transitionToState(AutoBuilder.State.WAIT_CONFIRMATION, "6-way clicked, awaiting world confirm");
                              }
                           }
                        }
                     }
                  }
               } else {
                  this.resetCameraPredictionTimes();
                  this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "6-way crosshair moved off the support (eye height changed) - realign");
               }
            }
         }
      }
   }

