   private boolean tryPlaceTempSupport(BlockPos longValue) {
      if (this.useTemporaryBlocks.isEnabled() && this.getHotbarDirtSlot() != -1 && longValue != null && this.schematicCells != null) {
         int n = this.getSchematicCells(longValue);
         if (n < 0) {
            return false;
         } else {
            for (DepPurpose depPurpose : this.supportMissionMap.values()) {
               if (depPurpose.owner == longValue.asLong()) {
                  return false;
               }
            }

            BlockState blockState2 = this.targetFluidItems.get(n);
            Direction requiredSupportDirection = this.getRequiredSupportDirection(longValue, blockState2);
            ArrayList<Direction> arrayList = new ArrayList<>();
            if (requiredSupportDirection != null) {
               arrayList.add(requiredSupportDirection);
            } else {
               arrayList.add(Direction.DOWN);

               for (Direction direction : Direction.values()) {
                  if (direction != Direction.DOWN) {
                     arrayList.add(direction);
                  }
               }
            }

            double d = this.reachSetting.getValue();
            this.rebuildReachableComponent();
            BlockPos offset = null;
            Object obj = null;
            Direction next = null;
            boolean contains = false;

            for (Direction arrayItem : arrayList) {
               BlockPos blockPos = longValue.offset(arrayItem);
               BlockState blockState = mc.world.getBlockState(blockPos);
               if ((blockState.isAir() || blockState.isReplaceable()) && !this.cellTemporarySet.contains(blockPos.asLong()) && this.hasSolidNeighborToPlaceOn(blockPos)) {
                  BlockPos standPosition = WalkRouteFinder.findStandPosition(
                     blockPos, d, this.cellTemporarySet, blockPos2x -> this.getBlockHitResult(blockPos, getStandingEyePos(blockPos2x), d, null, null) != null, null
                  );
                  if (standPosition != null) {
                     boolean flag = this.component.contains(standPosition.asLong());
                     if (offset == null || flag && !contains) {
                        offset = blockPos;
                        next = arrayItem;
                        contains = flag;
                        if (flag) {
                           break;
                        }
                     }
                  }
               }
            }

            if (offset != null) {
               this.blockPos3SupportConstructive = offset;
               this.blockPos2SupportConstructive = longValue;
               this.supportFloorValue = 0;
               this.name = requiredSupportDirection != null ? "FACING_SUPPORT" : "ATTACHMENT_SUPPORT";
               long l = ++this.supportAttachmentTime;
               com.corz.client.utils.DepPurpose.Purpose purpose = requiredSupportDirection != null ? com.corz.client.utils.DepPurpose.Purpose.FACING : com.corz.client.utils.DepPurpose.Purpose.ATTACHMENT;
               this.supportMissionMap.put(offset.asLong(), new DepPurpose(l, purpose, longValue.asLong(), offset.asLong(), this.moduleTick));
               this.currentTargetPos = longValue;
               this.supportAccessValue = n;
               this.logDebugMessage(
                  "\u00a7b[TempAccess]\u00a7r type=SUPPORT reason=no_reachable_support cell="
                     + offset.toShortString()
                     + " for="
                     + longValue.toShortString()
                     + " side="
                     + next
                     + " (temp block so the floating target has a face)"
               );
               this.setSupportText("TEMP_SUPPORT", "no reachable face for " + longValue.toShortString() + " - temp support " + offset.toShortString());
               this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.SUPPORT, 1);
               this.transitionToState(AutoBuilder.State.TEMP_SUPPORT, "building temp support (no reachable face)");
               return true;
            } else {
               return false;
            }
         }
      } else {
         return false;
      }
   }

   private void updateRepairBreak() {
      this.updatePressedOptions2();
      this.setOwnerSneak(false);
      if (this.blockPos == null) {
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "no repair target");
      } else {
         int n = this.getSchematicCells(this.blockPos);
         BlockState blockState = n >= 0 ? this.targetFluidItems.get(n) : null;
         BlockState blockState2 = mc.world.getBlockState(this.blockPos);
         boolean flag = blockState != null
            && (this.isTwistingVinesTarget(this.blockPos, blockState, blockState2) || blockState2.isAir() && this.hasTwistingVinesTargetBelow(this.blockPos, blockState));
         if (blockState != null && (this.isTrackedOrSpecialBlock(this.blockPos, blockState) || flag)) {
            BlockState blockState3 = mc.world.getBlockState(this.blockPos);
            if (blockState3.isAir() || blockState3.isReplaceable()) {
               this.worldBlockMap.remove(this.blockPos.asLong());
               BlockPos blockPos = this.blockPos;
               int orDefault = this.directionalFacingMap.getOrDefault(blockPos.asLong(), 0);
               if (this.repairBreakFlag) {
                  int merge = this.directionalFacingMap.merge(blockPos.asLong(), 1, Integer::sum);
               }

               this.blockPos = null;
               this.repairBreakFlag = false;
               this.noneRepair.handleCompletedRepair(blockPos.asLong());
               com.corz.client.utils.NoneRepair.Ticket none = this.noneRepair.getNoneForLong(blockPos.asLong());
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "wrong block broken");
            } else if (this.staleCount > 60) {
               this.recordRepairFailure(this.blockPos, "repair break timeout");
               this.blockPos = null;
               this.repairBreakFlag = false;
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "repair break timeout");
            } else {
               Vec3d vec3d = mc.player.getEyePos();
               double d = this.reachSetting.getValue();
               if (vec3d.squaredDistanceTo(Vec3d.ofCenter(this.blockPos)) > d * d && this.findReachablePointOnBlock(this.blockPos, vec3d, d) == null) {
                  this.currentTargetPos = this.blockPos;
                  this.supportAccessValue = this.getSchematicCells(this.blockPos);
                  this.blockHitResultEgressStand = null;
                  this.blockPos2LayerAccess = null;
                  this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "reach repair target");
               } else {
                  Vec3d vec3d2 = this.findReachablePointOnBlock(this.blockPos, vec3d, d);
                  float[] fs = MathClampUtils.getWrapDegrees(vec3d, vec3d2 != null ? vec3d2 : this.getOutlineCenter(this.blockPos, blockState3));
                  float[] aimRotation2 = this.computeAimRotation(fs[0], fs[1]);
                  BlockHitResult blockHitResult = this.raycastFromEye(vec3d, aimRotation2[0], aimRotation2[1], d);
                  if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(this.blockPos)) {
                     this.repairBreakFlag = true;
                     this.mineBlockStep(this.blockPos, blockHitResult.getSide(), true);
                     if (this.swing.isEnabled()) {
                        mc.player.swingHand(Hand.MAIN_HAND);
                     }
                  }
               }
            }
         } else {
            this.noneRepair.handle(this.blockPos.asLong());
            this.blockPos = null;
            this.repairBreakFlag = false;
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "foreign block protected from repair");
         }
      }
   }

   private BlockHitResult findDirectionalFaceHit(
      BlockState state,
      BlockPos pos,
      Direction face,
      Direction blockStateFacingDirection,
      com.corz.client.utils.PistonStickyUtils.Kind kind,
      Vec3d vec,
      double squaredAxisFactor,
      double squaredAxisLimit
   ) {
      double d8 = squaredAxisFactor * squaredAxisFactor;
      boolean flag = PistonStickyUtils.getFaceObserver(kind) == com.corz.client.utils.PistonStickyUtils.Family.FACE_AWAY;
      Vec3d vec3d4 = this.getFaceAimPoint(state, pos, face);
      BlockHitResult blockSide = null;
      double maxValue9 = Double.MAX_VALUE;
      double[] ds = new double[]{0.5, 0.35, 0.65, 0.25, 0.75, 0.15, 0.85, 0.08, 0.92};

      for (double d5 : ds) {
         for (double d4 : ds) {
            Vec3d vec3d = this.getFaceAimPointInRange(state, pos, face, d5, d4);
            if (vec3d != null && !(vec.squaredDistanceTo(vec3d) > d8)) {
               Vec3d vec3d2 = vec3d.subtract(vec);
               if (!(vec3d2.lengthSquared() < 1.0E-6)) {
                  int n = PistonStickyUtils.getValue(vec3d2.x, vec3d2.y, vec3d2.z);
                  Direction direction = buildfinishedCorzclientDirections[n];
                  Direction direction2 = flag ? direction : direction.getOpposite();
                  if (direction2 == blockStateFacingDirection && !(getAxisDominance(vec3d2, direction.getAxis()) < squaredAxisLimit)) {
                     float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d);
                     BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec, fs[0], fs[1], squaredAxisFactor);
                     if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                        && blockHitResult.getBlockPos().equals(pos)
                        && blockHitResult.getSide() == face) {
                        double d = vec3d.squaredDistanceTo(vec3d4);
                        double axisDominance2 = getAxisDominance(vec3d2, direction.getAxis());
                        double d3 = d * 4.0 - axisDominance2;
                        if (d3 < maxValue9) {
                           maxValue9 = d3;
                           blockSide = blockHitResult;
                        }
                     }
                  }
               }
            }
         }
      }

      return blockSide;
   }

