   private boolean tickIntervalAdjust() {
      Certificate certificate2 = this.intervalReportCertificate;
      if (certificate2 == null) {
         return false;
      } else if (this.currentTargetPos != null
         && this.placementExplicit != null
         && this.placementExplicit.isRevalidateAlign()
         && certificate2.target() == this.currentTargetPos.asLong()
         && this.deckMicroMoves.isProbingExitingLatched()) {
         this.intervalAdjustCount++;
         Interval interval = certificate2.interval();
         double d = mc.player.getX();
         double d2 = mc.player.getZ();
         Vec3d vec3d = mc.player.getVelocity();
         double slipperiness3 = this.getSlipperiness();
         Decision decision = SlidingPulseUtils.decideSlidingAction(interval, d, d2, vec3d.x, vec3d.z, slipperiness3);
         boolean containsPoint = interval.containsPoint(d, d2);
         boolean flag3 = decision.action() == com.corz.client.utils.SlidingPulseUtils.Action.COAST;
         boolean flag4 = decision.action() == com.corz.client.utils.SlidingPulseUtils.Action.BRAKE;
         this.intervalAdjustTable[decision.action().ordinal()]++;
         if (!containsPoint && !flag3 && !flag4) {
            this.intervalParityFlag = true;
            if (this.builderValue < 1) {
               this.releaseMovementKeys();
               return true;
            } else if (this.intervalAdjustCount > this.intervalReportValue) {
               this.finishIntervalReport(false);
               this.onExecutorFailure("adjust exceeded the hard cap (report: certificate interval unreachable)");
               return true;
            } else if (!this.intervalReportTimer.canTime(this.moduleTick)) {
               return true;
            } else {
               double hypot4 = Math.hypot(d - this.intervalAdjustAmount, d2 - this.intervalReportAmount);
               this.intervalAdjustAmount = d;
               this.intervalReportAmount = d2;
               if (this.intervalAdjustCount > 3 && hypot4 < 0.001) {
                  if (++this.intervalReportCount >= 4) {
                     this.finishIntervalReport(false);
                     this.onExecutorFailure("body blocked " + formatTwoDecimals(interval.distanceToPoint(d, d2)) + " short of the proven interval");
                     return true;
                  }
               } else {
                  this.intervalReportCount = 0;
               }

               this.handlePressedOptions(interval.settleX(), interval.settleZ(), false);
               return true;
            }
         } else {
            if (flag4) {
               if (!this.applyCounterStrafeKeys(0.004)) {
                  this.releaseMovementKeys();
               }
            } else {
               this.releaseMovementKeys();
            }

            if (!containsPoint) {
               return true;
            } else {
               if (!flag4) {
                  this.intervalParityFlag = false;
               }

               if (decision.action() != com.corz.client.utils.SlidingPulseUtils.Action.SETTLED && this.intervalAdjustCount < this.intervalReportValue) {
                  return true;
               } else {
                  boolean flag = certificate2.sneak()
                     || this.partnerClickFlag
                     || this.sneakBlock != null && Boolean.TRUE.equals(this.sneakBlock.sneak)
                     || this.safeSneak.isEnabled() && this.shouldSneakForEdge();
                  if ((flag ? this.builderValue < 2 : mc.player.isSneaking()) && this.intervalAdjustCount < this.intervalReportValue) {
                     return true;
                  } else if (this.findPlacementHit(this.currentTargetPos, mc.player.getEyePos(), this.reachSetting.getValue()) != null) {
                     this.finishIntervalReport(true);
                     return false;
                  } else {
                     if (this.intervalParityValue < 2 && this.placementExplicit.executorUnavailableObject.deckPick() != null) {
                        this.intervalParityValue++;
                        int schematicCells2 = this.getSchematicCells(this.currentTargetPos);
                        Certificate certificate = schematicCells2 < 0
                           ? null
                           : this.getPlacementCertificate(
                              this.placementExplicit.executorUnavailableObject.deckPick(),
                              this.getPrimaryStandPosition(),
                              this.targetFluidItems.get(schematicCells2),
                              this.reachSetting.getValue(),
                              true
                           );
                        if (certificate != null) {
                           this.adjustEdge.recordCertificate(certificate);
                        }

                        if (certificate != null && certificate.status() == com.corz.client.utils.CrouchedBodyUtils.Status.EXECUTABLE_CURRENT_POSE) {
                           if (this.sneakBlock != null && this.sneakBlock.sneakPoseFlag != certificate.sneak()) {
                              this.sneakBlock.sneakPoseFlag = certificate.sneak();
                              this.adjustEdge.eyeSwitchCount++;
                           }

                           this.finishIntervalReport(true);
                           return true;
                        }

                        if (certificate != null && certificate.isExecutableWithAdjust()) {
                           this.adjustEdge.recordEdgeAdjustRefined(this.intervalAdjustCount);
                           int n = this.intervalParityValue;
                           this.setupIntervalAdjust(
                              new AutoBuilder.MissionPlacement(this.sneakBlock, this.placementExplicit.executorUnavailableObject.deckPick(), null, certificate),
                              this.currentTargetPos
                           );
                           this.intervalParityValue = n;
                           return true;
                        }
                     }

                     this.adjustEdge.parityFailureCount++;
                     this.finishIntervalReport(false);
                     this.onExecutorFailure("pose parity: inside the proven interval, no visible support face");
                     return true;
                  }
               }
            }
         }
      } else {
         this.intervalReportCertificate = null;
         this.intervalParityFlag = false;
         this.intervalReportBlockPos = null;
         return false;
      }
   }

