   private AutoBuilder.TempDriveResult driveTempPlacement(String unstableRecenterText, BlockPos pos, BlockHitResult blockHitResult2, boolean unstableRecenterFlag) {
      if (this.unstableRecenterChangedTimeo != null && !this.isUnstableTargetCell(pos)) {
         this.failTempPlacement(com.corz.client.utils.ChangedTimeout.Failure.ABORTED);
      }

      if (this.unstableRecenterChangedTimeo == null) {
         if (blockHitResult2 == null) {
            return AutoBuilder.TempDriveResult.NEED_CONTEXT;
         }

         if (this.getSchematicCells(pos) >= 0 && !this.isSourceFluidTarget(pos)) {
            this.releaseUnknownOwnerForTarget("temp target is a schematic cell");
            this.transaction = "refused_schematic_cell";
            return AutoBuilder.TempDriveResult.FAILED;
         }

         String blockShort = this.describeObserverPulseHazard(pos);
         if (blockShort == null) {
            blockShort = this.formatBlockShort(pos);
         }

         if (blockShort == null && this.isSurroundedByFullCubes(pos)) {
            blockShort = "a pocket the schematic walls in on all six sides (the temp could never be taken out)";
         }

         if (blockShort == null && this.isFacedByExtendedPiston(pos)) {
            blockShort = "the head cell of a schematic piston (it extends into it and pushes the temp into the build)";
         }

         if (blockShort == null && this.isIslandStandViable(pos, this.getFeetBlockPos())) {
            blockShort = "it would wall the builder into a pocket (it takes the head room of the only way out)";
         }

         if (blockShort != null) {
            this.releaseUnknownOwnerForTarget("temp target is watched by a live observer");
            this.transaction = "refused_redstone_hazard";
            return AutoBuilder.TempDriveResult.FAILED;
         }

         if (this.unknown == null || this.unknown.getMaxDescentBound() <= 0) {
            this.observerHazardCount++;
            return AutoBuilder.TempDriveResult.FAILED;
         }

         SupportSnapshot supportSnapshot = this.buildSupportSnapshot(unstableRecenterText, pos, blockHitResult2, unstableRecenterFlag);
         if (blockHitResult2 != this.missionShortBlockHitResult && this.isCellTemporarilyBlocked(supportSnapshot.getExpectedTime())) {
            this.transaction = "context_banned";
            return AutoBuilder.TempDriveResult.FAILED;
         }

         int n = this.getHotbarDirtSlot();
         if (n == -1) {
            this.transaction = "no_dirt_in_hotbar";
            return AutoBuilder.TempDriveResult.FAILED;
         }

         this.selectHotbarSlot(n);
         this.unstableRecenterChangedTimeo = new ChangedTimeout(supportSnapshot, this.getClockTicks());
         this.lastNanoTimeUnstableRecenter = -1L;
         this.alignConfirmationType = null;
         this.workingPlayerValue = Long.MIN_VALUE;
      }

      SupportSnapshot supportSnapshot2 = this.unstableRecenterChangedTimeo.getSupportSnapshot();
      BlockPos blockPos3 = this.getBlockPos(supportSnapshot2.getRequiredStand());
      BlockPos feetBlockPos = this.getFeetBlockPos();
      boolean supportSnapshotFlag = supportSnapshot2.getPhase().endsWith("PILLAR_EXTENSION") || blockPos3.equals(pos.up());
      if (!supportSnapshotFlag && !this.unstableRecenterChangedTimeo.isFlag()) {
         boolean onGround3 = !mc.player.isOnGround();
         boolean intersects = mc.player.getBoundingBox().intersects(new Box(pos));
         boolean nearlyStill5 = !IncompleteStand.isNearlyStill(mc.player.getVelocity().horizontalLengthSquared());
         if (nearlyStill5 && !onGround3 && this.isOnNonSlipperyGround() && this.getFeetBlockPos().equals(blockPos3)) {
            Vec3d vec3d = mc.player.getVelocity();
            double d = this.getSlipperiness();
            double d2 = mc.player.getX() + SlidingPulseUtils.getDriftDistance(vec3d.x, d);
            double d3 = mc.player.getZ() + SlidingPulseUtils.getDriftDistance(vec3d.z, d);
            if (BlockStandBounds.isInsideStandArea(d2, d3, blockPos3.getX(), blockPos3.getZ())) {
               nearlyStill5 = false;
            }
         }

         if (onGround3 || intersects || nearlyStill5) {
            BlockPos blockPos = this.getBlockPos(supportSnapshot2.getRequiredStand());
            String unstableRecenterText2 = "unstable_body";
            boolean flag = false;
            boolean flag2 = !onGround3 && this.workingPlayerValue == blockPos.asLong() && this.getFeetBlockPos().equals(blockPos);
            if (flag2
               || !onGround3
                  && !nearlyStill5
                  && intersects
                  && this.getFeetBlockPos().equals(blockPos)
                  && !BlockStandBounds.isInsideStandArea(mc.player.getX(), mc.player.getZ(), blockPos.getX(), blockPos.getZ())) {
               AutoBuilder.Recentre recentre = this.centrePlayerOnBlock(blockPos);
               if (recentre == AutoBuilder.Recentre.WORKING) {
                  this.initUnstableRecenterNanoTime();
                  return AutoBuilder.TempDriveResult.WAITING;
               }

               if (recentre == AutoBuilder.Recentre.FAILED) {
                  String string = "recenter_failed";
                  flag = true;
               }
            }

            if (!flag && this.recenterUnstableValue < 40) {
               this.initUnstableRecenterNanoTime();
            }

            if (!flag && ++this.recenterUnstableValue <= 40) {
               this.releaseMovementKeys();
               return AutoBuilder.TempDriveResult.WAITING;
            }

            this.recenterUnstableValue = 0;
            this.unstableRecenterChangedTimeo.getAborted(com.corz.client.utils.ChangedTimeout.Failure.ABORTED);
            this.unstableRecenterChangedTimeo = null;
            this.alignConfirmationType = null;
            this.setSneakOwner(AutoBuilder.SneakOwner.NONE);
            this.setOwnerSneak(this.isFeetCellBlocked());
            this.transaction = "unstable_body";
            return AutoBuilder.TempDriveResult.FAILED;
         }

         this.recenterUnstableValue = 0;
      }

      this.resumeClockAfterPause();
      if (!SupportSnapshot.canFlag(toSupportCell(blockPos3), toSupportCell(feetBlockPos), supportSnapshotFlag) && !this.unstableRecenterChangedTimeo.isFlag()) {
         return this.failTempPlacement(com.corz.client.utils.ChangedTimeout.Failure.STAND_CHANGED);
      } else {
         if (supportSnapshot2.isInteractionRequiredFlag()) {
            this.setSneakOwner(AutoBuilder.SneakOwner.TEMP_PLACEMENT);
            this.updatePressedOptions5();
         } else {
            this.setSneakOwner(AutoBuilder.SneakOwner.NONE);
         }

         BlockState blockState = mc.world.getBlockState(pos);
         boolean dirtOrGrassBlock = isDirtOrGrassBlock(blockState);
         boolean flag9 = blockState.isAir() || blockState.isReplaceable();
         boolean flag10 = this.doesSnapshotMatchWorldBlock(supportSnapshot2);
         BlockHitResult sideBlock = null;
         if (!this.unstableRecenterChangedTimeo.isFlag() && flag10 && (!supportSnapshot2.isInteractionRequiredFlag() || this.builderValue >= supportSnapshot2.getMax())) {
            sideBlock = this.findSupportClickHit(supportSnapshot2);
         }

         Action action = this.unstableRecenterChangedTimeo
            .getSupportSnapshot(new Observation(this.getClockTicks(), mc.player.isSneaking(), this.builderValue, sideBlock != null, dirtOrGrassBlock, flag9, flag10));
         this.setAlignConfirmationType(action);
         if (action == Action.HOLD_SNEAK || action == Action.ALIGN || action == Action.WAIT_CONFIRMATION) {
            return AutoBuilder.TempDriveResult.WAITING;
         } else if (action == Action.FAILED) {
            return this.failTempPlacement(this.unstableRecenterChangedTimeo.getTimeoutChangedType());
         } else if (action == Action.CLICK_ONCE) {
            if (sideBlock != null && mc.player.getMainHandStack().getItem() == Blocks.DIRT.asItem()) {
               this.guardAccessTime = hashPosAndDirection(pos, sideBlock.getSide());
               this.worthFewerMap.put(pos.asLong(), this.moduleTick);
               this.unstableRecenterCount++;
               this.recordHitForCurrentTarget(sideBlock);
               this.performBlockInteraction(sideBlock);
               mc.player.swingHand(Hand.MAIN_HAND);
               return AutoBuilder.TempDriveResult.CLICKED;
            } else {
               return this.failTempPlacement(com.corz.client.utils.ChangedTimeout.Failure.WRONG_RESULT);
            }
         } else if (action != Action.CONFIRMED) {
            return AutoBuilder.TempDriveResult.WAITING;
         } else if (!this.confirmTemporaryDirtPlacement(pos) && !this.cells.contains(pos.asLong())) {
            return this.failTempPlacement(com.corz.client.utils.ChangedTimeout.Failure.WRONG_RESULT);
         } else {
            this.tempPlaced++;
            if (this.unstableRecenterPositionSet.add(pos.asLong())) {
               this.unstableRecenterAttemptCount++;
            } else {
               this.unstableRecenterRetryCount++;
            }

            this.handleDeclaredConfirmed(pos);
            this.unstableRecenterChangedTimeo = null;
            this.alignConfirmationType = null;
            this.setSneakOwner(AutoBuilder.SneakOwner.NONE);
            this.setOwnerSneak(false);
            return AutoBuilder.TempDriveResult.CONFIRMED;
         }
      }
   }

