   public void handleWriteCamera(QueueCommand queueCommand) {
      if (this.showRestockContainers.isEnabled() && mc.world != null && mc.player != null) {
         List<DimensionPosData> list = this.restockSources.getEntriesSnapshot();
         if (!list.isEmpty() || !this.copyOnWriteArrayList.isEmpty()) {
            String string = mc.world.getRegistryKey().getValue().toString();
            Vec3d vec3d = mc.gameRenderer.getCamera().getCameraPos();
            double d10 = this.restockRenderDistance.getValue() * this.restockRenderDistance.getValue();
            float f15 = (float)this.restockOutlineAlpha.getValue();
            int withAlpha3 = withAlpha(MatrixEspUtils.releaseRightValue, f15);
            int withAlpha4 = withAlpha(0, f15 * 0.5F);
            MatrixStack matrixStack = queueCommand.matrices;
            matrixStack.push();
            matrixStack.translate(-vec3d.x, -vec3d.y, -vec3d.z);
            Matrix4f matrix4f = matrixStack.peek().getPositionMatrix();
            Set<Long> set = this.getPositionsForDimension(list, string);

            for (DimensionPosData dimensionPosData : list) {
               if (dimensionPosData.dimension().equals(string)) {
                  AutoBuilder.RestockDraw restockDraw = this.getChestTrapped(dimensionPosData, set);
                  if (restockDraw != null) {
                     BlockPos blockPos = restockDraw.lo();
                     BlockPos hi2 = restockDraw.hi();
                     double d = (blockPos.getX() + hi2.getX()) / 2.0 + 0.5;
                     double d2 = blockPos.getY() + 0.5;
                     double d3 = (blockPos.getZ() + hi2.getZ()) / 2.0 + 0.5;
                     double d4 = d - vec3d.x;
                     double d5 = d2 - vec3d.y;
                     double d6 = d3 - vec3d.z;
                     if (!(d4 * d4 + d5 * d5 + d6 * d6 > d10)) {
                        float f = blockPos.getX() + 0.03F;
                        float f2 = blockPos.getY() + 0.03F;
                        float f3 = blockPos.getZ() + 0.03F;
                        float f4 = hi2.getX() + 0.97F;
                        float f5 = hi2.getY() + 0.97F;
                        float f6 = hi2.getZ() + 0.97F;
                        VertexBuilderUtils.handle(matrix4f, f, f2, f3, f4, f5, f6, withAlpha4, 4.0F);
                        VertexBuilderUtils.handle(matrix4f, f, f2, f3, f4, f5, f6, withAlpha3, 2.0F);
                     }
                  }
               }
            }

            if (!this.copyOnWriteArrayList.isEmpty()) {
               long l = System.currentTimeMillis();

               for (AutoBuilder.FadingRestock fadingRestock : this.copyOnWriteArrayList) {
                  if (fadingRestock.dimension().equals(string)) {
                     float f7 = (float)(l - fadingRestock.startMs()) / 600.0F;
                     if (!(f7 < 0.0F) && !(f7 >= 1.0F)) {
                        BlockPos fromLong = BlockPos.fromLong(fadingRestock.pos());
                        double d7 = fromLong.getX() + 0.5 - vec3d.x;
                        double d8 = fromLong.getY() + 0.5 - vec3d.y;
                        double d9 = fromLong.getZ() + 0.5 - vec3d.z;
                        if (!(d7 * d7 + d8 * d8 + d9 * d9 > d10)) {
                           float f8 = f15 * (1.0F - f7);
                           int n = withAlpha(MatrixEspUtils.releaseRightValue, f8);
                           int withAlpha2 = withAlpha(0, f8 * 0.5F);
                           float f9 = fromLong.getX() + 0.03F;
                           float f10 = fromLong.getY() + 0.03F;
                           float f11 = fromLong.getZ() + 0.03F;
                           float f12 = fromLong.getX() + 0.97F;
                           float f13 = fromLong.getY() + 0.97F;
                           float f14 = fromLong.getZ() + 0.97F;
                           VertexBuilderUtils.handle(matrix4f, f9, f10, f11, f12, f13, f14, withAlpha2, 4.0F);
                           VertexBuilderUtils.handle(matrix4f, f9, f10, f11, f12, f13, f14, n, 2.0F);
                        }
                     }
                  }
               }
            }

            VertexBuilderUtils.updateDrawImmediate();
            matrixStack.pop();
         }
      }
   }

   private static boolean doesSegmentPassThroughBlock(Vec3d vec, Vec3d vec2, BlockPos pos) {
      double d2 = vec2.x - vec.x;
      double d3 = vec2.y - vec.y;
      double d4 = vec2.z - vec.z;
      double sqrt5 = Math.sqrt(d2 * d2 + d3 * d3 + d4 * d4);
      if (sqrt5 < 1.0E-6) {
         return false;
      } else {
         int n2 = (int)Math.ceil(sqrt5 * 4.0) + 1;

         for (int n = 0; n <= n2; n++) {
            double d = (double)n / n2;
            if (MathHelper.floor(vec.x + d2 * d) == pos.getX()
               && MathHelper.floor(vec.y + d3 * d) == pos.getY()
               && MathHelper.floor(vec.z + d4 * d) == pos.getZ()) {
               return true;
            }
         }

         return false;
      }
   }

