      float max6 = Math.max(vertexTextureFont.getAbcdefghijklmnopqrstuvwxyzCorzfont(string2), vertexTextureFont.getAbcdefghijklmnopqrstuvwxyzCorzfont(corzfontText));
      float f7 = 6.0F;
      float f8 = 4.0F;
      float f9 = 1.5F;
      float f10 = f4 + f5 + max6 + f7 * 2.0F;
      float f11 = f3 * 2.0F + f9 + f8 * 2.0F;
