   private com.corz.client.utils.HeavyBatchUtils.Decision chooseRunPlacementDecision(LaneRowUtils.Run run, BlockPos pos, int adjustEdgeLimit, boolean adjustEdgeFlag) {
      int min2 = Math.min(this.getPaveDistance(run.laneStart(), pos), this.getPaveDistance(run.laneEnd(), pos));
      int n3 = min2 == Integer.MAX_VALUE ? 200 : min2 * 5;
      boolean laneStartSlippery = this.isLaneStartSlippery(run);
      long l = run.getMembersTarget();
      com.corz.client.utils.HeavyBatchUtils.Candidate candidate = HeavyBatchUtils.buildContinuousRunCandidate(
         run.kind(), l, run.getMembers(), n3 + (adjustEdgeFlag ? 60 : 0), 4.0, laneStartSlippery, run.getMembersDirectional(), run.getMembersPulse()
      );
      double d = this.adjustEdge.edgeAdjustCompletedCount > 0 ? (double)this.adjustEdge.edgeAdjustTicksTotal / this.adjustEdge.edgeAdjustCompletedCount : 27.0;
      double d2 = this.deckMicroMoves.surfacePlacementsCount > 0 && this.deckMicroMoves.deckSurfaceCount > 0
         ? (double)this.deckMicroMoves.surfacePlacementsCount / this.deckMicroMoves.deckSurfaceCount
         : 2.0;
      com.corz.client.utils.HeavyBatchUtils.Candidate candidate2 = this.deckMode.isEnabled()
         ? HeavyBatchUtils.buildDeckEdgeRunCandidate(l, run.getMembers(), adjustEdgeFlag ? 0 : n3 + 30, d, d2, 6.0, 4.0, 3)
         : null;
      com.corz.client.utils.HeavyBatchUtils.Candidate totalPriceData = adjustEdgeLimit > 0 ? HeavyBatchUtils.buildStaticStandBatchCandidate(l, Math.min(adjustEdgeLimit, run.getMembers()), 0, 22.0) : null;
      int needsAccess4 = this.needsAccess;
      com.corz.client.utils.HeavyBatchUtils.Candidate candidate4 = needsAccess4 > 0
         ? HeavyBatchUtils.buildAccessHeavyCandidate(
            l, Math.min(needsAccess4, run.getMembers()), n3 + 30, 3.0, 4.0, this.getValueUsingPosTime(BlockPos.fromLong(run.members().get(0).target())) <= 0 ? 0.75 : 0.25
         )
         : null;
      ArrayList<com.corz.client.utils.HeavyBatchUtils.Candidate> arrayList = new ArrayList<>();
      arrayList.add(candidate);
      if (candidate2 != null) {
         arrayList.add(candidate2);
      }

      if (totalPriceData != null) {
         arrayList.add(totalPriceData);
      }

      if (candidate4 != null) {
         arrayList.add(candidate4);
      }

      com.corz.client.utils.HeavyBatchUtils.Decision decision = HeavyBatchUtils.chooseBestCandidate(arrayList);
      if (decision.selected() != null && decision.selected().kind() == com.corz.client.utils.HeavyBatchUtils.Kind.ACCESS_PLATFORM_RUN) {
         this.adjustEdgeCount++;
      }

      return decision;
   }

   private boolean isNearPendingCompletionCell(BlockPos pos) {
      for (Long longValue : this.completionMissionMap.keySet()) {
         BlockPos blockPos = BlockPos.fromLong(longValue);
         if (blockPos.getY() >= pos.getY() - 1
            && Math.max(Math.abs(blockPos.getX() - pos.getX()), Math.abs(blockPos.getZ() - pos.getZ())) <= 6) {
            return true;
         }
      }

      return false;
   }

   private void lockYawToPlayerYaw() {
      this.applyClampedRotation(mc.player.getYaw(), this.getSinePulseValue(), 0.0F, 0.0F);
   }

   private boolean areRailNeighborsSupported(BlockPos pos, BlockState state) {
      if (!(state.getBlock() instanceof AbstractRailBlock abstractRailBlock)) {
         return true;
      } else {
         var property = abstractRailBlock.getShapeProperty();
         if (!state.contains(property)) {
            return true;
         } else {
            BlockPos[] blockPoss = getRailNeighbours(pos, state.get(property));

            for (Direction direction : Type.HORIZONTAL) {
               BlockPos offsetPos = pos.offset(direction);
               BlockPos supportBlockNear = this.findSupportBlockNear(offsetPos);
               if (supportBlockNear != null) {
                  boolean flag = false;

                  for (BlockPos blockPos : blockPoss) {
                     if (isSameColumn(blockPos, offsetPos)) {
                        flag = true;
                        break;
                     }
                  }

                  if (!flag && this.countConnectedRails(supportBlockNear) < 2) {
                     return false;
                  }
               }
            }

            return true;
         }
      }
   }

   private float[] getSmoothedRotation(float yawPitchValue, float f2) {
      float yaw3 = mc.player.getYaw();
      float pitch4 = mc.player.getPitch();
      if (!this.bucketCrouchFlag) {
         this.bucketCrouchFlag = true;
         this.yaw = yaw3;
         this.pitch = pitch4;
      }

      this.vanishedRayCount = 0;
      this.rayVanishedFlag = false;
      if (this.yawPitchValue != this.moduleTick) {
         float[] fs = MathDegreesUtils.getWrapDegrees(
            this.yaw, this.pitch, yawPitchValue, f2, 0.4F + 0.2F * this.random.nextFloat(), 18.0F + 6.0F * this.random.nextFloat(), 1.5F, ClampMath.getSensitivityMouse()
         );
         this.yaw = yaw3 + MathHelper.wrapDegrees(fs[0] - yaw3);
         this.pitch = fs[1];
         this.yawPitchValue = this.moduleTick;
      }

      boolean flag = Math.abs(MathHelper.wrapDegrees(this.yaw - yaw3)) > 0.01F;
      MathClampUtils.handleWrapDegrees(this, this.yaw, this.pitch, 1000, true, flag, false);
      return new float[]{this.yaw, this.pitch};
   }

