   private boolean advanceStaleCleanupWalk(Vec3d vec, double staleValue) {
      if (this.cleanupStaleItems != null || this.blockPos4Stale == null) {
         if (this.cleanupStaleItems == null) {
            BlockPos blockPos2Exit3 = this.blockPos2Exit;
            if (this.longValue != blockPos2Exit3.asLong()) {
               this.longValue = blockPos2Exit3.asLong();
               this.reachingCleanupValue = this.moduleTick;
               this.cleanupAimValue = 0;
            }

            if (++this.cleanupAimValue > 3 || this.moduleTick - this.reachingCleanupValue > 1200) {
               this.longValue = Long.MIN_VALUE;
               this.finishStaleCleanup("cleanup walk re-planned without reaching an aim");
               return true;
            }

            BlockPos nearestStandPosition = WalkRouteFinder.findNearestStandPosition(
               blockPos2Exit3,
               staleValue,
               blockPos2x -> !FlagPoseUtils.canFlagPosePair(blockPos2Exit3.asLong(), blockPos2x.asLong())
                  && !this.stalePositionSet.contains((blockPos2Exit3.asLong() * 31L + blockPos2x.asLong()) * 31L + this.cells.size())
                  && this.isWithinReachFromStand(blockPos2Exit3, blockPos2x)
                  && (
                     !this.isBlockCriticalForAccess(blockPos2Exit3, blockPos2x)
                        || FlagHandlerUtils.canFlagWithCount(this.digMissionFlag, this.cells.size() - (this.cells.contains(blockPos2Exit3.asLong()) ? 1 : 0))
                  )
            );
            List<BlockPos> list = nearestStandPosition == null ? null : (nearestStandPosition.equals(this.getFeetBlockPos()) ? Collections.emptyList() : this.findGoPath(this.getFeetBlockPos(), nearestStandPosition));
            if (nearestStandPosition == null || list == null) {
               this.finishStaleCleanup("stale cleanup unreachable");
               return true;
            }

            if (!this.digMissionFlag
               && this.coverReasonMap.containsKey(blockPos2Exit3.asLong())
               && nearestStandPosition.getY() < this.getFeetBlockPos().getY()
               && list.contains(blockPos2Exit3.up())
               && !this.cells.contains(blockPos2Exit3.down().asLong())) {
               this.finishStaleCleanup("temp cover: the way down to the break pose steps on the temp itself - broken from below, the body has no way back up");
               return true;
            }

            for (int n4 = 1; !this.digMissionFlag && n4 < list.size(); n4++) {
               BlockPos blockPos = list.get(n4 - 1);
               BlockPos blockPos2 = list.get(n4);
               if (blockPos2.getY() < blockPos.getY()) {
                  Terrain terrain = WalkRouteFinder.createTerrainView(mc.world);
                  BlockState blockState = mc.world.getBlockState(blockPos2);
                  VoxelShape voxelShape = blockState.getCollisionShape(mc.world, blockPos2);
                  int n = !WalkRouteFinder.isHazardBlock(blockState)
                        && !WalkRouteFinder.isPartialHeightBlock(blockState)
                        && !voxelShape.isEmpty()
                        && voxelShape.getMax(Axis.Y) < 1.0
                     ? 1
                     : 0;
                  int countReachableCells2 = WalkableRegionAnalyzer.countReachableCells(terrain, blockPos.getX(), blockPos.getY(), blockPos.getZ(), 40);
                  int countReachableCells3 = WalkableRegionAnalyzer.countReachableCells(terrain, blockPos2.getX(), blockPos2.getY() + n, blockPos2.getZ(), 40);
                  if (countReachableCells2 < 40 ? countReachableCells3 < countReachableCells2 && countReachableCells3 <= 12 : countReachableCells3 < 40) {
                     this.finishStaleCleanup("cleanup route drops into a closed pocket");
                     return true;
                  }
               }
            }

            if (list.isEmpty()) {
               if (this.findReachablePointOnBlock(blockPos2Exit3, vec, staleValue) != null) {
                  return false;
               }

               if (this.longStale != blockPos2Exit3.asLong()) {
                  this.longStale = blockPos2Exit3.asLong();
                  this.blockPos4Stale = nearestStandPosition;
                  this.lastTickStale = this.moduleTick;
                  this.cleanupAimValue--;
                  this.staleCount = 1;
                  return true;
               }

               this.finishStaleCleanup("stale cleanup stand reached without an aim");
               return true;
            }

            if (this.isRouteAccepted(list, nearestStandPosition)) {
               this.arrivedPoseFlag = this.isWithinAttemptLimit(blockPos2Exit3);
               this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "cleanup: walk to break pose");
               return true;
            }

            this.cleanupStaleItems = list;
            this.cleanupStaleCount = list.size() > 1 ? 1 : 0;
            this.cleanupStaleValue = this.moduleTick;
            this.cleanupWalkAmount = Double.MAX_VALUE;
            this.staleCleanupValue = this.moduleTick;
         }

         if (this.moduleTick - this.cleanupStaleValue > 600) {
            this.finishStaleCleanup("stale cleanup walk timeout");
            return true;
         } else if (this.moduleTick - this.staleCleanupValue > 40) {
            this.finishStaleCleanup("stale cleanup walk stalled");
            return true;
         } else {
            if (this.cleanupStaleCount < this.cleanupStaleItems.size()) {
               BlockPos pos = this.cleanupStaleItems.get(this.cleanupStaleCount);
               double d = pos.getX() + 0.5 - mc.player.getX();
               double d2 = pos.getZ() + 0.5 - mc.player.getZ();
               double d3 = d * d + d2 * d2;
               if (d3 < this.cleanupWalkAmount - 0.01) {
                  this.cleanupWalkAmount = d3;
                  this.staleCleanupValue = this.moduleTick;
               }

               if (d3 < 0.09) {
                  this.cleanupStaleCount++;
                  this.cleanupWalkAmount = Double.MAX_VALUE;
                  this.staleCleanupValue = this.moduleTick;
               } else {
                  this.applyYawOffsetRotation((float)Math.toDegrees(Math.atan2(-d, d2)), this.getSinePulseValue());
                  this.setOwnerSneak((this.isNeighborCellDangerous(this.getFeetBlockPos()) || this.isNeighborCellDangerous(pos)) && pos.getY() >= this.getFeetBlockPos().getY());
                  mc.player.setSprinting(false);
                  mc.options.forwardKey.setPressed(true);
                  boolean flag = pos.getY() > this.getFeetBlockPos().getY() && mc.player.isOnGround() && d3 < 2.25;
                  this.runGapRoute(flag);
               }
            } else {
               this.cleanupStaleItems = null;
            }

            this.staleCount = 1;
            return true;
         }
      } else if (this.findReachablePointOnBlock(this.blockPos2Exit, vec, staleValue) != null) {
         this.blockPos4Stale = null;
         this.releaseMovementKeys();
         return false;
      } else {
         AutoBuilder.Recentre recentre = this.centrePlayerOnBlock(this.blockPos4Stale);
         if (recentre == AutoBuilder.Recentre.WORKING && this.moduleTick - this.lastTickStale < 60) {
            this.staleCount = 1;
            return true;
         } else {
            this.blockPos4Stale = null;
            this.releaseMovementKeys();
            if (this.findReachablePointOnBlock(this.blockPos2Exit, mc.player.getEyePos(), staleValue) != null) {
               return false;
            } else {
               this.finishStaleCleanup("stale cleanup stand reached without an aim (centred)");
               return true;
            }
         }
      }
   }

