   private BlockPos findLowerOwnedStandCell(BlockPos pos) {
      if (!this.hasActiveCompoundCompletion() && this.getFeetBlockPos().getY() >= pos.getY()) {
         BlockPos down = pos.down();
         if (mc.world.getBlockState(down).getCollisionShape(mc.world, down).isEmpty()) {
            return null;
         } else {
            Vec3d vec3d = new Vec3d(mc.player.getX(), mc.player.getY() + 1.62, mc.player.getZ());

            for (Direction direction : Type.HORIZONTAL) {
               BlockPos blockPos = pos.down(2).offset(direction);
               BlockPos blockBelowPos = blockPos.down();
               BlockPos blockAbovePos = blockPos.up(2);
               if (this.cells.contains(blockPos.asLong())
                  && !this.cells.contains(blockBelowPos.asLong())
                  && this.getSchematicCells(blockBelowPos) < 0
                  && !mc.world.getBlockState(blockBelowPos).getCollisionShape(mc.world, blockBelowPos).isEmpty()
                  && mc.world.getBlockState(blockAbovePos).getCollisionShape(mc.world, blockAbovePos).isEmpty()
                  && !this.isCellCoveredOrBlocked(blockPos.asLong())
                  && !this.isCellInColumnBelowPlayer(blockPos)
                  && this.findReachablePointOnBlock(blockPos, mc.player.getEyePos(), this.reachSetting.getValue()) != null
                  && this.findReachablePointOnBlock(blockPos, vec3d, this.reachSetting.getValue()) != null) {
                  return blockPos;
               }
            }

            return null;
         }
      } else {
         return null;
      }
   }

