   private boolean tryStreamPartialPlan() {
      List<SupportStandUtils.Step> list = this.planStream.getCopyOf();
      int n = SupportStandUtils.PlanStream.getPlaceStand(list);
      if (this.missionCompletionMission != null) {
         if (this.blockers == this.missionCompletionMission && this.stepIndex >= this.missionCompletionMission.steps().size() && n > this.missionCompletionMission.steps().size()) {
            SupportStandUtils.Mission mission = this.buildPartialMission(list, n);
            this.blockers = mission;
            this.missionCompletionMission = mission;
            this.staleUnreachableValue = this.moduleTick;
            this.stepsTimeBudget.handleMaxTime(n, this.stepIndex, this.budgetExhaustedTime);
            return true;
         } else {
            return false;
         }
      } else {
         long l = this.planStream.getTime();
         if (n == 0 || l < 500000000L || this.confirms == this.exhaustedValue) {
            return false;
         } else if (!this.completionMissionActive && this.waitFullPass == Integer.MIN_VALUE && !this.digMissionFlag && this.cleanupMissionValue == Integer.MIN_VALUE) {
            if (this.computeCompletionHash() == this.planningRemovalTime && this.getFeetBlockPos().asLong() == this.longCompletionMission) {
               if (this.stepsCompletionTextBuilder.containsEntryPair(this.hashPlanStep(list.get(0)), this.getProgressFingerprint())) {
                  return false;
               } else if (!this.planStream.isAndSet()) {
                  return false;
               } else {
                  var copyOf = this.planStream.getCopyOf();
                  int placeStand = SupportStandUtils.PlanStream.getPlaceStand(copyOf);
                  SupportStandUtils.Mission partialMission2 = this.buildPartialMission(copyOf, placeStand);
                  this.exhaustedValue = this.confirms;
                  this.nanoTimeExhausted = System.nanoTime();
                  this.claims++;
                  this.blockers = partialMission2;
                  this.missionCompletionMission = partialMission2;
                  this.stepIndex = 0;
                  this.staleUnreachableValue = this.moduleTick;
                  this.budgetExhaustedText = null;
                  this.reachedCoverFlag = false;
                  this.budgetExhaustedTime = this.planningRemovalTime;
                  this.stepsTimeBudget.setMaxProgress(placeStand, this.budgetExhaustedTime);
                  this.logDebugMessage(
                     "\u00a7b[CompletionMission]\u00a7r streaming "
                        + placeStand
                        + " step(s) of the strict plan after "
                        + l / 1000000L
                        + " ms - the planner keeps computing "
                        + this.copyOf
                        + " cell(s) behind the body"
                  );
                  return true;
               }
            } else {
               return false;
            }
         } else {
            return false;
         }
      }
   }

