   private boolean isPairedBlockPlaced(BlockPos pos) {
      int n = this.getSchematicCells(pos);
      if (n < 0) {
         return false;
      } else {
         BlockState blockState = this.targetFluidItems.get(n);
         BlockPos rotateYcounterclockwise = this.getRotateYcounterclockwise(pos, blockState);
         return rotateYcounterclockwise != null && mc.world.getBlockState(rotateYcounterclockwise).getBlock() == blockState.getBlock();
      }
   }

   private boolean isBlockPlacedWithoutStateDiff(BlockPos pos, BlockState state) {
      if (matchesBlockStateRule(state) && mc.world != null) {
         BlockState blockState2 = mc.world.getBlockState(pos);
         if (blockState2.getBlock() != state.getBlock()) {
            return false;
         } else {
            SouthNorth southNorth = this.getMultifaceBlock(pos, state);
            return !southNorth.isEquals() && !southNorth.isUnmodifiable();
         }
      } else {
         return false;
      }
   }

