   private boolean isCellInFluidFloodSet(BlockPos pos) {
      if (this.schematicCells != null && this.targetFluidItems != null) {
         if (this.containsObject != this.schematicCells || this.containsValue != this.blockValue) {
            this.containsObject = this.schematicCells;
            this.containsValue = this.blockValue;
            this.containsWaterPositions.clear();
            this.containsPositionSet.clear();
            this.fluidPositionSet.clear();
            this.positionSet.clear();
            int min = Integer.MAX_VALUE;
            int intersectsCenterBound = Integer.MAX_VALUE;
            int maxValue3 = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            int aggroPreemptBound = Integer.MIN_VALUE;
            int minValue3 = Integer.MIN_VALUE;
            boolean flag3 = false;

            for (int n = 0; n < this.schematicCells.size(); n++) {
               BlockPos blockPos = this.schematicCells.get(n);
               min = Math.min(min, blockPos.getX());
               intersectsCenterBound = Math.min(intersectsCenterBound, blockPos.getY());
               maxValue3 = Math.min(maxValue3, blockPos.getZ());
               max = Math.max(max, blockPos.getX());
               aggroPreemptBound = Math.max(aggroPreemptBound, blockPos.getY());
               minValue3 = Math.max(minValue3, blockPos.getZ());
               if (hasFluidState(this.targetFluidItems.get(n))) {
                  flag3 = true;
               }
            }

            if (!flag3) {
               return false;
            }

            min--;
            maxValue3--;
            max++;
            aggroPreemptBound++;
            minValue3++;
            int n12 = aggroPreemptBound - intersectsCenterBound + 1;
            int n13 = minValue3 - maxValue3 + 1;
            long l = (long)(max - min + 1) * n12 * n13;
            if (l > 1000000L) {
               return false;
            }

            boolean[] flags = new boolean[(int)l];
            ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();

            for (int min4 = min; min4 <= max; min4++) {
               for (int intersectsCenterBound3 = intersectsCenterBound; intersectsCenterBound3 <= aggroPreemptBound; intersectsCenterBound3++) {
                  for (int n2 = maxValue3; n2 <= minValue3; n2++) {
                     if (min4 == min || min4 == max || n2 == maxValue3 || n2 == minValue3 || intersectsCenterBound3 == aggroPreemptBound) {
                        BlockPos blockPos2 = new BlockPos(min4, intersectsCenterBound3, n2);
                        if (this.isFluidTargetBlock(blockPos2)) {
                           flags[((min4 - min) * n12 + (intersectsCenterBound3 - intersectsCenterBound)) * n13 + (n2 - maxValue3)] = true;
                           arrayDeque.add(blockPos2);
                        }
                     }
                  }
               }
            }

            while (!arrayDeque.isEmpty()) {
               BlockPos poll4 = arrayDeque.poll();

               for (Direction direction : Direction.values()) {
                  BlockPos offset3 = poll4.offset(direction);
                  if (offset3.getX() >= min
                     && offset3.getX() <= max
                     && offset3.getY() >= intersectsCenterBound
                     && offset3.getY() <= aggroPreemptBound
                     && offset3.getZ() >= maxValue3
                     && offset3.getZ() <= minValue3) {
                     int n5 = ((offset3.getX() - min) * n12 + (offset3.getY() - intersectsCenterBound)) * n13 + (offset3.getZ() - maxValue3);
                     if (!flags[n5] && this.isFluidTargetBlock(offset3)) {
                        flags[n5] = true;
                        arrayDeque.add(offset3);
                     }
                  }
               }
            }

            for (int n6 = 0; n6 < this.schematicCells.size(); n6++) {
               BlockPos blockPos5 = this.schematicCells.get(n6);
               if (hasFluidState(this.targetFluidItems.get(n6))
                  && !flags[((blockPos5.getX() - min) * n12 + (blockPos5.getY() - intersectsCenterBound)) * n13 + (blockPos5.getZ() - maxValue3)]) {
                  this.containsWaterPositions.add(blockPos5.asLong());
               }
            }

            int intersectsCenterBound15 = intersectsCenterBound;
            final int lowX = min;
            final int highX = max;
            final int highY = aggroPreemptBound;
            final int lowZ = maxValue3;
            final int highZ = minValue3;
            PlanGrid planGrid = (n7x, n8x, n9x) -> {
               if (n7x >= lowX && n7x <= highX && n8x >= intersectsCenterBound15 && n8x <= highY && n9x >= lowZ && n9x <= highZ) {
                  int n10x = this.getSchematicCells(new BlockPos(n7x, n8x, n9x));
                  if (n10x < 0) {
                     return PlanCell.VOID;
                  } else {
                     BlockState blockStatex = this.targetFluidItems.get(n10x);
                     return !(blockStatex.getBlock() instanceof FluidBlock) ? PlanCell.WALL : (hasFluidState(blockStatex) ? PlanCell.SOURCE : PlanCell.FLOW);
                  }
               } else {
                  return PlanCell.WALL;
               }
            };

            for (int n7 = 0; n7 < this.schematicCells.size(); n7++) {
               BlockPos blockPos6 = this.schematicCells.get(n7);
               if (this.targetFluidItems.get(n7).isOf(Blocks.WATER) && this.containsWaterPositions.contains(blockPos6.asLong())) {
                  boolean flag = this.containsPositionSet.contains(blockPos6.down().asLong());

                  for (Direction direction2 : Type.HORIZONTAL) {
                     flag |= this.containsPositionSet.contains(blockPos6.offset(direction2).asLong());
                  }

                  if (flag || WallWatchedUtils.canEscapeToVoid(planGrid, blockPos6.getX(), blockPos6.getY(), blockPos6.getZ(), 256)) {
                     this.containsPositionSet.add(blockPos6.asLong());
                  }
               }
            }

            if (!this.containsPositionSet.isEmpty()) {
               for (int min10 = min; min10 <= max; min10++) {
                  for (int intersectsCenterBound9 = intersectsCenterBound; intersectsCenterBound9 <= aggroPreemptBound; intersectsCenterBound9++) {
                     for (int n8 = maxValue3; n8 <= minValue3; n8++) {
                        if (!flags[((min10 - min) * n12 + (intersectsCenterBound9 - intersectsCenterBound)) * n13 + (n8 - maxValue3)] && this.getSchematicCells(new BlockPos(min10, intersectsCenterBound9, n8)) < 0) {
                           this.fluidPositionSet.add(BlockPos.asLong(min10, intersectsCenterBound9, n8));
                        }
                     }
                  }
               }
            }

            for (int n11 = 0; n11 < this.schematicCells.size(); n11++) {
               BlockPos blockPos7 = this.schematicCells.get(n11);
               BlockState blockState = this.targetFluidItems.get(n11);
               if (blockState.isOf(Blocks.WATER) && hasFluidState(blockState) && !this.containsWaterPositions.contains(blockPos7.asLong()) && !this.isFluidTargetBlock(blockPos7.up())) {
                  boolean flag2 = true;

                  for (Direction direction3 : Direction.values()) {
                     if (this.getSchematicCells(blockPos7.offset(direction3)) < 0) {
                        flag2 = false;
                        break;
                     }
                  }

                  if ((!flag2 || WallWatchedUtils.isSealedByWalls(planGrid, blockPos7.getX(), blockPos7.getY(), blockPos7.getZ(), 256))
                     && flag2
                     && !WallWatchedUtils.canEscapeToVoid(planGrid, blockPos7.getX(), blockPos7.getY(), blockPos7.getZ(), 256)) {
                     this.containsWaterPositions.add(blockPos7.asLong());
                     this.positionSet.add(blockPos7.asLong());
                  }
               }
            }
         }

         return this.containsWaterPositions.contains(pos.asLong());
      } else {
         return false;
      }
   }

   private Vec3d findBestAimPointOnFace(BlockPos pos2, Direction direction3, Vec3d vec, double autoBuilderFactor, Vec3d vec2, Direction direction4) {
      if (mc.world == null) {
         return null;
      } else {
         BlockState blockState = mc.world.getBlockState(pos2);
         VoxelShape voxelShape = blockState.getOutlineShape(mc.world, pos2);
         if (voxelShape.isEmpty()) {
            return null;
         } else {
            Vec3d pos = null;
            double distanceTo = Double.MAX_VALUE;

            for (Box box : voxelShape.getBoundingBoxes()) {
               double d7 = direction3 == Direction.EAST ? box.maxX : (direction3 == Direction.WEST ? box.minX : Double.NaN);
               double d8 = direction3 == Direction.UP ? box.maxY : (direction3 == Direction.DOWN ? box.minY : Double.NaN);
               double d9 = direction3 == Direction.SOUTH ? box.maxZ : (direction3 == Direction.NORTH ? box.minZ : Double.NaN);

               for (int n2 = 0; n2 <= 4; n2++) {
                  for (int n = 0; n <= 4; n++) {
                     double d = 0.1 + 0.2 * n2;
                     double d2 = 0.1 + 0.2 * n;
                     double d3 = !Double.isNaN(d7) ? d7 : box.minX + (box.maxX - box.minX) * d;
                     double d4 = !Double.isNaN(d8) ? d8 : box.minY + (box.maxY - box.minY) * (Double.isNaN(d7) ? d2 : d);
                     double d5 = !Double.isNaN(d9) ? d9 : box.minZ + (box.maxZ - box.minZ) * d2;
                     Vec3d vec3d = new Vec3d(pos2.getX() + d3, pos2.getY() + d4, pos2.getZ() + d5);
                     if (!(vec.squaredDistanceTo(vec3d) > autoBuilderFactor * autoBuilderFactor)) {
                        double squaredDistanceTo6 = vec3d.squaredDistanceTo(vec2);
                        if (!(squaredDistanceTo6 >= distanceTo)) {
                           float[] fs = MathClampUtils.getWrapDegrees(vec, vec3d);
                           if (direction4 == null || Direction.fromHorizontalDegrees(fs[0]) == direction4) {
                              BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec, fs[0], fs[1], autoBuilderFactor);
                              if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                                 && blockHitResult.getBlockPos().equals(pos2)
                                 && blockHitResult.getSide() == direction3) {
                                 distanceTo = squaredDistanceTo6;
                                 pos = blockHitResult.getPos();
                              }
                           }
                        }
                     }
                  }
               }
            }

            return pos;
         }
      }
   }

