   private boolean isHopperLoopCanonicalCell(BlockPos pos, BlockState state) {
      if (state.getBlock() instanceof HopperBlock
         && mc.world != null
         && this.schematicCells != null
         && this.targetFluidItems != null
         && state.get(Properties.HOPPER_FACING).getAxis().isHorizontal()) {
         if (this.changedPlanCountAxisHorizont != changedPlanCount || this.axisHorizontalObject != this.schematicCells) {
            this.axisHorizontalBooleanMap.clear();
            this.changedPlanCountAxisHorizont = changedPlanCount;
            this.axisHorizontalObject = this.schematicCells;
         }

         Boolean booleanValue = this.axisHorizontalBooleanMap.get(pos.asLong());
         if (booleanValue != null) {
            return booleanValue;
         } else {
            ArrayList<BlockPos> arrayList = new ArrayList<>();
            boolean flag = false;
            boolean flag2 = false;
            BlockPos offset = pos;

            for (int n2 = 0; n2 < 64; n2++) {
               int n = this.getSchematicCells(offset);
               if (n < 0) {
                  flag2 = true;
                  break;
               }

               BlockState blockState = this.targetFluidItems.get(n);
               BlockState blockState2 = mc.world.getBlockState(offset);
               if (!(blockState.getBlock() instanceof HopperBlock) || !blockState2.isAir() && !blockState2.isReplaceable()) {
                  flag2 = true;
                  break;
               }

               Direction direction = blockState.get(Properties.HOPPER_FACING);
               if (!direction.getAxis().isHorizontal()) {
                  flag2 = true;
                  break;
               }

               arrayList.add(offset);
               offset = offset.offset(direction);
               if (offset.equals(pos)) {
                  flag = true;
                  break;
               }
            }

            BlockPos blockPos2 = null;
            if (flag) {
               BlockPos next = null;

               for (BlockPos blockPos : arrayList) {
                  if (next == null || blockPos.asLong() < next.asLong()) {
                     next = blockPos;
                  }

                  if ((blockPos2 == null || blockPos.asLong() < blockPos2.asLong()) && this.hasSolidNeighborToPlaceOn(blockPos)) {
                     blockPos2 = blockPos;
                  }
               }

               if (blockPos2 == null) {
                  blockPos2 = next;
               }
            }

            if (flag || flag2) {
               for (BlockPos arrayItem : arrayList) {
                  this.axisHorizontalBooleanMap.put(arrayItem.asLong(), arrayItem.equals(blockPos2));
               }
            }

            this.axisHorizontalBooleanMap.put(pos.asLong(), pos.equals(blockPos2));
            return pos.equals(blockPos2);
         }
      } else {
         return false;
      }
   }

   private BlockHitResult raycastBlockSideForAim(Vec3d vec, float blockSideValue, float f2, double absentRaycastValue) {
      BlockHitResult blockHitResult = BlockStateUtilsView.getAbsentRaycast(mc.world, this.getShapeContext(), vec, blockSideValue, f2, absentRaycastValue, this.apiAutoPolicy);
      if (this.currentTargetPos != null
         && (
            blockHitResult.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK
               || !blockHitResult.getBlockPos().offset(blockHitResult.getSide()).equals(this.currentTargetPos)
         )) {
         BlockHitResult absentRaycast = BlockStateUtilsView.getAbsentRaycast(mc.world, this.getShapeContext(), vec, blockSideValue, f2, absentRaycastValue, null, true);
         return absentRaycast.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK
               || !absentRaycast.getBlockPos().offset(absentRaycast.getSide()).equals(this.currentTargetPos)
               || !BlockStateUtilsView.canBlockOpen(mc.world.getBlockState(absentRaycast.getBlockPos()))
                  && (
                     absentRaycast.getSide() != Direction.UP
                        || !(
                           mc.world
                                 .getBlockState(absentRaycast.getBlockPos())
                                 .getCollisionShape(mc.world, absentRaycast.getBlockPos())
                                 .getMax(Axis.Y)
                              > 1.0001
                        )
                  )
                  && (
                     absentRaycast.getSide() != Direction.UP
                        || !BlockStateUtilsView.canWireIterator(mc.world.getBlockState(absentRaycast.getBlockPos()))
                  )
            ? blockHitResult
            : absentRaycast;
      } else {
         return blockHitResult;
      }
   }

