   private int countReachableTargetsNearby(BlockPos pos, int iteratorCenterValue, int iteratorCenterLimit) {
      BlockPos abovePos = pos.up(iteratorCenterValue);
      BlockPos adjacentWalkableCell = this.findAdjacentWalkableCell(abovePos);
      if (adjacentWalkableCell == null) {
         return 0;
      } else {
         double d = this.reachSetting.getValue();
         double max2 = Math.max(1.0, d - 0.6);
         double d3 = max2 * max2;
         HashSet<Long> hashSet = new HashSet<>();
         ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
         hashSet.add(adjacentWalkableCell.asLong());
         arrayDeque.add(adjacentWalkableCell);
         int n4 = 0;
         int n5 = 0;
         HashSet<Long> hashSet2 = new HashSet<>();

         while (!arrayDeque.isEmpty() && hashSet.size() < 120 && n4 < iteratorCenterLimit && n5 < 400 + 40 * iteratorCenterLimit) {
            BlockPos poll3 = arrayDeque.poll();

            for (Entry<Long, BlockState> entry : this.completionMissionMap.entrySet()) {
               if (!hashSet2.contains(entry.getKey()) && (this.iteratorCenterPositionSet.isEmpty() || this.iteratorCenterPositionSet.contains(entry.getKey()))) {
                  BlockPos blockPos = BlockPos.fromLong(entry.getKey());
                  if (!(getStandingEyePos(poll3).squaredDistanceTo(Vec3d.ofCenter(blockPos)) > d3)) {
                     n5++;
                     if (this.canPlaceFromEyePosition(blockPos, entry.getValue(), getStandingEyePos(poll3), d, false)
                        || this.canPlaceFromEyePosition(blockPos, entry.getValue(), getLoweredTargetPoint(poll3), d, true)) {
                        hashSet2.add(entry.getKey());
                        n4++;
                     }
                  }
               }
            }

            for (Direction direction : Type.HORIZONTAL) {
               for (int n = 1; n >= -1; n--) {
                  BlockPos up2 = poll3.offset(direction).up(n);
                  if (Math.abs(up2.getY() - abovePos.getY()) <= 1
                     && !this.cellTemporarySet.contains(up2.asLong())
                     && WalkRouteFinder.isStandable(mc.world, up2)
                     && hashSet.add(up2.asLong())) {
                     arrayDeque.add(up2);
                     break;
                  }
               }
            }
         }

         return n4;
      }
   }

   private boolean runIslandRecoveryStep() {
      if (this.islandAbort != 0L && this.exitIslandFlag) {
         return this.tryStartIslandExit();
      } else if (this.islandAbort != 0L && this.useTemporaryBlocks.isEnabled() && mc.world != null && this.getHotbarDirtSlot() == -1) {
         return this.parkIslandAndCheckExit("NO_DIRT in the hotbar");
      } else if (this.islandAbort == 0L || !this.useTemporaryBlocks.isEnabled() || this.getHotbarDirtSlot() == -1 || mc.world == null) {
         return false;
      } else if (this.oursFlag) {
         return this.runIslandChainStep();
      } else {
         Solid solid = this::isSolidNonReplaceableAt;
         Blocked blocked = (islandSeedValue, islandSeedValue2, islandSeedValue3) -> this.cellTemporarySet.contains(BlockPos.asLong(islandSeedValue, islandSeedValue2, islandSeedValue3));
         BlockPos fromLong = BlockPos.fromLong(this.islandAbort);
         long[] ls = this.solveSupportPositionBelow(fromLong, 8, solid, blocked);
         if (ls == null) {
            int n = this.getSchematicCells(fromLong);
            BlockState blockState = n >= 0 ? this.targetFluidItems.get(n) : null;
            boolean flag = blockState != null
               && mc.world.getBlockState(fromLong).getBlock() == blockState.getBlock()
               && this.isPlacedStateAcceptable(fromLong, blockState);
            if (flag) {
               BlockPos blockPos = this.getFeetBlockPos();
               if (this.longIslandSeed == 0L
                  || BlockPos.unpackLongX(this.longIslandSeed) != blockPos.getX()
                  || BlockPos.unpackLongZ(this.longIslandSeed) != blockPos.getZ()) {
                  this.admittedColumnItems.add(new long[]{blockPos.getX(), blockPos.getZ(), blockPos.getY() - 1, fromLong.getY() + 6 + 2});
                  this.longIslandSeed = blockPos.asLong();
                  this.riseRaiseItems.add(blockPos.asLong());
               }

               this.oursFlag = true;
               this.seedIslandValue = -1;
               this.chainIslandValue = 0;
               this.airborneChainValue = 0;
               return this.runIslandChainStep();
            } else if (n >= 0 && this.hasSolidNeighborToPlaceOn(fromLong) && this.canObtainItemForPlacement(getItemForBlockState(blockState))) {
               if (this.seedIslandValue < 0) {
                  this.seedIslandValue = this.moduleTick;
               }

               this.setTransferTarget(fromLong, "island_seed_faced");
               Vec3d vec3d = mc.player.getEyePos();
               double d = this.reachSetting.getValue();
               BlockPos feetBlockPos = this.getFeetBlockPos();
               Vec3d vec3d2 = this.getAimPointForSneakState(feetBlockPos, fromLong, vec3d, true);
               boolean flag2 = vec3d2.squaredDistanceTo(Vec3d.ofCenter(fromLong)) <= d * d
                  && this.canPlaceFromEyePosition(fromLong, blockState, vec3d2, d, this.shouldCrouchForSafeSneak(feetBlockPos, fromLong))
                  && !this.isAirborneChainRepeated(fromLong, feetBlockPos);
               if (flag2) {
                  if (this.canNone(fromLong, feetBlockPos)) {
                     return this.parkIslandAndCheckExit("EGRESS_DEFERRED owner " + fromLong.toShortString() + " from " + feetBlockPos.toShortString());
                  } else if (this.canPlanContinuation(fromLong, n, blockState)) {
                     this.airborneChainValue = 0;
                     this.trackAirborneChainRepeat(fromLong, feetBlockPos);
                     return true;
                  } else {
                     return ++this.airborneChainValue > 60
                        ? this.parkIslandAndCheckExit("COMMIT_REFUSED owner " + fromLong.toShortString() + " " + this.airborneChainValue + " passes")
                        : true;
                  }
               } else if (this.isNearIslandAbortHeight(fromLong)) {
                  this.seedIslandValue = this.moduleTick;
                  return true;
               } else if (ClearanceHeadroomUtils.canClearanceRaise(this.airborne)
                  && this.longIslandSeed != 0L
                  && BlockPos.unpackLongX(this.longIslandSeed) == feetBlockPos.getX()
                  && BlockPos.unpackLongZ(this.longIslandSeed) == feetBlockPos.getZ()) {
                  this.onIslandAborted("stand column " + feetBlockPos.toShortString() + " cannot raise: " + this.airborne);
                  return false;
               } else {
                  BlockPos replaceableWorld = null;
                  if (this.longIslandSeed != 0L) {
                     BlockPos pos = BlockPos.fromLong(this.longIslandSeed);
                     BlockPos feetBlockPos3 = this.getFeetBlockPos();
                     if (feetBlockPos3.getX() != pos.getX() || feetBlockPos3.getZ() != pos.getZ()) {
                        replaceableWorld = this.getReplaceableWorld(pos);
                     }
                  }

                  if (replaceableWorld == null) {
                     replaceableWorld = this.getShortCls(fromLong, d);
                  }

                  if (replaceableWorld != null && replaceableWorld.equals(feetBlockPos)) {
                     replaceableWorld = null;
                  }

                  if (replaceableWorld != null && this.seedIslandValue >= 0 && this.moduleTick - this.seedIslandValue > 1200) {
                     return this.parkIslandAndCheckExit(
                        "FACED_TIMEOUT owner "
                           + fromLong.toShortString()
                           + " - its stand was never reached in "
                           + (this.moduleTick - this.seedIslandValue)
                           + " ticks"
                     );
                  } else if (replaceableWorld != null) {
                     this.currentTargetPos = fromLong;
                     this.supportAccessValue = n;
                     this.blockHitResultEgressStand = null;
                     this.sideRunValue = 0;
                     this.blockPos2LayerAccess = replaceableWorld;
                     this.standRouteCount = 0;
                     this.discoveryConcreteFlag = false;
                     this.solverUnavailableDirection = null;
                     this.blockHitResult = null;
                     this.resetCameraPredictionTimes();
                     this.updatePlacementRecipeForTarget(fromLong, blockState);
                     if (this.seedIslandValue < 0) {
                        this.seedIslandValue = this.moduleTick;
                     }

                     this.reachableBuildFlag = true;
                     this.setSupportText("BUILD_REACHABLE", "island seed owner " + fromLong.toShortString() + " - walk to its stand");
                     this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "island seed owner - walk to stand");
                     return true;
                  } else {
                     if (this.moduleTick - this.seedIslandValue > 400) {
                        this.onIslandAborted("faced but no stand for it (held " + (this.moduleTick - this.seedIslandValue) + " ticks)");
                     }

                     return false;
                  }
               }
            } else {
               this.onIslandAborted("owner no longer ours");
               return false;
            }
         } else {
            long l = BlockPos.asLong((int)ls[0], (int)ls[1], (int)ls[2]);
            if (l != this.longIslandExit) {
               this.islandHandoverMap.remove(this.islandAbort);
            } else if (this.isIslandHandoverRecent(this.islandAbort)) {
               if (this.islandHandoverMap.getOrDefault(this.islandAbort, 0) >= 4) {
                  this.onIslandAborted(
                     "step " + BlockPos.fromLong(l).toShortString() + " did not stick " + this.islandHandoverMap.get(this.islandAbort) + " times"
                  );
               }

               return false;
            }

            return this.trySetupIslandSupport(fromLong, ls, 8, this.getAnchoredResult(fromLong).size(), solid, blocked);
         }
      }
   }

