   private boolean hasRecoveryWorkBeforePause() {
      if (this.startLastMileRetry()) {
         return true;
      } else if (this.layerPlanFlag) {
         this.layerPlanFlag = false;
         this.layerAccessCooldownUntilTick = this.moduleTick + 7200;
         this.logDebugMessage("\u00a7e[LayerPlan]\u00a7r walking layer re-deferred: the released hanging cells have no way down - back to the work above");
         return true;
      } else if (this.tryStartHangingLayerRecovery()) {
         return true;
      } else if (this.canClimbOutOfSmallComponent()) {
         this.logDebugMessage(
            "\u00a7e[Recover]\u00a7r action=PERCH_DESCENT - a " + this.component.size() + "-cell perch is not the build: back down own tower before any pause"
         );
         return true;
      } else if (this.tryPerchDropRecovery(this.getFeetBlockPos())) {
         return true;
      } else if (this.startStrandedClimb()) {
         return true;
      } else if (this.tryPocketClimb()) {
         return true;
      } else if (this.islandAbort == 0L
         && this.useTemporaryBlocks.isEnabled()
         && this.getHotbarDirtSlot() != -1
         && mc.player != null
         && this.canBlockChangeAt(this.getFeetBlockPos(), Integer.MAX_VALUE, true)) {
         return true;
      } else if (this.islandAbort == 0L
         && this.useTemporaryBlocks.isEnabled()
         && this.getHotbarDirtSlot() != -1
         && mc.player != null
         && this.isBlockPlacementPossible(this.getFeetBlockPos())) {
         return true;
      } else {
         for (long l : new ArrayList<>(this.completionMissionMap.keySet())) {
            BlockPos blockPos = BlockPos.fromLong(l);
            if ((!this.isMachineArmedAt(blockPos) || this.held <= 0) && this.canFacelessSeed(blockPos)) {
               return true;
            }
         }

         return this.facelessSeedValue == this.moduleTick;
      }
   }

   private void confirmPurchaseReceived() {
      int n = this.countItemInInventory(this.affordablePagesItem) - this.receivedDeliveryValue;
      if (n <= 0) {
         this.onListingMissed("no items received");
      } else {
         if (this.state2Builder == AutoBuilder.State.BUY_CONFIRM || this.state2Builder == AutoBuilder.State.BUY_VERIFY) {
            this.captureBuyQueueSnapshot();
         }

         this.affordablePagesFlag = true;
         this.receivedCompleteShowedCount++;
         this.receivedCount += n;
         this.buyAutoPurchasedCount += n;
         this.buyShowedTotalCount += n;
         this.buyShowedValue = this.buyShowedValue + (n + this.affordablePagesItem.getMaxCount() - 1) / Math.max(1, this.affordablePagesItem.getMaxCount());
         if (n >= 16) {
            this.buyShowedCount++;
         } else {
            this.buyShowedEventCount++;
         }

         boolean flag = buildfinishedTime >= 0L
            && buildfinishedValue == n
            && KmbtSellerUtils.canFlag(buildfinishedText, new ItemStack(this.affordablePagesItem).getName().getString());
         long l = flag ? buildfinishedTime : this.showedListingTime;
         resetBuildFinishedStats();
         this.buyAutoTime += l;
         this.jsonArrayMemory.canDayConcurrent(this.affordablePagesItem, LimitBuyerUtils.getTime(l, n), getCurrentEpochDay());
         ModuleConfigAutosave.updateFlag2();
         this.freeInventoryMap.remove(this.affordablePagesItem);
         this.buyShowedIntegerMap.remove(this.affordablePagesItem);
         this.spaceFreeMap.remove(this.affordablePagesItem);
         this.buyAutoMap.remove(this.affordablePagesItem);
         this.missBoardValue = 0;
         this.boardSnipesValue = 0;
         this.snipesFreshValue = 0;
         this.purchaseMinutesValue = this.moduleTick;
         this.buyQuantity = this.getMissingItemCount(this.affordablePagesItem);
         this.costBuyMap.put(this.affordablePagesItem, this.buyQuantity);
         if (this.buyNotifications.isEnabled()) {
            this.sendPlayerChatMessage(
               "\u00a7a[AutoBuy]\u00a7r bought \u00a7f"
                  + n
                  + "\u00d7\u00a7r "
                  + getItemIdPath(this.affordablePagesItem)
                  + " for "
                  + BuyerAppendUtils.formatText(l)
                  + " \u00a77("
                  + this.buyQuantity
                  + " left)"
            );
         }

         long showedListingTime2 = this.showedListingTime;
         this.optional = null;
         if (flag && LimitBuyerUtils.canFlag(l, showedListingTime2)) {
            this.sendPlayerChatMessage(
               "\u00a7c[AutoBuy]\u00a7r charged "
                  + BuyerAppendUtils.formatText(l)
                  + " for a listing read as "
                  + BuyerAppendUtils.formatText(showedListingTime2)
                  + " - buying stopped (check 'Price Is Per' and 'Price Keyword', then press Buy)"
            );
            if (this.listingShowedFlag) {
               this.showedBuyText = "a purchase cost more than its listing showed";
            }

            this.finishBuyAndReportCost("charged more than the listing showed");
         } else if (this.maxTotalSpend.getValue() > 0 && this.buyAutoTime >= this.maxTotalSpend.getValue()) {
            this.finishBuyAndReportCost("spend cap reached");
         } else if (this.buyQuantity <= 0) {
            this.advanceToNextBuyItem();
         } else if (this.isAuctionScreenOpen()) {
            this.buyAutoSyncId = mc.player.currentScreenHandler.syncId;
            this.listingVanishedSet.clear();
            this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SCAN, "buy more " + getItemIdPath(this.affordablePagesItem) + " (same board)");
         } else {
            this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SEARCH, "buy more " + getItemIdPath(this.affordablePagesItem));
         }
      }
   }

   private String describeObserverPulseHazard(BlockPos pos) {
      if (pos != null && mc.world != null) {
         for (Direction direction : Direction.values()) {
            BlockPos blockPos = pos.offset(direction);
            BlockState blockState = mc.world.getBlockState(blockPos);
            if (blockState.getBlock() instanceof ObserverBlock && blockState.get(Properties.FACING) == direction.getOpposite()) {
               BlockPos blockOffsetPos = blockPos.offset(direction);
               if (isRedstoneRelatedBlock(mc.world.getBlockState(blockOffsetPos)) && !this.isDispenserSafeToPlace(blockOffsetPos, mc.world.getBlockState(blockOffsetPos))
                  )
                {
                  return "observer " + blockPos.toShortString() + " would pulse into " + blockOffsetPos.toShortString();
               }

               if (mc.world.getBlockState(blockOffsetPos.down()).getBlock() instanceof PistonBlock) {
                  return "observer "
                     + blockPos.toShortString()
                     + " would pulse into "
                     + blockOffsetPos.toShortString()
                     + " above the piston "
                     + blockOffsetPos.down().toShortString()
                     + " (quasi-connectivity)";
               }
            }
         }

         return null;
      } else {
         return null;
      }
   }

