   private void markSupersededByNewMission() {
      long l = this.unknown == null ? 0L : this.unknown.getReusableDescentTime();
      long l2 = this.unknown != null && this.unknown.getNext() != 0L ? this.unknown.getNext() : (this.currentTargetPos == null ? 0L : this.currentTargetPos.asLong());
      com.corz.client.utils.DescentReusable.Kind kind = this.unknown == null ? this.getTempStructureKindForState() : this.unknown.getDescentStairType();
      if (l2 != 0L) {
         if (this.supersededByNewMission) {
            if (this.supersededMissionTime == l && this.supersededUnknownValue == l2) {
               return;
            }

            this.resolveAccessMission(false, "superseded_by_new_mission");
         }

         this.supersededByNewMission = true;
         this.declaredProgressValue = this.moduleTick;
         this.supersededMissionTime = l;
         this.supersededUnknownValue = l2;
         this.descentStairType = kind;
         this.supersededUnknownLinkedHashS.clear();
         this.supersededUnknownLinkedHashS.add(l2);
         if (kind == com.corz.client.utils.DescentReusable.Kind.PLATFORM && this.mission == l) {
            this.supersededUnknownLinkedHashS.addAll(this.linkedHashSet);
         }
      }
   }

