   private static double getAxisDominance(Vec3d vec, Axis axis) {
      double d = Math.abs(vec.x);
      double abs2 = Math.abs(vec.y);
      double abs3 = Math.abs(vec.z);

      return switch (axis) {
         case X -> d - Math.max(abs2, abs3);
         case Y -> abs2 - Math.max(d, abs3);
         case Z -> abs3 - Math.max(d, abs2);
      };
   }

   private com.corz.client.utils.BottleLevelUtils.Result computeBlockStateMismatch(BlockPos pos, BlockState state) {
      Set<String> copyOf = null;
      if (matchesBlockStateRule(state)) {
         copyOf = Set.copyOf(SouthNorthUtilsFormat.ATTACHED_EAST_ITEMS);
      } else if (state.getBlock() instanceof AbstractSignBlock) {
         copyOf = Set.of("waterlogged", "attached");
      } else if (state.getBlock() instanceof FenceGateBlock) {
         BooleanProperty booleanProperty = Properties.POWERED;
         BlockState blockState = mc.world == null ? null : mc.world.getBlockState(pos);
         if (blockState != null && blockState.isOf(state.getBlock()) && (!blockState.contains(booleanProperty) || !blockState.get(booleanProperty))) {
            copyOf = Set.of("open");
         }
      } else if (state.getBlock() instanceof LeverBlock) {
         copyOf = Set.of("powered");
      }

      if (this.powered.isEnabled()
         && state.getBlock() instanceof Waterloggable
         && state.contains(Properties.WATERLOGGED)
         && !this.waterloggedExhaustedSet.contains(pos.asLong())) {
         if (copyOf == null) {
            copyOf = Set.of("waterlogged");
         } else if (!copyOf.contains("waterlogged")) {
            HashSet<String> hashSet = new HashSet<>(copyOf);
            hashSet.add("waterlogged");
            copyOf = hashSet;
         }
      }

      Set<String> set = null;
      BlockState blockState3 = mc.world.getBlockState(pos);
      if (state.getBlock() instanceof StairsBlock && blockState3.isOf(state.getBlock()) && !this.areNeighborStairsOrientedCorrectly(pos)) {
         set = Set.of("shape");
      }

      if (state.getBlock() instanceof AbstractRailBlock abstractRailBlock && blockState3.isOf(state.getBlock())) {
         Property<RailShape> property = abstractRailBlock.getShapeProperty();
         if (state.contains(property)
            && blockState3.contains(property)
            && SouthNorthUtilsFormat.canFlag(state.get(property).asString(), blockState3.get(property).asString(), this.hasNoMissingRailsNearby(pos))) {
            set = Set.of("shape");
         }
      }

      return BottleLevelUtils.getThicknessLeaves(getBlockStatePropertyMap(state), getBlockStatePropertyMap(blockState3), set, copyOf);
   }

