   private boolean tickJumpLoopGuard() {
      if (!this.repeatedlyRoutingActive) {
         return false;
      } else {
         this.repeatedlyRoutingActive = false;
         BlockPos blockPos = this.getFeetBlockPos();
         if (blockPos.asLong() != this.longRepeatedlyRouting) {
            this.longRepeatedlyRouting = blockPos.asLong();
            this.repeatedlyRoutingValue = 0;
         }

         boolean flag = this.transition == Kind.STEP_UP || this.transition == Kind.JUMP_MOUNT || this.transition == Kind.OWNED_DIRT_STEP;
         if (!flag
            || !this.stuckDetection.isEnabled()
            || ++this.repeatedlyRoutingValue < 4
            || this.lethalBesideValue != 0
            || mc.player == null
            || !mc.player.isOnGround()
            || this.path.isEmpty()
            || this.hasNoFloorWithinThreeBelow(blockPos)
            || this.isNeighborCellDangerous(blockPos)
               && (this.indexNodeTransition <= 0 || this.indexNodeTransition >= this.path.size() || blockPos.getY() >= this.path.get(this.indexNodeTransition).getY() || this.lethalEdgeFlag)) {
            this.repeatedlyRoutingCount++;
            this.updatePressedOptions2();
            this.path.clear();
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "jump demand refused repeatedly - routing around this edge");
            return true;
         } else {
            this.repeatedlyRoutingValue = 0;
            this.demandVetoValue = 0;
            this.recordLocalRecoveryStart(
               "jump loop guard starved " + blockPos.toShortString() + " - " + 4 + " reroutes rebuilt the same edge; one certified step instead of a freeze",
               this.transition
            );
            return false;
         }
      }
   }

