   private List<BlockPos> getTemporarySetting(BlockPos pos, int temporarySettingLimit) {
      int schematicCells2 = this.getSchematicCells(pos);
      if (schematicCells2 < 0) {
         return new ArrayList<>();
      } else {
         BlockState blockState = this.targetFluidItems.get(schematicCells2);
         double d = this.reachSetting.getValue();
         Predicate<BlockPos> predicate = blockPos2x -> !this.canSealsDeferred(pos, blockPos2x)
            && this.canPlaceFromEyePosition(pos, blockState, getStandingEyePos(blockPos2x), d, false);
         LinkedHashSet<BlockPos> linkedHashSet = new LinkedHashSet<>(WalkRouteFinder.findStandPositions(pos, d, this.cellTemporarySet, predicate, temporarySettingLimit));
         if (linkedHashSet.size() < temporarySettingLimit) {
            for (BlockPos blockPos : WalkRouteFinder.findStandPositions(pos, d, null, predicate, temporarySettingLimit)) {
               linkedHashSet.add(blockPos);
               if (linkedHashSet.size() >= temporarySettingLimit) {
                  break;
               }
            }
         }

         return new ArrayList<>(linkedHashSet);
      }
   }

