   private SneakBlock getRotationPaired(BlockPos pos, BlockState state) {
      SneakBlock sneakBlock = new SneakBlock(pos, state, getItemForBlockState(state));
      Direction requiredSupportDirection = this.getRequiredSupportDirection(pos, state);
      Float floatValue = this.getPlacementFloatHint(pos, state);
      boolean flag = this.isRelaxedBlockShortCell(pos);
      if (requiredSupportDirection != null) {
         BlockPos blockPos = pos.offset(requiredSupportDirection);
         sneakBlock.getClick(blockPos, requiredSupportDirection.getOpposite());
         BlockState blockState = mc.world == null ? null : mc.world.getBlockState(blockPos);
         if (isPlaceableWithoutSpecialSneak(state)
            && requiredSupportDirection.getAxis() == Axis.Y
            && blockState != null
            && (blockState.isAir() || blockState.isReplaceable())
            && this.getSchematicCells(blockPos) < 0) {
            sneakBlock.getPoseSneak(blockPos);
         }
      }

      if (hasFluidState(state)) {
         sneakBlock.getKind(com.corz.client.utils.SneakBlock.Kind.SOURCE_FLUID);
      } else if (matchesBlockStateRule(state)) {
         sneakBlock.getKind(com.corz.client.utils.SneakBlock.Kind.MULTIFACE);

         for (Direction direction : Direction.values()) {
            if (MultifaceBlock.hasDirection(state, direction)) {
               sneakBlock.getFaces(direction);
            }
         }
      } else if (floatValue != null) {
         int n = state.get(Properties.ROTATION);
         sneakBlock.getKind(com.corz.client.utils.SneakBlock.Kind.SIGN_ROTATION).getRotation(n).getYaw(floatValue);
      } else if (!flag && this.getRotateYcounterclockwise(pos, state) != null) {
         sneakBlock.getKind(com.corz.client.utils.SneakBlock.Kind.PAIRED).getMax(3);
      } else if (flag || !isPlaceableWithoutSpecialSneak(state) && requiredSupportDirection == null) {
         if (!flag && getDirectionForBlockState(state) != null) {
            sneakBlock.getKind(com.corz.client.utils.SneakBlock.Kind.YAW_FACING);
         }
      } else {
         sneakBlock.getKind(com.corz.client.utils.SneakBlock.Kind.CLICK_FACE);
      }

      sneakBlock.getFlag(false);
      return sneakBlock;
   }

