   private boolean canNudgingNudge(BlockPos pos, BlockState state, double nudgingNudgeValue) {
      if (mc.player != null && mc.player.isOnGround()) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         long l = pos.asLong() ^ feetBlockPos.asLong() * -7046029254386353131L;
         if (this.nudgeGroundedTime != l) {
            this.nudgeGroundedTime = l;
            this.nudgingNudgeValue = 0;
         }

         if (this.nudgingNudgeValue >= 30) {
            this.nudgingCentredText = "NUDGE_EXHAUSTED";
            return false;
         } else {
            double d2 = feetBlockPos.getX() + 0.5;
            double d3 = feetBlockPos.getZ() + 0.5;
            double d4 = d2 - mc.player.getX();
            double d5 = d3 - mc.player.getZ();
            double sqrt6 = Math.sqrt(d4 * d4 + d5 * d5);
            if (sqrt6 < 0.07) {
               this.nudgingCentredText = "AT_CENTRE";
               return false;
            } else {
               Vec3d vec3d = getStandingEyePos(feetBlockPos);
               boolean flag = this.getOppositeBlock(pos, state, vec3d, nudgingNudgeValue, false) != null
                  || this.crouchMicroPose.isEnabled()
                     && this.getOppositeBlock(pos, state, vec3d.subtract(0.0, 0.3500000000000001, 0.0), nudgingNudgeValue, true) != null;
               if (!flag) {
                  this.nudgingCentredText = "CENTRED_EYE_REJECTED";
                  return false;
               } else {
                  this.nudgingCentredText = "NUDGING";
                  this.nudgingNudgeValue++;
                  double radians7 = Math.toRadians(mc.player.getYaw());
                  double sin8 = -Math.sin(radians7);
                  double cos9 = Math.cos(radians7);
                  double cos10 = Math.cos(radians7);
                  double sin11 = Math.sin(radians7);
                  double d12 = d4 * sin8 + d5 * cos9;
                  double d13 = d4 * cos10 + d5 * sin11;
                  mc.options.forwardKey.setPressed(d12 > 0.04);
                  mc.options.backKey.setPressed(d12 < -0.04);
                  mc.options.leftKey.setPressed(d13 > 0.04);
                  mc.options.rightKey.setPressed(d13 < -0.04);
                  mc.player.setSprinting(false);
                  this.setOwnerSneak(true);
                  return true;
               }
            }
         }
      } else {
         this.nudgingCentredText = "NOT_GROUNDED";
         return false;
      }
   }

   private boolean canBlockersFluid(BlockPos pos) {
      if (this.blockers != null && !this.isCompletionMissionActiveWithFuture() && !this.isServiceAccessMission(this.blockers) && !this.digMissionFlag && this.targetFluidItems != null) {
         int schematicCells2 = this.getSchematicCells(pos);
         if (schematicCells2 >= 0 && this.targetFluidItems.get(schematicCells2).getBlock() instanceof ObserverBlock) {
            BlockPos offsetPos = pos.offset(this.targetFluidItems.get(schematicCells2).get(Properties.FACING).getOpposite());
            Long longValue = this.placedExactMap.get(offsetPos.asLong());
            if (longValue != null && longValue == pos.asLong() && this.completionMissionMap.containsKey(offsetPos.asLong())) {
               SupportStandUtils.Cell cell = getDataForBlockPos(offsetPos);

               for (int n = Math.max(0, this.stepIndex); n < this.blockers.steps().size(); n++) {
                  SupportStandUtils.Step step = this.blockers.steps().get(n);
                  if (step.op() == SupportStandUtils.Op.PLACE && cell.equals(step.cell())) {
                     return false;
                  }
               }

               return !this.excludedTargets.canFingerprintCells(offsetPos.asLong(), this::getRawBlockStateIdAt) && this.getRedstoneDeferralReason(offsetPos) == null;
            } else {
               return false;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

