   private boolean canBlockAxis(int blockAxisValue, int blockAxisLimit) {
      if (this.useTemporaryBlocks.isEnabled()
         && this.getHotbarDirtSlot() != -1
         && this.schematicCells != null
         && mc.world != null
         && mc.player != null) {
         if (this.isTempBlockDebtAtLimit()) {
            return false;
         } else {
            BlockPos feetBlockPos = this.getFeetBlockPos();
            BlockPos blockPos5 = null;
            double squaredDistance = Double.MAX_VALUE;
            int max = Integer.MAX_VALUE;
            boolean flag = false;

            for (int n2 = 0; n2 < this.schematicCells.size(); n2++) {
               BlockPos blockPos2 = this.schematicCells.get(n2);
               if (blockPos2.getY() < blockAxisLimit && blockPos2.getY() >= blockAxisValue) {
                  BlockState blockState = this.targetFluidItems.get(n2);
                  if (!isPlaceableWithoutSpecialSneak(blockState) && !(blockState.getBlock() instanceof HopperBlock) && !matchesBlockStateRule(blockState) && !hasFluidState(blockState)) {
                     Direction direction = this.getRequiredSupportDirection(blockPos2, blockState);
                     if (direction != null) {
                        BlockPos pos = blockPos2.offset(direction);
                        if (this.getSchematicCells(pos) < 0) {
                           BlockState blockState2 = mc.world.getBlockState(blockPos2);
                           if (blockState2.getBlock() != blockState.getBlock()
                              && (blockState2.isAir() || blockState2.isReplaceable())
                              && mc.world.getBlockState(pos).isAir()
                              && !this.cellTemporarySet.contains(pos.asLong())) {
                              if (blockState.contains(Properties.AXIS) && direction.getAxis() == blockState.get(Properties.AXIS)) {
                                 BlockPos blockPos = blockPos2.offset(direction.getOpposite());
                                 int n = this.getSchematicCells(blockPos);
                                 if (n >= 0 && !this.targetFluidItems.get(n).getCollisionShape(mc.world, blockPos).isEmpty()) {
                                    continue;
                                 }
                              }

                              if (!this.isSupportCellEmptyAir(blockPos2, blockState)
                                 && !this.isCellBlockedByTemporaryNeighbors(blockPos2)
                                 && !this.isMachineArmedAt(blockPos2)
                                 && !this.isPoweredOrCompletionCell(blockPos2.asLong())
                                 && this.canObtainItemForPlacement(getItemForBlockState(blockState))
                                 && !this.excludedTargets.canFingerprintCells(blockPos2.asLong(), this::getRawBlockStateIdAt)) {
                                 if (!flag) {
                                    max = this.layer == Integer.MIN_VALUE ? this.getLowestPendingLayerY() : Math.max(this.getLowestPendingLayerY(), this.layer);
                                    flag = true;
                                 }

                                 if (blockPos2.getY() <= max) {
                                    double d = feetBlockPos.getSquaredDistance(blockPos2);
                                    if (d < squaredDistance) {
                                       squaredDistance = d;
                                       blockPos5 = blockPos2;
                                    }
                                 }
                              }
                           }
                        }
                     }
                  }
               }
            }

            if (blockPos5 == null) {
               return false;
            } else if (!this.canFiniteBlocked(
               "layer "
                  + blockPos5.getY()
                  + ": "
                  + blockPos5.toShortString()
                  + " faces a support outside the schematic - temp and click before the layer above closes it"
            )) {
               return false;
            } else {
               this.longFiniteBlocked = blockPos5.asLong();
               return true;
            }
         }
      } else {
         return false;
      }
   }

   private void updateCycleDispatched() {
      long l = this.cycleDispatchedValue;
      if (this.currentTargetPos != null
         && this.currentTargetPos.asLong() == l
         && (
            this.state2Builder == AutoBuilder.State.GO_TO_POSITION
               || this.state2Builder == AutoBuilder.State.SCAFFOLD_UP
               || this.state2Builder == AutoBuilder.State.TEMP_SUPPORT
               || this.state2Builder == AutoBuilder.State.STATE_REPAIR
         )) {
         if (this.unstableRecenterChangedTimeo == null || !this.unstableRecenterChangedTimeo.isFlag()) {
            this.cycleDispatchedValue = Long.MIN_VALUE;
            if (!this.churnRefunds.canRefundsTime(this.confirms, this.hashCellSet())) {
               BlockPos blockPos = this.currentTargetPos;
               if (l != this.dispatchedCycleTime) {
                  this.logDebugMessage(
                     "\u00a7e[CycleBudget]\u00a7r "
                        + this.dispatchedCycleText
                        + " - aborted: the target is deferred and the planner goes elsewhere ("
                        + this.churnRefunds.formatChurnRefunds()
                        + ")"
                  );
               }

               this.dispatchedCycleTime = l;
               if (this.state2Builder == AutoBuilder.State.TEMP_SUPPORT) {
                  this.onTempSupportFailed("r180 cycle: re-dispatched without progress");
               } else {
                  if (this.islandAbort == l) {
                     this.parkIslandAndCheckExit("r180 cycle: re-dispatched without progress");
                  }

                  this.updatePressedOptions2();
                  this.path.clear();
                  this.resetPillarTracking();
                  this.standClimbFlag = false;
                  this.arrivedSupportFlag = false;
                  if (this.placementExplicit != null && this.placementExplicit.owner == Owner.DECK) {
                     this.dispatchedFailureCount++;
                     this.failExplicitPlacement("EXECUTOR_FAILURE: r180 cycle: re-dispatched without progress");
                  }

                  if (this.reason != null && this.reason.isPinnedDispatched() && this.reason.getUnassignedMembersUnassignedMembersData() == l) {
                     this.onRouteRedirectInvalidated("deferred: r180 cycle: re-dispatched without progress");
                  }

                  if (this.blockPos != null && this.blockPos.equals(blockPos)) {
                     this.recordRepairFailure(blockPos, "r180 cycle: re-dispatched without progress");
                     this.blockPos = null;
                     this.repairBreakFlag = false;
                  }

                  if (this.blockMultifaceBlockPos != null && this.blockMultifaceBlockPos.equals(blockPos)) {
                     this.blockMultifaceBlockPos = null;
                     this.blockDeferBlockPos = null;
                  }

                  if (this.superseded != null && this.superseded.isContains(l)) {
                     this.sessionResetTimeUpdate.resetPrimaryCount();
                  }

                  this.setBudgetExhaustedReason("defer: r180 cycle: re-dispatched without progress");
                  this.releaseUnknownOwnerForTarget("access failed: r180 cycle: re-dispatched without progress");
                  this.setCellCooldown(l, Math.max(this.cooldown.getOrDefault(l, 0), this.churnRefunds.getMax(l)));
                  if (this.blockPos3BridgeCell != null) {
                     this.recordBannedStandPair(getTimeForBlockPos(blockPos, this.blockPos3BridgeCell), this.moduleTick + 140);
                  }

                  this.transitionToState(AutoBuilder.State.SELECT_TARGET, "r180 cycle: re-dispatched without progress");
               }
            }
         }
      } else {
         this.cycleDispatchedValue = Long.MIN_VALUE;
      }
   }

