   private boolean canConstrainedStrand(BlockPos pos) {
      if (pos == null) {
         return false;
      } else if (this.holdForRedstoneSafety(pos)) {
         return true;
      } else if (this.tryReclaimTempBeforeSealing(pos)) {
         return true;
      } else if (!this.isCandidateScopeAllowed(pos)) {
         this.deferTargetBriefly(pos, "access recovery in progress in this component");
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "access recovery obligation outstanding");
         return true;
      } else if (!this.accessAwareOrder.isEnabled()) {
         return false;
      } else {
         this.refreshTargetStandCandidates(this.reachSetting.getValue());
         BlockPos coupledTargetNear = this.findCoupledTargetNear(pos);
         if (coupledTargetNear == null) {
            return false;
         } else {
            Integer integer = this.constrainedStrandMap.get(coupledTargetNear.asLong());
            Long longValue = this.precommitHeld.get(coupledTargetNear.asLong());
            boolean flag2 = longValue != null && longValue == pos.asLong() && integer != null && this.moduleTick - integer <= 240;
            boolean equals = pos.equals(this.findCoupledTargetNear(coupledTargetNear));
            if (flag2 || equals) {
               int n = this.getTargets(coupledTargetNear, pos);
               int targets2 = this.getTargets(pos, coupledTargetNear);
               CycleChoice cycleChoice = FlagVictimUtils.getPlaceVictimChoice(true, n, targets2);
               String constrainedStrandText = "victimIfCandidate=" + n + " candidateIfVictim=" + targets2;
               if (cycleChoice == CycleChoice.DEADLOCKED_NEEDS_ESCAPE) {
                  long l = pos.asLong() ^ coupledTargetNear.asLong() * 31L;
                  Integer moduleTick = this.constrainedStrandIntegerMap.get(l);
                  if (moduleTick == null) {
                     this.constrainedStrandIntegerMap.put(l, this.moduleTick);
                     moduleTick = this.moduleTick;
                  }

                  if (this.moduleTick - moduleTick > 300) {
                     this.constrainedStrandIntegerMap.remove(l);
                     this.precommitHeld.remove(pos.asLong());
                     this.precommitHeld.remove(coupledTargetNear.asLong());
                     this.constrainedStrandMap.remove(pos.asLong());
                     this.constrainedStrandMap.remove(coupledTargetNear.asLong());
                     return false;
                  }
               } else {
                  boolean flag = cycleChoice == CycleChoice.PLACE_CANDIDATE;
                  if (flag) {
                     this.precommitHeld.remove(pos.asLong());
                     this.precommitHeld.remove(coupledTargetNear.asLong());
                     this.constrainedStrandMap.remove(pos.asLong());
                     this.constrainedStrandMap.remove(coupledTargetNear.asLong());
                     return false;
                  }
               }
            }

            this.precommitHeld.put(pos.asLong(), coupledTargetNear.asLong());
            this.constrainedStrandMap.put(pos.asLong(), this.moduleTick);
            if (this.isCurrentTransferTarget(pos.asLong())) {
               this.handleActionableContinuation("would_strand_constrained");
            }

            this.resetCameraPredictionTimes();
            this.deferTargetBriefly(pos, "precommit: would strand a constrained target's last pose");
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "pre-commit access guard held this block");
            return true;
         }
      }
   }

