   private boolean isReplaceableCellEnclosedByFullCubes(BlockPos pos) {
      if (mc.world == null) {
         return false;
      } else {
         BlockState blockState2 = mc.world.getBlockState(pos);
         if (!blockState2.isAir() && !blockState2.isReplaceable()) {
            return false;
         } else {
            for (Direction direction : Direction.values()) {
               if (direction != Direction.DOWN) {
                  BlockPos blockPos = pos.offset(direction);
                  BlockState blockState = mc.world.getBlockState(blockPos);
                  if (blockState.isAir() || blockState.isReplaceable() || !blockState.isFullCube(mc.world, blockPos)) {
                     return false;
                  }
               }
            }

            BlockPos down = pos.down();
            BlockState blockState3 = mc.world.getBlockState(down);
            return !blockState3.isAir() && !blockState3.isReplaceable()
               ? blockState3.isFullCube(mc.world, down)
               : this.isFullCubeFloorUnderReach(pos);
         }
      }
   }

