   private void handlePressedOptions(double pressedOptionsValue, double pressedOptionsValue2, boolean pressedOptionsFlag) {
      double d3 = pressedOptionsValue - mc.player.getX();
      double d4 = pressedOptionsValue2 - mc.player.getZ();
      double max5 = Math.max(0.001, Math.hypot(d3, d4));
      double radians6 = Math.toRadians(mc.player.getYaw());
      double d7 = (-Math.sin(radians6) * d3 + Math.cos(radians6) * d4) / max5;
      double d8 = (-Math.cos(radians6) * d3 - Math.sin(radians6) * d4) / max5;
      mc.options.forwardKey.setPressed(d7 > 0.3);
      mc.options.backKey.setPressed(d7 < -0.3);
      mc.options.rightKey.setPressed(d8 > 0.3);
      mc.options.leftKey.setPressed(d8 < -0.3);
      mc.player.setSprinting(pressedOptionsFlag && d7 > 0.9 && max5 > 1.5 && !this.isOnNonSlipperyGround());
   }

