   private boolean canCatwalkWalk(BlockPos longValue, BlockPos pos, boolean catwalkWalkFlag) {
      if (this.useTemporaryBlocks.isEnabled()
         && mc.player != null
         && !this.hasActiveBlockersStep()
         && !this.deckMicroMoves.isProbingExitingConfirmed()
         && this.isOpenCompletionCellAboveBase(longValue)) {
         this.catwalkWalkFlag = false;
         int[] ns = this.catwalkWalkIntArrayMap.get(longValue.asLong());
         if (this.countGapCellsInRow(pos.down(), longValue) >= 0 && (ns == null || ns[1] < 4 || !this.isWalkAttemptBackedOff(longValue.asLong()))) {
            this.currentTargetPos = longValue;
            this.supportAccessValue = this.getSchematicCells(longValue);
            this.bridgeTimeoutSet.clear();
            Direction direction = Direction.getFacing((float)(longValue.getX() - pos.getX()), 0.0F, (float)(longValue.getZ() - pos.getZ()));

            for (int n = 1; n <= 4; n++) {
               BlockPos blockPos = pos.down().offset(direction, n);
               if (this.cellTemporarySet.contains(blockPos.asLong()) && !this.isPlainFullCubeMissionBlock(blockPos)) {
                  this.bridgeTimeoutSet.add(blockPos.asLong());
               }

               if (blockPos.equals(longValue)) {
                  break;
               }
            }

            if (this.startSchematicBridge(pos)) {
               this.recordConfirmVisit(longValue.asLong());
               this.logDebugMessage("\u00a7b[Catwalk]\u00a7r paving " + longValue.toShortString() + " edge to edge from the structure at " + pos.toShortString());
               return true;
            } else {
               this.bridgeTimeoutSet.clear();
               return false;
            }
         } else if (this.isWalkAttemptBackedOff(longValue.asLong())) {
            return false;
         } else {
            List<BlockPos> sortedHorizontalCandidates = this.getSortedHorizontalCandidates(longValue, pos);
            if (sortedHorizontalCandidates.isEmpty()) {
               return false;
            } else {
               int n2 = 0;

               for (BlockPos sortedHorizontalCandidatesItem : sortedHorizontalCandidates) {
                  BlockPos destinationPos = sortedHorizontalCandidatesItem.up();
                  if (!destinationPos.equals(pos)) {
                     if (++n2 <= 4) {
                        List<BlockPos> list = this.getCachedPath(pos, destinationPos);
                        if (list != null && !list.isEmpty() && !this.hasHeadroomCell(list) && isPathHeightContinuous(pos, list)) {
                           this.currentTargetPos = longValue;
                           this.supportAccessValue = this.getSchematicCells(longValue);
                           this.standClimbFlag = false;
                           this.arrivedSupportFlag = false;
                           if (this.tryFollowMovementRoute(list, destinationPos, this.createMovementMission(Purpose.MISSION_STAND_MOVE, destinationPos, null))) {
                              this.recordConfirmVisit(longValue.asLong());
                              this.logDebugMessage(
                                 "\u00a7b[Catwalk]\u00a7r walking onto the structure at "
                                    + destinationPos.toShortString()
                                    + " to pave "
                                    + longValue.toShortString()
                                    + " edge to edge"
                              );
                              this.setSupportText("CATWALK", "walk onto the 1-wide structure");
                              this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "catwalk: walk onto the spine");
                              this.layerAccessBlockPos = longValue;
                              return true;
                           }
                        }
                     }
                  }
               }

               if (catwalkWalkFlag && !this.catwalkWalkFlag) {
                  this.currentTargetPos = longValue;
                  this.supportAccessValue = this.getSchematicCells(longValue);
                  return this.tryStartCatwalkTower(sortedHorizontalCandidates.get(0).up(), pos, longValue);
               } else {
                  return false;
               }
            }
         }
      } else {
         return false;
      }
   }

