   private boolean canSealsDeferred(BlockPos pos, BlockPos pos2) {
      if (this.isStandCoveredByContainedCells(pos, pos2)) {
         return true;
      } else {
         if (!this.egressDeferredMap.isEmpty()) {
            Long longValue = this.egressDeferredMap.get(getTimeForBlockPos(pos, pos2));
            if (longValue != null) {
               long l = SHARED_HASH_OPEN.hashOpenCellsInRadius(pos2.getX(), pos2.getY(), pos2.getZ(), 24);
               if (longValue == l) {
                  return true;
               }

               if (mc.world != null && WalkRouteFinder.isStandable(mc.world, pos2) && this.canPlaceFromStandWithoutSealing(pos, pos2)) {
                  this.egressDeferredMap.replace(getTimeForBlockPos(pos, pos2), l);
                  return true;
               }

               this.egressDeferredMap.remove(getTimeForBlockPos(pos, pos2));
               this.sealsPlacementCount++;
            }
         }

         Integer integer = this.bannedStandPairs.get(getTimeForBlockPos(pos, pos2));
         if (integer == null) {
            return false;
         } else if (this.moduleTick >= integer) {
            this.bannedStandPairs.remove(getTimeForBlockPos(pos, pos2));
            this.sealsPlacementCount++;
            return false;
         } else {
            return true;
         }
      }
   }

