   private boolean canConnectorSupport(BlockPos longValue, BlockPos pos, BlockState state) {
      if (this.useTemporaryBlocks.isEnabled() && this.getHotbarDirtSlot() != -1) {
         Direction direction = getFacingForOrientedState(state);
         if (direction != null && direction.getAxis() == Axis.Y) {
            com.corz.client.utils.SolidColumnUtils.Step step = this.getSolidColumnStep(longValue, state);
            return step != null ? this.startVerticalFacingContextSupport(longValue, state, step, "vertical six-way support absent during align") : false;
         } else if (!(state.getBlock() instanceof DispenserBlock)) {
            return false;
         } else if (this.getSchematicCells(pos) >= 0) {
            return false;
         } else {
            BlockState blockState2 = mc.world.getBlockState(pos);
            if (!blockState2.isAir() && !blockState2.isReplaceable()) {
               return false;
            } else {
               long[] ls;
               if (this.hasSolidNeighborToPlaceOn(pos)) {
                  ls = new long[]{pos.getX(), pos.getY(), pos.getZ()};
               } else {
                  ls = SolidBlockedUtils.getTimes(
                     pos.getX(),
                     pos.getY(),
                     pos.getZ(),
                     6,
                     this::isSolidNonReplaceableAt,
                     (x, y, z) -> this.getSchematicCells(new BlockPos(x, y, z)) >= 0
                  );
                  if (ls == null) {
                     return false;
                  }
               }

               BlockPos blockPos3 = new BlockPos((int)ls[0], (int)ls[1], (int)ls[2]);
               if (this.getSchematicCells(blockPos3) >= 0) {
                  return false;
               } else {
                  this.blockPos3SupportConstructive = blockPos3;
                  this.blockPos2SupportConstructive = longValue;
                  this.supportFloorValue = 0;
                  this.name = "FLOATING_CONNECTOR";
                  this.setSupportText("TEMP_SUPPORT", "dispenser facing connector for " + longValue.toShortString());
                  this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.SUPPORT, 1);
                  this.transitionToState(AutoBuilder.State.TEMP_SUPPORT, "dispenser facing connector");
                  return true;
               }
            }
         }
      } else {
         return false;
      }
   }

