   private boolean canDroppedPlaced(BlockPos pos, Vec3d vec, double droppedPlacedValue) {
      if (this.droppedPlaced == null) {
         return false;
      } else if (!this.droppedPlaced.canStand(pos.asLong())) {
         this.abortDroppedAdjustRun(Abort.STAND_CHANGED);
         return false;
      } else if (!this.remaining.containsCell(pos.asLong())) {
         this.abortDroppedAdjustRun(Abort.SAFETY);
         return false;
      } else {
         while (!this.droppedPlaced.isEmpty()) {
            Member member = this.droppedPlaced.getPoll();
            BlockPos blockPos = BlockPos.fromLong(member.cell());
            int n = this.getSchematicCells(blockPos);
            if (n >= 0 && mc.world.getBlockState(blockPos).getBlock() != this.targetFluidItems.get(n).getBlock()) {
               if (!this.canObtainItemForPlacement(getItemForBlockState(this.targetFluidItems.get(n)))) {
                  this.droppedPlaced.handleRemaining(member);
                  this.abortDroppedAdjustRun(Abort.MATERIAL_CHANGED);
                  return false;
               }

               int n2 = blockPos.getX() - pos.getX();
               int n3 = blockPos.getZ() - pos.getZ();
               FloorBuildPlanner.Pick pick = new FloorBuildPlanner.Pick(
                  member.cell(),
                  pos.asLong(),
                  Math.abs(n2) + Math.abs(n3) == 1 ? FloorBuildPlanner.Pose.EDGE : FloorBuildPlanner.Pose.DIAGONAL,
                  0,
                  n2,
                  n3
               );
               AutoBuilder.MissionPlacement missionPlacement = this.planEdgePlacement(pick, pos, vec, droppedPlacedValue, true);
               this.preparedDeck = null;
               if (missionPlacement != null) {
                  this.deckMicroMoves.arraylistSize = this.droppedPlaced.getRemaining() + 1;
                  this.adjustEdge.recordCurrentRun(this.droppedPlaced);
                  this.noneFrontierValue = 0;
                  this.orElse = 0;
                  this.deckFrontierText = "none";
                  this.distinctCountDroppedPlaced = Math.max(1, this.distinctCountDroppedPlaced);
                  return this.tryExecuteMissionPick(pick, missionPlacement, pos);
               }

               this.adjustEdge.runMembersDroppedCount++;
            }
         }

         this.abortDroppedAdjustRun(Abort.EXHAUSTED);
         return false;
      }
   }

