   private boolean hasMissingSchematicBlockNear(BlockPos pos, int blockSchematicLimit, boolean blockSchematicFlag) {
      int n = 0;

      while (true) {
         if (n >= this.schematicCells.size()) {
            return false;
         }

         BlockPos blockPos = this.schematicCells.get(n);
         if (Math.abs(blockPos.getX() - pos.getX()) <= blockSchematicLimit
            && Math.abs(blockPos.getY() - pos.getY()) <= blockSchematicLimit
            && Math.abs(blockPos.getZ() - pos.getZ()) <= blockSchematicLimit) {
            BlockState blockState = mc.world.getBlockState(blockPos);
            if (blockState.getBlock() != this.targetFluidItems.get(n).getBlock()
               && (blockState.isAir() || blockState.isReplaceable())
               && !this.isExcludedByMachineOrFloor(blockPos)) {
               if (!blockSchematicFlag) {
                  break;
               }

               Integer integer = this.cooldown.get(blockPos.asLong());
               if (integer == null || this.moduleTick >= integer) {
                  break;
               }
            }
         }

         n++;
      }

      return true;
   }

   private void floodFillTemporaryCells(BlockPos pos) {
      this.offsetTemporaryPositionSet.clear();
      ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
      arrayDeque.add(pos);
      this.offsetTemporaryPositionSet.add(pos.asLong());

      while (!arrayDeque.isEmpty() && this.offsetTemporaryPositionSet.size() <= 20000) {
         BlockPos poll2 = arrayDeque.poll();

         for (Direction direction : Direction.values()) {
            BlockPos blockPos = poll2.offset(direction);
            long l = blockPos.asLong();
            if (this.cellTemporarySet.contains(l) && this.offsetTemporaryPositionSet.add(l)) {
               arrayDeque.add(blockPos);
            }
         }
      }
   }

