   private BlockPos findTemporaryBlockToRemove(long autoBuilderValue) {
      if (this.removeTempAfter.isEnabled() && !this.sessionLinkedHashSet.isEmpty()) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         ArrayList<BlockPos> arrayList = new ArrayList<>();

         for (long l2 : this.cells) {
            long l = this.enableModuleMap.getOrDefault(l2, 0L);
            if (this.sessionLinkedHashSet.contains(l) && (autoBuilderValue == 0L || l == autoBuilderValue)) {
               BlockPos blockPos = BlockPos.fromLong(l2);
               if (!mc.world.getBlockState(blockPos).isAir()
                  && !this.isCellCoveredOrBlocked(l2)
                  && !this.isMissionOwnedCell(l2)
                  && !this.isNearIslandAbortColumn(l2)
                  && !this.cells.contains(blockPos.up().asLong())
                  && !blockPos.equals(feetBlockPos.down())
                  && !blockPos.equals(feetBlockPos)
                  && !blockPos.equals(feetBlockPos.up())) {
                  arrayList.add(blockPos);
               }
            }
         }

         arrayList.sort(Comparator.comparingDouble(blockPos2x -> blockPos2x.getSquaredDistance(feetBlockPos)));
         int n = 0;
         int n2 = RecoverReadmitUtils.getValue(this.digMissionFlag, arrayList.size());
         long nanoTime4 = System.nanoTime();

         for (BlockPos arrayItem : arrayList) {
            if (mc.player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(arrayItem)) <= this.reachSetting.getValue() * this.reachSetting.getValue()
               && this.isWithinReachFromEye(arrayItem)) {
               return arrayItem;
            }

            n++;
            if (n > n2 || !this.digMissionFlag && System.nanoTime() - nanoTime4 > 8000000L) {
               break;
            }

            if (this.hasReachableStandForTarget(arrayItem, feetBlockPos)) {
               return arrayItem;
            }
         }

         return null;
      } else {
         return null;
      }
   }

