   private boolean canWalkOrDropToTarget(BlockPos pos, BlockPos pos2) {
      HashSet<Long> hashSet = new HashSet<>();

      for (BlockPos blockPos : new BlockPos[]{pos2, pos2.up()}) {
         hashSet.add(blockPos.asLong());

         for (Direction direction : Type.HORIZONTAL) {
            hashSet.add(blockPos.offset(direction).asLong());
         }

         hashSet.add(blockPos.up().asLong());
      }

      HashMap<Long, Integer> hashMap = new HashMap<>();
      ArrayDeque<long[]> arrayDeque = new ArrayDeque<>();
      hashMap.put(pos.asLong(), 4);
      arrayDeque.add(new long[]{pos.asLong(), 4L});
      int n2 = 0;

      while (!arrayDeque.isEmpty() && n2++ < 400 && hashMap.size() < 256) {
         long[] ls = arrayDeque.poll();
         BlockPos fromLong = BlockPos.fromLong(ls[0]);
         if (hashSet.contains(fromLong.asLong())) {
            return true;
         }

         BlockPos down = fromLong.down();
         if (this.isReplaceable(down)) {
            Integer integer = hashMap.get(down.asLong());
            if (integer == null || integer < 4) {
               hashMap.put(down.asLong(), 4);
               arrayDeque.add(new long[]{down.asLong(), 4L});
            }
         } else {
            int n = (int)ls[1];
            if (n > 0) {
               for (Direction direction2 : Type.HORIZONTAL) {
                  BlockPos fromLongOffset = fromLong.offset(direction2);
                  if (this.isReplaceable(fromLongOffset)) {
                     Integer integer2 = hashMap.get(fromLongOffset.asLong());
                     if (integer2 == null || integer2 < n - 1) {
                        hashMap.put(fromLongOffset.asLong(), n - 1);
                        arrayDeque.add(new long[]{fromLongOffset.asLong(), n - 1});
                     }
                  }
               }
            }
         }
      }

      return false;
   }

   private boolean isChestPartnerSettled(BlockPos pos, BlockState state) {
      if (this.isCompletionPhaseActive() && state != null) {
         BlockPos rotateYcounterclockwise = this.getRotateYcounterclockwise(pos, state);
         if (rotateYcounterclockwise == null) {
            return false;
         } else if (this.isChestPartnerMissing(pos, state)) {
            return true;
         } else {
            Direction direction = this.getPlacementFacing(pos, state);
            BlockState blockState2 = mc.world.getBlockState(rotateYcounterclockwise);
            if (direction != null
               && blockState2.getBlock() == state.getBlock()
               && blockState2.contains(Properties.HORIZONTAL_FACING)
               && blockState2.get(Properties.HORIZONTAL_FACING) != direction.getOpposite()) {
               return true;
            } else {
               if (this.blockers != null) {
                  SupportStandUtils.Cell cell = getDataForBlockPos(rotateYcounterclockwise);

                  for (SupportStandUtils.Step step : this.blockers.steps()) {
                     if ((step.op() == SupportStandUtils.Op.PLACE || step.op() == SupportStandUtils.Op.BREAK) && step.cell().equals(cell)) {
                        return true;
                     }
                  }
               }

               return false;
            }
         }
      } else {
         return false;
      }
   }

