   private boolean confirmTemporaryDirtPlacement(BlockPos pos) {
      Integer integer = this.worthFewerMap.remove(pos.asLong());
      if (integer == null || this.moduleTick - integer > 40) {
         return false;
      } else if (mc.world.getBlockState(pos).getBlock() != Blocks.DIRT) {
         return false;
      } else if (this.getSchematicCells(pos) >= 0 && !this.isSourceFluidTarget(pos)) {
         return false;
      } else {
         if (this.unknown == null || this.currentTargetPos != null && this.unknown.getNext() != this.currentTargetPos.asLong()) {
            this.startAccessMission(this.getTempStructureKindForState(), 1);
         }

         if (!this.unknown.canLinkedHash(pos.asLong(), true, true) && !this.unknown.isContains(pos.asLong())) {
            return false;
         } else {
            this.cells.add(pos.asLong());
            this.recordHashOpenPos(pos);
            this.enableModuleMap.put(pos.asLong(), this.unknown.getReusableDescentTime());
            long time = this.getSupersededOwnerTime(this.unknown.getReusableDescentTime());
            if (time == 0L) {
               time = this.cleanedEvicted.createEntry(this.unknown.getNext(), this.moduleTick);
               this.supersededOwnerPositionMap.put(this.unknown.getReusableDescentTime(), time);
            }

            this.cleanedEvicted.handleCleanedLinked(time, pos.asLong());
            this.handleRetiredCell(Event.TOPOLOGY_TEMP_CONFIRMED);
            this.staleSweepMap.put(pos.asLong(), this.moduleTick);
            this.dirtConfirmedCount++;
            this.unknownTimeRepeat.updateTime();
            BlockPos blockPos2 = this.unknown.getNext() != 0L ? BlockPos.fromLong(this.unknown.getNext()) : this.currentTargetPos;
            this.setTransferTarget(blockPos2, "temp_dirt_confirmed");
            this.markCompoundProgress();
            return true;
         }
      }
   }

