   private boolean isCompletionCellPlaceable(long verticalAxisValue) {
      BlockState blockState = this.completionMissionMap.get(verticalAxisValue);
      if (blockState == null || this.worldBlockMap.containsKey(verticalAxisValue)) {
         return false;
      } else if (hasFluidState(blockState) || matchesBlockStateRule(blockState)) {
         return false;
      } else if (isStateSensitiveBlock(blockState) && !isPlaceableWithoutSpecialSneak(blockState) && getFacingDirectionOrNull(blockState) == null) {
         return false;
      } else if (this.getPlantChainPlacementTarget(BlockPos.fromLong(verticalAxisValue), blockState) != null) {
         return false;
      } else if (isFlaggedBlockState(blockState) && !isHopperState(blockState)) {
         return false;
      } else {
         if (isPlaceableWithoutSpecialSneak(blockState)) {
            Direction direction = getBlockStateFacingDirection(blockState);
            if (direction == null || direction.getAxis().isVertical()) {
               return false;
            }
         }

         Direction facingDirectionOrNull = getFacingDirectionOrNull(blockState);
         if (facingDirectionOrNull != null && facingDirectionOrNull.getAxis().isVertical() && facingDirectionOrNull != Direction.DOWN) {
            return false;
         } else {
            BlockPos blockPos = BlockPos.fromLong(verticalAxisValue);
            if (this.isRelaxedBlockShortCell(blockPos)) {
               return false;
            } else if (this.hasFluidNearBelowCell(blockPos)) {
               return false;
            } else if (this.needsFillForOpenNeighbor(blockPos)) {
               return false;
            } else if (this.isAirCellSplittingNeighbors(blockPos)) {
               return false;
            } else {
               Integer integer = this.cooldown.get(verticalAxisValue);
               if (integer != null && this.moduleTick < integer) {
                  return false;
               } else {
                  return this.isCellBlockedByTemporaryNeighbors(blockPos) ? false : this.canObtainItemForPlacement(getItemForBlockState(blockState));
               }
            }
         }
      }
   }

   private void holdAccessFamilyMembers(BlockPos pos, String shortModuleText) {
      this.updateUnpackTimeUnforced();
      Long longValue = this.unpackPositionMap.get(pos.asLong());
      if (longValue != null) {
         long familiesEpochTime2 = this.eventsFamilies.getFamiliesEpochTime();
         int n = this.failures.getFailuresTime(pos.asLong(), longValue, familiesEpochTime2);
         List<Long> list = this.getUnpackedGroupMembers(longValue);
         int n2 = 0;
         long activeComponentKey3 = this.getActiveComponentKey();

         for (long l : list) {
            if (l != pos.asLong()) {
               long[] ls = this.proofLayerMap.get(l);
               if (ls == null || ls[0] != activeComponentKey3 || this.cooldown.getOrDefault(l, 0) <= this.moduleTick) {
                  BlockPos blockPos = BlockPos.fromLong(l);
                  this.recordProofLayerCooldown(l, activeComponentKey3, this.hashPosVariantEight(blockPos));
                  this.recordLayerPlanHash(blockPos);
                  n2++;
               }
            }
         }

         this.shortModuleCount++;
         if (n2 > 0 || this.moduleTick - this.lastTickShortModule > 200) {
            this.lastTickShortModule = this.moduleTick;
            this.logDebugMessage(
               "\u00a7e[AccessFamily]\u00a7r ONE access problem: root="
                  + BlockPos.fromLong(longValue).toShortString()
                  + " members="
                  + list.size()
                  + " held="
                  + n2
                  + " attempts="
                  + n
                  + " epoch="
                  + familiesEpochTime2
                  + " reason="
                  + shortModuleText
                  + " - held until the walkable component or the geometry changes; the connection is solved once"
            );
         }

         this.queueAccessRequest(list, "access family " + BlockPos.fromLong(longValue).toShortString() + " (" + shortModuleText + ")");
      }
   }

