   private void handleGeometryEmergency(BlockPos pos, String geometryEmergencyText) {
      AutoBuilder.FailReason failReason = this.parseFailReason(geometryEmergencyText);
      if (failReason != null && pos != null) {
         this.eventsFamilies.recordNonEvent(NonEvent.FAILURE_MEMORY_WRITE);
         AutoBuilder.FailRec failRec = this.entries.computeIfAbsent(pos.asLong(), longValue -> new AutoBuilder.FailRec());
         failRec.failReason = failReason;
         failRec.geometryEmergencyValue = this.computeNeighborhoodHash(pos, failReason);
         failRec.blockPos = this.getFeetBlockPos();
         failRec.changedGeometryTime = SHARED_HASH_OPEN.hashOpenCellsInRadius(pos.getX(), pos.getY(), pos.getZ(), 3);
         failRec.changedWorldTime = changedPlanCount;
         failRec.changedStandValue = this.countNearbyTempCells(pos);
         failRec.geometryEmergencyCount++;
         boolean flag = failRec.geometryEmergencyCount >= 4;
         failRec.emergencyGeometryValue = this.moduleTick + (this.hasFewRemainingFloats() ? 600 : (flag ? 28800 : 4800));
         if (this.entries.size() > 96) {
            long key = 0L;
            int geometryValue = Integer.MAX_VALUE;

            for (Entry<Long, AutoBuilder.FailRec> entry : this.entries.entrySet()) {
               if (entry.getValue().emergencyGeometryValue < geometryValue) {
                  geometryValue = entry.getValue().emergencyGeometryValue;
                  key = entry.getKey();
               }
            }

            this.entries.remove(key);
         }
      }
   }

