   private void recoverFromStuckProgress() {
      this.updatePressedOptions2();
      this.path.clear();
      this.resetPillarTracking();
      if (this.staleCount >= 6) {
         int merge = 0;
         if (this.currentTargetPos != null) {
            merge = this.confirmSlowIntegerMap.merge(this.currentTargetPos.asLong(), 1, Integer::sum);
            this.setCellCooldown(this.currentTargetPos.asLong(), this.moduleTick + (200 << Math.min(merge - 1, 4)));
         }

         BlockPos blockPos = this.getFeetBlockPos();
         if (merge <= 3 && this.blockPos3BridgeCell != null && this.currentTargetPos != null && this.blockPos3BridgeCell.getY() > blockPos.getY()) {
            int n = this.blockPos3BridgeCell.getY() - blockPos.getY();
            if (n >= 2 && this.tryPillarUpToElevatedWork(blockPos, this.currentTargetPos)) {
               this.stuckProgressValue = 0;
               return;
            }

            if (this.canReachWithElevatedStand(blockPos, this.blockPos3BridgeCell)) {
               this.stuckProgressValue = 0;
               return;
            }

            if (this.tryStartDeckMount(blockPos, this.blockPos3BridgeCell, this.currentTargetPos)) {
               this.stuckProgressValue = 0;
               return;
            }
         }

         if (++this.stuckProgressValue < this.maxPathAttempts.getValue() || !this.pauseIfNoPath.isEnabled()) {
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "recovered from stuck - target deferred");
         } else if (this.canFiniteBlocked("stuck: no path progress")) {
            this.stuckProgressValue = 0;
         } else {
            this.handleReportedUnsolvable("stuck", "Paused: stuck with no progress", null);
            this.stuckProgressValue = 0;
         }
      }
   }

