   private boolean tryInteractBlockFace(BlockPos pos, Direction direction3) {
      Vec3d vec3d2 = mc.player.getEyePos();
      double d = this.reachSetting.getValue();
      double d2 = d * d;
      BlockState blockState = mc.world.getBlockState(pos);
      boolean flag = !blockState.contains(Properties.OPEN) || !blockState.get(Properties.OPEN);
      Direction[] directions = new Direction[]{Direction.UP, Direction.NORTH, Direction.SOUTH, Direction.WEST, Direction.EAST, Direction.DOWN};

      for (Direction direction : directions) {
         Vec3d vec3d = this.getFaceAimPoint(blockState, pos, direction);
         if (vec3d != null && !(vec3d2.squaredDistanceTo(vec3d) > d2)) {
            float[] fs = MathClampUtils.getWrapDegrees(vec3d2, vec3d);
            BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d2, fs[0], fs[1], d);
            if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
               float[] aimRotation2 = this.computeAimRotation(fs[0], fs[1]);
               BlockHitResult adjustedHit = this.raycastBlockSideForAim(vec3d2, aimRotation2[0], aimRotation2[1], d);
               if (adjustedHit.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK || !adjustedHit.getBlockPos().equals(pos)) {
                  return false;
               }

               if (!flag || direction3 != Direction.fromHorizontalDegrees(aimRotation2[0]).getOpposite()) {
                  this.recordHitForCurrentTarget(adjustedHit);
                  this.performBlockInteraction(adjustedHit);
                  if (this.swing.isEnabled()) {
                     mc.player.swingHand(Hand.MAIN_HAND);
                  }

                  return true;
               }
            }
         }
      }

      return false;
   }

   private boolean tryDeckPlacement(BlockPos pos, Vec3d vec, double lowestEffectiveValue, double reachLimit) {
      if (!this.deckMicroMoves.isProbingExitingConfirmed() && this.schematicCells != null) {
         boolean flag = !this.islandDeckFlag && (this.isCompletionPhaseActive() || this.hasActiveBlockersStep() || this.islandAbort != 0L);
         boolean flag2 = this.moduleTick - this.lastTickDeckMoves < 100;
         com.corz.client.utils.DeckPlanning.Outcome outcome = this.deckPlanning
            .evaluateCandidateSearch(pos.asLong(), this.moduleTick, flag, this.deckMode.isEnabled());
         if (outcome == com.corz.client.utils.DeckPlanning.Outcome.ACTIVATE) {
            if (this.activateDeckMission(
               this.deckPlanning.getSearchCandidate().getRemaining(), this.deckPlanning.getSearchCandidate().getCandidateNoneValue(), pos, vec, lowestEffectiveValue, reachLimit
            )) {
               return true;
            }

            if (this.deckMicroMoves.isProbingExitingConfirmed()) {
               return true;
            }
         }

         if (outcome == com.corz.client.utils.DeckPlanning.Outcome.SEARCHING) {
            this.refreshDeckPlanningTransition();
         }

         long l = System.nanoTime();
         long effectiveLowest2 = this.getEffectiveLowest(pos);
         long emptyRawValue3 = this.getEmptyRawValue();
         if (this.decision != null
            && !this.decision.isRejectDeck()
            && isNoSeedRejection(this.decision.reject())
            && this.lowestEffectiveLastNanos != Long.MIN_VALUE
            && l - this.lowestEffectiveLastNanos < 2000000000L
            && this.familiesEpochTime == this.eventsFamilies.getFamiliesEpochTime()
            && this.longLowestEffective == pos.asLong()
            && this.lowestEffectiveValue == effectiveLowest2
            && this.lowestEffectiveLastKey == emptyRawValue3
            && this.trueLowestUnfinishedY == this.effectiveLowestData.trueLowestUnfinishedY()
            && this.effectiveWorkLayerY == this.effectiveLowestData.effectiveWorkLayerY()
            && this.componentKeyLowestEffective == this.effectiveLowestData.componentKey()
            && this.componentSizeLowestEffective == this.effectiveLowestData.componentSize()) {
            return false;
         } else if (this.decision != null
            && !isNoSeedRejection(this.decision.reject())
            && this.changedPlanCountLowestEffect == changedPlanCount
            && this.moduleTick - this.lastTickLowestEffective < 60
            && !this.decision.isRejectDeck()) {
            return false;
         } else {
            long nanoTime4 = this.selectPasses.getNanoTime();
            MomentsExitedUtils.Decision decision = MomentsExitedUtils.getDataForProbeEffectiveLowestDataInt(
               this.supersedesRemainingProbe,
               this.effectiveLowestData,
               pos.getX(),
               pos.getZ(),
               16,
               3000,
               this.deckActivations,
               this.deckMode.isEnabled(),
               flag,
               flag2,
               (java.util.function.Function<FloorBuildPlanner.Deck, MomentsExitedUtils.Reject>) deck -> this.deckPlanning.checkDeckCandidate(deck, pos.asLong(), this.moduleTick, changedPlanCount)
            );
            this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.SELECT_COVERAGE, nanoTime4);
            this.decision = decision;
            this.changedPlanCountLowestEffect = changedPlanCount;
            this.lastTickLowestEffective = this.moduleTick;
            this.familiesEpochTime = this.eventsFamilies.getFamiliesEpochTime();
            this.longLowestEffective = pos.asLong();
            this.lowestEffectiveValue = effectiveLowest2;
            this.lowestEffectiveLastKey = emptyRawValue3;
            this.lowestEffectiveLastNanos = l;
            this.trueLowestUnfinishedY = this.effectiveLowestData.trueLowestUnfinishedY();
            this.effectiveWorkLayerY = this.effectiveLowestData.effectiveWorkLayerY();
            this.componentKeyLowestEffective = this.effectiveLowestData.componentKey();
            this.componentSizeLowestEffective = this.effectiveLowestData.componentSize();
            if (decision.probe() != null && decision.probe().deck != null && decision.probe().deck.hasEnoughEdgeFrontiers()) {
               this.deckMissionValue = this.moduleTick;
            }

            com.corz.client.utils.DeckPlanning.Outcome resolveSearchOutcome = this.deckPlanning.resolveSearchOutcome(decision, pos.asLong(), this.moduleTick);
            switch (resolveSearchOutcome) {
               case ACTIVATE:
                  return this.activateDeckMission(
                     decision.deck() != null ? decision.deck() : this.deckPlanning.getSearchCandidate().getRemaining(),
                     decision.deck() != null ? decision.deckY() : this.deckPlanning.getSearchCandidate().getCandidateNoneValue(),
                     pos,
                     vec,
                     lowestEffectiveValue,
                     reachLimit
                  );
               case RECLAIM_STARTED:
                  return true;
               case SEARCHING:
                  this.refreshDeckPlanningTransition();
                  return false;
               default:
                  if (this.deckMode.isEnabled() && this.moduleTick - this.probeDeckValue > 100) {
                     this.probeDeckValue = this.moduleTick;
                     this.logDebugMessage(
                        "\u00a78[DeckProbe] enabled="
                           + this.deckMode.isEnabled()
                           + " trueLowest="
                           + this.effectiveLowestData.trueLowestUnfinishedY()
                           + " effectiveLayers="
                           + this.effectiveLowestData.getEffectiveLowest()
                           + " playerFeetY="
                           + pos.getY()
                           + " "
                           + (decision.probe() == null ? "layer=none" : decision.probe().formatBuiltFloor())
                           + " rejectReason="
                           + decision.reject()
                           + " entry="
                           + this.deckPlanning.getSearchCandidate().getCommittedDiscoveredType()
                     );
                  }

                  return false;
            }
         }
      } else {
         return false;
      }
   }

