   private Probe getHandlerForBlockPosDouble(BlockPos pos, BlockPos pos2, double autoBuilderFactor, String autoBuilderText) {
      return new Probe() {
         @Override
         public Hit findPlacementHit(double x2, double y, double z2, EyeMode eyeMode) {
            AutoBuilder.TempSupportChoice blockSide = AutoBuilder.this.chooseTempSupportFace(pos, pos2, new Vec3d(x2, y, z2), autoBuilderFactor, autoBuilderText, false);
            if (blockSide == null) {
               return null;
            } else {
               BlockHitResult hit = blockSide.hit();
               return new Hit(hit.getBlockPos().asLong(), hit.getSide().ordinal(), hit.getPos().x, hit.getPos().y, hit.getPos().z);
            }
         }

         @Override
         public boolean isBodySpaceClear(double spaceCrouchedValue, double spaceCrouchedValue2, double spaceCrouchedValue3, EyeMode eyeMode) {
            double spaceCrouchedValue4 = 0.3;
            double spaceCrouchedValue5 = eyeMode == EyeMode.CROUCHED ? 1.5 : 1.8;
            return Module.mc.world.isSpaceEmpty(new Box(spaceCrouchedValue - spaceCrouchedValue4, spaceCrouchedValue2 + 0.001, spaceCrouchedValue3 - spaceCrouchedValue4, spaceCrouchedValue + spaceCrouchedValue4, spaceCrouchedValue2 + spaceCrouchedValue5 - 0.001, spaceCrouchedValue3 + spaceCrouchedValue4));
         }

         @Override
         public boolean isNearSolidNeighbour(double x3, double y2, double z3) {
            double replaceableCollisionValue = autoBuilderFactor * autoBuilderFactor;
            Vec3d vec3d = new Vec3d(x3, y2, z3);

            for (Direction direction : Direction.values()) {
               BlockPos offset = pos.offset(direction);
               BlockState blockState = Module.mc.world.getBlockState(offset);
               if (!blockState.isAir()
                  && !blockState.isReplaceable()
                  && !blockState.getCollisionShape(Module.mc.world, offset).isEmpty()
                  && vec3d.squaredDistanceTo(Vec3d.ofCenter(offset)) <= replaceableCollisionValue + 1.0) {
                  return true;
               }
            }

            return false;
         }
      };
   }

