   private BlockPos findNearbyStandPos(BlockPos pos, double worldSquaredValue) {
      if (mc.player != null && mc.world != null) {
         int ceil4 = (int)Math.ceil(worldSquaredValue);
         BlockPos feetBlockPos = this.getFeetBlockPos();
         BlockPos add = null;
         double squaredDistance = Double.MAX_VALUE;

         for (int n3 = -ceil4; n3 <= ceil4; n3++) {
            for (int n2 = -ceil4; n2 <= ceil4; n2++) {
               for (int n = -3; n <= 2; n++) {
                  BlockPos blockPos = pos.add(n3, n, n2);
                  if (!blockPos.equals(pos)
                     && !blockPos.equals(pos.up())
                     && !blockPos.down().equals(pos)
                     && !FlagPoseUtils.canFlagPosePair(pos.asLong(), blockPos.asLong())
                     && WalkRouteFinder.isStandable(mc.world, blockPos)
                     && this.findReachablePointOnBlock(pos, getStandingEyePos(blockPos), worldSquaredValue) != null) {
                     double d = blockPos.getSquaredDistance(feetBlockPos);
                     if (d < squaredDistance) {
                        squaredDistance = d;
                        add = blockPos;
                     }
                  }
               }
            }
         }

         return add;
      } else {
         return null;
      }
   }

