   private boolean shouldWaitForTeammates(SupportStandUtils.Mission mission2) {
      if (this.multiplayer.isEnabled() && this.multiLeaving.isHostMulti8() && !mission2.unsolved().isEmpty()) {
         HashSet<SupportStandUtils.Cell> hashSet = new HashSet<>();
         LinkedHashSet<SupportStandUtils.Cell> linkedHashSet = new LinkedHashSet<>();
         boolean flag3 = true;

         while (flag3) {
            flag3 = false;

            for (SupportStandUtils.Blocker blocker : mission2.blockers()) {
               if (!hashSet.contains(blocker.target())) {
                  boolean flag2 = blocker.reason().startsWith("SUPPORT_TEAMMATE") || this.hasSupportedBlockBelowInMission(blocker.target());

                  for (SupportStandUtils.Cell cell : blocker.dependsOn()) {
                     boolean flag = !this.multiLeaving.canHostMulti(cell.x(), cell.y(), cell.z());
                     if (flag) {
                        linkedHashSet.add(cell);
                     }

                     if (flag || hashSet.contains(cell)) {
                        flag2 = true;
                     }
                  }

                  if (flag2) {
                     hashSet.add(blocker.target());
                     flag3 = true;
                  }
               }
            }
         }

         long l = -3750763034362895579L;
         long l2 = -3750763034362895579L;
         StringBuilder stringBuilder = new StringBuilder();
         int n = 0;

         for (SupportStandUtils.Cell unsolvedItem : mission2.unsolved()) {
            if (!hashSet.contains(unsolvedItem)) {
               return false;
            }

            l = (l ^ BlockPos.asLong(unsolvedItem.x(), unsolvedItem.y(), unsolvedItem.z())) * 1099511628211L;
            if (n < 4) {
               stringBuilder.append(n > 0 ? ", " : "").append(unsolvedItem);
            }

            n++;
         }

         this.teammatesMultiplayerBlockPos.clear();
         StringBuilder stringBuilder2 = new StringBuilder();
         int n2 = 0;

         for (SupportStandUtils.Cell linkedHashItem : linkedHashSet) {
            BlockPos blockPos = toBlockPos(linkedHashItem);
            l2 = (l2 ^ blockPos.asLong()) * 1099511628211L;
            if (this.teammatesMultiplayerBlockPos.size() < 8) {
               this.teammatesMultiplayerBlockPos.add(blockPos);
            }

            if (n2 < 3) {
               String string = this.multiLeaving.formatHostMulti(blockPos.getX(), blockPos.getY(), blockPos.getZ());
               stringBuilder2.append(n2 > 0 ? ", " : "").append(blockPos.toShortString()).append(string == null ? "" : " (" + string + ")");
            }

            n2++;
         }

         if (l2 != this.teammatesMultiplayerValue) {
            this.teammatesMultiplayerValue = l2;
            this.lastTickSession = this.moduleTick;
         }

         this.sessionTeammatesSignature = this.computeCompletionHash() ^ this.sessionTeammatesSalt;
         this.multiplayerTeammatesValue = this.moduleTick + 200;
         if (l != this.multiplayerTeammatesTime || this.moduleTick - this.lastTickTeammatesMultiplayer > 1200) {
            this.multiplayerTeammatesTime = l;
            this.lastTickTeammatesMultiplayer = this.moduleTick;
            this.sendPlayerChatMessage(
               "\u00a7e[Multiplayer]\u00a7r waiting for teammates - my last "
                  + mission2.unsolved().size()
                  + " cell(s) hang on "
                  + (stringBuilder2.length() == 0 ? "blocks a teammate is placing" : stringBuilder2 + (linkedHashSet.size() > 3 ? ", ..." : ""))
                  + " (mine: "
                  + stringBuilder
                  + (mission2.unsolved().size() > 4 ? ", ..." : "")
                  + "). Holding; resumes when they're built or the jobs move"
                  + (linkedHashSet.isEmpty() ? "" : "; if their owner stays idle on that job for 45 s I take it over")
                  + "."
            );
         }

         return true;
      } else {
         return false;
      }
   }

