   private AutoBuilder.Recentre centrePlayerOnBlock(BlockPos pos) {
      if (mc.player == null) {
         return AutoBuilder.Recentre.FAILED;
      } else {
         double d = mc.player.getX();
         double d2 = mc.player.getZ();
         int n = pos.getX();
         int n2 = pos.getZ();
         long l = pos.asLong();
         if (BlockStandBounds.isInsideStandArea(d, d2, n, n2)) {
            if (this.workingPlayerValue == l) {
               this.releaseMovementKeys();
               double hypot = Math.hypot(d - this.autoBuilderAmount, d2 - this.workingPlayerLastZ);
               this.workingPlayerValue = Long.MIN_VALUE;
               this.workingPlayerStuckCount = 0;
               this.workingPlayerCount = 0;
            }

            return AutoBuilder.Recentre.OK;
         } else {
            if (this.workingPlayerValue != l) {
               this.workingPlayerValue = l;
               this.workingPlayerStuckCount = 0;
               this.workingPlayerCount = 0;
               this.autoBuilderAmount = d;
               this.workingPlayerLastZ = d2;
               this.workingPlayerLastX = d;
               this.workingPlayerAmount = d2;
            }

            this.workingPlayerStuckCount++;
            double hypot3 = Math.hypot(d - this.workingPlayerLastX, d2 - this.workingPlayerAmount);
            this.workingPlayerLastX = d;
            this.workingPlayerAmount = d2;
            if (this.workingPlayerStuckCount > 3 && hypot3 < 0.001) {
               this.workingPlayerCount++;
            } else {
               this.workingPlayerCount = 0;
            }

            if (this.workingPlayerStuckCount <= 20 && this.workingPlayerCount < 4) {
               if (this.isFeetCellBlocked() || this.isNeighborCellDangerous(pos)) {
                  this.setOwnerSneak(true);
               }

               if (!this.intervalReportTimer.canTime(this.moduleTick)) {
                  return AutoBuilder.Recentre.WORKING;
               } else {
                  Interval interval = BlockStandBounds.getStandInterval(n, n2);
                  Vec3d vec3d = mc.player.getVelocity();
                  Decision decision = SlidingPulseUtils.decideSlidingAction(interval, d, d2, vec3d.x, vec3d.z, this.getSlipperiness());
                  if (decision.action() == com.corz.client.utils.SlidingPulseUtils.Action.BRAKE) {
                     if (!this.applyCounterStrafeKeys(0.004)) {
                        this.releaseMovementKeys();
                     }

                     return AutoBuilder.Recentre.WORKING;
                  } else if (decision.action() != com.corz.client.utils.SlidingPulseUtils.Action.COAST && decision.action() != com.corz.client.utils.SlidingPulseUtils.Action.WAIT_STOP) {
                     this.handlePressedOptions(BlockStandBounds.clampToStandRange(d, n), BlockStandBounds.clampToStandRange(d2, n2), false);
                     return AutoBuilder.Recentre.WORKING;
                  } else {
                     this.releaseMovementKeys();
                     return AutoBuilder.Recentre.WORKING;
                  }
               }
            } else {
               this.releaseMovementKeys();
               this.workingPlayerValue = Long.MIN_VALUE;
               this.workingPlayerStuckCount = 0;
               this.workingPlayerCount = 0;
               return AutoBuilder.Recentre.FAILED;
            }
         }
      }
   }

   private boolean tryPocketClimb() {
      if (!this.useTemporaryBlocks.isEnabled()
         || mc.player == null
         || mc.world == null
         || this.schematicCells == null
         || !mc.player.isOnGround()
         || this.getHotbarDirtSlot() == -1) {
         return false;
      } else if (this.moduleTick - this.confirmMultiValue >= 600
         && this.cellsUnpackWorkspaceReturn == null
         && !this.hasActiveBlockersStep()
         && this.islandAbort == 0L
         && !this.isFallRecoveryActive()
         && !this.deckMicroMoves.isProbingExitingConfirmed()
         && this.unstableRecenterChangedTimeo == null) {
         this.rebuildReachableComponent();
         if (!this.component.isEmpty() && this.component.size() <= 12) {
            if (this.climbPocketValue != this.confirms) {
               this.climbPocketValue = this.confirms;
               this.climbPocketCount = 0;
               this.climbPocketPositionSet.clear();
            }

            BlockPos feetBlockPos = this.getFeetBlockPos();
            if (this.climbPocketCount < 3 && !this.climbPocketPositionSet.contains(feetBlockPos.asLong())) {
               Terrain terrain = WalkRouteFinder.createPartialHeightTerrain(mc.world, WalkRouteFinder.createTerrainView(mc.world));
               if (this.component.size() > 3) {
                  for (long l : this.component) {
                     for (Direction direction : Type.HORIZONTAL) {
                        BlockPos blockPos = BlockPos.fromLong(l).offset(direction);
                        if (!this.component.contains(blockPos.asLong())
                           && !terrain.solid(blockPos.getX(), blockPos.getY(), blockPos.getZ())
                           && !terrain.solid(blockPos.getX(), blockPos.getY() + 1, blockPos.getZ())) {
                           return false;
                        }
                     }
                  }
               }

               PillarPlacementCheck pillarBase = (x, y, z) -> {
                  BlockPos blockPosx = new BlockPos(x, y, z);
                  BlockState blockState = mc.world.getBlockState(blockPosx);
                  return (this.getSchematicCells(blockPosx) < 0 && !this.cellTemporarySet.contains(blockPosx.asLong()) || this.isSourceFluidTarget(blockPosx))
                     && (blockState.isAir() || blockState.isReplaceable())
                     && blockState.getFluidState().isEmpty()
                     && !this.isFacedByExtendedPiston(blockPosx)
                     && this.describeObserverPulseHazard(blockPosx) == null
                     && this.formatBlockShort(blockPosx) == null;
               };
               BlockPos longValue = null;
               int allowed = Integer.MAX_VALUE;

               for (long l2 : this.component) {
                  BlockPos fromLong = BlockPos.fromLong(l2);
                  if (!this.canColumnsBanned(fromLong)) {
                     int n = WalkableRegionAnalyzer.getPillarHeightToEscape(terrain, fromLong.getX(), fromLong.getY(), fromLong.getZ(), 4, pillarBase);
                     if (n > 0 && (n < allowed || n == allowed && fromLong.equals(feetBlockPos))) {
                        allowed = n;
                        longValue = fromLong;
                     }
                  }
               }

               BlockPos pos = null;
               double squaredDistance = Double.MAX_VALUE;

               for (long l3 : this.completionMissionMap.keySet()) {
                  if (!this.machineArmedSet.contains(l3)) {
                     double d = BlockPos.fromLong(l3).getSquaredDistance(feetBlockPos);
                     if (d < squaredDistance) {
                        squaredDistance = d;
                        pos = BlockPos.fromLong(l3);
                     }
                  }
               }

               if (longValue == null && pos != null && this.escapeEnclosedByTempBlocks(feetBlockPos)) {
                  this.climbPocketCount++;
                  return true;
               } else if (longValue != null && pos != null) {
                  this.climbPocketCount++;
                  this.climbPocketPositionSet.add(feetBlockPos.asLong());
                  if (!longValue.equals(feetBlockPos)) {
                     List<BlockPos> list = this.findGoPath(feetBlockPos, longValue);
                     this.standClimbFlag = false;
                     this.arrivedSupportFlag = false;
                     MovementMissionData movementMissionData = new MovementMissionData(
                        Owner.EGRESS, 0L, Purpose.EGRESS, longValue.asLong(), null, 1, Scope.GLOBAL_SELECTION
                     );
                     if (list != null && !list.isEmpty() && this.tryFollowMovementRoute(list, longValue, movementMissionData)) {
                        this.logDebugMessage(
                           "\u00a7e[PocketClimb]\u00a7r a "
                              + this.component.size()
                              + "-cell walk component - walking to "
                              + longValue.toShortString()
                              + " to pillar "
                              + allowed
                              + " and step off"
                        );
                        this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "pocket climb: walk to the climb cell");
                        return true;
                     } else {
                        return false;
                     }
                  } else {
                     this.currentTargetPos = pos;
                     this.supportAccessValue = this.getSchematicCells(pos);
                     this.longFallRecovery = feetBlockPos.asLong();
                     this.resetPillarTracking();
                     this.blockPos3BridgeCell = feetBlockPos;
                     this.pillarDirtValue = feetBlockPos.getY() + allowed;
                     this.startAccessMission(com.corz.client.utils.DescentReusable.Kind.PILLAR, 1);
                     this.logDebugMessage(
                        "\u00a7e[PocketClimb]\u00a7r a "
                           + this.component.size()
                           + "-cell walk component, nothing placed for "
                           + (this.moduleTick - this.confirmMultiValue) / 20
                           + " s, every recovery spent - pillaring "
                           + allowed
                           + " at "
                           + feetBlockPos.toShortString()
                           + " and stepping off the top"
                     );
                     this.setSupportText("TEMP_SUPPORT", "pocket climb");
                     this.transitionToState(AutoBuilder.State.SCAFFOLD_UP, "pocket climb: pillar up and step off");
                     return true;
                  }
               } else {
                  return false;
               }
            } else {
               return false;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

   private boolean hasAdjacentCollisionSupport(BlockPos pos) {
      boolean flag = false;

      for (Direction direction : Direction.values()) {
         if (direction != Direction.DOWN) {
            BlockPos blockPos = pos.offset(direction);
            if (!mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
               return true;
            }

            int n = this.getSchematicCells(blockPos);
            if (n >= 0 && !this.targetFluidItems.get(n).getCollisionShape(mc.world, blockPos).isEmpty()) {
               flag = true;
            }
         }
      }

      return !flag;
   }

