   private boolean isFluidSealedByWalls(BlockPos pos, BlockState state) {
      if (state != null
         && (state.isOf(Blocks.WATER) || state.isOf(Blocks.LAVA))
         && mc.world != null
         && this.targetFluidItems != null) {
         for (Direction direction : Direction.values()) {
            BlockPos blockPos = pos.offset(direction);
            BlockState blockState = mc.world.getBlockState(blockPos);
            if (blockState.getBlock() instanceof ObserverBlock && blockPos.offset(blockState.get(Properties.FACING)).equals(pos)) {
               return false;
            }

            if (direction != Direction.UP) {
               if (this.cells.contains(blockPos.asLong()) || blockState.isAir() || blockState.isReplaceable() || !blockState.getFluidState().isEmpty()) {
                  return false;
               }

               if (!(blockState.getBlock() instanceof FluidFillable) || direction == Direction.DOWN && !state.isOf(Blocks.LAVA)) {
                  if (!Block.isFaceFullSquare(blockState.getOutlineShape(mc.world, blockPos), direction.getOpposite())) {
                     return false;
                  }

                  int schematicCells2 = this.getSchematicCells(blockPos);
                  if (schematicCells2 >= 0
                     ? !blockState.equals(this.targetFluidItems.get(schematicCells2)) && !areBlocksEquivalentVariants(this.targetFluidItems.get(schematicCells2), blockState)
                     : direction != Direction.DOWN) {
                     return false;
                  }
               } else {
                  int n = this.getSchematicCells(blockPos);
                  if (n < 0 || blockState.getBlock() != this.targetFluidItems.get(n).getBlock()) {
                     return false;
                  }
               }
            }
         }

         return true;
      } else {
         return false;
      }
   }

