   private long computeWorldFingerprint() {
      if (mc.world != null && mc.player != null) {
         long long5 = this.getFeetBlockPos().asLong();
         long l6 = long5 * -7046029254386353131L ^ (long)this.completionMissionMap.size() << 20 ^ this.cells.size();
         boolean flag = true;

         for (long l : this.completionMissionMap.keySet()) {
            if (!this.machineArmedSet.contains(l)) {
               flag = false;
               break;
            }
         }

         ArrayList<Long> arrayList = new ArrayList<>();

         for (long l2 : this.completionMissionMap.keySet()) {
            if (flag || !this.machineArmedSet.contains(l2)) {
               arrayList.add(l2);
            }
         }

         arrayList.add(long5);
         HashSet<Long> hashSet = new HashSet<>();

         for (long l3 : arrayList) {
            int unpackLongX4 = BlockPos.unpackLongX(l3);
            int unpackLongY5 = BlockPos.unpackLongY(l3);
            int unpackLongZ6 = BlockPos.unpackLongZ(l3);

            for (int n3 = -2; n3 <= 2; n3++) {
               for (int n2 = -2; n2 <= 2; n2++) {
                  for (int n = -2; n <= 2; n++) {
                     hashSet.add(BlockPos.asLong(unpackLongX4 + n3, unpackLongY5 + n2, unpackLongZ6 + n));
                  }
               }
            }
         }

         for (long l4 : hashSet) {
            BlockPos blockPos = BlockPos.fromLong(l4);
            l6 += l4 * -4417276706812531889L ^ classifyBlockPassability(mc.world.getBlockState(blockPos), blockPos) + 7L;
         }

         return l6;
      } else {
         return Long.MIN_VALUE + this.moduleTick;
      }
   }

