   private boolean continueLifelineExtension() {
      BlockPos pos = this.blockPos2LifelineExtension;
      if (mc.player != null && this.moduleTick - this.lastTickLifelineTop <= 1200) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         if (feetBlockPos.getY() >= this.lifelineExtensionValue) {
            this.blockPos2LifelineExtension = null;
            return false;
         } else {
            boolean flag = feetBlockPos.equals(pos)
               || feetBlockPos.getY() == pos.getY()
                  && Math.abs(mc.player.getX() - pos.getX() - 0.5) < 0.8
                  && Math.abs(mc.player.getZ() - pos.getZ() - 0.5) < 0.8
                  && this.isSolidNonReplaceableAt(pos.getX(), pos.getY() - 1, pos.getZ());
            if (!flag) {
               this.blockPos2LifelineExtension = null;
               return false;
            } else if (!mc.player.isOnGround()) {
               this.releaseMovementKeys();
               return true;
            } else {
               AutoBuilder.Recentre recentre = this.centrePlayerOnBlock(pos);
               if (recentre == AutoBuilder.Recentre.WORKING) {
                  return true;
               } else if (recentre == AutoBuilder.Recentre.FAILED && !feetBlockPos.equals(pos)) {
                  this.blockPos2LifelineExtension = null;
                  return false;
               } else if (recentre == AutoBuilder.Recentre.OK && !IncompleteStand.isNearlyStill(mc.player.getVelocity().horizontalLengthSquared())) {
                  this.releaseMovementKeys();
                  return true;
               } else {
                  BlockPos longValue = null;
                  double squaredDistance = Double.MAX_VALUE;

                  for (long l : this.completionMissionMap.keySet()) {
                     BlockPos blockPos = BlockPos.fromLong(l);
                     if (blockPos.getY() >= this.lifelineExtensionValue - 1) {
                        double d = blockPos.getSquaredDistance(feetBlockPos);
                        if (d < squaredDistance) {
                           squaredDistance = d;
                           longValue = blockPos;
                        }
                     }
                  }

                  if (longValue == null) {
                     this.blockPos2LifelineExtension = null;
                     return false;
                  } else {
                     this.blockPos2LifelineExtension = null;
                     this.longFallRecovery = feetBlockPos.asLong();
                     this.resetPillarTracking();
                     this.blockPos3BridgeCell = feetBlockPos;
                     this.pillarDirtValue = this.lifelineExtensionValue;
                     this.currentTargetPos = longValue;
                     this.supportAccessValue = this.getSchematicCells(longValue);
                     this.setSupportText("TEMP_SUPPORT", "lifeline extension");
                     this.transitionToState(AutoBuilder.State.SCAFFOLD_UP, "lifeline: pillar the way down up to the walking floor");
                     return true;
                  }
               }
            }
         }
      } else {
         this.blockPos2LifelineExtension = null;
         return false;
      }
   }

