   private boolean tryStartLifelineClimb() {
      BlockPos feetBlockPos = this.getFeetBlockPos();
      if (feetBlockPos.getY() >= this.unpackLifelineValue - 1) {
         this.cellsUnpack = null;
         return false;
      } else if (this.moduleTick - this.lastTickUnpackLifeline >= 40 && this.blockPos2LifelineExtension == null && this.cellsUnpackWorkspaceReturn == null && this.islandAbort == 0L) {
         this.lastTickUnpackLifeline = this.moduleTick;
         boolean flag = this.censusBuildableValue <= 0 && this.moduleTick - this.confirmMultiValue > 1200;
         if (this.layer != Integer.MIN_VALUE && (this.layer > this.workspaceReturnValue || flag)) {
            if (!flag) {
               for (long l : this.completionMissionMap.keySet()) {
                  int n = BlockPos.unpackLongY(l);
                  if (n >= this.workspaceReturnValue - 1
                     && n <= this.workspaceReturnValue
                     && Math.abs(BlockPos.unpackLongX(l) - feetBlockPos.getX()) <= 8
                     && Math.abs(BlockPos.unpackLongZ(l) - feetBlockPos.getZ()) <= 8) {
                     Integer integer = this.cooldown.get(l);
                     if (this.hasSolidNeighborToPlaceOn(BlockPos.fromLong(l)) && (integer == null || this.moduleTick >= integer)) {
                        return false;
                     }
                  }
               }
            }

            if (this.useTemporaryBlocks.isEnabled() && this.getHotbarDirtSlot() != -1) {
               this.rebuildReachableComponent();
               BlockPos pos = null;

               for (int n2 = this.unpackLifelineValue - 1; n2 >= this.unpackLifelineValue - 24; n2--) {
                  BlockPos blockPos = new BlockPos(this.cellsUnpack.getX(), n2, this.cellsUnpack.getZ());
                  if (WalkRouteFinder.isStandable(mc.world, blockPos)) {
                     pos = blockPos;
                     break;
                  }

                  if (!mc.world.getBlockState(blockPos).getCollisionShape(mc.world, blockPos).isEmpty()) {
                     break;
                  }
               }

               if (pos != null && !pos.equals(feetBlockPos) && !this.paveFacelessMap.containsKey(pos.asLong())) {
                  pos = null;
               }

               if (pos != null && (!this.canReplaceableAir(pos, this.unpackLifelineValue) || !this.isColumnClearAbove(pos))) {
                  pos = null;
               }

               if (pos == null || !this.isColumnClearAbove(pos)) {
                  BlockPos longValue = null;
                  double squaredDistance = Double.MAX_VALUE;

                  for (long l2 : this.component) {
                     BlockPos fromLong = BlockPos.fromLong(l2);
                     if (Math.abs(fromLong.getX() - feetBlockPos.getX()) <= 14
                        && Math.abs(fromLong.getZ() - feetBlockPos.getZ()) <= 14
                        && fromLong.getY() <= this.unpackLifelineValue - 2) {
                        double d = fromLong.getSquaredDistance(feetBlockPos);
                        if (!(d >= squaredDistance) && this.canReplaceableAir(fromLong, this.unpackLifelineValue) && this.isColumnClearAbove(fromLong)) {
                           squaredDistance = d;
                           longValue = fromLong;
                        }
                     }
                  }

                  if (longValue != null) {
                     pos = longValue;
                  }
               }

               if (pos == null) {
                  this.cellsUnpack = null;
                  return false;
               } else {
                  if (this.hasActiveBlockersStep()) {
                     this.blockers = null;
                     this.stepIndex = -1;
                     this.stepsTimeBudget.updateTimeMax();
                  }

                  this.blockPos2LifelineExtension = pos;
                  this.lifelineExtensionValue = this.unpackLifelineValue;
                  this.lastTickLifelineTop = this.moduleTick;
                  this.logDebugMessage(
                     "\u00a7b[Lifeline]\u00a7r climbing out the way down came: re-pillaring "
                        + pos.toShortString()
                        + " up to feet y="
                        + this.unpackLifelineValue
                        + " (the lifeline stays for the next release)"
                  );
                  this.cellsUnpack = null;
                  if (pos.equals(feetBlockPos)) {
                     return this.continueLifelineExtension();
                  } else {
                     List<BlockPos> list = this.findGoPath(feetBlockPos, pos);
                     this.standClimbFlag = false;
                     this.arrivedSupportFlag = false;
                     MovementMissionData movementMissionData = new MovementMissionData(
                        Owner.EGRESS, 0L, Purpose.EGRESS, pos.asLong(), null, 1, Scope.GLOBAL_SELECTION
                     );
                     if (list != null && !list.isEmpty() && this.tryFollowMovementRoute(list, pos, movementMissionData)) {
                        this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "lifeline: walk to the descent column");
                        return true;
                     } else {
                        this.blockPos2LifelineExtension = null;
                        return false;
                     }
                  }
               }
            } else {
               return false;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

