   private boolean isFailureRecordStillValid(BlockPos pos, AutoBuilder.FailRec failRec) {
      if (isAimStandOrFaceFailure(failRec.failReason) && !this.hasFewRemainingFloats()) {
         if (failRec.failReason != AutoBuilder.FailReason.NO_LEGAL_AIM && this.countNearbyTempCells(pos) != failRec.changedStandValue) {
            this.emergencyTimeout = "temp_stand_changed";
            return false;
         } else {
            long l = SHARED_HASH_OPEN.hashOpenCellsInRadius(pos.getX(), pos.getY(), pos.getZ(), 3);
            if (l == failRec.changedGeometryTime) {
               return true;
            } else if (this.computeNeighborhoodHash(pos, failRec.failReason) == failRec.geometryEmergencyValue) {
               failRec.changedGeometryTime = l;
               return true;
            } else {
               this.emergencyTimeout = "local_geometry_changed";
               return false;
            }
         }
      } else if (this.moduleTick >= failRec.emergencyGeometryValue) {
         this.emergencyTimeoutCount++;
         this.emergencyTimeout = "emergency_timeout";
         return false;
      } else if (failRec.geometryEmergencyCount >= 4 && !this.hasFewRemainingFloats()) {
         return true;
      } else {
         boolean flag2 = (failRec.failReason == AutoBuilder.FailReason.NO_SUPPORT_FACE || failRec.failReason == AutoBuilder.FailReason.NO_VALID_STAND)
            && this.hasSolidNeighborToPlaceOn(pos);
         if ((failRec.failReason.pathFailure || flag2) && failRec.blockPos != null) {
            BlockPos blockPos = this.getFeetBlockPos();
            int n = Math.max(
               Math.abs(blockPos.getX() - failRec.blockPos.getX()),
               Math.max(Math.abs(blockPos.getY() - failRec.blockPos.getY()), Math.abs(blockPos.getZ() - failRec.blockPos.getZ()))
            );
            boolean flag = this.isInReachableComponent(failRec.blockPos);
            Suppression suppression = HeldStayUtils.classifyReopenSuppression(n, 3, failRec.changedWorldTime, changedPlanCount, flag);
            if (!HeldStayUtils.isHeldSuppression(suppression)) {
               if (flag && failRec.changedWorldTime == changedPlanCount) {
                  this.changedEmergencyCount++;
               }

               this.emergencyTimeout = suppression == Suppression.REOPEN_WORLD_CHANGED
                  ? "world_changed"
                  : (flag2 && !failRec.failReason.pathFailure ? "region_changed(positional)" : "region_changed");
               return false;
            }

            if (n > 3) {
               this.changedRegionCount++;
            }
         }

         if (this.computeNeighborhoodHash(pos, failRec.failReason) != failRec.geometryEmergencyValue) {
            this.emergencyTimeout = "geometry_changed";
            return false;
         } else {
            return true;
         }
      }
   }

