   private void advanceToNextBuyItem() {
      this.accumulateReceivedTotals();
      this.optional = null;
      this.listingVanishedSet.clear();
      this.listingWordingValue = 0;
      this.missBoardValue = 0;
      this.buyAutoSyncId = -1;
      this.listingPageValue = -1L;
      this.listingAffordableFlag = false;
      this.affordablePagesActive = false;
      this.snipesFreshValue = 0;
      this.deliveryUnprovenValue = -1;
      this.queueMap.clear();
      this.queueSlotTotalPriceData = null;
      this.boardSnipesFlag = false;
      this.affordablePagesFlag = false;

      do {
         this.queueCompleteValue++;
         if (this.queueCompleteValue >= this.pricingMaterialItems.size()) {
            this.enterStateWithRandomDelays(AutoBuilder.State.BUY_DONE, "queue complete");
            return;
         }

         this.affordablePagesItem = this.pricingMaterialItems.get(this.queueCompleteValue);
         this.orDefault = this.queueCompleteMap.getOrDefault(this.affordablePagesItem, 0);
         this.buyQuantity = this.complete == AutoBuilder.BuyMode.BUY ? this.getMissingItemCount(this.affordablePagesItem) : this.costBuyMap.getOrDefault(this.affordablePagesItem, 0);
         this.costBuyMap.put(this.affordablePagesItem, this.buyQuantity);
      } while (this.buyQuantity <= 0);

      this.receivedCompleteValue = this.moduleTick;
      if (this.queueCompleteStartTick < 0) {
         this.queueCompleteStartTick = this.moduleTick;
      }

      this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SEARCH, "shop " + getItemIdPath(this.affordablePagesItem));
   }

