   private int findLowestStructuralY(BlockPos pos, int unpackStructuralLimit, int unpackStructural) {
      if (unpackStructural != Integer.MAX_VALUE && unpackStructuralLimit != Integer.MIN_VALUE) {
         int longY = Integer.MAX_VALUE;

         for (long l : this.structuralSpecialSet) {
            int n = BlockPos.unpackLongY(l);
            if (n < unpackStructuralLimit
               && n >= unpackStructural
               && n < longY
               && Math.abs(BlockPos.unpackLongX(l) - pos.getX()) <= 8
               && Math.abs(BlockPos.unpackLongZ(l) - pos.getZ()) <= 8) {
               longY = n;
            }
         }

         return longY == Integer.MAX_VALUE ? unpackStructural : longY;
      } else {
         return unpackStructural;
      }
   }

