   private boolean tickAutoEat() {
      if (this.autoEat.isEnabled() && !mc.player.getAbilities().creativeMode) {
         int foodLevel2 = mc.player.getHungerManager().getFoodLevel();
         int effectiveEatAt3 = this.getEffectiveEatAt();
         int min4 = Math.min(20, effectiveEatAt3 + 5);
         long l = System.nanoTime();
         boolean flag = this.lastNanoTimeStackInventory >= 0L;
         if (this.foodStarvingFlag || flag || foodLevel2 <= effectiveEatAt3 && l >= this.foodStarvingTime) {
            if (!this.foodStarvingFlag && !flag && !mc.player.isOnGround() && !mc.player.isTouchingWater()) {
               return false;
            } else if (this.foodStarvingFlag && foodLevel2 >= min4) {
               this.resetFoodState();
               return false;
            } else {
               int stackInventory = flag ? -1 : this.getBestFoodHotbarSlot();
               if (stackInventory < 0) {
                  if (this.foodStarvingFlag) {
                     mc.options.useKey.setPressed(false);
                  }

                  int n = this.stepGoldenAppleSwap(l);
                  if (n == -2) {
                     this.releaseMovementKeys();
                     mc.player.setSprinting(false);
                     return true;
                  }

                  stackInventory = n;
               }

               if (stackInventory < 0) {
                  if (this.foodStarvingFlag) {
                     this.resetFoodState();
                  }

                  this.foodStarvingTime = l + 3000000000L;
                  if (stackInventory == -1 && foodLevel2 <= 3) {
                     this.handleReportedUnsolvable(
                        "starving: no food",
                        "Out of food",
                        "\u00a7cAuto Builder paused:\u00a7r hunger "
                           + foodLevel2
                           + "/20 and no food in your inventory - add food, then turn Auto Builder back on (it stops before you starve)"
                     );
                     return true;
                  } else {
                     if (stackInventory == -1 && this.moduleTick - this.foodStarvingValue > 1200) {
                        this.foodStarvingValue = this.moduleTick;
                        this.sendPlayerChatMessage(
                           "\u00a7e[AutoEat]\u00a7r hunger "
                              + foodLevel2
                              + "/20 and no food in the inventory - add food (bread, steak, carrots...) so the builder keeps sprinting"
                        );
                     }

                     return false;
                  }
               } else {
                  if (!this.foodStarvingFlag) {
                     this.foodStarvingFlag = true;
                     this.foodStarvingSinceNanos = l;
                     this.foodLevel = foodLevel2;
                     mc.options.forwardKey.setPressed(false);
                     mc.options.backKey.setPressed(false);
                     mc.options.leftKey.setPressed(false);
                     mc.options.rightKey.setPressed(false);
                     mc.options.jumpKey.setPressed(false);
                     this.setOwnerSneak(this.isFeetCellBlocked());
                     mc.player.setSprinting(false);
                  } else if (foodLevel2 > this.foodLevel) {
                     this.foodLevel = foodLevel2;
                     this.foodStarvingSinceNanos = l;
                  } else if (l - this.foodStarvingSinceNanos > 6000000000L) {
                     this.resetFoodState();
                     this.foodStarvingTime = l + 3000000000L;
                     this.sendPlayerChatMessage("\u00a7e[AutoEat]\u00a7r no bite in 6 s at hunger " + foodLevel2 + "/20 - building on, retrying in 3 s");
                     return false;
                  }

                  if (mc.player.getInventory().getSelectedSlot() != stackInventory) {
                     mc.player.getInventory().setSelectedSlot(stackInventory);
                  }

                  float[] fs = this.computeAimRotation(mc.player.getYaw(), -90.0F);
                  mc.options.useKey.setPressed(fs[1] <= -75.0F && !this.bucketCrouchFlag);
                  return true;
               }
            }
         } else {
            return false;
         }
      } else {
         if (this.foodStarvingFlag) {
            this.resetFoodState();
         }

         this.updateInventoryStackSwap();
         return false;
      }
   }

   private boolean isBelowStructuralSpecial(BlockPos pos) {
      if (!this.unpackCellsIntArrayMap.isEmpty() && !this.structuralSpecialSet.isEmpty()) {
         for (Entry<Long, int[]> entry : this.unpackCellsIntArrayMap.entrySet()) {
            int[] ns = entry.getValue();
            if (ns.length <= 2) {
               int n = BlockPos.unpackLongX(entry.getKey());
               int unpackLongZ2 = BlockPos.unpackLongZ(entry.getKey());
               int n3 = ns[0];
               if (this.cells.contains(BlockPos.asLong(n, n3, unpackLongZ2))) {
                  while (this.cells.contains(BlockPos.asLong(n, n3 + 1, unpackLongZ2))) {
                     n3++;
                  }

                  int n4 = pos.getY() - n3 - 1;
                  if (n4 >= 2 && n4 <= 3) {
                     for (long l : this.structuralSpecialSet) {
                        if (BlockPos.unpackLongY(l) <= n3 + 2 && Math.abs(BlockPos.unpackLongX(l) - n) <= 8 && Math.abs(BlockPos.unpackLongZ(l) - unpackLongZ2) <= 8) {
                           return true;
                        }
                     }
                  }
               }
            }
         }

         return false;
      } else {
         return false;
      }
   }

   private AutobuyShortfallCalculator.Capacity computeAutoBuyCapacity(boolean surveyedPlanFlag) {
      if (this.availableLow == null) {
         this.updateMaterialAvailability();
      }

      if (this.availableLow != null && mc.world != null) {
         LinkedHashMap<Item, Integer> linkedHashMap = new LinkedHashMap<>();
         LinkedHashMap<Item, Integer> linkedHashMap2 = new LinkedHashMap<>();
         LinkedHashMap<Item, Integer> linkedHashMap3 = new LinkedHashMap<>();

         for (MaxMaterialsUtils.Row<Item> row : this.availableLow.readSelectedItems) {
            if (row.next != Items.AIR) {
               linkedHashMap.put(row.next, row.surveyedPlanValue);
               linkedHashMap2.put(row.next, row.minCount);
               linkedHashMap3.put(row.next, row.preferredCount);
            }
         }

         Map<Item, Integer> map = (Map<Item, Integer>)(this.stockpileInChests.isEnabled() ? this.getRestockItemCounts() : Map.of());
         List<AutobuyShortfallCalculator.Row<Item>> list = AutobuyShortfallCalculator.buildRows(linkedHashMap, linkedHashMap2, linkedHashMap3, map, Item::getMaxCount);
         String string = mc.world.getRegistryKey().getValue().toString();
         BlockPos feetBlockPos = this.getFeetBlockPos();
         double d2 = this.restockWalkDistance.getValue() * this.restockWalkDistance.getValue();
         int n = 0;
         int n2 = 0;
         int n3 = 0;
         int n4 = 0;

         for (DimensionPosData dimensionPosData : this.restockSources.getEntriesSnapshot()) {
            if (dimensionPosData.dimension().equals(string)) {
               BlockPos blockPos = dimensionPosData.getLong();
               ChestTrappedType chestTrappedType = ChestTrappedType.getChestTrapped(mc.world.getBlockState(blockPos).getBlock());
               double d = Math.min(
                  feetBlockPos.getSquaredDistance(blockPos), this.buyAutoBlockPos == null ? Double.MAX_VALUE : this.buyAutoBlockPos.getSquaredDistance(blockPos)
               );
               if (chestTrappedType != null && !(d > d2)) {
                  n3++;
                  ProofContainerData proofContainerData = this.findContainerAccessProof(blockPos, null);
                  if (proofContainerData == null) {
                     n2++;
                  } else {
                     n++;
                     AutoBuilder.ContainerView containerView = this.restockSourceMap.get(formatDimensionPosKey(string, blockPos.asLong()));
                     n4 += containerView != null ? containerView.freeSlots() : (surveyedPlanFlag ? 0 : getChestSlotCount(chestTrappedType));
                  }
               }
            }
         }

         AutobuyShortfallCalculator.Capacity capacity = AutobuyShortfallCalculator.computeCapacity(list, this.countEmptyInventorySlots(), n4, n, n2);
         this.logDebugMessage(
            "\u00a7b[AutoBuyPlan]\u00a7r " + AutobuyShortfallCalculator.formatAutobuySummary(list, capacity, n3) + (surveyedPlanFlag ? " surveyed=true" : " surveyed=false")
         );
         return capacity;
      } else {
         return null;
      }
   }

   private boolean canFloodFillEscape(Terrain terrain, int solidValue, BlockPos pos, HashSet<Long> hashSet3) {
      int n8 = solidValue + 1;
      HashSet<Long> hashSet = new HashSet<>();
      ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
      hashSet.add(pos.asLong());
      arrayDeque.add(pos);
      int[][] ns2 = new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

      while (!arrayDeque.isEmpty()) {
         if (hashSet.size() >= 2500) {
            return true;
         }

         BlockPos blockPos = arrayDeque.poll();
         int n4 = blockPos.getX();
         int n5 = blockPos.getY();
         int n6 = blockPos.getZ();

         for (int[] ns : ns2) {
            if (hashSet3.add(BlockPos.asLong(n4 + ns[0], n5, n6 + ns[1])) && this.canStepDownAt(terrain, n4 + ns[0], n5, n6 + ns[1])) {
               return true;
            }

            enqueueWalkableCell(terrain, hashSet, arrayDeque, n4 + ns[0], n5, n6 + ns[1], n8);
            if (n5 - 1 >= n8 && !terrain.solid(n4 + ns[0], n5 + 1, n6 + ns[1])) {
               enqueueWalkableCell(terrain, hashSet, arrayDeque, n4 + ns[0], n5 - 1, n6 + ns[1], n8);
            }

            for (int n = 1; n <= 2; n++) {
               enqueueWalkableCell(terrain, hashSet, arrayDeque, n4 + ns[0], n5 + n, n6 + ns[1], n8);
            }

            enqueueWalkableCell(terrain, hashSet, arrayDeque, n4 + 2 * ns[0], n5, n6 + 2 * ns[1], n8);
            enqueueWalkableCell(terrain, hashSet, arrayDeque, n4 + 2 * ns[0], n5 + 1, n6 + 2 * ns[1], n8);
         }

         for (int n3 = -1; n3 <= 1; n3 += 2) {
            for (int n2 = -1; n2 <= 1; n2 += 2) {
               enqueueWalkableCell(terrain, hashSet, arrayDeque, n4 + n3, n5, n6 + n2, n8);
            }
         }
      }

      return false;
   }

