   private void loadRecordingMirror() {
      this.mirrorIntegerMap.clear();
      this.mirrorBlockPosMap.clear();
      this.mirrorValue = 0;
      if (this.followRecording.isEnabled() && this.folderOpenFlag) {
         ElseBuilder loadedSchematic = this.schematicBuilder.getLoadedSchematic();
         if (loadedSchematic != null) {
            String string = this.schematicBuilder.getLoadedFileName() != null && !this.schematicBuilder.getLoadedFileName().isBlank()
               ? this.schematicBuilder.getLoadedFileName()
               : loadedSchematic.orElse;
            boolean flag = this.jsonMirror != null && string.equals(this.mirrorText);
            JsonMirror jsonMirror = flag ? this.jsonMirror : RecordingsUnnamedUtils.getJsonMirror(string);
            if (jsonMirror == null) {
               this.jsonMirror = null;
               this.mirrorText = null;
            } else if (!jsonMirror.canMirrorRotation(string, this.rotationEnumFolder.getCurrentIndex(), this.enumHelper.getCurrentIndex())) {
               this.jsonMirror = null;
               this.mirrorText = null;
               if (this.enableModuleText == null || !this.enableModuleText.equals(string)) {
                  this.enableModuleText = string;
                  this.logDebugMessage(
                     "\u00a7e[Recording]\u00a7r found one for \u00a7f" + string + "\u00a7r but it was made at a different rotation/mirror - ignoring it."
                  );
               }
            } else {
               this.enableModuleText = null;
               int n = 0;

               for (com.corz.client.utils.JsonMirror.Entry entry : jsonMirror.getMirrorRotationMirrorRotationMap()) {
                  BlockPos blockPos = new BlockPos(this.originX + entry.value3, this.originY + entry.value2, this.originZ + entry.value);
                  this.mirrorIntegerMap.put(blockPos.asLong(), n++);
                  this.mirrorBlockPosMap.put(blockPos.asLong(), new BlockPos(this.originX + entry.value6, this.originY + entry.value5, this.originZ + entry.value4));
               }

               this.mirrorValue = n;
               if (this.mirrorValue > 0 && !flag) {
                  this.logDebugMessage("\u00a7a[Recording]\u00a7r following your build order - \u00a7f" + this.mirrorValue + "\u00a7r block(s) from " + string);
               }

               this.jsonMirror = jsonMirror;
               this.mirrorText = string;
            }
         }
      }
   }

