   static int classifyBlockPassability(BlockState state, BlockPos pos) {
      if (state == null) {
         return -1;
      } else if (state.isAir()) {
         return 0;
      } else if (WalkRouteFinder.isHazardBlock(state)) {
         return 5;
      } else if (WalkRouteFinder.isPartialHeightBlock(state) && !(state.getBlock() instanceof HopperBlock)) {
         return 6;
      } else {
         ClientWorld clientWorld = MinecraftClient.getInstance().world;
         if (clientWorld == null) {
            return !state.getFluidState().isEmpty() ? 1 : (state.isReplaceable() ? 0 : 4);
         } else {
            VoxelShape voxelShape = state.getCollisionShape(clientWorld, pos);
            if (voxelShape.isEmpty()) {
               return state.getFluidState().isEmpty() ? 0 : 1;
            } else {
               double d = voxelShape.getMax(Axis.Y);
               return d <= 0.26 ? 2 : (d < 0.8 ? 3 : 4);
            }
         }
      }
   }

