   private int countConnectedRails(BlockPos pos) {
      BlockState blockState2 = mc.world.getBlockState(pos);
      if (!(blockState2.getBlock() instanceof AbstractRailBlock abstractRailBlock)) {
         return 0;
      } else {
         var shapeProperty = abstractRailBlock.getShapeProperty();
         if (!blockState2.contains(shapeProperty)) {
            return 0;
         } else {
            int n = 0;

            for (BlockPos down : getRailNeighbours(pos, blockState2.get(shapeProperty))) {
               BlockPos supportBlockNear = this.findSupportBlockNear(down);
               if (supportBlockNear != null) {
                  BlockState blockState = mc.world.getBlockState(supportBlockNear);
                  Property<RailShape> property = ((AbstractRailBlock)blockState.getBlock()).getShapeProperty();
                  if (blockState.contains(property)) {
                     for (BlockPos blockPos : getRailNeighbours(supportBlockNear, blockState.get(property))) {
                        if (isSameColumn(blockPos, pos)) {
                           n++;
                           break;
                        }
                     }
                  }
               }
            }

            return n;
         }
      }
   }

   private void placeOrientedBlock(BlockState state) {
      this.setOwnerSneak(this.bodyYieldsFlag);
      Vec3d vec3d = mc.player.getEyePos();
      double d = this.reachSetting.getValue();
      float f = mc.player.getYaw();
      float pitch2 = mc.player.getPitch();
      BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d, f, pitch2, d);
      if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
         && blockHitResult.getBlockPos().offset(blockHitResult.getSide()).equals(this.currentTargetPos)) {
         int n = this.getSchematicCells(this.currentTargetPos);
         if (n < 0) {
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "target vanished");
         } else if (!this.canConstrainedStrand(this.currentTargetPos)) {
            int n2 = SelectedInventoryUtils.getValue(getItemForBlockState(state));
            if (n2 == -1) {
               this.handleStuckProgress("no material");
            } else {
               ItemStack itemStack = mc.player.getInventory().getStack(n2);
               BlockState placementState = PlacementBlockUtils.getPlacementState(mc.player, Hand.MAIN_HAND, itemStack, blockHitResult);
               if (placementState != null
                  && placementState.getBlock() == state.getBlock()
                  && BottleLevelUtils.getEmpty(getBlockStatePropertyMap(state), getBlockStatePropertyMap(placementState), getIgnoredStairProperties(state)).empty) {
                  this.orientedPredictionValue = 0;
                  this.blockState2HalfBlock = placementState;
                  boolean flag = isFlaggedBlockState(mc.world.getBlockState(blockHitResult.getBlockPos()));
                  if (flag && this.placeOrientedFlag) {
                     this.banFaceHittingGui(blockHitResult, "oriented place");
                  } else {
                     if (flag) {
                        this.setOwnerSneak(true);
                        if (this.builderValue < this.getRevertedPlacement()) {
                           this.transitionToState(AutoBuilder.State.SNEAK_SETTLE, "need sneak first");
                           return;
                        }
                     }

                     if (!this.hasTrackedPosEntry(blockHitResult.getBlockPos())) {
                        if (!this.rejectPlacementFaceCertificate(blockHitResult)) {
                           this.selectHotbarSlot(n2);
                           this.guardAccessTime = hashPosAndDirection(this.currentTargetPos, blockHitResult.getSide());
                           this.blockHitResultEgressStand = blockHitResult;
                           this.recordHitForCurrentTarget(blockHitResult);
                           this.performBlockInteraction(blockHitResult);
                           if (this.swing.isEnabled()) {
                              mc.player.swingHand(Hand.MAIN_HAND);
                           }

                           this.worldBlockMap.put(this.currentTargetPos.asLong(), this.moduleTick);
                           this.recordPlacementAttempt(blockHitResult, state);
                           this.realignHitAutoAggro.restart();
                           this.transitionToState(AutoBuilder.State.WAIT_CONFIRMATION, "oriented clicked, awaiting world confirm");
                        }
                     }
                  }
               } else {
                  long long2 = this.currentTargetPos.asLong();
                  this.orientedPredictionValue = long2 == this.lastOrientedPredictionKey ? this.orientedPredictionValue + 1 : 1;
                  this.lastOrientedPredictionKey = long2;
                  if (this.orientedPredictionValue >= 8) {
                     this.orientedPredictionValue = 0;
                     this.rejectPoseNoLineOfSight(null, "oriented prediction keeps drifting from this stand");
                  } else {
                     this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "oriented prediction drifted before click");
                  }
               }
            }
         }
      } else {
         long l = this.currentTargetPos.asLong();
         this.orientedPredictionValue = l == this.lastOrientedPredictionKey ? this.orientedPredictionValue + 1 : 1;
         this.lastOrientedPredictionKey = l;
         if (this.orientedPredictionValue >= 8) {
            this.orientedPredictionValue = 0;
            this.rejectPoseNoLineOfSight(null, "no oriented aim survives to the click from this pose");
         } else {
            this.transitionToState(AutoBuilder.State.ALIGN_ROTATION, "oriented ray lost before click");
         }
      }
   }

