   private boolean hasMoreAuctionPagesToScan() {
      if (!this.hasRootBase() || this.listingWordingValue + 1 >= 20) {
         return false;
      } else {
         return this.pageListingValue > 0
            ? this.listingWordingValue + 1 < this.listingPageStart + this.maxAhPages.getValue()
            : this.listingWordingValue + 1 < this.maxAhPages.getValue() || this.moduleTick - this.lastTickBoardListing < 600;
      }
   }

