               this.blockers = null;
               this.stepIndex = -1;
               this.stepsTimeBudget.updateTimeMax();
               this.logDebugMessage(
                  "\u00a7b[Liveness]\u00a7r escalation COMPLETION_PLAN -> ISLAND_SEED: a faceless member is seeded by a floor pillar (reclaimed on exit)"
               );
