   private BlockPos findNearerBridgingCell(BlockPos pos, BlockPos replaceableAir, BlockPos pos2) {
      int abs5 = Math.abs(replaceableAir.getX() - pos2.getX());
      int abs6 = Math.abs(replaceableAir.getZ() - pos2.getZ());
      if (Math.max(abs5, abs6) <= 3) {
         return replaceableAir;
      } else {
         BlockPos blockPos5 = null;
         int maxValue7 = Integer.MAX_VALUE;
         int n8 = -1;

         for (int n4 = -4; n4 <= 4; n4++) {
            for (int n3 = -4; n3 <= 4; n3++) {
               if (Math.abs(n4) + Math.abs(n3) <= 4) {
                  BlockPos blockPos = new BlockPos(pos2.getX() + n4, pos2.getY() - 1, pos2.getZ() + n3);
                  if (this.getSchematicCells(blockPos) < 0
                     && !this.cellTemporarySet.contains(blockPos.asLong())
                     && !this.isSequenceRecentlyAttempted(pos, blockPos)) {
                     BlockState blockState = mc.world.getBlockState(blockPos);
                     if ((blockState.isAir() || blockState.isReplaceable()) && this.describeObserverPulseHazard(blockPos) == null && !this.isFacedByPiston(blockPos)) {
                        int n = Math.abs(replaceableAir.getX() - blockPos.getX()) + Math.abs(replaceableAir.getZ() - blockPos.getZ());
                        int n2 = abs5 + abs6 - n;
                        if (n2 >= 2 && (n < maxValue7 || n == maxValue7 && n2 > n8)) {
                           blockPos5 = blockPos;
                           maxValue7 = n;
                           n8 = n2;
                        }
                     }
                  }
               }
            }
         }

         return blockPos5;
      }
   }

   private ProofContainerData findContainerAccessProof(BlockPos pos, Set<Long> set2) {
      if (mc.world != null && mc.player != null) {
         BlockState blockState = mc.world.getBlockState(pos);
         ChestTrappedType chestTrappedType = ChestTrappedType.getChestTrapped(blockState.getBlock());
         if (chestTrappedType == null) {
            return null;
         } else {
            boolean flag = chestTrappedType == ChestTrappedType.CHEST || chestTrappedType == ChestTrappedType.TRAPPED_CHEST;
            BlockPos abovePos = pos.up();
            boolean aboveSolid = !mc.world.getBlockState(abovePos).getCollisionShape(mc.world, abovePos).isEmpty();
            if (!ProofContainerData.canFlag(flag, aboveSolid)) {
               return null;
            } else {
               Integer integer = blockState.contains(Properties.HORIZONTAL_FACING) ? blockState.get(Properties.HORIZONTAL_FACING).ordinal() : null;
               var geometryImpl = new com.corz.client.utils.ProofContainerData.Geometry() {
                  @Override
                  public boolean isOpenUnbuiltCell(long autoBuilderValue) {
                     BlockPos long2 = BlockPos.fromLong(autoBuilderValue);
                     return !AutoBuilder.this.cellTemporarySet.contains(autoBuilderValue)
                        && AutoBuilder.this.getSchematicCells(long2) < 0
                        && WalkRouteFinder.isStandable(Module.mc.world, long2);
                  }

                  @Override
                  public boolean hasCollisionShapeAt(long collisionValue) {
                     BlockPos long3 = BlockPos.fromLong(collisionValue);
                     return !Module.mc.world.getBlockState(long3).getCollisionShape(Module.mc.world, long3).isEmpty();
                  }
               };
               double d = this.reachSetting.getValue();
               double d2 = d * d;
               BlockPos feetBlockPos = this.getFeetBlockPos();

               for (long[] ls : ProofContainerData.getItems(pos.asLong(), integer, geometryImpl)) {
                  if (set2 == null || !set2.contains(ls[0])) {
                     BlockPos blockPos = BlockPos.fromLong(ls[0]);
                     double[] ds = ProofContainerData.getAmounts(pos.asLong(), (int)ls[1]);
                     Vec3d vec3d = new Vec3d(ds[0], ds[1], ds[2]);
                     Vec3d vec3d2 = getStandingEyePos(blockPos);
                     if (!(vec3d2.squaredDistanceTo(vec3d) > d2)) {
                        float[] fs = MathClampUtils.getWrapDegrees(vec3d2, vec3d);
                        BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d2, fs[0], fs[1], d);
                        if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(pos)) {
                           return ProofContainerData.getProofContainerData(
                              pos.asLong(),
                              ls[0],
                              (int)ls[1],
                              blockPos.equals(feetBlockPos) ? "at_stand" : "walkable",
                              getContainerScreenType(chestTrappedType)
                           );
                        }
                     }
                  }
               }

               return null;
            }
         }
      } else {
         return null;
      }
   }

