   private boolean canReachRepairTarget(BlockPos pos) {
      double d = this.reachSetting.getValue();
      Vec3d vec3d = mc.player.getEyePos();
      if (vec3d.squaredDistanceTo(Vec3d.ofCenter(pos)) <= d * d && this.isWithinReachFromEye(pos)) {
         this.noneRepair.handleNone(pos.asLong(), this.getFeetBlockPos().asLong(), "in_reach");
         return true;
      } else {
         WalkRouteFinder.StandStats standStats = new WalkRouteFinder.StandStats();
         BlockPos standPositionWithOffsets = WalkRouteFinder.findStandPositionWithOffsets(
            pos, d, null, blockPos2x -> this.isWithinReachFromStand(pos, blockPos2x), standStats, WalkRouteFinder.STAND_Y_OFFSETS_NARROW
         );
         if (standPositionWithOffsets == null) {
            this.recordRepairFailure(pos, "no visible standing position for repair " + pos.toShortString() + " [" + standStats + "]");
            return false;
         } else {
            BlockPos feetBlockPos = this.getFeetBlockPos();
            if (standPositionWithOffsets.equals(feetBlockPos)) {
               this.noneRepair.handleNone(pos.asLong(), standPositionWithOffsets.asLong(), "stand:here");
               return true;
            } else {
               this.rebuildReachableComponent();
               if (this.component.contains(standPositionWithOffsets.asLong())) {
                  this.noneRepair
                     .handleNone(pos.asLong(), standPositionWithOffsets.asLong(), "stand:" + standPositionWithOffsets.toShortString() + "/component(" + this.component.size() + ")");
                  return true;
               } else {
                  List<BlockPos> list = this.findPathWithoutLimit(feetBlockPos, standPositionWithOffsets, com.corz.client.utils.OpsCalls.Phase.GO_PATH);
                  if (list != null && !list.isEmpty()) {
                     this.noneRepair.handleNone(pos.asLong(), standPositionWithOffsets.asLong(), "stand:" + standPositionWithOffsets.toShortString() + "/route(" + list.size() + ")");
                     return true;
                  } else {
                     this.recordRepairFailure(pos, "repair stand " + standPositionWithOffsets.toShortString() + " unreachable: no path to any stand from here");
                     return false;
                  }
               }
            }
         }
      }
   }

