   private boolean hasFluidNearBelowCell(BlockPos pos) {
      if (mc.world != null && !this.completionMissionMap.isEmpty()) {
         BlockPos down = pos.down();
         if (this.isPlacedWaterNotStill(down)) {
            return true;
         } else {
            for (Direction direction : Type.HORIZONTAL) {
               if (this.isPlacedWaterNotStill(down.offset(direction))) {
                  return true;
               }
            }

            boolean flag = this.needsWaterPlacement(down);

            for (Direction direction2 : Type.HORIZONTAL) {
               flag = flag || this.needsWaterPlacement(down.offset(direction2));
            }

            return flag && !this.isPositionStalled(pos);
         }
      } else {
         return false;
      }
   }

