   private boolean shouldRelaxStandRequirement(BlockPos pos, int accessStandLimit, String accessStandText) {
      if (pos != null && accessStandText != null && accessStandLimit >= 3 && this.relaxFacingWhenStuck.isEnabled() && !this.isCompletionPhaseActive() && !this.isRelaxedFacingCell(pos)) {
         int schematicCells2 = this.getSchematicCells(pos);
         if (schematicCells2 < 0) {
            return false;
         } else {
            BlockState blockState = this.targetFluidItems.get(schematicCells2);
            boolean flag = this.getRotateYcounterclockwise(pos, blockState) == null;
            if (!flag || blockState.getBlock() instanceof ChestBlock && accessStandLimit < 9) {
               if (flag
                  || !accessStandText.startsWith("no proven stand - access already failed")
                     && !accessStandText.startsWith("far above active layer")
                     && !accessStandText.startsWith("future-cell stand only")) {
                  AutoBuilder.FailReason failReason = this.parseFailReason(accessStandText);
                  if ((failReason == null || !failReason.pathFailure && failReason != AutoBuilder.FailReason.NO_VALID_STAND)
                     && !accessStandText.startsWith("access family")
                     && StandReachable.getTextsExecutor(accessStandText) != FailureKind.ACCESS) {
                     return false;
                  } else {
                     double d = this.reachSetting.getValue();
                     if (flag) {
                        return WalkRouteFinder.findStandPosition(
                              pos,
                              d,
                              this.cellTemporarySet,
                              pos2 -> !this.isReachRepeatPrevented(pos, pos2)
                                 && !this.hasExecutorProof(pos, pos2)
                                 && this.canPlaceFromEyePosition(pos, blockState, getStandingEyePos(pos2), d, false),
                              null
                           )
                           != null;
                     } else {
                        Predicate<BlockPos> predicate = blockPos2 -> !this.canSealsDeferred(pos, blockPos2)
                           && !this.isReachRepeatPrevented(pos, blockPos2)
                           && !this.hasExecutorProof(pos, blockPos2)
                           && this.canPlaceFromEyePosition(pos, blockState, getStandingEyePos(blockPos2), d, false);
                        if (WalkRouteFinder.findStandPosition(pos, d, null, predicate, null) != null) {
                           return true;
                        } else {
                           boolean add2 = this.completionShortPositionSet.add(pos.asLong());

                           boolean accessStand;
                           try {
                              accessStand = WalkRouteFinder.findStandPosition(pos, d, null, predicate, null) == null;
                           } finally {
                              if (add2) {
                                 this.completionShortPositionSet.remove(pos.asLong());
                              }
                           }

                           return accessStand;
                        }
                     }
                  }
               } else {
                  return true;
               }
            } else {
               return false;
            }
         }
      } else {
         return false;
      }
   }

   private boolean isChestPairTypeMismatched(BlockPos pos, BlockState state) {
      if (this.getRotateYcounterclockwise(pos, state) != null && !this.isRelaxedFacingCell(pos)) {
         Direction direction = state.get(Properties.HORIZONTAL_FACING);
         ChestType chestType = this.isSingleChestWithMatchingFacing(pos.offset(direction.rotateYClockwise()), state)
            ? ChestType.LEFT
            : (this.isSingleChestWithMatchingFacing(pos.offset(direction.rotateYCounterclockwise()), state) ? ChestType.RIGHT : null);
         return chestType != null && chestType != state.get(Properties.CHEST_TYPE);
      } else {
         return false;
      }
   }

