   private boolean tryHandleLayerMaterialStarvation() {
      if (this.complete != AutoBuilder.BuyMode.NONE) {
         return false;
      } else {
         this.updateFreeInventory();
         Set<Item> set = this.getMissingItemSet();
         if (set.isEmpty()) {
            this.layersNeedValue = -1;
            return false;
         } else if (this.layersNeedValue >= 0 && this.confirmMultiValue <= this.layersNeedValue) {
            if (this.moduleTick - this.layersNeedValue < 20) {
               return false;
            } else if (this.canBuyAuto(AutoBuilder.LayerBuyTrigger.STARVED, "the next layers need blocks")) {
               return true;
            } else if (this.layerStats.missingMat > 0
               && this.layerStats.solvableBuildableCount <= 0
               && this.layerStats.solvableMatCount <= 0
               && this.layerStats.deadUnreachableCount <= 0) {
               boolean flag = this.showedBuyText != null || this.countEmptyInventorySlots() == 0 || this.moduleTick < this.buyAutoCooldownUntilTick;
               if (!flag) {
                  for (Item item : set) {
                     Integer integer = this.freeInventoryMap.get(item);
                     if (integer != null && this.moduleTick < integer) {
                        flag = true;
                        break;
                     }
                  }
               }

               if (!flag) {
                  return false;
               } else if (this.restockWhenEmpty.isEnabled() && this.tryStartWithdrawRestock()) {
                  return true;
               } else {
                  BlockPos blockPos = this.isCompletionPhaseActive() ? null : this.findTempCellToRemove(true);
                  if (blockPos != null) {
                     this.blockPos2Exit = blockPos;
                     this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "cleanup while waiting for the auction house");
                     return true;
                  } else {
                     this.updatePressedOptions2();
                     this.notifyWaitingForAuctionHouse();
                     this.transitionToState(AutoBuilder.State.FAILED_NO_MATERIALS, "waiting for the auction house");
                     return true;
                  }
               }
            } else {
               return false;
            }
         } else {
            this.layersNeedValue = this.moduleTick;
            return false;
         }
      }
   }

