   private boolean isContainerTransferLimitReached(ScreenHandler screenHandler) {
      if (this.containerOpenValue >= 0 && this.containerOpenValue < screenHandler.slots.size()) {
         ItemStack itemStack = screenHandler.getSlot(this.containerOpenValue).getStack();
         if (!itemStack.isEmpty() && itemStack.getItem() == this.containerSlotItem && itemStack.getCount() == this.containerSlotValue) {
            this.containerOpenSet.add(this.containerOpenValue);
         }
      }

      this.containerOpenValue = -1;
      return this.completeLoadValue + this.depositCompleteCount >= 160;
   }

   private HashSet<Long> computeWaterFlowCells(BlockPos pos) {
      HashMap<Long, Integer> hashMap = new HashMap<>();
      ArrayDeque<long[]> arrayDeque = new ArrayDeque<>();
      hashMap.put(pos.asLong(), 7);
      arrayDeque.add(new long[]{pos.asLong(), 7L});
      int n2 = 0;

      while (!arrayDeque.isEmpty() && n2++ < 2048 && hashMap.size() < 256) {
         long[] ls = arrayDeque.poll();
         BlockPos fromLong = BlockPos.fromLong(ls[0]);
         BlockPos down = fromLong.down();
         if (this.isReplaceable(down)) {
            Integer integer = hashMap.get(down.asLong());
            if (down.getY() >= pos.getY() - 6 && (integer == null || integer < 7)) {
               hashMap.put(down.asLong(), 7);
               arrayDeque.add(new long[]{down.asLong(), 7L});
            }

            if (ls[0] != pos.asLong()
               || !mc.world.getFluidState(down).isStill()
               || !mc.world.getFluidState(down).isIn(FluidTags.WATER)) {
               continue;
            }
         }

         int n = (int)ls[1];
         if (n > 0) {
            for (Direction direction : Type.HORIZONTAL) {
               BlockPos blockPos = fromLong.offset(direction);
               if (this.isReplaceable(blockPos)) {
                  Integer integer2 = hashMap.get(blockPos.asLong());
                  if (integer2 == null || integer2 < n - 1) {
                     hashMap.put(blockPos.asLong(), n - 1);
                     arrayDeque.add(new long[]{blockPos.asLong(), n - 1});
                  }
               }
            }
         }
      }

      return new HashSet<>(hashMap.keySet());
   }

   private boolean isReachableWalkingCell(BlockPos pos) {
      this.rebuildReachableComponent();
      if (this.component.contains(pos.asLong())) {
         return true;
      } else if (this.component.size() < 600) {
         return false;
      } else {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         if (Math.abs(pos.getX() - feetBlockPos.getX()) <= 20 && Math.abs(pos.getZ() - feetBlockPos.getZ()) <= 20) {
            long l = SHARED_HASH_OPEN.getHashTickCounter();
            if (feetBlockPos.asLong() != this.longContains || l != this.cachedContainsStateKey) {
               this.longContains = feetBlockPos.asLong();
               this.cachedContainsStateKey = l;
               this.containsBooleanMap.clear();
            }

            Boolean booleanValue = this.containsBooleanMap.get(pos.asLong());
            if (booleanValue != null) {
               return booleanValue;
            } else if (this.containsCount <= 0) {
               if (this.blockSchematicStartIndex < 0) {
                  this.blockSchematicStartIndex = this.pendingBlockSchematicIndex;
               }

               return false;
            } else {
               this.containsCount--;
               List<BlockPos> list = this.findGoPath(feetBlockPos, pos);
               boolean flag = list != null && (!list.isEmpty() || feetBlockPos.equals(pos));
               this.containsBooleanMap.put(pos.asLong(), flag);
               return flag;
            }
         } else {
            long hashTickCounter2 = SHARED_HASH_OPEN.getHashTickCounter();
            if (feetBlockPos.asLong() != this.cachedContainsPosKey || hashTickCounter2 != this.cachedContainsStateKeyB) {
               this.cachedContainsPosKey = feetBlockPos.asLong();
               this.cachedContainsStateKeyB = hashTickCounter2;
               this.autoBuilderPositionSet.clear();
               ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
               this.autoBuilderPositionSet.add(feetBlockPos.asLong());
               arrayDeque.add(feetBlockPos);
               int n2 = 0;

               while (!arrayDeque.isEmpty() && this.autoBuilderPositionSet.size() < 6000 && n2++ < 24000) {
                  BlockPos poll2 = arrayDeque.poll();

                  for (Direction direction : Type.HORIZONTAL) {
                     BlockPos blockPos = poll2.offset(direction);
                     if (Math.abs(blockPos.getX() - feetBlockPos.getX()) <= 48 && Math.abs(blockPos.getZ() - feetBlockPos.getZ()) <= 48) {
                        BlockPos offset = null;
                        if (WalkRouteFinder.isStandable(mc.world, blockPos)) {
                           offset = blockPos;
                        } else if (WalkRouteFinder.isStandable(mc.world, blockPos.up())) {
                           offset = blockPos.up();
                        } else {
                           for (int n = 1;
                              n <= 2
                                 && mc.world
                                    .getBlockState(blockPos.down(n - 1))
                                    .getCollisionShape(mc.world, blockPos.down(n - 1))
                                    .isEmpty();
                              n++
                           ) {
                              if (WalkRouteFinder.isStandable(mc.world, blockPos.down(n))) {
                                 offset = blockPos.down(n);
                                 break;
                              }
                           }
                        }

                        if (offset != null && this.autoBuilderPositionSet.add(offset.asLong())) {
                           arrayDeque.add(offset);
                        }
                     }
                  }
               }
            }

            return this.autoBuilderPositionSet.contains(pos.asLong());
         }
      }
   }

   private Context getCachedPlanningContext() {
      if (this.maroonedDigValue == this.moduleTick && this.strategyAssetsData != null) {
         return this.strategyAssetsData;
      } else {
         this.rebuildReachableComponent();
         this.strategyAssetsData = new Context(this.componentKey, this.component.size(), this.computeCellsStateHash(), this.deadlockIsolatedFingerprintU.getMountsStrict().ordinal());
         this.maroonedDigValue = this.moduleTick;
         return this.strategyAssetsData;
      }
   }

   private void updatePlatformMissionProgress() {
      if (!this.linkedHashSet.isEmpty()) {
         int n2 = 0;
         int n3 = 0;
         Iterator<Long> iterator = this.linkedHashSet.iterator();

         while (iterator.hasNext()) {
            long l = iterator.next();
            BlockPos blockPos = BlockPos.fromLong(l);
            int n = this.getSchematicCells(blockPos);
            if (n < 0) {
               iterator.remove();
               n3++;
            } else {
               BlockState blockState = this.targetFluidItems.get(n);
               BlockState blockState2 = mc.world.getBlockState(blockPos);
               if (this.isPlacedStateAcceptable(blockPos, blockState)) {
                  iterator.remove();
                  n2++;
               } else if (!blockState2.isAir() && !blockState2.isReplaceable() && blockState2.getBlock() != blockState.getBlock()) {
                  iterator.remove();
                  n3++;
               }
            }
         }

         if (this.linkedHashSet.isEmpty()) {
            this.platformWorkTime = this.mission;
            if (n3 > 0) {
               this.logDebugMessage(
                  "\u00a7b[WorkPlatform]\u00a7r mission="
                     + this.platformWorkTime
                     + " complete after "
                     + (this.moduleTick - this.platformWorkValue) / 20
                     + "s"
                     + (n3 > 0 ? " blockedForeign=" + n3 : "")
                     + " - reclaiming its dirt as one cleanup pass"
               );
            }

            this.mission = 0L;
            this.platformWorkLastY = Integer.MIN_VALUE;
            this.linkedhashsetSize = 0;
            this.handleAccessRoute("platform_retired");
         }
      }
   }

   private void updateAuctionListingPurchase() {
      if (this.optional != null && this.isBuyAutoScreenSynced()) {
         if (this.moduleTick - this.deliveryAwaitingValue >= this.searchDialogValue) {
            if (this.listingShowedFlag && this.getItemCapacityAfterReserve(this.affordablePagesItem) < this.optional.count()) {
               this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SCAN, "no room for that listing - re-scan");
            } else if (this.hasInventoryRoomForItem(this.affordablePagesItem)) {
               ItemStack itemStack = mc.player.currentScreenHandler.getSlot(this.optional.slot()).getStack();
               if (!itemStack.isEmpty() && itemStack.isOf(this.affordablePagesItem)) {
                  TotalPriceData totalPriceData = this.parseListingSlot(mc.player.currentScreenHandler, this.optional.slot(), this.affordablePagesItem);
                  if (totalPriceData == null || totalPriceData.count() != this.optional.count() || totalPriceData.totalPrice() != this.optional.totalPrice()) {
                     this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SCAN, "listing changed before click - re-scan");
                  } else if (!this.verifyPurchaseDelivery()) {
                     if (this.deliveryUnprovenValue >= 0 && this.countItemInInventory(this.affordablePagesItem) > this.deliveryUnprovenValue) {
                        this.deliveryUnprovenValue = -1;
                        this.buyQuantity = this.getMissingItemCount(this.affordablePagesItem);
                        this.costBuyMap.put(this.affordablePagesItem, this.buyQuantity);
                        if (this.buyQuantity <= 0) {
                           this.advanceToNextBuyItem();
                        } else {
                           this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SCAN, "unproven delivery - re-plan");
                        }
                     } else {
                        this.deliveryUnprovenValue = -1;
                        this.receivedDeliveryValue = this.countItemInInventory(this.affordablePagesItem);
                        this.deliveryListingValue = 0;
                        arrivedDeliveryFlag = false;
                        resetBuildFinishedStats();
                        mc.interactionManager.clickSlot(this.buyAutoSyncId, this.optional.slot(), 0, SlotActionType.PICKUP, mc.player);
                        this.deliveryAwaitingValue = this.moduleTick;
                        this.enterStateWithRandomDelays(AutoBuilder.State.BUY_CONFIRM, "clicked listing");
                     }
                  }
               } else {
                  this.listingVanishedSet.add(this.optional.slot());
                  this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SCAN, "listing vanished before click - re-scan");
               }
            } else if (!this.isHandledClose()) {
               this.finishBuyAndReportCost(
                  this.stockpileInChests.isEnabled() && this.hasSchematicItemInInventory()
                     ? "inventory full and no restock chest with room - mark another"
                     : "inventory full - make room and re-run"
               );
            }
         }
      } else {
         this.enterStateWithRandomDelays(AutoBuilder.State.BUY_SEARCH, "board lost before click");
      }
   }

