   private long computeRegionBoundsHash(int[] unpackSettingValues, long unpackSettingValue) {
      if (unpackSettingValues != null && unpackSettingValues.length >= 6) {
         int[] values2 = PosesBoundaryUtils.getValues(this.reachSetting.getValue());
         long hashHitCountsInBox3 = SHARED_HASH_OPEN.hashHitCountsInBox(unpackSettingValues[0] - values2[0], unpackSettingValues[1] - values2[2], unpackSettingValues[2] - values2[0], unpackSettingValues[3] + values2[0], unpackSettingValues[4] + values2[1], unpackSettingValues[5] + values2[0]);
         if (unpackSettingValue != Long.MIN_VALUE) {
            int n = BlockPos.unpackLongX(unpackSettingValue);
            int unpackLongY2 = BlockPos.unpackLongY(unpackSettingValue);
            int unpackLongZ3 = BlockPos.unpackLongZ(unpackSettingValue);
            int max4 = Math.max(11, 10 + (int)Math.ceil(this.reachSetting.getValue()) + 1);
            long l = SHARED_HASH_OPEN.hashHitCountsInBox(
               Math.min(unpackSettingValues[0], n) - max4,
               Math.min(unpackSettingValues[1], unpackLongY2) - values2[2],
               Math.min(unpackSettingValues[2], unpackLongZ3) - max4,
               Math.max(unpackSettingValues[3], n + 15) + max4,
               Math.max(unpackSettingValues[4], unpackLongY2 + 15) + values2[1],
               Math.max(unpackSettingValues[5], unpackLongZ3 + 15) + max4
            );
            hashHitCountsInBox3 = hashHitCountsInBox3 * -7046029254386353131L ^ Long.rotateLeft(l, 21);
         }

         return hashHitCountsInBox3 == Long.MIN_VALUE ? hashHitCountsInBox3 ^ 1L : hashHitCountsInBox3;
      } else {
         return Long.MIN_VALUE;
      }
   }

