   private boolean isFlatCorridorWalkable(Vec3d vec, BlockPos pos, int floorWorldValue) {
      double d4 = pos.getX() + 0.5;
      double d5 = pos.getZ() + 0.5;
      double d6 = d4 - vec.x;
      double d7 = d5 - vec.z;
      double hypot8 = Math.hypot(d6, d7);
      if (hypot8 < 1.0E-6) {
         return true;
      } else {
         double d9 = -d7 / hypot8 * 0.32;
         double d10 = d6 / hypot8 * 0.32;
         int ceil4 = (int)Math.ceil(hypot8 / 0.25);
         Mutable mutable = new Mutable();

         for (int n2 = 0; n2 <= ceil4; n2++) {
            double d = (double)n2 / ceil4;
            double d2 = vec.x + d6 * d;
            double d3 = vec.z + d7 * d;

            for (int n = -1; n <= 1; n++) {
               mutable.set(MathHelper.floor(d2 + d9 * n), floorWorldValue, MathHelper.floor(d3 + d10 * n));
               if (!WalkRouteFinder.isStandable(mc.world, mutable)) {
                  return false;
               }
            }
         }

         return true;
      }
   }

