   private boolean tryStartIslandExit() {
      if (this.islandAbort != 0L && mc.player != null && mc.world != null) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         if (!mc.player.isOnGround()) {
            return true;
         } else {
            Vec3d vec3d = mc.player.getEyePos();
            double d2 = this.reachSetting.getValue();
            double d3 = (d2 + 1.0) * (d2 + 1.0);
            long long2 = feetBlockPos.down().asLong();
            BlockPos longValue = null;
            int y = Integer.MIN_VALUE;
            double distanceTo = Double.MAX_VALUE;

            for (long l : this.cells) {
               if (l != long2
                  && this.isNearIslandAbortColumn(l)
                  && !this.reclaimExitSet.contains(l)
                  && !this.isCellCoveredOrBlocked(l)
                  && !this.exitIslandSet.contains(mixHashValues(l, feetBlockPos.asLong()))) {
                  BlockPos blockPos = BlockPos.fromLong(l);
                  if (!blockPos.equals(feetBlockPos) && !blockPos.equals(feetBlockPos.up()) && !this.isRiseColumnWalkable(blockPos.getX(), blockPos.getZ(), feetBlockPos)) {
                     double d = vec3d.squaredDistanceTo(Vec3d.ofCenter(blockPos));
                     if (!(d > d3) && this.findReachablePointOnBlock(blockPos, vec3d, d2) != null && (blockPos.getY() > y || blockPos.getY() == y && d < distanceTo)) {
                        longValue = blockPos;
                        y = blockPos.getY();
                        distanceTo = d;
                     }
                  }
               }
            }

            if (longValue != null) {
               int n = this.islandExitIntegerMap.merge(longValue.asLong(), 1, Integer::sum);
               if (n >= 3) {
                  this.reclaimExitSet.add(longValue.asLong());
               }

               this.blockPos2Exit = longValue;
               this.cleanupStaleItems = null;
               this.cleanupExitFlag = false;
               this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "island exit: reclaim own dirt");
               return true;
            } else if (this.cells.contains(long2) && this.isNearIslandAbortColumn(long2)) {
               int n3 = 0;

               BlockPos down;
               for (down = feetBlockPos.down(); this.cells.contains(down.asLong()) && n3 < 64; down = down.down()) {
                  n3++;
               }

               boolean flag = this.isSolidNonReplaceableAt(down.getX(), down.getY(), down.getZ());
               if (!flag && n3 < 2) {
                  BlockPos adjacentRiseCell = this.findAdjacentRiseCell(feetBlockPos);
                  if (adjacentRiseCell != null) {
                     this.ledgeAlongSet.add(ClearanceHeadroomUtils.packHeadroomKey(adjacentRiseCell.getX(), adjacentRiseCell.getZ()));
                     this.blockPos5IslandExit = adjacentRiseCell;
                     this.islandExitValue = 3;
                     this.islandStepValue = 0;
                     this.updatePressedOptions2();
                     this.path.clear();
                     this.transitionToState(AutoBuilder.State.ISLAND_MIGRATE, "island exit: step back along the ledge");
                     return true;
                  } else {
                     BlockPos down2 = down;

                     for (int n2 = 0; n2 < 64 && !this.isSolidNonReplaceableAt(down2.getX(), down2.getY(), down2.getZ()); n2++) {
                        down2 = down2.down();
                     }

                     int max4 = Math.max(0, feetBlockPos.getY() - (down2.getY() + 1));
                     double health4 = mc.player.getHealth();
                     if (max4 > 2 && !ClearanceHeadroomUtils.exceedsHeadroomThreshold(max4, health4)) {
                        return this.releaseIslandOwner(
                           "stopped: no safe way down from " + feetBlockPos.toShortString() + " (drop " + max4 + ", health " + formatTwoDecimals(health4) + ")"
                        );
                     } else {
                        return this.tryDescendThroughOwnedDirt() ? true : this.releaseIslandOwner("stopped: descent refused at " + feetBlockPos.toShortString());
                     }
                  }
               } else {
                  return this.tryDescendThroughOwnedDirt() ? true : this.releaseIslandOwner("stopped: descent refused at " + feetBlockPos.toShortString());
               }
            } else {
               return this.releaseIslandOwner("complete");
            }
         }
      } else {
         return false;
      }
   }

