   private void refreshTargetStandCandidates(double targetsConfirmsValue) {
      if (this.confirms != this.targetsConfirmsValue || this.moduleTick - this.lastTickTargetsConfirms >= 10) {
         boolean flag = this.confirms != this.targetsConfirmsValue;
         this.lastTickTargetsConfirms = this.moduleTick;
         this.targetsConfirmsValue = this.confirms;
         this.targets.clear();
         this.budgetExhaustedSet.clear();
         int n2 = 0;
         BlockPos blockPos3 = mc.player == null ? null : this.getFeetBlockPos();

         for (Entry<Long, BlockState> entry : this.completionMissionMap.entrySet()) {
            if (n2 >= 24) {
               break;
            }

            BlockPos fromLong = BlockPos.fromLong(entry.getKey());
            if (blockPos3 == null || !(fromLong.getSquaredDistance(blockPos3) > 1600.0)) {
               BlockState blockState = entry.getValue();
               if (this.hasOrientationRequirement(fromLong, blockState) && !this.isRelaxedBlockShortCell(fromLong) && !this.isCellBlockedByTemporaryNeighbors(fromLong)) {
                  n2++;
                  List<BlockPos> list = this.findStandCandidatesAround(fromLong, blockState, targetsConfirmsValue, 3);
                  this.targets.put(entry.getKey(), list);

                  for (BlockPos blockPos : list) {
                     this.budgetExhaustedSet.add(blockPos.asLong());
                  }

                  if (flag) {
                     Integer integer = this.targetsConfirmsIntegerMap.get(entry.getKey());
                     int n = list.size();
                     if (integer != null && integer > 0 && n == 0) {
                        this.recordAccessLostProgram(fromLong, this.confirmSlowBlockPos, integer, this.targetsConfirmsListMap.get(entry.getKey()));
                     }
                  }

                  this.targetsConfirmsIntegerMap.put(entry.getKey(), list.size());
                  if (!list.isEmpty()) {
                     this.targetsConfirmsListMap.put(entry.getKey(), List.copyOf(list));
                  }
               }
            }
         }

         this.targetsConfirmsIntegerMap.keySet().retainAll(this.targets.keySet());
         this.targetsConfirmsListMap.keySet().retainAll(this.targets.keySet());
      }
   }

