   private Bucket getTickActivityBucket() {
      Class<Bucket> classValue = Bucket.class;

      return switch (this.state2Builder) {
         case SELECT_TARGET -> Bucket.DEAD_SCHEDULER;
         case GO_TO_POSITION, SCAFFOLD_UP, TEMP_SUPPORT, CLEANUP_TEMP, TEMP_BRIDGE, ISLAND_MIGRATE, SIDE_RUN -> mc.player != null
               && mc.player.getVelocity().horizontalLengthSquared() > 1.0E-4
            ? Bucket.PRODUCTIVE_MOVEMENT
            : Bucket.DEAD_MOVEMENT;
         case JUMP_PLACE, PLACE_BLOCK, POST_INTERACT, WATERLOG, CRAFTER_CONFIG, STATE_REPAIR -> Bucket.PLACEMENT;
         case ALIGN_ROTATION, SNEAK_SETTLE -> this.staleCount <= 20 || this.placementExplicit != null && this.placementExplicit.isRevalidateAlign()
            ? Bucket.CAMERA_PREP
            : Bucket.DEAD_AIM;
         case WAIT_CONFIRMATION -> Bucket.CONFIRMATION;
         case INVENTORY_SWAP, RESTOCK_GO, RESTOCK_OPEN, RESTOCK_WITHDRAW, RESTOCK_DEPOSIT, RESTOCK_CLOSE -> Bucket.INVENTORY;
         case RECOVER_STUCK -> Bucket.DEAD_MOVEMENT;
         default -> Bucket.OTHER;
      };
   }

