   private void updateFinalCleanupPass() {
      if (!this.blockPosLongArrayMap.isEmpty()) {
         this.updatePressedOptions2();
      } else {
         if (this.unsolvableTailTexts != null && this.hasUnbuiltSchematicCell()) {
            if (this.cells.size() < this.unsolvableSequenceValue) {
               this.unsolvableSequenceValue = this.cells.size();
               this.lastTickPass = this.moduleTick;
            }

            if (this.cells.size() <= this.countCellsWithOffset()
               || !this.removeTempAfter.isEnabled()
               || this.cleanupPassFlag && this.appearedFlag
               || this.moduleTick - this.lastTickPass > 6000) {
               String[] strings = this.unsolvableTailTexts;
               this.unsolvableTailTexts = null;
               this.completionMissionFlag = true;
               this.digMissionFlag = false;
               this.handleReportedUnsolvable(strings[0], strings[1], strings[2]);
               return;
            }
         } else if (this.hasUnbuiltSchematicCell()) {
            this.digMissionFlag = false;
            this.appearedWorkFlag = false;
            this.transitionToState(AutoBuilder.State.SELECT_TARGET, "new work appeared");
            return;
         }

         if (this.removeTempAfter.isEnabled() && !this.cells.isEmpty()) {
            if (!this.digMissionFlag) {
               this.digMissionFlag = true;
               this.cleanupPassFlag = false;
               this.cleanupMissionFlag = false;
               this.appearedFlag = false;
               this.passCount = 0;
               this.passValue = Integer.MIN_VALUE;
               this.blockers = null;
               this.stepIndex = -1;
               this.cleanupOwnedValue = 0;
               this.linkedHashSet.clear();
               this.mission = 0L;
               this.platformWorkTime = 0L;
               this.platformWorkLastY = Integer.MIN_VALUE;
               this.linkedhashsetSize = 0;
               this.coverBodyMap.clear();
               this.cleanupExitFlag = false;
               this.passCleanupItems.clear();
               this.setSupportText("CLEANUP_PASS", "build complete - removing " + this.cells.size() + " temp/scaffold blocks");
            }

            if (this.cleanupPassFlag && this.cells.size() != this.passCleanupValue) {
               this.cleanupPassFlag = false;
               this.cleanupMissionFlag = false;
            }

            if (this.cleanupPassFlag && this.lastTickStepsCompletion != this.passValue) {
               this.passValue = this.lastTickStepsCompletion;
               if (++this.passCount >= 2 && !this.appearedFlag) {
                  this.appearedFlag = true;
                  this.cleanupPassFlag = false;
                  this.cleanupMissionFlag = false;
                  this.clearCoverTracking();
                  this.logDebugMessage(
                     "\u00a7e[FinalCleanup]\u00a7r gave up twice with "
                        + this.cells.size()
                        + " temp(s) left - re-planning with a "
                        + 16
                        + "-block window and the lifelines released"
                  );
               }
            }

            if (this.cleanupMissionFlag && !this.cleanupPassFlag && mc.player != null) {
               Vec3d vec3d = mc.player.getEyePos();
               double d = this.reachSetting.getValue();
               if (this.canFlag(this.getFeetBlockPos(), vec3d, d, d * d)) {
                  return;
               }
            }

            if (this.cleanupMissionFlag || !this.cleanupPassFlag || !this.tryDescendThroughOwnedDirt()) {
               if (this.cellsUnpackWorkspaceReturn != null || !this.areUnclaimedCellsAllBelow(this.getFeetBlockPos()) || !this.startHangingCellsDescent(this.getFeetBlockPos(), this.getFeetBlockPos().getY() - 2)) {
                  if (this.cleanupPassFlag && this.moduleTick - this.lastTickStepsCompletion > 1200) {
                     this.cleanupPassFlag = false;
                     this.clearCoverTracking();
                  }

                  if (!this.cleanupMissionFlag && this.moduleTick >= this.cleanupOwnedValue) {
                     BlockPos longValue = this.findNearestReachableCell();
                     if (longValue == null && this.cleanupPassFlag) {
                        longValue = this.findTempCellToRemove(true);
                     }

                     if (longValue == null && this.cleanupPassFlag) {
                        longValue = this.findRemovableTempBlock(true);
                     }

                     if (longValue != null) {
                        this.blockPos2Exit = longValue;
                        this.cleanupExitFlag = false;
                        this.transitionToState(AutoBuilder.State.CLEANUP_TEMP, "final cleanup: route to owned temp");
                        return;
                     }

                     this.cleanupOwnedValue = this.moduleTick + 40;
                  }

                  if (!this.cleanupMissionFlag && !this.cleanupPassFlag && mc.player != null) {
                     Vec3d vec3d2 = mc.player.getEyePos();
                     double d2 = this.reachSetting.getValue();
                     if (this.canFlag(this.getFeetBlockPos(), vec3d2, d2, d2 * d2)) {
                        return;
                     }
                  }

                  this.updatePressedOptions2();
                  this.path.clear();
               }
            }
         } else {
            this.digMissionFlag = false;
            this.updatePressedOptions2();
            this.path.clear();
            this.resetPillarTracking();
            if (!this.appearedWorkFlag) {
               this.appearedWorkFlag = true;
               this.logDebugMessage(
                  "\u00a7a[Completion]\u00a7r verified again after cleanup: 0 required cells remain, owned temp left " + this.cells.size() + " - DONE"
               );
            }
         }
      }
   }

