   private BlockPos findRemovableTempBlock(boolean autoBuilderFlag) {
      if (this.removeTempAfter.isEnabled() && !this.cells.isEmpty()) {
         BlockPos feetBlockPos = this.getFeetBlockPos();
         ArrayList<BlockPos> arrayList = new ArrayList<>();
         Iterator<Long> iterator = this.cells.iterator();

         while (iterator.hasNext()) {
            long l = iterator.next();
            BlockPos blockPos = BlockPos.fromLong(l);
            if (mc.world.getBlockState(blockPos).isAir()) {
               iterator.remove();
               if (this.unknown != null) {
                  this.unknown.isRemove(l);
               }
            } else if (!this.isCellCoveredOrBlocked(l)
               && !this.isMissionOwnedCell(l)
               && !this.isNearIslandAbortColumn(l)
               && (
                  autoBuilderFlag
                     || this.moduleTick - this.staleSweepMap.getOrDefault(l, this.moduleTick) > 6000
                     || this.enableModuleMap.getOrDefault(l, 0L) == this.platformWorkTime
               )
               && !this.cells.contains(blockPos.up().asLong())
               && !blockPos.equals(feetBlockPos.down())
               && !blockPos.equals(feetBlockPos)
               && !blockPos.equals(feetBlockPos.up())) {
               arrayList.add(blockPos);
            }
         }

         boolean nearPendingCompletionCell = this.isNearPendingCompletionCell(feetBlockPos);
         arrayList.sort(
            Comparator.<BlockPos, Boolean>comparing(blockPos2x -> nearPendingCompletionCell && blockPos2x.getY() < feetBlockPos.getY() - 1)
               .thenComparing(blockPosx -> this.enableModuleMap.getOrDefault(blockPosx.asLong(), 0L) != this.platformWorkTime)
               .thenComparingDouble(blockPos2x -> blockPos2x.getSquaredDistance(feetBlockPos))
         );
         if (nearPendingCompletionCell) {
            arrayList.removeIf(blockPos2x -> blockPos2x.getY() < feetBlockPos.getY() - 1 && !autoBuilderFlag);
         }

         int n = 0;
         int n2 = RecoverReadmitUtils.getValue(this.digMissionFlag, arrayList.size());
         long nanoTime2 = System.nanoTime();

         for (BlockPos arrayItem : arrayList) {
            n++;
            if (n > n2 || !this.digMissionFlag && System.nanoTime() - nanoTime2 > 8000000L) {
               break;
            }

            if (mc.player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(arrayItem)) <= this.reachSetting.getValue() * this.reachSetting.getValue()
               && this.isWithinReachFromEye(arrayItem)) {
               return arrayItem;
            }

            if (this.hasReachableStandForTarget(arrayItem, feetBlockPos)) {
               return arrayItem;
            }
         }

         return null;
      } else {
         return null;
      }
   }

