   private void updateRestockContainerOpening() {
      if (this.restockContainerBlockPos != null
         && mc.world != null
         && ChestTrappedType.getChestTrapped(mc.world.getBlockState(this.restockContainerBlockPos).getBlock()) != null) {
         this.containerGoneFlag = false;
         if (this.isContainerScreenOpen()) {
            this.syncId = mc.player.currentScreenHandler.syncId;
            this.containerGoneCount++;
            this.completeLoadValue = 0;
            this.depositCompleteCount = 0;
            this.containerScreenValue = this.moduleTick - 2;
            this.containerOpenSet.clear();
            this.containerOpenValue = -1;
            this.recordRestockContainerContents();
            switch (this.restockPurpose) {
               case WITHDRAW:
                  this.transitionToState(AutoBuilder.State.RESTOCK_WITHDRAW, "container open");
                  break;
               case DEPOSIT:
                  this.transitionToState(AutoBuilder.State.RESTOCK_DEPOSIT, "container open - stockpiling");
                  break;
               case SURVEY:
                  this.transitionToState(AutoBuilder.State.RESTOCK_CLOSE, "container open - reading contents");
            }
         } else if (mc.currentScreen == null) {
            if (InventoryStackUtilsHandle.canFlagForObject(this)) {
               this.updatePressedOptions2();
               Vec3d vec3d = this.getRestockContainerClickPoint();
               float[] fs = MathClampUtils.getWrapDegrees(mc.player.getEyePos(), vec3d);
               float[] aimRotation2 = this.computeAimRotation(fs[0], fs[1]);
               if (this.moduleTick - this.containerScreenValue >= 8) {
                  BlockHitResult blockHitResult = this.raycastBlockSideForAim(mc.player.getEyePos(), aimRotation2[0], aimRotation2[1], this.reachSetting.getValue());
                  if (blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && blockHitResult.getBlockPos().equals(this.restockContainerBlockPos)) {
                     this.recordHitForCurrentTarget(blockHitResult);
                     this.performBlockInteraction(blockHitResult);
                     if (this.swing.isEnabled()) {
                        mc.player.swingHand(Hand.MAIN_HAND);
                     }

                     this.containerScreenValue = this.moduleTick;
                  }
               }

               if (this.staleCount > 120) {
                  this.timedOpenCount++;
                  if (this.timedCount < 2 && this.repositionToNextRestockFrontStand()) {
                     this.containerOpenCount++;
                     return;
                  }

                  this.markRestockContainerFailed(this.restockContainerBlockPos);
                  this.onRestockPurposeFinished("open timed out");
               }
            }
         }
      } else {
         if (this.restockContainerBlockPos != null) {
            this.markRestockContainerFailed(this.restockContainerBlockPos);
         }

         this.onRestockPurposeFinished("container gone");
      }
   }

   private boolean isBlockCriticalForAccess(BlockPos pos, BlockPos pos2) {
      Terrain terrain = WalkableRegionAnalyzer.withStrictDiagonals(WalkRouteFinder.createTerrainView(mc.world));
      Terrain withStrictDiagonals = WalkableRegionAnalyzer.withStrictDiagonals(
         (worldValue, candidateY, candidateZ) -> (worldValue != pos.getX() || candidateY != pos.getY() || candidateZ != pos.getZ()) && terrain.solid(worldValue, candidateY, candidateZ)
      );
      int n = 40;
      return WalkableRegionAnalyzer.countReachableCells(withStrictDiagonals, pos2.getX(), pos2.getY(), pos2.getZ(), n) < n
         && WalkableRegionAnalyzer.countReachableCells(terrain, pos2.getX(), pos2.getY(), pos2.getZ(), n) >= n;
   }

