   private void onTempSupportFailed(String islandPathText) {
      DescentReusable descentReusable = this.unknown;
      long l2 = descentReusable == null ? 0L : descentReusable.getReusableDescentTime();
      long l3 = this.blockPos2SupportConstructive == null ? 0L : this.blockPos2SupportConstructive.asLong();
      boolean flag = descentReusable != null && l3 != 0L && descentReusable.getNext() == l3 && !this.isEnableModuleValueActive(l2);
      if (this.blockPos2SupportConstructive != null
         && this.blockPos3SupportConstructive != null
         && this.supportFloorMap.getOrDefault(this.blockPos3SupportConstructive.asLong(), 0L) == this.blockPos2SupportConstructive.asLong()
         && !this.cells.contains(this.blockPos3SupportConstructive.asLong())) {
         this.sequenceConstructiveMap.put(DepsReasonData.packTargetStandKey(this.blockPos2SupportConstructive.asLong(), this.blockPos3SupportConstructive.asLong()), this.moduleTick);
         if (islandPathText.contains("no_constructive_sequence")
            && !islandPathText.contains("NATURAL_PATH_AVAILABLE")
            && !this.pathAvailableMap.containsKey(this.blockPos2SupportConstructive.asLong())) {
            this.handleConfirmsHandover(this.blockPos2SupportConstructive, this.blockPos3SupportConstructive);
         }
      }

      boolean flag2 = islandPathText.startsWith("no_path") || "unstable_body".equals(islandPathText);
      if (flag2
         && this.blockPos2SupportConstructive != null
         && this.blockPos2SupportConstructive.asLong() == this.islandAbort
         && this.unstableMap.merge(this.islandAbort, 1, Integer::sum) % 4 == 0) {
         flag2 = false;
      }

      if (this.blockPos2SupportConstructive != null && this.blockPos2SupportConstructive.asLong() == this.islandAbort && !flag2) {
         this.islandHandover.put(this.islandAbort, this.moduleTick);
         this.islandHandoverMap.merge(this.islandAbort, 1, Integer::sum);
      }

      this.onTemporaryBlockPlaceFailed(islandPathText);
      this.setBudgetExhaustedReason("temp support failed: " + islandPathText);
      this.releaseUnknownOwnerForTarget("constructive support failed: " + islandPathText);
      if (flag) {
         long l = this.getSupersededOwnerTime(l2);
         if (l != 0L) {
            this.cleanedEvicted.markEntryReturnPath(l);
         }

         this.supersededOwnerPositionMap.remove(l2);
         this.retainedLeaseSet.remove(l2);
         this.sessionLinkedHashSet.remove(l2);
         if (this.movementMissionData != null && this.movementMissionData.owner() == Owner.ACCESS && this.movementMissionData.missionId() == l2) {
            this.movementMissionData = null;
         }

         if (this.islandSeedTime == l2 && this.islandAbort == l3) {
            if (this.compoundCompleteValue == l3 && this.transfer.startsWith("island")) {
               this.releaseCompoundLease("access_unfunded_failure");
            }

            this.resetIslandExitState();
         }

         this.unknown = null;
         this.islandCompoundText = "access mission " + l2 + " failed before first temp owner " + BlockPos.fromLong(l3).toShortString();
      }

      if (this.blockPos2SupportConstructive != null) {
         this.setCellCooldown(this.blockPos2SupportConstructive.asLong(), this.moduleTick + 160);
      }

      if (this.dirtFeet != null) {
         this.budgetReclaimPositionSet.add(this.dirtFeet.fingerprint());
         this.solverPipelinedSet.add((this.dirtFeet.fingerprint() ^ islandPathText.hashCode()) * 1099511628211L);
      }

      this.dirtFeet = null;
      this.stepNoProgress = 0;
      this.supportPlanValue = 0;
      this.planSupportValue = -100000;
      this.supportEndedValue = -100000;
      this.blockPos3SupportConstructive = null;
      this.blockPos2SupportConstructive = null;
      this.name = "";
      this.updatePressedOptions2();
      this.path.clear();
      this.handleWakeRev("temp_support_failed");
      this.transitionToState(AutoBuilder.State.SELECT_TARGET, "temp support failed: " + islandPathText);
   }

   private void buildLayerSupportDistanceMap(int schematicCellsValue) {
      this.schematicCellsIntegerMap.clear();
      HashSet<Long> hashSet = new HashSet<>();
      ArrayDeque<Long> arrayDeque = new ArrayDeque<>();

      for (int n = 0; n < this.schematicCells.size(); n++) {
         BlockPos blockPos = this.schematicCells.get(n);
         if (blockPos.getY() == schematicCellsValue) {
            BlockState blockState = this.targetFluidItems.get(n);
            if (mc.world.getBlockState(blockPos).getBlock() != blockState.getBlock()
               && this.getRequiredSupportDirection(blockPos, blockState) == null
               && (!blockState.getCollisionShape(mc.world, blockPos).isEmpty() || BlockStateUtilsView.canBlockOpen(blockState))) {
               hashSet.add(blockPos.asLong());
            }
         }
      }

      for (long l : hashSet) {
         BlockPos fromLong = BlockPos.fromLong(l);
         int schematicCells2 = this.getSchematicCells(fromLong);
         BlockState blockState2 = this.targetFluidItems.get(schematicCells2);
         if (this.hasSolidNeighborToPlaceOn(fromLong) || this.isSupportBelowMissing(fromLong, blockState2)) {
            this.schematicCellsIntegerMap.put(l, 0);
            arrayDeque.add(l);
         }
      }

      while (!arrayDeque.isEmpty()) {
         long poll3 = arrayDeque.poll();
         int n3 = this.schematicCellsIntegerMap.get(poll3);
         if (n3 < 3) {
            BlockPos fromLong3 = BlockPos.fromLong(poll3);

            for (Direction direction : Type.HORIZONTAL) {
               long long2 = fromLong3.offset(direction).asLong();
               if (hashSet.contains(long2) && !this.schematicCellsIntegerMap.containsKey(long2)) {
                  this.schematicCellsIntegerMap.put(long2, n3 + 1);
                  arrayDeque.add(long2);
               }
            }
         }
      }

      this.changedPlanCountSchematicCel = changedPlanCount;
      this.schematicCellsValueSchematic = schematicCellsValue;
      this.lastSeenSchematicCells = this.schematicCells;
   }

