   private int countLayerBlockers(int pinParkedValue) {
      this.matNeedsValue = this.layerStats.missingMat;
      this.coolingNeedsValue = this.changeSessionItems.size();
      this.owedDispatcherCount = 0;
      this.parkedPinCount = 0;

      for (Entry<Long, Integer> entry : this.cooldown.entrySet()) {
         if (this.moduleTick < entry.getValue()) {
            long l = entry.getKey();
            if (BlockPos.unpackLongY(l) == pinParkedValue) {
               if (this.proofLayerMap.containsKey(l)) {
                  Long longValue = this.handBack.getNumberForPosition(l);
                  FamilyGained.State state = longValue == null ? null : this.handBack.getExecutingTerminalState(longValue);
                  if (state != null
                     && state != FamilyGained.State.TERMINAL_IMPOSSIBLE
                     && state != FamilyGained.State.TERMINAL_REACHABLE
                     && state != FamilyGained.State.TERMINAL_BUILT) {
                     this.parkedPinCount++;
                  }
               } else if (entry.getValue() - this.moduleTick <= 640) {
                  this.owedDispatcherCount++;
               }
            }
         }
      }

      return this.matNeedsValue + this.coolingNeedsValue + this.owedDispatcherCount + this.parkedPinCount;
   }

