   private boolean tryStartSideRunStrategy(BlockPos pos, Vec3d vec, double changedPlanValue, BlockPos pos2, List<MaterialVisibleUtils.Candidate> arrayList) {
      if (this.sideRuns.isEnabled()
         && this.sideRunSkippedDraining == null
         && !this.arrivedLaneFlag
         && !this.hasActiveBlockersStep()
         && !this.isCompletionPhaseActive()
         && !this.deckMicroMoves.isProbingExitingConfirmed()) {
         if (this.moduleTick - this.lastTickRemainingChanged < 20 && this.changedPlanCountRemainingCha == changedPlanCount) {
            return false;
         } else {
            this.lastTickRemainingChanged = this.moduleTick;
            this.changedPlanCountRemainingCha = changedPlanCount;
            LaneRowUtils.Run run = this.findBestLaneRun(pos, pos2, arrayList);
            if (run == null) {
               return false;
            } else {
               LaneRowUtils.Run laneEnd = this.orientLaneRunToward(run, pos);
               com.corz.client.utils.HeavyBatchUtils.Decision decision = this.chooseRunPlacementDecision(
                  laneEnd, pos, arrayList == null ? 0 : (int)arrayList.stream().filter(candidate -> candidate.visibleNow()).count(), false
               );
               this.logDebugMessage(
                  "\u00a7d[BuildStrategy]\u00a7r cluster=" + BlockPos.fromLong(laneEnd.members().get(0).target()).toShortString() + " " + decision.describeDecision()
               );
               if (decision.selected() != null && HeavyBatchUtils.canRunSide(decision.selected().kind())) {
                  List<BlockPos> pathToLaneStart = this.getPathToLaneStart(laneEnd, pos);
                  if (pathToLaneStart == null) {
                     return false;
                  } else if (!this.commitSideRun(laneEnd, pos, decision, pathToLaneStart)) {
                     return false;
                  } else {
                     this.remainingChangedAmount = this.remainingChangedAmount + decision.ticksSaved();
                     return true;
                  }
               } else {
                  return false;
               }
            }
         }
      } else {
         return false;
      }
   }

