   private void updateDurableObligations() {
      if (this.candidateDurableScopeCaused.getValue() != 0) {
         for (Obligation getItem : this.candidateDurableScopeCaused.getItems()) {
            long nanoTime4 = System.nanoTime();
            this.builtCellCount++;
            this.candidateDurableCount++;
            BlockPos fromLong = BlockPos.fromLong(getItem.target());
            if (this.builtCellSet.contains(getItem.target())) {
               this.recordAccessRecovered(getItem, "the cell is built");
            } else if (this.completionMissionMap.get(getItem.target()) == null) {
               int n = this.getSchematicCells(fromLong);
               if (n >= 0 && mc.world != null && this.bitSet.get(n) && this.isPlacedStateAcceptable(fromLong, this.targetFluidItems.get(n))) {
                  this.recordAccessRecovered(getItem, "the cell is built");
               }
            } else {
               BlockPos longValue3 = null;

               for (long l : this.getLostProgramCells(fromLong)) {
                  BlockPos blockPos = BlockPos.fromLong(l);
                  if (this.isDurableStandCell(blockPos)) {
                     longValue3 = blockPos;
                     break;
                  }
               }

               if (longValue3 != null) {
                  this.handlePlanningShort(
                     getItem, Attempt.ALTERNATE_DURABLE_STAND, System.nanoTime() - nanoTime4, "RECOVERED durableStand=" + longValue3.toShortString()
                  );
                  this.recordAccessRecovered(getItem, "durable stand " + longValue3.toShortString());
               } else {
                  Obligation obligation = this.candidateDurableScopeCaused.getScopeCausedData(getItem.target());
                  if (obligation != null && obligation.isStateProgress()) {
                     Optional<Attempt> optional = obligation.getEmpty();
                     if (optional.isEmpty()) {
                        this.candidateDurableScopeCaused.handleTarget(obligation.getCausalFingerprint(ScopeCaused.State.PROVEN_IMPOSSIBLE));
                        this.candidateDurableUpdateCount++;
                     } else {
                        Attempt attempt = optional.get();
                        Obligation causalFingerprint = obligation.getCausalFingerprint(attempt).getCausalFingerprint(this.moduleTick);
                        this.candidateDurableScopeCaused.handleTarget(causalFingerprint);
                        if (causalFingerprint.getTickAction() >= 0) {
                           this.maxTickAction = Math.max(this.maxTickAction, causalFingerprint.getTickAction());
                        }
                        this.handlePlanningShort(
                           getItem,
                           attempt,
                           System.nanoTime() - nanoTime4,
                           switch (attempt) {
                              case BOUNDED_RECENTER -> {
                                 BlockPos feetBlockPos = this.getFeetBlockPos();
                                 boolean flag = !BlockStandBounds.isInsideStandArea(
                                    mc.player.getX(), mc.player.getZ(), feetBlockPos.getX(), feetBlockPos.getZ()
                                 );
                                 yield flag && this.centrePlayerOnBlock(feetBlockPos) != AutoBuilder.Recentre.FAILED
                                    ? "RECENTRE_STARTED stand=" + feetBlockPos.toShortString()
                                    : "NO_CANDIDATE";
                              }
                              case RELOCATION -> {
                                 BlockPos longValue = null;

                                 for (long l2 : this.getLostProgramCells(fromLong)) {
                                    BlockPos fromLong3 = BlockPos.fromLong(l2);
                                    if (WalkRouteFinder.isStandable(mc.world, fromLong3) && !fromLong3.equals(this.getFeetBlockPos())) {
                                       longValue = fromLong3;
                                       break;
                                    }
                                 }

                                 yield longValue == null ? "NO_CANDIDATE" : "RELOCATE stand=" + longValue.toShortString();
                              }
                              case TEMP_REUSE -> {
                                 BlockPos pos2 = null;

                                 for (long l3 : this.getLostProgramCells(fromLong)) {
                                    BlockPos pos = BlockPos.fromLong(l3);
                                    if (this.cells.contains(pos.down().asLong()) && WalkRouteFinder.isStandable(mc.world, pos)) {
                                       pos2 = pos;
                                       break;
                                    }
                                 }

                                 yield pos2 == null ? "NO_CANDIDATE" : "TEMP_REUSE stand=" + pos2.toShortString();
                              }
                              case COMPLETION_ESCAPE -> {
                                 this.durableCandidateCount++;
                                 this.recordCompletionEscapeFamily(
                                    new com.corz.client.utils.FamiliesNoneUtils.Request(
                                       com.corz.client.utils.FamiliesNoneUtils.Reason.LAST_DURABLE_WORKSPACE_LOST, Set.of(getItem.target()), 12, Set.of()
                                    ),
                                    "access loss: last durable workspace consumed"
                                 );
                                 yield "ESCAPE_RAISED";
                              }
                              case ALTERNATE_DURABLE_STAND -> "NO_DURABLE_STAND";
                              default -> "NO_CANDIDATE";
                           }
                        );
                        this.durableCandidateDeadline = this.durableCandidateDeadline + (System.nanoTime() - nanoTime4);
                     }
                  }
               }
            }
         }
      }
   }

