   private boolean verifyPurchaseDelivery() {
      if (this.deliveryUnprovenValue < 0 || this.affordablePagesItem == null || this.countItemInInventory(this.affordablePagesItem) <= this.deliveryUnprovenValue) {
         return false;
      } else if ((this.snipesBoardActive || arrivedDeliveryFlag)
         && (
            buildfinishedTime < 0L
               || buildfinishedValue != this.countItemInInventory(this.affordablePagesItem) - this.deliveryUnprovenValue
               || !KmbtSellerUtils.canFlag(buildfinishedText, new ItemStack(this.affordablePagesItem).getName().getString())
         )) {
         this.buyQuantity = Math.max(0, this.snipesBoardValue - (this.countItemInInventory(this.affordablePagesItem) - this.deliveryUnprovenValue));
         if (this.buyQuantity > 0) {
            return false;
         } else {
            this.advanceToNextBuyItem();
            return true;
         }
      } else {
         this.receivedDeliveryValue = this.deliveryUnprovenValue;
         this.showedListingTime = this.snipesBoardSavedShowedTime;
         this.deliveryUnprovenValue = -1;
         this.confirmPurchaseReceived();
         return true;
      }
   }

