   private boolean tryClickBlockAtPos(BlockPos pos) {
      if (mc.player.isSneaking()) {
         return false;
      } else {
         Vec3d vec3d = mc.player.getEyePos();
         double d = this.reachSetting.getValue();
         BlockState blockState = mc.world.getBlockState(pos);
         VoxelShape voxelShape = blockState.getOutlineShape(mc.world, pos);
         if (voxelShape.isEmpty()) {
            return false;
         } else {
            Vec3d vec3d2 = voxelShape.getBoundingBox().getCenter().add(pos.getX(), pos.getY(), pos.getZ());
            float[] wrapDegrees = MathClampUtils.getWrapDegrees(vec3d, vec3d2);
            BlockHitResult blockHitResult = vec3d.squaredDistanceTo(vec3d2) > d * d ? null : this.raycastFromEye(vec3d, wrapDegrees[0], wrapDegrees[1], d);
            if (blockHitResult == null
               || blockHitResult.getType() != net.minecraft.util.hit.HitResult.Type.BLOCK
               || !blockHitResult.getBlockPos().equals(pos)) {
               Vec3d minMax = this.findVisibleShapePoint(vec3d, pos, voxelShape, d);
               if (minMax == null) {
                  return false;
               }

               wrapDegrees = MathClampUtils.getWrapDegrees(vec3d, minMax);
            }

            float[] fs = this.computeAimRotation(wrapDegrees[0], wrapDegrees[1]);
            BlockHitResult adjustedHit = this.raycastFromEye(vec3d, fs[0], fs[1], d);
            if (adjustedHit.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK && adjustedHit.getBlockPos().equals(pos)) {
               this.recordHitForCurrentTarget(adjustedHit);
               this.performBlockInteraction(adjustedHit);
               if (this.swing.isEnabled()) {
                  mc.player.swingHand(Hand.MAIN_HAND);
               }

               return true;
            } else {
               return false;
            }
         }
      }
   }

