   private void updateRestockClose() {
      this.updatePressedOptions2();
      if (this.isScreenSyncIdMatching()) {
         this.recordRestockContainerContents();
         if (this.staleCount < 4) {
            return;
         }
      }

      AutoBuilder.RestockPurpose restockPurpose = this.restockPurpose;
      boolean flag = this.inventoryFull;
      boolean chestFullFlag2 = this.chestFullFlag;
      boolean completeLoadFlag3 = this.completeLoadFlag;
      BlockPos blockPos = this.restockContainerBlockPos;
      this.stackPulledValue = this.stackPulledValue + this.completeLoadValue;
      this.pulledRestockValue = this.pulledRestockValue + this.depositCompleteCount;
      this.pulledValue = this.pulledValue + this.completeLoadValue;
      this.totalPulledCount = this.totalPulledCount + this.depositCompleteCount;
      this.resetRestockState();
      long l = blockPos == null ? Long.MIN_VALUE : blockPos.asLong();
      switch (restockPurpose) {
         case WITHDRAW:
            if (completeLoadFlag3) {
               this.handlePulledRestock("load ready - bottom layers in hand");
               return;
            }

            if (flag) {
               this.handlePulledRestock("inventory full - build, then resume");
               return;
            }

            if (blockPos != null) {
               this.retryFailureSet.add(l);
            }

            if (this.canWithdrawFromContainer()) {
               return;
            }

            this.handlePulledRestock("all containers swept");
            break;
         case DEPOSIT:
            if (chestFullFlag2 && blockPos != null) {
               this.staffNearbySet.add(l);
            }

            if (chestFullFlag2 && this.hasSchematicItemInInventory() && this.tryStartRestockTrip(AutoBuilder.RestockPurpose.DEPOSIT)) {
               return;
            }

            this.onBuyDeposited();
            break;
         case SURVEY:
            if (blockPos != null) {
               this.staffCheckingSet.add(l);
            }

            if (this.tryStartRestockTrip(AutoBuilder.RestockPurpose.SURVEY)) {
               return;
            }

            this.checkRestockContainersBeforeAutobuy();
      }
   }

