   private boolean tryAdjustSneakPose(double adjustSneakValue) {
      if (this.deckMicroMoves.isProbingExitingLatched()
         && this.placementExplicit != null
         && this.placementExplicit.owner == Owner.DECK
         && this.placementExplicit.isPlacementMove()
         && this.placementExplicit.executorUnavailableObject.deckPick() != null
         && this.currentTargetPos != null
         && this.intervalReportCertificate == null) {
         int n = this.getSchematicCells(this.currentTargetPos);
         if (n < 0) {
            return false;
         } else {
            FloorBuildPlanner.Pick pick = this.placementExplicit.executorUnavailableObject.deckPick();
            Certificate certificate = this.getPlacementCertificate(pick, this.getPrimaryStandPosition(), this.targetFluidItems.get(n), adjustSneakValue, true);
            this.adjustEdge.recordCertificate(certificate);
            if (certificate.status() == com.corz.client.utils.CrouchedBodyUtils.Status.EXECUTABLE_CURRENT_POSE) {
               if (this.sneakBlock != null && certificate.sneak() != this.sneakBlock.sneakPoseFlag && this.adjustSneakCount < 2) {
                  this.sneakBlock.sneakPoseFlag = certificate.sneak();
                  this.adjustSneakCount++;
                  this.adjustEdge.eyeSwitchCount++;
                  return true;
               } else {
                  return false;
               }
            } else if (certificate.isExecutableWithAdjust()) {
               this.setupIntervalAdjust(new AutoBuilder.MissionPlacement(this.sneakBlock, pick, null, certificate), this.currentTargetPos);
               return true;
            } else {
               this.adjustEdge.parityFailureCount++;
               this.updatePressedOptions2();
               this.path.clear();
               this.intervalReportBlockPos = null;
               this.dispatchedFailureCount++;
               this.failExplicitPlacement("EXECUTOR_POSE_PARITY: " + certificate.formatStatusLabel());
               this.transitionToState(AutoBuilder.State.SELECT_TARGET, "pose parity failure - rejected now");
               return true;
            }
         }
      } else {
         return false;
      }
   }

