   private boolean handIslandToDeck(String islandHandoverText) {
      if (this.islandAbort == 0L) {
         return false;
      } else {
         BlockPos fromLong = BlockPos.fromLong(this.islandAbort);
         this.logDebugMessage(
            "\u00a7b[FloatingSupport]\u00a7r island "
               + fromLong.toShortString()
               + " hands its stand column to the deck: "
               + islandHandoverText
               + " (the column stays as the entry pillar)"
         );
         int n2 = this.layerPlanFloorY != Integer.MAX_VALUE ? this.layerPlanFloorY : this.layerAccessLowestCellY;

         for (long l : this.cells) {
            BlockPos blockPos = BlockPos.fromLong(l);
            if (blockPos.getY() < fromLong.getY()
               && Math.abs(blockPos.getX() - fromLong.getX()) <= 3
               && Math.abs(blockPos.getZ() - fromLong.getZ()) <= 3
               && !this.cells.contains(blockPos.up().asLong())
               && isDirtOrGrassBlock(mc.world.getBlockState(blockPos))) {
               BlockPos down = blockPos;

               int n;
               for (n = 1; this.cells.contains(down.down().asLong()); n++) {
                  down = down.down();
               }

               if (n >= 3 && this.canDownCollision(down) && this.isColumnClearAbove(blockPos.up()) && (n2 == Integer.MAX_VALUE || down.getY() <= n2 + 1)) {
                  this.unpackCellsIntArrayMap.put(BlockPos.asLong(blockPos.getX(), 0, blockPos.getZ()), new int[]{down.getY(), blockPos.getY()});
               }
            }
         }

         if (this.compoundCompleteValue != 0L && (this.compoundCompleteValue == this.islandAbort || this.transfer.startsWith("island"))) {
            this.releaseCompoundLease("island_handover");
         }

         this.islandHandover.put(this.islandAbort, this.moduleTick);
         this.islandHandoverMap.merge(this.islandAbort, 1, Integer::sum);
         this.resetIslandExitState();
         this.updatePressedOptions2();
         this.path.clear();
         this.islandDeckFlag = true;
         this.transitionToState(AutoBuilder.State.SELECT_TARGET, "island chain handed to the deck");
         return true;
      }
   }

