   private Verdict getDescendVerdict() {
      this.rebuildReachableComponent();
      BlockPos feetBlockPos = this.getFeetBlockPos();
      long l3 = this.componentKey * -7046029254386353131L ^ changedPlanCount ^ feetBlockPos.asLong() * -4658895280553007687L;
      if (l3 == this.isolatedDescendValue && this.isolatedDescendType != null) {
         return this.isolatedDescendType;
      } else {
         int n3 = 0;
         if (this.schematicCells != null && this.targetFluidItems != null && mc.world != null) {
            LongPredicate longPredicate = isolatedDescendValue -> this.component
               .contains(BlockPos.asLong(ProofSupportUtils.getValueInt(isolatedDescendValue), ProofSupportUtils.getValue(isolatedDescendValue), ProofSupportUtils.getValueForLong(isolatedDescendValue)));

            for (long l : this.iteratorCenterPositionSet) {
               BlockPos blockPos = BlockPos.fromLong(l);
               if (Math.abs(blockPos.getX() - feetBlockPos.getX()) <= 28
                  && Math.abs(blockPos.getZ() - feetBlockPos.getZ()) <= 28
                  && Math.abs(blockPos.getY() - feetBlockPos.getY()) <= 12) {
                  int n = this.getSchematicCells(blockPos);
                  if (n >= 0) {
                     BlockState blockState = mc.world.getBlockState(blockPos);
                     if (blockState.getBlock() != this.targetFluidItems.get(n).getBlock()
                        && (blockState.isAir() || blockState.isReplaceable())
                        && DescendReturnUtils.isWithinDescendLimitFiltered(blockPos.getX(), blockPos.getY(), blockPos.getZ(), longPredicate)) {
                        n3++;
                     }
                  }
               }
            }
         }

         if (n3 == 0
            && this.component.size() >= 64
            && this.schematicCells != null
            && this.targetFluidItems != null
            && mc.world != null
            && !this.completionMissionMap.isEmpty()) {
            LongPredicate longPredicate2 = proofSupportValue -> this.component
               .contains(BlockPos.asLong(ProofSupportUtils.getValueInt(proofSupportValue), ProofSupportUtils.getValue(proofSupportValue), ProofSupportUtils.getValueForLong(proofSupportValue)));
            int n2 = 0;

            for (long l2 : this.completionMissionMap.keySet()) {
               if (++n2 > 4096) {
                  break;
               }

               BlockPos fromLong = BlockPos.fromLong(l2);
               if (Math.abs(fromLong.getX() - feetBlockPos.getX()) <= 28
                  && Math.abs(fromLong.getZ() - feetBlockPos.getZ()) <= 28
                  && Math.abs(fromLong.getY() - feetBlockPos.getY()) <= 12
                  && DescendReturnUtils.isWithinDescendLimitFiltered(fromLong.getX(), fromLong.getY(), fromLong.getZ(), longPredicate2)) {
                  n3++;
               }
            }
         }

         int n4 = this.floats == Integer.MAX_VALUE ? Math.max(1, this.iteratorCenterPositionSet.size()) : this.floats;
         int max5 = Math.max(0, n4 - n3);
         boolean flag = this.cells.contains(feetBlockPos.down().asLong());
         BlockPos blockPos4 = !flag && n3 <= 0 && max5 != 0 ? this.findNearestOpenCellTop(feetBlockPos) : null;
         this.reachableElsewhereData = new Situation(n3, flag, blockPos4 != null, max5, this.component.size());
         this.isolatedDescendType = DescendReturnUtils.getOwnReachable(this.reachableElsewhereData);
         this.blockPosMountedElsewhere = blockPos4;
         this.isolatedDescendValue = l3;
         return this.isolatedDescendType;
      }
   }

