   private SupportStandUtils.Target buildSupportTarget(BlockPos pos, BlockState state) {
      SupportStandUtils.Kind facePlayer = SupportStandUtils.Kind.PLAIN;
      int ordinal3 = -1;
      if (matchesBlockStateRule(state)) {
         return null;
      } else if (this.isSupportCellEmptyAir(pos, state)) {
         return null;
      } else {
         if (isPlaceableWithoutSpecialSneak(state)) {
            facePlayer = getPistonStickyType(state.getBlock()) == com.corz.client.utils.PistonStickyUtils.Kind.OBSERVER
               ? SupportStandUtils.Kind.FACE_AWAY
               : SupportStandUtils.Kind.FACE_PLAYER;
            ordinal3 = getBlockStateFacingDirection(state).ordinal();
         } else if (state.getBlock() instanceof HopperBlock && state.contains(Properties.HOPPER_FACING)) {
            facePlayer = SupportStandUtils.Kind.HOPPER;
            ordinal3 = state.get(Properties.HOPPER_FACING).ordinal();
         } else if (hasFluidState(state)) {
            facePlayer = SupportStandUtils.Kind.FLUID;
         } else if (getDirectionForBlockState(state) != null && state.contains(Properties.HORIZONTAL_FACING)) {
            facePlayer = SupportStandUtils.Kind.YAW_OPPOSITE;
            Direction direction = this.getPlacementFacing(pos, state);
            ordinal3 = direction == null ? -1 : direction.getOpposite().ordinal();
         } else if (getAxis(state) != null) {
            facePlayer = SupportStandUtils.Kind.YAW_AXIS;
            ordinal3 = getAxis(state) == Axis.X ? Direction.EAST.ordinal() : Direction.NORTH.ordinal();
         } else if (state.getBlock() instanceof TrapdoorBlock
            && state.contains(Properties.HORIZONTAL_FACING)
            && state.contains(Properties.BLOCK_HALF)) {
            facePlayer = state.get(Properties.BLOCK_HALF) == BlockHalf.TOP ? SupportStandUtils.Kind.TRAPDOOR_TOP : SupportStandUtils.Kind.TRAPDOOR_BOTTOM;
            ordinal3 = state.get(Properties.HORIZONTAL_FACING).ordinal();
         }

         if (this.isRelaxedBlockShortCell(pos) && facePlayer != SupportStandUtils.Kind.FLUID && facePlayer != SupportStandUtils.Kind.HOPPER) {
            facePlayer = SupportStandUtils.Kind.PLAIN;
            ordinal3 = -1;
         }

         SupportStandUtils.Shape shape = state.getBlock() instanceof ChestBlock
            ? SupportStandUtils.Shape.CHEST
            : (
               state.getBlock() instanceof HopperBlock
                  ? SupportStandUtils.Shape.HOPPER
                  : (
                     state.getBlock() instanceof AbstractRedstoneGateBlock
                        ? SupportStandUtils.Shape.THIN
                        : (state.getCollisionShape(mc.world, pos).isEmpty() ? SupportStandUtils.Shape.NONE : SupportStandUtils.Shape.FULL)
                  )
            );
         BlockPos rotateYcounterclockwise = this.getRotateYcounterclockwise(pos, state);
         Direction down = this.getRequiredSupportDirection(pos, state);
         if (down == null && isRedstoneComponentBlock(state)) {
            down = Direction.DOWN;
         }

         if (down == null && facePlayer == SupportStandUtils.Kind.HOPPER) {
            facePlayer = SupportStandUtils.Kind.PLAIN;
            ordinal3 = -1;
         }

         return new SupportStandUtils.Target(
            getDataForBlockPos(pos),
            getBlockRegistryPath(state),
            facePlayer,
            ordinal3,
            shape,
            isFlaggedBlockState(state),
            rotateYcounterclockwise == null ? null : getDataForBlockPos(rotateYcounterclockwise),
            down == null ? -1 : down.ordinal()
         );
      }
   }

