   private void loadItemLimitsFromJson(JsonElement json) {
      if (json != null && json.isJsonObject()) {
         this.jsonArrayMemory.updateConcurrentHash();

         for (Entry<String, JsonElement> entry : json.getAsJsonObject().entrySet()) {
            try {
               Identifier identifier = Identifier.tryParse(entry.getKey());
               if (identifier != null && entry.getValue().isJsonArray()) {
                  JsonArray jsonArray = entry.getValue().getAsJsonArray();
                  if (jsonArray.size() >= 2) {
                     Item item = Registries.ITEM.get(identifier);
                     if (item != null && item != Items.AIR) {
                        this.jsonArrayMemory
                           .handleConcurrentUnit(
                              item,
                              jsonArray.size() >= 4
                                 ? new com.corz.client.utils.LimitBuyerUtils.Entry(
                                    jsonArray.get(0).getAsLong(), jsonArray.get(1).getAsLong(), jsonArray.get(2).getAsLong(), jsonArray.get(3).getAsLong()
                                 )
                                 : new com.corz.client.utils.LimitBuyerUtils.Entry(jsonArray.get(0).getAsLong(), jsonArray.get(1).getAsLong())
                           );
                     }
                  }
               }
            } catch (RuntimeException e) {
            }
         }
      }
   }

   private void onAccessRouteFailed(String accessRouteText) {
      if (this.currentTargetPos != null && this.superseded != null && this.superseded.isContains(this.currentTargetPos.asLong())) {
         String classifyReason = BlockedReasonTracker.classifyReason(accessRouteText);
         if (classifyReason.equals("NO_ACCESS_ROUTE") || classifyReason.equals("NO_STAND")) {
            Long longValue2 = this.standRouteMap.get(this.currentTargetPos.asLong());
            int n = 0;

            for (long l : this.superseded.targets()) {
               if (l != this.currentTargetPos.asLong()) {
                  Long longValue = this.standRouteMap.get(l);
                  BlockPos blockPos = BlockPos.fromLong(l);
                  boolean flag = longValue2 != null && longValue2.equals(longValue);
                  boolean flag2 = longValue2 == null
                     && longValue == null
                     && ClusterFieldsUtils.floorDivClusterSecondary(blockPos.getX()) == ClusterFieldsUtils.floorDivClusterSecondary(this.currentTargetPos.getX())
                     && ClusterFieldsUtils.floorDivClusterSecondary(blockPos.getZ()) == ClusterFieldsUtils.floorDivClusterSecondary(this.currentTargetPos.getZ())
                     && ClusterFieldsUtils.floorDivCluster(blockPos.getY()) == ClusterFieldsUtils.floorDivCluster(this.currentTargetPos.getY());
                  if (flag || flag2) {
                     Integer integer = this.cooldown.get(l);
                     if (integer == null || integer < this.moduleTick + 160) {
                        this.setCellCooldown(l, this.moduleTick + 160);
                     }

                     this.handleGeometryEmergency(BlockPos.fromLong(l), accessRouteText);
                     n++;
                  }
               }
            }

            this.markPositionPairHandled(this.currentTargetPos, null);
            this.accessValue += n;
            this.handleAccessRoute("access_failed");
         }
      }
   }

