   private int countReachableWalkableCells(BlockPos pos, int iteratorOffsetLimit) {
      ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
      HashSet<Long> hashSet = new HashSet<>();
      arrayDeque.add(pos);
      hashSet.add(pos.asLong());

      while (!arrayDeque.isEmpty() && hashSet.size() < iteratorOffsetLimit) {
         BlockPos poll2 = arrayDeque.poll();

         for (Direction direction : Type.HORIZONTAL) {
            for (int n = -1; n <= 1; n++) {
               BlockPos blockPos = poll2.offset(direction).up(n);
               if (!hashSet.contains(blockPos.asLong()) && WalkRouteFinder.isStandable(mc.world, blockPos)) {
                  hashSet.add(blockPos.asLong());
                  arrayDeque.add(blockPos);
               }
            }
         }
      }

      return hashSet.size();
   }

