               if (n >= 0) {
                  if (n > 0) {
                     this.machineDownPositionSet.add(blockPos.asLong());
                     return true;
                  }

                  if (machineDownFlag && this.machineDownPositionSet.contains(blockPos.asLong())) {
                     return true;
                  }
               }
