   private static long hashMissionCells(SupportStandUtils.Mission mission2) {
      ArrayList<Long> arrayList = new ArrayList<>();

      for (SupportStandUtils.Step step : mission2.steps()) {
         if (step.op() == SupportStandUtils.Op.PLACE) {
            arrayList.add(ProofSupportUtils.getTime(step.cell().x(), step.cell().y(), step.cell().z()));
         }
      }

      for (SupportStandUtils.Cell cell : mission2.unsolved()) {
         arrayList.add(ProofSupportUtils.getTime(cell.x(), cell.y(), cell.z()));
      }

      for (SupportStandUtils.Cycle cycle : mission2.cycles()) {
         for (SupportStandUtils.Cell membersItem : cycle.members()) {
            arrayList.add(ProofSupportUtils.getTime(membersItem.x(), membersItem.y(), membersItem.z()));
         }
      }

      long[] ls = new long[arrayList.size()];

      for (int n = 0; n < ls.length; n++) {
         ls[n] = arrayList.get(n);
      }

      return ParkMerge.getTime(ls);
   }

   private boolean isSingleChestNextToMatchingChest(BlockPos pos, BlockState state) {
      if (!(state.getBlock() instanceof ChestBlock)) {
         return false;
      } else if (state.contains(Properties.CHEST_TYPE) && state.get(Properties.CHEST_TYPE) == ChestType.SINGLE) {
         Direction direction2 = state.get(Properties.HORIZONTAL_FACING);

         for (Direction direction : new Direction[]{direction2.rotateYClockwise(), direction2.rotateYCounterclockwise()}) {
            BlockState blockState = mc.world.getBlockState(pos.offset(direction));
            if (blockState.getBlock() == state.getBlock()
               && blockState.contains(Properties.HORIZONTAL_FACING)
               && blockState.get(Properties.HORIZONTAL_FACING) == direction2
               && blockState.contains(Properties.CHEST_TYPE)
               && blockState.get(Properties.CHEST_TYPE) == ChestType.SINGLE) {
               return true;
            }
         }

         return false;
      } else {
         return false;
      }
   }

