   private double getSquaredDistanceToSchematicCenter(BlockPos pos) {
      if (this.schematicCellsObject != this.schematicCells) {
         int min = Integer.MAX_VALUE;
         int max = Integer.MIN_VALUE;
         int maxValue = Integer.MAX_VALUE;
         int minValue = Integer.MIN_VALUE;

         for (BlockPos blockPos : this.schematicCells) {
            min = Math.min(min, blockPos.getX());
            max = Math.max(max, blockPos.getX());
            maxValue = Math.min(maxValue, blockPos.getZ());
            minValue = Math.max(minValue, blockPos.getZ());
         }

         this.schematicCellsAmount = (min + max) / 2.0;
         this.schematicCenterZ = (maxValue + minValue) / 2.0;
         this.schematicCellsObject = this.schematicCells;
      }

      double d = pos.getX() + 0.5 - this.schematicCellsAmount - 0.5;
      double d2 = pos.getZ() + 0.5 - this.schematicCenterZ - 0.5;
      return d * d + d2 * d2;
   }

   private Regime getFootingRegime() {
      Vec3d vec3d = mc.player.getEntityPos();
      Vec3d vec3d2 = mc.player.getVelocity();
      double d4 = vec3d2.x * 2.0;
      double d5 = vec3d2.z * 2.0;
      if (this.state2Builder == AutoBuilder.State.GO_TO_POSITION || this.intervalReportBlockPos != null) {
         BlockPos blockPos = this.state2Builder == AutoBuilder.State.GO_TO_POSITION ? this.blockPos3BridgeCell : this.intervalReportBlockPos;
         if (blockPos != null) {
            double d = blockPos.getX() + 0.5 - vec3d.x;
            double d2 = blockPos.getZ() + 0.5 - vec3d.z;
            double hypot3 = Math.hypot(d, d2);
            if (hypot3 > 0.05) {
               d4 += d / hypot3 * 0.35;
               d5 += d2 / hypot3 * 0.35;
            }
         }
      }

      int n = this.getFeetBlockPos().getY() - 1;
      return SafetyRecipeUtils.getControlInterior(vec3d.x, vec3d.z, d4, d5, (integer, integer2) -> {
         BlockPos blockPosx = new BlockPos(integer, n, integer2);
         return mc.world.getBlockState(blockPosx).isFullCube(mc.world, blockPosx);
      });
   }

