   private void applyMovementKeysFromVector(double pressedOptionsFactor, double d11) {
      double radians3 = Math.toRadians(mc.player.getYaw());
      double sin4 = -Math.sin(radians3);
      double cos5 = Math.cos(radians3);
      double cos6 = Math.cos(radians3);
      double sin7 = Math.sin(radians3);
      double d8 = pressedOptionsFactor * sin4 + d11 * cos5;
      double d9 = pressedOptionsFactor * cos6 + d11 * sin7;
      mc.options.forwardKey.setPressed(d8 > 0.05);
      mc.options.backKey.setPressed(d8 < -0.05);
      mc.options.leftKey.setPressed(d9 > 0.05);
      mc.options.rightKey.setPressed(d9 < -0.05);
   }

   private boolean hasReachableReclaimCircuit(BlockPos pos) {
      if (pos.asLong() == this.longModuleTick && changedPlanCount == this.changedPlanCountModuleTick && this.moduleTick - this.lastPlanCheckTick < 100) {
         return false;
      } else {
         this.longModuleTick = pos.asLong();
         this.changedPlanCountModuleTick = changedPlanCount;
         this.lastPlanCheckTick = this.moduleTick;
         ArrayList<BlockPos[]> arrayList = new ArrayList<>();

         for (long l : new ArrayList<>(this.completionMissionMap.keySet())) {
            BlockPos blockPos = BlockPos.fromLong(l);
            if (this.isMachineArmedAt(blockPos) && this.getRedstoneDeferralReason(blockPos) != null && this.blockPos2ShortPowered != null) {
               arrayList.add(new BlockPos[]{this.blockPos2ShortPowered, blockPos});
            }
         }

         arrayList.sort(Comparator.comparingDouble(blockPossx -> blockPossx[0].getSquaredDistance(pos)));
         double d = this.reachSetting.getValue();

         for (BlockPos[] blockPoss : arrayList) {
            BlockPos blockPos2 = blockPoss[0];
            if (!this.canDigMission(blockPos2.asLong()) && this.moduleTick - this.staleSweepMap.getOrDefault(blockPos2.asLong(), this.moduleTick) >= 400) {
               BlockPos nearestStandPosition = WalkRouteFinder.findNearestStandPosition(
                  blockPos2,
                  d,
                  blockPos2x -> !FlagPoseUtils.canFlagPosePair(blockPos2.asLong(), blockPos2x.asLong())
                     && this.isWithinReachFromStand(blockPos2, blockPos2x)
                     && (this.digMissionFlag || !this.isBlockCriticalForAccess(blockPos2, blockPos2x))
               );
               if (nearestStandPosition != null
                  && (nearestStandPosition.equals(this.getFeetBlockPos()) || this.findGoPath(this.getFeetBlockPos(), nearestStandPosition) != null)
                  && this.tryReclaimTempBesideCircuit(blockPos2, blockPoss[1])) {
                  return true;
               }
            }
         }

         return false;
      }
   }

