   private void rebuildReachableComponent() {
      if (this.moduleTick != this.lastSessionModuleTick) {
         this.lastSessionModuleTick = this.moduleTick;
         BlockPos feetBlockPos = this.getFeetBlockPos();
         if (feetBlockPos.asLong() == this.longComponentChanged && changedPlanCount == this.changedPlanCountComponentCha && !this.component.isEmpty()) {
            this.selectPasses.handleTimes(Counter.COMPONENT_CACHE_HITS);
         } else {
            long longComponentChanged2 = this.longComponentChanged;
            this.longComponentChanged = feetBlockPos.asLong();
            this.changedPlanCountComponentCha = changedPlanCount;
            this.selectPasses.handleTimes(Counter.COMPONENT_BUILDS);
            this.component.clear();
            this.paveFacelessMap.clear();
            this.componentPositionSet.clear();
            this.componentChangedActive = false;
            BlockPos feetBlockPos4 = this.getFeetBlockPos();
            ArrayDeque<BlockPos> arrayDeque = new ArrayDeque<>();
            this.component.add(feetBlockPos4.asLong());
            this.paveFacelessMap.put(feetBlockPos4.asLong(), 0);
            arrayDeque.add(feetBlockPos4);
            int n4 = 0;

            while (!arrayDeque.isEmpty() && this.component.size() < 600 && n4++ < 2500) {
               BlockPos poll2 = arrayDeque.poll();
               int orDefault3 = this.paveFacelessMap.getOrDefault(poll2.asLong(), 0);

               for (Direction direction : Type.HORIZONTAL) {
                  BlockPos blockPos = poll2.offset(direction);
                  if (Math.abs(blockPos.getX() - feetBlockPos4.getX()) <= 24 && Math.abs(blockPos.getZ() - feetBlockPos4.getZ()) <= 24) {
                     BlockPos offset = null;
                     int n2 = 0;
                     if (WalkRouteFinder.isStandable(mc.world, blockPos)) {
                        offset = blockPos;
                     } else if (WalkRouteFinder.isStandable(mc.world, blockPos.up())) {
                        offset = blockPos.up();
                     } else if (mc.world.getBlockState(blockPos.up()).getCollisionShape(mc.world, blockPos.up()).isEmpty()) {
                        for (int n = 1;
                           n <= 2
                              && mc.world
                                 .getBlockState(blockPos.down(n - 1))
                                 .getCollisionShape(mc.world, blockPos.down(n - 1))
                                 .isEmpty();
                           n++
                        ) {
                           if (WalkRouteFinder.isStandable(mc.world, blockPos.down(n))) {
                              if (!WalkRouteFinder.isUnsafeSlipperyStand(mc.world, blockPos.down(n))) {
                                 offset = blockPos.down(n);
                                 n2 = n;
                              }
                              break;
                           }
                        }
                     }

                     if (offset != null && this.component.add(offset.asLong())) {
                        this.paveFacelessMap.put(offset.asLong(), orDefault3 + 1);
                        arrayDeque.add(offset);
                        if (n2 >= 2) {
                           this.handleWorldDown(offset);
                        }
                     }
                  } else {
                     this.componentChangedActive = true;
                  }
               }
            }

            long next = Long.MAX_VALUE;
            long l3 = -7046029254386353131L;

            for (long l : this.component) {
               if (l < next) {
                  next = l;
               }

               l3 += l * -7046029254386353131L ^ l >>> 29;
            }

            this.componentKey = next;
            this.unpackValue = l3;
            if (this.component.size() >= 600) {
               this.componentChangedActive = true;
            }

            long next4;
            if (!this.componentChangedActive) {
               next4 = next;
               this.componentValue = Long.MIN_VALUE;
            } else if (this.componentValue != Long.MIN_VALUE && longComponentChanged2 != Long.MIN_VALUE && this.component.contains(longComponentChanged2)) {
               next4 = this.componentValue;
            } else {
               next4 = this.componentValue = feetBlockPos4.asLong() * -7046029254386353131L ^ 6510615555426900570L;
            }

            if (!this.componentChangedActive && this.componentChangedValue >= 0 && this.component.size() > this.componentChangedValue + 2) {
               this.handleRetiredCell(Event.REACHABLE_COMPONENT_EXPANDED);
            }

            if (this.componentChangedTime != Long.MIN_VALUE && next4 != this.componentChangedTime) {
               this.runWithSessionActive("component changed");
            }

            this.componentChangedTime = next4;
            this.nextSession = next;
            this.componentChangedValue = this.component.size();
         }
      }
   }

