   private boolean tryExtendLifelineStair(BlockPos pos) {
      if (this.unpackCellsIntArrayMap.isEmpty()
         || !this.useTemporaryBlocks.isEnabled()
         || this.getHotbarDirtSlot() == -1
         || mc.player == null
         || !mc.player.isOnGround()) {
         return false;
      } else if (this.cellsUnpackWorkspaceReturn == null
         && this.islandAbort == 0L
         && !this.isFallRecoveryActive()
         && !this.deckMicroMoves.isProbingExitingConfirmed()
         && this.unstableRecenterChangedTimeo == null
         && !this.isServiceAccessBlocked()
         && this.submitCompletionMission == null) {
         BlockPos tempSupportCell = this.findTempSupportCell(pos);
         if (tempSupportCell != null && (!this.hasActiveBlockersStep() || pos.getY() - tempSupportCell.getY() >= 2)) {
            this.lifelineTopValue = this.moduleTick;
            if (this.hasActiveBlockersStep()) {
               this.blockers = null;
               this.stepIndex = -1;
               this.stepsTimeBudget.updateTimeMax();
            }

            this.blockPos2LifelineExtension = tempSupportCell;
            this.lifelineExtensionValue = pos.getY();
            this.lastTickLifelineTop = this.moduleTick;
            this.logDebugMessage(
               "\u00a7b[Lifeline]\u00a7r exit stair: extending "
                  + tempSupportCell.toShortString()
                  + " up to feet y="
                  + pos.getY()
                  + " - the climb out stays the way back down for the final cleanup"
            );
            List<BlockPos> list = this.findGoPath(pos, tempSupportCell);
            this.standClimbFlag = false;
            this.arrivedSupportFlag = false;
            MovementMissionData movementMissionData = new MovementMissionData(
               Owner.EGRESS, 0L, Purpose.EGRESS, tempSupportCell.asLong(), null, 1, Scope.GLOBAL_SELECTION
            );
            if (list != null && !list.isEmpty() && this.tryFollowMovementRoute(list, tempSupportCell, movementMissionData)) {
               this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "lifeline: walk onto the exit stair top");
               return true;
            } else {
               this.blockPos2LifelineExtension = null;
               this.lifelineTopValue = this.moduleTick + 100;
               return false;
            }
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

