   private boolean canDescendOwnTower(BlockPos pos, BlockPos pos2) {
      if (mc.world != null && pos2.getY() < pos.getY()) {
         final Terrain terrain = WalkRouteFinder.createTerrainView(mc.world);
         boolean flag = WalkableRegionAnalyzer.countReachableCells(terrain, pos2.getX(), pos2.getY(), pos2.getZ(), 17) <= 16;
         if (!WalkableRegionAnalyzer.isRegionEnclosed(
            terrain,
            pos.getX(),
            pos.getY(),
            pos.getZ(),
            pos2.getX(),
            pos2.getY(),
            pos2.getZ(),
            (downWorldValue, n2x, n3x) -> {
               long l = BlockPos.asLong(downWorldValue, n2x, n3x);
               BlockState blockState = this.cellTemporarySet.contains(l) ? this.completionMissionMap.get(l) : null;
               Direction direction = blockState == null ? null : this.getRequiredSupportDirection(BlockPos.fromLong(l), blockState);
               return blockState != null && flag && this.cells.contains(BlockPos.asLong(downWorldValue, n2x - 1, n3x)) && !this.isPlainFullCubeMissionBlock(BlockPos.fromLong(l))
                  ? false
                  : (direction == null || direction == Direction.DOWN) && this.isTempCellAcceptable(l);
            }
         )) {
            return false;
         } else {
            final HashSet<Long> hashSet = new HashSet<>();

            BlockPos down;
            for (down = pos2.down(); this.cells.contains(down.asLong()) && hashSet.size() < 64; down = down.down()) {
               hashSet.add(down.asLong());
            }

            if (hashSet.isEmpty()) {
               return false;
            } else {
               Terrain terrain2 = new Terrain() {
                  @Override
                  public boolean solid(int solidValue, int candidateY, int candidateZ) {
                     return !hashSet.contains(BlockPos.asLong(solidValue, candidateY, candidateZ)) && terrain.solid(solidValue, candidateY, candidateZ);
                  }

                  @Override
                  public boolean canStandOn(int mutableValue, int y, int mutableValue3) {
                     return !hashSet.contains(BlockPos.asLong(mutableValue, y, mutableValue3)) && terrain.canStandOn(mutableValue, y, mutableValue3);
                  }
               };
               BlockPos downAbove = down.up();

               for (int n = 1; !terrain2.canStandOn(downAbove.getX(), downAbove.getY() - 1, downAbove.getZ()); downAbove = downAbove.down()) {
                  if (++n > 2) {
                     return true;
                  }
               }

               int countReachableCells2 = WalkableRegionAnalyzer.countReachableCells(terrain, pos.getX(), pos.getY(), pos.getZ(), 40);
               int n3 = pos2.getX();
               int n4 = pos2.getZ();
               return WalkableRegionAnalyzer.countReachableCells(terrain2, downAbove.getX(), downAbove.getY(), downAbove.getZ(), 40) < Math.min(40, countReachableCells2)
                  && WalkableRegionAnalyzer.isRegionEnclosed(
                     terrain2,
                     pos.getX(),
                     pos.getY(),
                     pos.getZ(),
                     downAbove.getX(),
                     downAbove.getY(),
                     downAbove.getZ(),
                     (n3x, n4x, z2) -> (n3x != n3 || z2 != n4) && this.getSchematicCells(new BlockPos(n3x, n4x, z2)) < 0
                  );
            }
         }
      } else {
         return false;
      }
   }

   private void startAccessMission(com.corz.client.utils.DescentReusable.Kind kind, int unknownSupersededValue) {
      if (this.unknown != null && this.currentTargetPos != null && this.unknown.getNext() == this.currentTargetPos.asLong()) {
         if (kind == com.corz.client.utils.DescentReusable.Kind.PLATFORM && this.unknown.getDescentStairType() != kind) {
            this.unknown.handleStairDescent(unknownSupersededValue);
         }
      } else {
         if (this.unknown != null) {
            this.releaseSupersededOwnerTemp(this.unknown, "superseded by a new access mission");
         }

         long l = this.currentTargetPos == null ? 0L : this.currentTargetPos.asLong();
         this.unknown = new DescentReusable(this.supersededAccessCount++, l, kind, unknownSupersededValue, this::isNonFluidSchematicCell);
         if (kind != com.corz.client.utils.DescentReusable.Kind.DESCENT) {
            this.rebuildReachableComponent();
            BlockPos blockPos = this.getFeetBlockPos();
            this.unknown
               .handleReusableDescent(
                  kind != com.corz.client.utils.DescentReusable.Kind.PLATFORM && unknownSupersededValue <= 1
                     ? ReusableDescentData.getReusableDescentData(this.componentKey, blockPos.asLong(), true)
                     : ReusableDescentData.getReusableDescentData(this.componentKey, unknownSupersededValue, blockPos.asLong(), true)
               );
         }
      }
   }

