   private boolean tryRecoverFromFall(BlockPos fromPos) {
      if (this.fallRecoveryValue != Integer.MIN_VALUE
         && this.useTemporaryBlocks.isEnabled()
         && mc.player != null
         && mc.world != null
         && this.schematicCells != null) {
         int n2 = this.layerAccessTowerBaseY != Integer.MIN_VALUE ? Math.min(this.fallRecoveryValue, this.layerAccessTowerBaseY) : this.fallRecoveryValue;
         if (fromPos.getY() - 1 >= n2) {
            this.logDebugMessage("\u00a7a[Fall]\u00a7r already at the walking floor (surface y=" + n2 + ") - nothing to climb back to");
            this.fallRecoveryValue = Integer.MIN_VALUE;
            this.longFallRecovery = Long.MIN_VALUE;
            return false;
         } else if (mc.player.isOnGround()
            && this.moduleTick >= this.fellFallValue
            && !this.deckMicroMoves.isProbingExitingConfirmed()
            && !this.hasActiveBlockersStep()
            && this.islandAbort == 0L) {
            int n3 = n2 + 1;
            if (fromPos.getY() + (this.fellPlannedFlag ? 2 : 3) > n3) {
               return false;
            } else {
               BlockPos longValue = null;
               double squaredDistance = Double.MAX_VALUE;

               for (long l : this.completionMissionMap.keySet()) {
                  BlockPos blockPos = BlockPos.fromLong(l);
                  if (blockPos.getY() >= n2) {
                     double d = blockPos.getSquaredDistance(fromPos);
                     if (!(d >= squaredDistance) && this.getRedstoneDeferralReason(blockPos) == null) {
                        squaredDistance = d;
                        longValue = blockPos;
                     }
                  }
               }

               if (longValue != null && this.getHotbarDirtSlot() != -1) {
                  this.rebuildReachableComponent();
                  BlockPos toPos = null;
                  double maxValue3 = Double.MAX_VALUE;

                  for (long l2 : this.component) {
                     BlockPos fromLong = BlockPos.fromLong(l2);
                     if (Math.abs(fromLong.getX() - fromPos.getX()) <= 16 && Math.abs(fromLong.getZ() - fromPos.getZ()) <= 16) {
                        int n = n3 - fromLong.getY();
                        if (n >= 1
                           && n <= this.maxVerticalAccess.getValue()
                           && !this.canColumnsBanned(fromLong)
                           && (this.canReplaceableAir(fromLong, n3) || this.component.size() <= 4 && this.isColumnClearUpToY(fromLong, n3))) {
                           BlockPos blockOffset = this.getBlockOffset(fromLong, n3);
                           if (blockOffset != null) {
                              double d2 = Math.sqrt(fromLong.getSquaredDistance(fromPos))
                                 + 2.0 * n
                                 + 0.05 * Math.sqrt(blockOffset.getSquaredDistance(longValue));
                              if (d2 < maxValue3) {
                                 maxValue3 = d2;
                                 toPos = fromLong;
                              }
                           }
                        }
                     }
                  }

                  if (toPos == null) {
                     this.fellFallValue = this.moduleTick + 200;
                     this.logDebugMessage(
                        "\u00a7e[FallRecovery]\u00a7r no clear column beside the walking layer (surface y=" + n2 + ") within 16 blocks - retrying later"
                     );
                     if (++this.fallRecoveryCount >= 5) {
                        this.fallRecoveryCount = 0;
                        this.fallRecoveryValue = Integer.MIN_VALUE;
                        this.longFallRecovery = Long.MIN_VALUE;
                        this.logDebugMessage("\u00a7e[FallRecovery]\u00a7r giving up the climb back - the normal access recoveries take over");
                     }

                     return false;
                  } else {
                     this.fallRecoveryCount = 0;
                     if (!toPos.equals(fromPos)) {
                        List<BlockPos> list = this.findGoPath(fromPos, toPos);
                        this.standClimbFlag = false;
                        this.arrivedSupportFlag = false;
                        if (list != null
                           && !list.isEmpty()
                           && this.tryFollowMovementRoute(list, toPos, this.createMovementMission(Purpose.MISSION_STAND_MOVE, toPos, null))) {
                           this.longFallRecovery = toPos.asLong();
                           this.logDebugMessage(
                              "\u00a7b[FallRecovery]\u00a7r "
                                 + (n3 - fromPos.getY())
                                 + " below the walking layer (surface y="
                                 + n2
                                 + ") - walking to the climb column "
                                 + toPos.toShortString()
                           );
                           this.transitionToState(AutoBuilder.State.GO_TO_POSITION, "fall recovery: walk to the climb column");
                           return true;
                        } else {
                           this.fellFallValue = this.moduleTick + 100;
                           return false;
                        }
                     } else if (++this.fallClimbValue > 6) {
                        this.fallClimbValue = 0;
                        this.fellFallValue = this.moduleTick + 600;
                        this.longFallRecovery = Long.MIN_VALUE;
                        return false;
                     } else {
                        this.longFallRecovery = fromPos.asLong();
                        this.resetPillarTracking();
                        this.blockPos3BridgeCell = fromPos;
                        this.pillarDirtValue = n3;
                        this.currentTargetPos = longValue;
                        this.supportAccessValue = this.getSchematicCells(longValue);
                        this.logDebugMessage(
                           "\u00a7b[FallRecovery]\u00a7r pillaring "
                              + (n3 - fromPos.getY())
                              + " back up to the walking layer at "
                              + fromPos.toShortString()
                              + " (surface y="
                              + n2
                              + ", work above: "
                              + longValue.toShortString()
                              + ")"
                        );
                        this.setSupportText("TEMP_SUPPORT", "fall recovery climb");
                        this.transitionToState(AutoBuilder.State.SCAFFOLD_UP, "fall recovery: climb back to the walking layer");
                        return true;
                     }
                  }
               } else {
                  return false;
               }
            }
         } else {
            return false;
         }
      } else {
         this.longFallRecovery = Long.MIN_VALUE;
         if (this.fallRecoveryValue == Integer.MIN_VALUE) {
            this.fellPlannedFlag = false;
         }

         return false;
      }
   }

