   private String formatMissionParityDebug(SupportStandUtils.Intent intent, BlockPos pos) {
      try {
         BlockPos blockPos = toBlockPos(intent.stand());
         BlockPos blockPos2 = toBlockPos(intent.support());
         Vec3d vec3d = getStandingEyePos(blockPos).add(0.0, intent.sneak() ? -0.35 : 0.0, 0.0);
         Vec3d vec3d2 = new Vec3d(intent.hx(), intent.hy(), intent.hz());
         float[] fs = MathClampUtils.getWrapDegrees(vec3d, vec3d2);
         BlockHitResult blockHitResult = this.raycastBlockSideForAim(vec3d, fs[0], fs[1], this.reachSetting.getValue());
         int n = this.getSchematicCells(pos);
         BlockState blockState = n >= 0 ? this.targetFluidItems.get(n) : null;
         Direction direction = Direction.values()[Math.max(0, Math.min(5, intent.face()))];
         Integer integer = this.faceParityMap.get(hashPosAndDirection(pos, direction));
         return " \u00a77[MissionParity] stand="
            + blockPos.toShortString()
            + (intent.sneak() ? " sneak" : "")
            + " lookDir="
            + Direction.fromHorizontalDegrees(fs[0])
            + " requiredLook="
            + (blockState == null ? "?" : this.getPlacementFacing(pos, blockState))
            + " requiredDir="
            + (blockState == null ? "?" : this.getRequiredSupportDirection(pos, blockState))
            + " ray="
            + (
               blockHitResult.getType() == net.minecraft.util.hit.HitResult.Type.BLOCK
                  ? blockHitResult.getBlockPos().toShortString() + "/" + blockHitResult.getSide()
                  : "MISS"
            )
            + " planned="
            + blockPos2.toShortString()
            + "/"
            + direction
            + " supportInteractive="
            + isFlaggedBlockState(mc.world.getBlockState(blockPos2))
            + " faceBanned="
            + (integer != null && this.moduleTick < integer)
            + " partnerPlaced="
            + this.isPairedBlockPlaced(pos)
            + String.format(Locale.ROOT, " dist=%.2f", Math.sqrt(vec3d.squaredDistanceTo(vec3d2)));
      } catch (Exception e) {
         return " [MissionParity] n/a: " + e;
      }
   }

