   private boolean trySelectProgram(String passesText) {
      if (mc.world == null || this.schematicCells == null) {
         return false;
      } else if (this.expectedConfirms == null && this.moduleTick >= this.selectPassesReadyTick) {
         if (this.plannerTicks.isTimeFlag() && !this.plannerTicks.canTime(System.nanoTime(), 1000000000L)) {
            return false;
         } else {
            long nanoTime2 = this.selectPasses.getNanoTime();

            boolean selectPasses;
            try {
               this.selectPassesReadyTick = this.moduleTick + 40;
               BlockViewHelper blockViewHelper = new BlockViewHelper(mc.world);
               BlockStateUtilsNodes.WorkSource workSource = this.getCachedWorkSource();
               BlockStateUtilsNodes.Survey survey = BlockStateUtilsNodes.buildSurvey(blockViewHelper, workSource);
               this.maxConfirmsSeen = Math.max(this.maxConfirmsSeen, survey.getMaxEntryCount());
               this.passesValue = survey.getRejectedCount();
               this.surveyAmountEstimate = survey.getAverageCount();
               Nodes nodes = BlockStateUtilsNodes.getNodes(blockViewHelper, workSource, survey);
               Nodes nodes2 = nodes != null && nodes.getValue() >= 4
                  ? null
                  : BlockStateUtilsNodes.getStandChaining(new BlockViewHelper(mc.world), workSource, 8, 48);
               Nodes nodes3 = nodes;
               if (nodes2 != null && (nodes == null || nodes2.getValue() > nodes.getValue())) {
                  nodes3 = nodes2;
               }

               if (nodes3 == null && this.useTemporaryBlocks.isEnabled() && this.hasUsableBlockItem()) {
                  BlockStateUtilsNodes.AccessDiag accessDiag = new BlockStateUtilsNodes.AccessDiag();
                  BlockStateUtilsNodes.AccessRequest accessRequest = this.throughputCompletionData != null
                     ? this.throughputCompletionData
                     : BlockStateUtilsNodes.AccessRequest.getThroughput();
                  boolean flag = this.throughputCompletionData == null;
                  this.throughputCompletionData = null;
                  nodes3 = BlockStateUtilsNodes.searchAllLanes(new BlockViewHelper(mc.world), workSource, survey, accessDiag, accessRequest);
                  BlockStateUtilsNodes.AccessRequest accessRequest2 = nodes3 == null && flag ? this.getFiniteBlocked() : null;
                  if (accessRequest2 != null) {
                     nodes3 = BlockStateUtilsNodes.searchAllLanes(new BlockViewHelper(mc.world), workSource, survey, accessDiag, accessRequest2);
                  }

                  if (nodes3 != null) {
                     this.passesCount++;
                  }
               }

               if (nodes3 == null || nodes3.isEmpty()) {
                  return false;
               }

               var iterator = nodes3.getCopyOf().iterator();

               Step step;
               do {
                  if (!iterator.hasNext()) {
                     if (nodes3.getRunSideType() == com.corz.client.utils.Nodes.Kind.ACCESS_CLUSTER_RUN) {
                        this.selectPassRetryCount++;
                     }

                     long l = nodes3.getCopyOf().get(0).target();
                     if (l != this.lastConfirmsExpectedKey || this.moduleTick >= this.confirmsExpectedDeadlineTick) {
                        this.expectedConfirms = nodes3;
                        this.cursor = 0;
                        this.programDispatchableValue = 0;
                        this.sessionStartConfirms = this.confirms;
                        this.confirmsValue = this.moduleTick;
                        this.confirmsCount++;
                        this.selectPassesReadyTick = this.moduleTick;
                        this.handleProgramsEnded(this.confirmsValue, nodes3.getRunSideType().name(), nodes3.getCopyOf().size());
                        this.logDebugMessage(
                           "\u00a7a[ProgramSelect]\u00a7r id="
                              + this.confirmsValue
                              + " kind="
                              + nodes3.getRunSideType()
                              + " members="
                              + nodes3.getCopyOf().size()
                              + " expectedConfirms="
                              + nodes3.getValue()
                              + " reason="
                              + passesText
                        );
                        return true;
                     }

                     return false;
                  }

                  step = (Step)iterator.next();
               } while (!step.isPlaceKind() || this.useTemporaryBlocks.isEnabled() && this.hasUsableBlockItem());

               selectPasses = false;
            } finally {
               this.selectPasses.handleTimesCalls(com.corz.client.utils.OpsCalls.Phase.SELECT_TOTAL, nanoTime2);
            }

            return selectPasses;
         }
      } else {
         return false;
      }
   }

