   private static final class LayerStats {
      int occupied;
      int solvableBuildableCount;
      int waitSupport;
      int buildableLayerCount;
      int dead;
      int deadUnreachableCount;
      int missingMat;
      int solvableMatCount;
      int complete;
      final LinkedHashMap<Item, Integer> missingMap = new LinkedHashMap<>();

      String formatMissingItems() {
         if (this.missingMap.isEmpty()) {
            return "";
         } else {
            StringBuilder stringBuilder = new StringBuilder(" missing=[");
            int appendCounter = 0;

            for (Entry entry : this.missingMap.entrySet()) {
               if (appendCounter++ > 0) {
                  stringBuilder.append(", ");
               }

               if (appendCounter > 4) {
                  stringBuilder.append("+").append(this.missingMap.size() - 4).append(" more");
                  break;
               }

               stringBuilder.append(Registries.ITEM.getId((Item)entry.getKey()).getPath()).append("\u00d7").append(entry.getValue());
            }

            return stringBuilder.append("]").toString();
         }
      }

      int getBlockedCount() {
         return this.missingMat + this.waitSupport + this.deadUnreachableCount + this.dead + this.occupied;
      }

      String formatSummary() {
         return "[buildable="
            + this.solvableBuildableCount
            + " tempSolvable="
            + this.solvableMatCount
            + " missingMat="
            + this.missingMat
            + " waitSupport="
            + this.waitSupport
            + " unreachable="
            + this.deadUnreachableCount
            + " dead="
            + this.dead
            + (this.occupied > 0 ? " occupied=" + this.occupied : "")
            + this.formatMissingItems()
            + "]";
      }
   }

