      @Override
      public void forEachTargetCell(WhoJsonUtils.CellConsumer cellConsumer) {
         if (AutoBuilder.this.isPlacementMatchingSchematic()) {
            var list = AutoBuilder.this.blockStateHelper.getItems();
            var cameraBlockStateList = AutoBuilder.this.blockStateHelper.getCameraBlockStateList();
            int autoBuilderLimit = Math.min(list.size(), cameraBlockStateList.size());

            for (int i = 0; i < autoBuilderLimit; i++) {
               Item item = AutoBuilder.getItemForBlockState((BlockState)cameraBlockStateList.get(i));
               if (item != Items.AIR) {
                  BlockPos blockPos = (BlockPos)list.get(i);
                  cellConsumer.accept(blockPos.getX(), blockPos.getY(), blockPos.getZ(), Registries.ITEM.getId(item).toString());
               }
            }
         }
      }

