   private static final class TailSnapshot implements SupportStandUtils.World {
      private final HashSet<Long> boxesPositionSet;
      private final HashMap<Long, List<SupportStandUtils.Box>> boxesListMap;
      private final HashSet<Long> apiLavaPositionSet;
      private final HashMap<Long, List<SupportStandUtils.Box>> apiLavaListMap;
      private final HashSet<Long> tailSnapshotPositionSet;
      private final HashSet<Long> apiPositionSet;
      private final HashMap<Long, List<SupportStandUtils.Box>> tailSnapshotListMap;
      private final HashMap<Long, AutoBuilder.TailSnapshot.CellData> boxesCellDataMap = new HashMap<>();

      @Override
      public boolean isForeignCell(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData != null && cellData.foreign();
      }

      @Override
      public List<SupportStandUtils.Box> getTailOverrideBoxes(SupportStandUtils.Cell cell) {
         var list = this.tailSnapshotListMap.get(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
         return list != null ? list : this.getCellBoxes(cell);
      }

      @Override
      public boolean isTailCell(SupportStandUtils.Cell cell) {
         return !this.tailSnapshotPositionSet.isEmpty() && this.tailSnapshotPositionSet.contains(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
      }

      private TailSnapshot() {
         this.boxesPositionSet = new HashSet<>();
         this.tailSnapshotListMap = new HashMap<>();
         this.apiLavaListMap = new HashMap<>();
         this.boxesListMap = new HashMap<>();
         this.apiPositionSet = new HashSet<>();
         this.apiLavaPositionSet = new HashSet<>();
         this.tailSnapshotPositionSet = new HashSet<>();
      }

      private static boolean isInteractiveBlock(BlockState state) {
         Block block = state.getBlock();
         return block instanceof PistonBlock
            || block instanceof TntBlock
            || block instanceof DispenserBlock
            || block instanceof DoorBlock
            || block instanceof TrapdoorBlock
            || block instanceof FenceGateBlock
            || block instanceof ObserverBlock;
      }

      @Override
      public boolean canOwnDirt(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData != null && cellData.ownDirt();
      }

      private AutoBuilder.TailSnapshot.CellData getCellData(SupportStandUtils.Cell cell) {
         return this.boxesCellDataMap.get(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
      }

      @Override
      public boolean isReservedCell(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData != null && cellData.reserved();
      }

      @Override
      public List<SupportStandUtils.Box> getLavaOverrideBoxes(SupportStandUtils.Cell cell) {
         var list = this.apiLavaListMap.get(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
         return list != null ? list : this.getTailOverrideBoxes(cell);
      }

      @Override
      public boolean isTrapCell(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData != null && cellData.trap();
      }

      static AutoBuilder.TailSnapshot buildSnapshot(
         AutoBuilder autoBuilder,
         List<SupportStandUtils.Target> list,
         BlockPos pos,
         int boxesValue,
         Set<Long> set,
         Set<Long> set2,
         Collection<Long> collection
      ) {
         MinecraftClient instance = MinecraftClient.getInstance();
         int x = pos.getX();
         int x2 = pos.getX();
         int y = pos.getY();
         int y2 = pos.getY();
         int z = pos.getZ();
         int z2 = pos.getZ();

         for (SupportStandUtils.Target target : list) {
            x = Math.min(x, target.cell().x());
            x2 = Math.max(x2, target.cell().x());
            y = Math.min(y, target.cell().y());
            y2 = Math.max(y2, target.cell().y());
            z = Math.min(z, target.cell().z());
            z2 = Math.max(z2, target.cell().z());
         }

         for (long boxesValue2 : collection) {
            BlockPos long2 = BlockPos.fromLong(boxesValue2);
            x = Math.min(x, long2.getX());
            x2 = Math.max(x2, long2.getX());
            y = Math.min(y, long2.getY());
            y2 = Math.max(y2, long2.getY());
            z = Math.min(z, long2.getZ());
            z2 = Math.max(z2, long2.getZ());
         }

         int boxesValue3 = x - boxesValue;
         int boxesLimit = x2 + boxesValue;
         int boxesValue4 = z - boxesValue;
         int boxesLimit2 = z2 + boxesValue;
         y -= 6;
         y2 += 6;
         AutoBuilder.TailSnapshot tailSnapshot = new AutoBuilder.TailSnapshot();

         for (Entry entry : autoBuilder.bannedColumns.entrySet()) {
            if (autoBuilder.moduleTick < (Integer)entry.getValue()) {
               tailSnapshot.apiPositionSet.add((Long)entry.getKey());
            }
         }

         var hashSet = new HashSet();
         boolean boxesFlag = false;
         var hashSet2 = new HashSet();

         for (SupportStandUtils.Target target2 : list) {
            if (target2.supportDir() == 0 && target2.kind() != SupportStandUtils.Kind.FACE_PLAYER && target2.kind() != SupportStandUtils.Kind.FACE_AWAY) {
               hashSet2.add(BlockPos.asLong(target2.cell().x(), target2.cell().y(), target2.cell().z()));
            }
         }

         for (SupportStandUtils.Target target3 : list) {
            if (target3.isKindFluid()) {
               boxesFlag = true;
               break;
            }
         }

         for (SupportStandUtils.Target target4 : list) {
            BlockPos blockPos = new BlockPos(target4.cell().x(), target4.cell().y(), target4.cell().z());
            int schematicCells = autoBuilder.getSchematicCells(blockPos);
            if (schematicCells >= 0 && isInteractiveBlock(autoBuilder.targetFluidItems.get(schematicCells))) {
               hashSet.add(blockPos.asLong());
            }

            if (schematicCells >= 0
               && WalkRouteFinder.isHazardBlock(autoBuilder.targetFluidItems.get(schematicCells))
               && autoBuilder.targetFluidItems.get(schematicCells).getFluidState().isEmpty()) {
               tailSnapshot.tailSnapshotPositionSet.add(blockPos.asLong());
            }
         }

         Mutable mutable = new Mutable();

         for (int i = boxesValue3; i <= boxesLimit; i++) {
            for (int j = y; j <= y2; j++) {
               for (int k = boxesValue4; k <= boxesLimit2; k++) {
                  mutable.set(i, j, k);
                  BlockState blockState = instance.world.getBlockState(mutable);
                  if (!blockState.isAir()) {
                     if (isInteractiveBlock(blockState)) {
                        hashSet.add(mutable.asLong());
                     }

                     VoxelShape collisionShape = blockState.getCollisionShape(instance.world, mutable);
                     List noBoxes2;
                     if (collisionShape.isEmpty()) {
                        noBoxes2 = SupportStandUtils.NO_BOXES;
                     } else {
                        var arrayList = new ArrayList(2);

                        for (Box box : collisionShape.getBoundingBoxes()) {
                           arrayList.add(new SupportStandUtils.Box(box.minX, box.minY, box.minZ, box.maxX, box.maxY, box.maxZ));
                        }

                        noBoxes2 = List.copyOf(arrayList);
                     }

                     VoxelShape voxelShape = boxesFlag ? blockState.getOutlineShape(instance.world, mutable) : collisionShape;
                     if (voxelShape != collisionShape && !voxelShape.isEmpty()) {
                        var arrayList2 = new ArrayList(2);

                        for (Box getBoundingBoxesItem : voxelShape.getBoundingBoxes()) {
                           arrayList2.add(new SupportStandUtils.Box(getBoundingBoxesItem.minX, getBoundingBoxesItem.minY, getBoundingBoxesItem.minZ, getBoundingBoxesItem.maxX, getBoundingBoxesItem.maxY, getBoundingBoxesItem.maxZ));
                        }

                        tailSnapshot.apiLavaListMap.put(mutable.asLong(), List.copyOf(arrayList2));
                     }

                     if (boxesFlag && blockState.getBlock() instanceof FluidFillable) {
                        tailSnapshot.apiLavaPositionSet.add(mutable.asLong());
                     }

                     boolean fireWither = WalkRouteFinder.isHazardBlock(blockState);
                     boolean boxesFlag2 = WalkRouteFinder.isPartialHeightBlock(blockState) && !(blockState.getBlock() instanceof HopperBlock);
                     if (fireWither && blockState.getFluidState().isEmpty()) {
                        tailSnapshot.tailSnapshotPositionSet.add(mutable.asLong());
                     }

                     if (blockState.getBlock() instanceof BambooBlock) {
                        tailSnapshot.tailSnapshotPositionSet.add(mutable.asLong());
                     }

                     if (noBoxes2.isEmpty() && !fireWither && !boxesFlag2) {
                        if (blockState.getBlock() instanceof FenceGateBlock && BlockStateUtilsView.canBlockOpen(blockState)) {
                           var arrayList3 = new ArrayList(2);

                           for (Box box3 : blockState.getOutlineShape(instance.world, mutable).getBoundingBoxes()) {
                              arrayList3.add(new SupportStandUtils.Box(box3.minX, box3.minY, box3.minZ, box3.maxX, box3.maxY, box3.maxZ));
                           }

                           if (!arrayList3.isEmpty()) {
                              tailSnapshot.boxesListMap.put(mutable.asLong(), List.copyOf(arrayList3));
                              tailSnapshot.boxesCellDataMap
                                 .put(
                                    mutable.asLong(),
                                    new AutoBuilder.TailSnapshot.CellData(noBoxes2, false, false, AutoBuilder.isFlaggedBlockState(blockState), false, false, false)
                                 );
                           }
                        }

                        if (BlockStateUtilsView.canWireIterator(blockState) && hashSet2.contains(BlockPos.asLong(i, j + 1, k))) {
                           var arrayList4 = new ArrayList(3);

                           for (Box box4 : blockState.getOutlineShape(instance.world, mutable).getBoundingBoxes()) {
                              arrayList4.add(new SupportStandUtils.Box(box4.minX, box4.minY, box4.minZ, box4.maxX, box4.maxY, box4.maxZ));
                           }

                           if (!arrayList4.isEmpty()) {
                              tailSnapshot.boxesListMap.put(mutable.asLong(), List.copyOf(arrayList4));
                           }
                        }
                     } else {
                        tailSnapshot.boxesCellDataMap
                           .put(
                              mutable.asLong(),
                              new AutoBuilder.TailSnapshot.CellData(
                                 noBoxes2, fireWither, boxesFlag2, AutoBuilder.isFlaggedBlockState(blockState), autoBuilder.cells.contains(mutable.asLong()), false, false
                              )
                           );
                        if (noBoxes2.isEmpty() && blockState.getBlock() instanceof PowderSnowBlock) {
                           var arrayList5 = new ArrayList(1);

                           for (Box box5 : blockState.getOutlineShape(instance.world, mutable).getBoundingBoxes()) {
                              arrayList5.add(new SupportStandUtils.Box(box5.minX, box5.minY, box5.minZ, box5.maxX, box5.maxY, box5.maxZ));
                           }

                           if (!arrayList5.isEmpty()) {
                              tailSnapshot.boxesListMap.put(mutable.asLong(), List.copyOf(arrayList5));
                           }
                        }

                        if (!collisionShape.isEmpty() && collisionShape.getMax(Axis.Y) > 1.0001) {
                           VoxelShape outlineShape = blockState.getOutlineShape(instance.world, mutable);
                           var arrayList6 = new ArrayList(4);

                           for (Box box6 : outlineShape.getBoundingBoxes()) {
                              arrayList6.add(new SupportStandUtils.Box(box6.minX, box6.minY, box6.minZ, box6.maxX, box6.maxY, box6.maxZ));
                           }

                           tailSnapshot.tailSnapshotListMap.put(mutable.asLong(), List.copyOf(arrayList6));
                        }

                        if (blockState.getBlock() instanceof HopperBlock && !noBoxes2.isEmpty()) {
                           var arrayList7 = new ArrayList(noBoxes2);
                           arrayList7.add(new SupportStandUtils.Box(0.125, 1.0, 0.125, 0.875, 1.0, 0.875));
                           tailSnapshot.tailSnapshotListMap.put(mutable.asLong(), List.copyOf(arrayList7));
                        }
                     }
                  }
               }
            }
         }

         for (long boxesValue5 : set) {
            BlockPos long3 = BlockPos.fromLong(boxesValue5);
            if (long3.getX() >= boxesValue3
               && long3.getX() <= boxesLimit
               && long3.getY() >= y
               && long3.getY() <= y2
               && long3.getZ() >= boxesValue4
               && long3.getZ() <= boxesLimit2) {
               int schematicCells2 = autoBuilder.getSchematicCells(long3);
               if (schematicCells2 >= 0 && !autoBuilder.targetFluidItems.get(schematicCells2).isFullCube(instance.world, long3)) {
                  tailSnapshot.boxesPositionSet.add(boxesValue5);
               }

               if (schematicCells2 >= 0 && isInteractiveBlock(autoBuilder.targetFluidItems.get(schematicCells2))) {
                  hashSet.add(boxesValue5);
               }

               AutoBuilder.TailSnapshot.CellData cellData = tailSnapshot.boxesCellDataMap.get(boxesValue5);
               if (cellData == null) {
                  tailSnapshot.boxesCellDataMap.put(boxesValue5, new AutoBuilder.TailSnapshot.CellData(SupportStandUtils.NO_BOXES, false, false, false, false, true, false));
               } else if (!cellData.reserved()) {
                  tailSnapshot.boxesCellDataMap
                     .put(
                        boxesValue5,
                        new AutoBuilder.TailSnapshot.CellData(
                           cellData.boxes(), cellData.hazard(), cellData.trap(), cellData.interactive(), cellData.ownDirt(), true, cellData.foreign()
                        )
                     );
               }
            }
         }

         for (long formatMinPop : set2) {
            BlockPos long4 = BlockPos.fromLong(formatMinPop);
            if (long4.getX() >= boxesValue3
               && long4.getX() <= boxesLimit
               && long4.getY() >= y
               && long4.getY() <= y2
               && long4.getZ() >= boxesValue4
               && long4.getZ() <= boxesLimit2) {
               AutoBuilder.TailSnapshot.CellData cellData2 = tailSnapshot.boxesCellDataMap.get(formatMinPop);
               if (cellData2 == null) {
                  tailSnapshot.boxesCellDataMap.put(formatMinPop, new AutoBuilder.TailSnapshot.CellData(SupportStandUtils.NO_BOXES, false, false, false, false, true, true));
               } else if (cellData2.boxes().isEmpty() && !cellData2.foreign()) {
                  tailSnapshot.boxesCellDataMap
                     .put(
                        formatMinPop,
                        new AutoBuilder.TailSnapshot.CellData(cellData2.boxes(), cellData2.hazard(), cellData2.trap(), cellData2.interactive(), cellData2.ownDirt(), true, true)
                     );
               }
            }
         }

         for (long boxesValue7 : (Iterable<Long>) (hashSet)) {
            for (Direction direction : Direction.values()) {
               BlockPos offset = BlockPos.fromLong(boxesValue7).offset(direction);
               if (offset.getX() >= boxesValue3
                  && offset.getX() <= boxesLimit
                  && offset.getY() >= y
                  && offset.getY() <= y2
                  && offset.getZ() >= boxesValue4
                  && offset.getZ() <= boxesLimit2) {
                  long long5 = offset.asLong();
                  AutoBuilder.TailSnapshot.CellData cellData3 = tailSnapshot.boxesCellDataMap.get(long5);
                  if ((cellData3 == null || !cellData3.reserved() && cellData3.boxes().isEmpty())
                     && (autoBuilder.formatBlockShort(offset) != null || autoBuilder.describeObserverPulseHazard(offset) != null)) {
                     tailSnapshot.boxesCellDataMap
                        .put(
                           long5,
                           cellData3 == null
                              ? new AutoBuilder.TailSnapshot.CellData(SupportStandUtils.NO_BOXES, false, false, false, false, true, false)
                              : new AutoBuilder.TailSnapshot.CellData(
                                 cellData3.boxes(), cellData3.hazard(), cellData3.trap(), cellData3.interactive(), cellData3.ownDirt(), true, cellData3.foreign()
                              )
                        );
                     tailSnapshot.boxesPositionSet.add(long5);
                  }
               }
            }
         }

         return tailSnapshot;
      }

      @Override
      public boolean isHazardCell(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData != null && cellData.hazard();
      }

      @Override
      public List<SupportStandUtils.Box> getExtraBoxes(SupportStandUtils.Cell cell) {
         var list = this.boxesListMap.get(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
         return list != null ? list : List.of();
      }

      @Override
      public boolean isLavaOverrideCell(SupportStandUtils.Cell cell) {
         return !this.apiLavaPositionSet.isEmpty() && this.apiLavaPositionSet.contains(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
      }

      @Override
      public List<SupportStandUtils.Box> getCellBoxes(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData == null ? SupportStandUtils.NO_BOXES : cellData.boxes();
      }

      @Override
      public boolean isInteractiveCell(SupportStandUtils.Cell cell) {
         AutoBuilder.TailSnapshot.CellData cellData = this.getCellData(cell);
         return cellData != null && cellData.interactive();
      }

      @Override
      public boolean isOutsideBoxesSet(SupportStandUtils.Cell cell) {
         return !this.boxesPositionSet.contains(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
      }

      @Override
      public boolean isApiCell(SupportStandUtils.Cell cell) {
         return this.apiPositionSet.contains(BlockPos.asLong(cell.x(), cell.y(), cell.z()));
      }

      private record CellData(
         List<SupportStandUtils.Box> boxes, boolean hazard, boolean trap, boolean interactive, boolean ownDirt, boolean reserved, boolean foreign
      ) {
      }
   }

